window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["1322025"]={"book":{"id":1322025,"title":"卓有成效的管理者","author":"[美] 彼得·德鲁克","translator":"许是祥","publisher":"机械工业出版社","pubdate":"2005-6","isbn":"9787111165170","tags":["管理","德鲁克","管理学","卓有成效的管理者","彼得·德鲁克","管理经典","商业","经典"],"memCount":53},"np":1,"pb":[90],"idx":[{"i":19635,"t":"如何诊断自己的时间","l":"TF1-1","c":"Ethan","g":1,"p":1},{"i":19438,"t":"如何诊断自己的时间：提高管理者的有效性。","l":"TF1-2","c":"张伊莲","g":1,"p":1},{"i":19330,"t":"善用上司长处 管理卓有成效","l":"TF2-1","c":"杏芙姐","g":1,"p":1},{"i":19328,"t":"掌控时间“三步走”","l":"TF1-2","c":"杏芙姐","g":1,"p":1},{"i":18456,"t":"在职场时间管理主要在于少做事、集中做重要事","l":"TF2-1","c":"郭世真无锡","g":1,"p":1},{"i":18415,"t":"要事第一","l":"TF1-2","c":"郭世真无锡","g":1,"p":1},{"i":18212,"t":"职场如何高效管理时间","l":"TF1-1","c":"郝致暐","g":1,"p":1},{"i":18144,"t":"聚焦“要事”，做时间和任务的主人","l":"TF1-2","c":"Ethan","g":1,"p":1},{"i":17907,"t":"卓有成效的管理者之时间管理","l":"TF1-2","c":"承哥","g":1,"p":1},{"i":17707,"t":"卓有成效的管理者常用的关注人的长处和贡献的全新考评方式","l":"TF1-1","c":"Minch明奇","g":1,"p":1},{"i":17618,"t":"晋级","l":"TF1-1","c":"汪教在路上","g":1,"p":1},{"i":17531,"t":"摆脱惯性思维","l":"TF1-1","c":"周云香","g":1,"p":1},{"i":17486,"t":"摆脱过去惯性思维","l":"TF1-1","c":"周云香","g":1,"p":1},{"i":17201,"t":"勇气与选择：在变化中优先排序的艺术","l":"TF1-2","c":"嫄","g":1,"p":1},{"i":17127,"t":"五个习惯养成卓有成效的管理者","l":"TF1-1","c":"嫄","g":1,"p":1},{"i":16893,"t":"如何管理好上司","l":"TF1-1","c":"张瑛","g":1,"p":1},{"i":16695,"t":"卓有成效的管理","l":"TF2-3","c":"陈璐","g":1,"p":1},{"i":16331,"t":"认识你的时间","l":"TF1-1","c":"英英2003","g":1,"p":1},{"i":14684,"t":"卓有成效的五步法","l":"TF1-1","c":"吕十七","g":1,"p":1},{"i":14682,"t":"掌握时间三步法","l":"TF1-2","c":"吕十七","g":1,"p":1},{"i":14644,"t":"做自己时间的主人","l":"TF2-3","c":"玄夕","g":1,"p":1},{"i":14362,"t":"管理自己时间的前提是-诊断自己的时间","l":"TF2-1","c":"孟欣","g":1,"p":1},{"i":14349,"t":"高效会议3步法","l":"TF2-1","c":"光子","g":1,"p":1},{"i":14220,"t":"一个卓有成效的管理者如何掌握自己时间的3个步骤","l":"TF1-2","c":"光子","g":1,"p":1},{"i":13956,"t":"卓有成效的管理者","l":"TF1-1","c":"光子","g":1,"p":1},{"i":13570,"t":"如何诊断自己的时间","l":"TF1-2","c":"张海燕","g":1,"p":1},{"i":13569,"t":"掌握自己的时间","l":"TF1-1","c":"张海燕","g":1,"p":1},{"i":13487,"t":"卓有成效的管理者","l":"TF1-2","c":"席路","g":1,"p":1},{"i":13098,"t":"卓有成效的管理者","l":"TF1-2","c":"任静","g":1,"p":1},{"i":13097,"t":"卓有成效的管理者","l":"TF1-1","c":"任静","g":1,"p":1},{"i":12909,"t":"集中精力只做好一件事","l":"TF3-3","c":"国子监","g":1,"p":1},{"i":11488,"t":"如何诊断自己的时间","l":"TF2-1","c":"杨颖春","g":1,"p":1},{"i":10253,"t":"有效授权","l":"TF3-1","c":"段志梅","g":1,"p":1},{"i":9871,"t":"学会利用整块时间","l":"TF1-2","c":"黄胜","g":1,"p":1},{"i":9870,"t":"卓有成效的管理5原则","l":"TF1-1","c":"黄胜","g":1,"p":1},{"i":9466,"t":"有效的人际关系","l":"TF1-1","c":"陈洪琪","g":1,"p":1},{"i":8236,"t":"学会诊断自己的时间，然后合理管理它","l":"TF2-1","c":"许娟","g":1,"p":1},{"i":7645,"t":"使用“掌控时间法”提升时间使用效率","l":"TF2-2","c":"阿风","g":1,"p":1},{"i":6729,"t":"如何诊断自己的时间？","l":"TF2-1","c":"陈慧卉","g":1,"p":1},{"i":6482,"t":"如何运用三步法表达反面意见？","l":"TF3-1","c":"绚绚","g":1,"p":1},{"i":6424,"t":"三问法排除浪费时间的内容","l":"TF1-2","c":"上好佳","g":1,"p":1},{"i":6314,"t":"诊断自己的时间，提升自我及团队效能","l":"TF2-1","c":"杨颖春","g":1,"p":1},{"i":6242,"t":"掌控自己的时间","l":"TF1-1","c":"pumafly","g":1,"p":1},{"i":5862,"t":"掌握自己的时间","l":"TF2-3","c":"鱼和十滴水","g":1,"p":1},{"i":5657,"t":"高效管理","l":"TF1-2","c":"棒妈","g":1,"p":1},{"i":5534,"t":"用“重人之长”代替“”视人之短”","l":"TF1-1","c":"彭梦","g":1,"p":1},{"i":5524,"t":"卓有成效的管理者必须高效利用时间","l":"TF1-1","c":"曾金泉","g":1,"p":1},{"i":5385,"t":"要事优先1","l":"TF1-1","c":"姜庆海","g":1,"p":1},{"i":4996,"t":"林妹妹TF1-2过级","l":"TF1-2","c":"林妹妹","g":1,"p":1},{"i":4975,"t":"林妹妹1-1过级","l":"TF1-1","c":"林妹妹","g":1,"p":1},{"i":4926,"t":"学习有效之聚焦贡献","l":"TF2-3","c":"鼓","g":1,"p":1},{"i":4925,"t":"学习“有效”之聚焦贡献-鼓","l":"TF3-1","c":"鼓","g":0,"p":1},{"i":4924,"t":"学习“有效”之聚焦贡献","l":"TF3-1","c":"鼓","g":1,"p":1},{"i":4923,"t":"学习有效之要事第一","l":"TF2-2","c":"鼓","g":1,"p":1},{"i":4622,"t":"掌握自己的时间，运用记录，管理，安排三个步骤管理时间，优化自","l":"TF2-2","c":"唐云霞","g":1,"p":1},{"i":4596,"t":"找回我们浪费的时间","l":"TF1-2","c":"AURORA佳","g":1,"p":1},{"i":4550,"t":"如何管理自己的时间","l":"TF1-2","c":"陈小媚","g":1,"p":1},{"i":3469,"t":"吴佳音TF1-1定级训练","l":"TF1-1","c":"吴佳音","g":1,"p":1},{"i":2881,"t":"五个思考习惯","l":"TF1-1","c":"牛牛0519","g":1,"p":1},{"i":2665,"t":"学习者能通过记录某段时间的实际耗用，分析记录的情况，合理安排","l":"TF2-2","c":"黄鹂","g":1,"p":1},{"i":2643,"t":"如何找到整段时间","l":"TF1-2","c":"牛牛0519","g":1,"p":1},{"i":2568,"t":"找寻“自己都去哪儿了？”的答案","l":"TF2-1","c":"黄鹂","g":1,"p":1},{"i":2369,"t":"如何统一安排可以自由支配的时间","l":"TF1-1","c":"李媛","g":1,"p":1},{"i":2362,"t":"统一安排可以自由支配的时间","l":"TF1-1","c":"李媛","g":1,"p":1},{"i":2037,"t":"有效的决策（选择）","l":"TF2-3","c":"Poul","g":1,"p":1},{"i":2034,"t":"要事优先之学会舍弃","l":"TF2-2","c":"Poul","g":1,"p":1},{"i":2030,"t":"充分发挥自己的长处","l":"TF2-1","c":"Poul","g":1,"p":1},{"i":2026,"t":"善于管理自己的时间","l":"TF3-3","c":"金家东","g":1,"p":1},{"i":1911,"t":"如何将零碎的时间集中起来支配","l":"TF2-1","c":"牛牛0519","g":1,"p":1},{"i":1763,"t":"如何决定优先","l":"TF1-2","c":"牛牛0519","g":1,"p":1},{"i":1709,"t":"卓有成效的管理者五个思考习惯","l":"TF1-1","c":"牛牛0519","g":1,"p":1},{"i":1708,"t":"卓有成效的管理者的五个习惯","l":"TF1-1","c":"牛牛0519","g":1,"p":1},{"i":1669,"t":"如何才能集中精力干好一件事","l":"TF3-2","c":"金家东","g":1,"p":1},{"i":1616,"t":"如何因事用人","l":"TF2-4","c":"sammi","g":1,"p":1},{"i":1551,"t":"如何使专业人员的工作卓有成效","l":"TF1-2","c":"Poul","g":1,"p":1},{"i":1550,"t":"管理者的承诺","l":"TF1-1","c":"Poul","g":1,"p":1},{"i":1220,"t":"向彼得·德鲁克学时间管理","l":"TF2-4","c":"鲁锋","g":1,"p":1},{"i":1204,"t":"如何确定会议是否有必要开？以及让会议开的更加有效","l":"TF2-4","c":"金家东","g":1,"p":1},{"i":1186,"t":"卓有成效的管理者思想上必须养成的习惯","l":"TF2-1","c":"刘红艳","g":1,"p":1},{"i":1070,"t":"如何用战略性思考与反面意见有效决策","l":"TF2-4","c":"刘云汉","g":1,"p":1},{"i":1069,"t":"发挥上级的长处","l":"TF2-3","c":"刘云汉","g":1,"p":1},{"i":996,"t":"如何因事用人选拔人才","l":"TF2-3","c":"金家东","g":1,"p":1},{"i":886,"t":"系统管理时间","l":"TF2-4","c":"熊媛","g":1,"p":1},{"i":657,"t":"共读实践分享：卓有成效的管理者","l":"TF2-1","c":"熊媛","g":1,"p":1},{"i":439,"t":"管理时间","l":"TF3-2","c":"喜羊羊","g":1,"p":1},{"i":438,"t":"授权","l":"TF3-1","c":"喜羊羊","g":1,"p":1},{"i":430,"t":"有效的考评方式","l":"TF1-2","c":"陈艳蓉","g":1,"p":1},{"i":196,"t":"卓有成效的管理者","l":"TF3-3","c":"Jacky","g":1,"p":1},{"i":176,"t":"要事第一，先后次序的考虑","l":"TF3-2","c":"Jacky","g":1,"p":1},{"i":68,"t":"如何组织更高效的会议","l":"TF1-2","c":"安静","g":1,"p":1}],"ms":[{"id":19635,"topic":"如何诊断自己的时间","learn_goal":"","remark":"无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"Ethan","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是徐毅，非常高兴加入拆书帮这个大家庭，我用三个标签介绍一下自己：\u003c/p>\u003cp>（1）拆书新手：我是在2024.05月第一次听说拆书帮，在2024.06月第一次参加拆书帮的线下活动，2024.7月参加拆书训练营，今天是我第一次参加拆书晋级；\u003c/p>\u003cp>（2）学习者：以前读书是从头读到尾的学院式学习，现在尝试聚焦解决问题的成人学习；\u003c/p>\u003cp>（3）管理者：我目前在一家国企从事技术管理工作，希望通过拆书学习可以提升我的逻辑思维能力、管理能力以及表达能力。\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】\u003c/strong>\u003c/p>\u003cp>今天是我第一次参加拆书帮晋级的日子，首先给小伙伴们解释一下什么是【拆书法】。\u003c/p>\u003cp>拆书法的拆并不是拆散的意思，而是强调把书本里的知识转化为学习者的能力。具体来说：\u003c/p>\u003cp>“拆书”是一种学习方法论，以提升能力、解决问题为目标。\u003c/p>\u003cp>强调以学习者为中心，而不是以书或老师为中心。\u003c/p>\u003cp>致力于内化和应用知识，实现能力提升和行为改变。\u003c/p>\u003cp>拆书法分为：个人学习的拆书法和组织学习的拆书法。\u003c/p>\u003cp>\u003cstrong>个人学习的拆书法：\u003c/strong>就是便签法，具体来说就是在阅读之后用自己的语言描述原文内容；然后联想过去的经验，将知识与过去的自己建立联结；最后结合这个知识点规划未来的应用，真正实现\u003cstrong>拆为己用\u003c/strong>，实现以学习者为中心。\u003c/p>\u003cp>\u003cstrong>组织学习的拆书法：\u003c/strong>是拆书家拿一本书加工成一场现场学习，引导和促进一群学习者把知识拆为己用。\u003c/p>\u003cp>【拆书帮】是拆书法学习爱好者的社群，现在全国各地有多个拆书帮分舵，也叫\u003cu>拆书帮俱乐部\u003c/u>。\u003c/p>\u003cp>拆书帮分舵是\u003cstrong>\u003cu>非营利性组织\u003c/u>\u003c/strong>，其使命是帮助更多学习爱好者成长为\u003cu>拆书家\u003c/u>。\u003c/p>","ratings_count":1,"texts":[{"id":24041,"quote":"\u003cp>请大家花2分钟时间看一下我发给大家的拆页，拆页片段来自图书《卓有成效的管理者》55周年新译本，作者：彼得﹒德鲁克 P：第51-52页。\u003c/p>\u003cp>德鲁克先生说：要想成为有效的管理者，必须学会五种惯常做法，或者在思想上养成五种习惯。其中一个习惯就是要认识你的时间，本拆页就是选自这一部分。\u003c/p>\u003cp>如何诊断自己的时间\u003c/p>\u003cp>要了解自己的时间花在哪里，进而据此管理时间，我们必须先记录时间，这个道理人们在半个多世纪以前就已明白。那是1900年前后推行科学管理的时候，人们会对某个具体动作耗费的时间加以记录——针对体力劳动，既包括高技能要求的劳动，也包括简单的劳动。时至今日，几乎没有哪个国家落后到不对体力劳动者的动作做系统的时间记录。\u003c/p>\u003cp>我们已经把这个方法用在时间不是特别重要的工作上，也就是用在时间利用得好坏只关乎效率和成本的地方。但是，我们还没有把它用于一种越来越重要，而且势必涉及时间的工作：知识工作者的工作，特别是管理者的工作。在这里，时间利用与时间浪费之间的差别在于有效性和成果。\u003c/p>\u003cp>因此，管理者取得有效性的第一步是记录时间的真实使用情况。\u003c/p>\u003cp>许多有效管理者会持续记录，每个月定期回顾，最少也是连续记录三四周，每年定期做两次。每次记完，他们都会重新思考和安排自己的日程表。然而，6个月之后，他们无一例外都会发现&quot;漂移&quot;，也就是在一些琐事上面浪费时间。虽然只要这样去做就能改善对时间的利用，但只有持续努力才能避免这种&quot;漂移&quot;发生。\u003c/p>\u003cp>接下来就是系统地管理时间。管理者要把那些没有成效和浪费时间的活动找出来，尽最大努力把他们砍掉。为此要回答几个诊断问题。\u003c/p>\u003cp>1.首先是找出并砍掉那些根本不需要做的事，也就是那些不会产生任何结果，纯属浪费时间的事情。\u003c/p>\u003cp>2.接下来要回答的问题是：“我时间记录表上的哪些活动，是别人同样可以做好，甚至做得更好的？”\u003c/p>\u003cp>3.还有一种浪费，是管理者造成他人的时间浪费。这是管理者自己基本可以控制，从而可予消除的时间浪费。\u003c/p>\u003cp>看完的小伙伴可以举手示意一下，谢谢。\u003c/p>","explains":"\u003cp>好，我看到大家都已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>【WHAT】：这个拆页告诉我们一种诊断自己时间花在哪里的方法。\u003c/p>\u003cp>【WHY】：我们每个人每天的时间都是有限的。在日常工作中，如果我们使用拆页中的方法来记录并系统的管理我们的时间，可以让我们把主要的时间花在重要的事情上，从而让我们的工作变得更有效；如果不用这个方法来梳理我们时间的去处，就可能会陷入日常的琐事之中，忙碌而不知所以。\u003c/p>\u003cp>【HOW】：我总结诊断自己的时间这个方法分成两步：\u003c/p>\u003cp>1、记录时间。\u003c/p>\u003cp>真实记录我们每天时间具体花在什么地方；\u003c/p>\u003cp>2、管理时间\u003c/p>\u003cp>找出和砍掉那些没有成效，没有产出浪费时间的事情，集中精力去做那些重要的事情。\u003c/p>\u003cp>【WHERE】：\u003c/p>\u003cp>这种方法非常适用于知识工作者，如专业人士、管理人员、研究人员等，时间管理尤其重要，这可以让他们的工作更有效。对于那些工作性质较为灵活、变化快或者需要高度创造性的工作，可能需要更加灵活和适应性强的时间管理策略。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>看完拆页的内容，我联想到发生在我身上的一个经历（故事）：\u003c/p>\u003cp> 我是我们公司一个部门的经理，我每天都在忙着应对那些我认为很重要的事情，开各种各样的会，写各种各样的材料。不知不觉一个星期就过完了，感觉每天都很忙，但是一周总结的时候又感觉没做个什么有意义的事情。\u003c/p>\u003cp>\u003cem>【反思】\u003c/em>\u003c/p>\u003cp>今天通过学习这个拆页，如果系统性记录每天时间花到哪去了，找出和砍掉那些浪费时间的事情或者别人也能做得很好的事情，集中精力做对部门、对自己都很重要的事情，那么可能会让我每天的工作变得更高效。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>在接下来的一个月，我将选用一个时间管理应用程序连续3周每天记录我的活动，找出那些可以砍掉或者别人也能做得很好的事情，争取在目前的基础上每日能多出2小时，做那些重要的事情，从而让自己的工作变得更有效。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>最后，我再总结一下诊断自己时间的两个步骤：记录时间、管理时间。\u003c/p>\u003cp>希望大家可以将今天学的诊断时间方法，用到自己日常的工作中，从而让我们的工作变得更高效。\u003c/p>\u003cp>好了，我的拆解结束了，感谢大家的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1768225279000,"updated_at":1768533597000,"ria":true},{"id":19438,"topic":"如何诊断自己的时间：提高管理者的有效性。","learn_goal":"","remark":"进行时间的系统管理，提高管理者的有效性。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"张伊莲","city":"南阳市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>各位伙伴，大家好！我是张伊莲。我是一名专注于终身学习的实践者和分享者。在我的工作和学习中，我始终在探索如何通过科学的方法，将我们的时间和精力发挥出最大价值。接下来我们将要探讨的，如何系统性地诊断并管理我们的时间。\u003c/p>\u003cp>这是一套非常务实的方法论：它首先要求我们像记账一样，真实地记录时间，打破忙碌的错觉。进而，通过三个关键步骤——“删除”不必要的任务、“授权”他人能胜任的工作，并“反省”我们是否在无意中浪费了团队的时间——来为我们自己和他人都释放出宝贵的效能空间。\u003c/p>","ratings_count":1,"texts":[{"id":23810,"quote":"\u003cp>接下来两分钟的时间，请大家阅读拆页内容，读完拆页的小伙伴可以举手示意我\u003c/p>\u003cp>R原文片段：\u003c/p>\u003cp>\u003cstrong>如何诊断自己的时间：\u003c/strong>\u003c/p>\u003cp> \u003cstrong> 要提高管理者的有效性，第一步就是记录其时间耗用的实际情形\u003c/strong>。\u003c/p>\u003cp> 许多有效的管理者都经常保持这样的一份时间记录，每月定期拿出来检讨。至少，有效的管理者往往以连续三四个星期为一个时段，每天记录，一年内记录两三个时段。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间耗用得很乱，浪费在种种无谓的小事上。经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免再回到浪费的状态上去。\u003c/p>\u003cp> \u003cstrong>第二个步骤就是要做到有系统的时间管理。\u003c/strong>我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以试问自己下列几个问题。\u003c/p>\u003cp> \u003cstrong>1、 首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。\u003c/strong>将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp> \u003cstrong>2、 第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果？”\u003c/strong>\u003c/p>\u003cp> 多年来在管理方面都在研究授权问题。任何一个组织——企业、政府、学校和军事机关，几乎每一位主管人员都接到过上级有关做好授权的指示，而且他们本人也曾屡屡对其下属阐明授权的重要。但是这样的谆谆告诫是否产生效果，实在令人怀疑。原因非常简单：只是因为没有完全明了授权的意义。如果认为所谓授权，意思是说：“我的”工作应该由别人来做，那就错了；因为你既拿了薪水，就该做你自己的工作。又有人认为：充分授权之后，最闲散的经理人便应该是最好的经理人。这样的看法不但荒唐，而且也是不道德的。\u003c/p>\u003cp> \u003cstrong>3、 还有一项时间浪费的因素，是管理者自己可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/strong>\u003c/p>\u003cp> 这种现象并不明显，但有一个简单方法可以诊断出来：去问问你的下属。有效的管理者懂得有系统及诚恳地问他的下属：“请你想想看，我常做哪些浪费你的时间而又不产生效果的事情？”问这样的问题，而且问得对方敢说真心话，才是有效管理者的特色。\u003c/p>\u003cp>即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。\u003c/p>","explains":"\u003cp>各位在座的管理者、项目负责人、以及每一位感觉“忙了一天却好像什么都没做成”的朋友，我们今天谈论的“时间管理”，其核心目的不是为了让你变得更忙，而是为了让你从无效的忙碌中解脱出来，把宝贵的精力聚焦在真正能产生成果和价值的事情上。\u003c/p>\u003cp>我们常常像陷入一个怪圈：会议一个接一个，消息不停地响，待办清单越写越长。一天结束，身心俱疲，却说不出口今天到底做成了哪件重要的事。这种“时间不知去向”的失控感，就是我们今天要解决的核心痛点。\u003c/p>\u003cp>（第一步：细化记录，夯实基础）\u003c/p>\u003cp>那么，如何破局？第一步，也是最重要的一步，就是面对真相——如实记录。这不仅仅是记个流水账，而是需要一点结构：\u003c/p>\u003cp>记录“事件”：在今天工作结束时，不是靠回忆，而是依据邮件、聊天记录等，按时间顺序列出你当天完成的所有事情。比如：“部门周会9：30-10：30 ”、“回复客户A的咨询邮件10：30-11：00 ”、“撰写季度报告第一部分11：00-12：00 ”。\u003c/p>\u003cp>记录“耗时”：在每一件事情后面，客观地标注出你所花费的时间。这一步至关重要，它能让许多“我以为只花了一小会儿”的事情现出原形。\u003c/p>\u003cp>只有将“事件”与“耗时”结合起来，你才能得到一份真正有诊断价值的“时间体检报告”。\u003c/p>\u003cp>（第二步：系统管理，精准施策）\u003c/p>\u003cp>有了这份真实的“时间体检报告”，第二步我们就可以对症下药，进行系统管理。请拿出你的记录，像医生审阅病历一样，逐项审视，并问自己三个灵魂问题：\u003c/p>\u003cp>第一问：删除—— “比如11：00-12：00撰写季度报告第一部分这件事如果不做，会有什么后果？”如果答案是“毫无影响”，那么请立刻、坚决地取消它。这是最高效的时间节省方式。\u003c/p>\u003cp>第二问：授权—— “比如10：30-11：00 回复客户A的咨询邮件这件事，是否可以由团队中其他能胜任的成员来完成？”记住，授权不是推卸责任，而是赋能和成长。把你从别人也能做的事中解放出来，你才能去做那些非你不可的战略性工作。\u003c/p>\u003cp>第三问：尊重—— “比如9：30-10：30部门周会，是否在无意中浪费了团队成员的时间？主动、诚恳地向你的下属寻求反馈，是消除这种浪费的唯一途径。\u003c/p>\u003cp>（阐明适用边界与挑战）\u003c/p>\u003cp>当然，这个卓越的战略性自我管理框架，其有效应用也存在一些前提和边界。\u003c/p>\u003cp>它主要适用于谁？ 最适合工作自主性较高的管理者与知识工作者。因为我们的时间安排相对灵活，更需要自我规划，这套方法能帮助我们找回主动权。\u003c/p>\u003cp>它可能面临什么挑战？\u003c/p>\u003cp>文化挑战： 在缺乏信任或等级森严的团队中，“授权”可能被误解为甩锅，“询问下属”可能得不到真实的反馈。这提醒我们，工具的使用离不开健康的团队土壤。\u003c/p>\u003cp>工作性质挑战： 对于高度依赖创意和灵感的“心流”工作，例如编程、写作、设计，过于结构化的实时记录本身可能就是一种干扰。对于这类工作，我们或许可以采取事后粗略复盘的方式，而非事无巨细地记录。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>现在我们进入——激活经验环节。\u003c/p>\u003cp>我们刚刚学习到的这个时间管理方法，核心就是两步：先记录，后管理。而管理的利器，就是那三个问题：“能否取消？”、“能否授权？”、“是否浪费了他人时间？”。\u003c/p>\u003cp>接下来，请大家分成两个小组，左手边三位伙伴为第一组，右手边的三位伙伴为第二组。在小组内，轮流分享一个你自己的相关经验。\u003c/p>\u003cp>【小组讨论指令】\u003c/p>\u003cp>接下来，我们有 3分钟 的小组讨论时间。\u003c/p>\u003cp>请大家在组内轮流分享：\u003c/p>\u003cp>“你曾经的一个与‘时间管理’相关的成功或失败的小故事。”\u003c/p>\u003cp>分享时，请尽量讲成一个鲜活的小故事，比如：\u003c/p>\u003cp>“当时是什么情况？”（背景）\u003c/p>\u003cp>“你做了什么或没做什么？”（行动）\u003c/p>\u003cp>“结果怎么样？”（结果）\u003c/p>\u003cp>“用今天所学的方法会怎么去做”（反思）\u003c/p>\u003cp>3分钟时间，现在开始！\u003c/p>\u003cp>（拆书家计时，并在场中巡视，2分30秒时给予提醒）\u003c/p>\u003cp>“大家注意，还有最后30秒，请准备一位代表稍后分享。”\u003c/p>\u003cp>（3分钟时间到）\u003c/p>\u003cp>“好，时间到！感谢各位的热烈讨论。”\u003c/p>\u003cp>【邀请代表分享】\u003c/p>\u003cp>现在，我们邀请一位代表，用 1分钟的时间，向全体伙伴分享你们组里最触动你的一个故事。\u003c/p>\u003cp>好，有请！\u003c/p>\u003cp>（代表分享后，拆书家回应）\u003c/p>\u003cp>感谢语1：\u003c/p>\u003cp>“非常感谢代表的分享！你刚才提到的（简要复述其故事核心，如：‘…在项目忙乱时，主动去记录和分析时间…’），正是我们原文中‘系统管理’的第一步，这个（成功/失败的）经验让我们非常直观地看到了‘记录’的力量。再次感谢！”\u003c/p>\u003cp>（邀请下一组，如时间允许）\u003c/p>\u003cp>“非常感谢！接下来，有请第二组的代表！”\u003c/p>\u003cp>（所有代表分享完毕后）\u003c/p>\u003cp>总结感谢语：\u003c/p>\u003cp>“非常感谢所有小组的分享和各位代表的精彩讲述！从鲜活的故事里，我们能真切地感受到，今天学习的这个方法并不是遥远的理论，而是可以立刻运用到我们工作和生活中去的实用工具。感谢大家的真诚投入，让我们看到了各位宝贵的经验！”\u003c/p>\u003cp>A2：\u003c/p>\u003cp>（A1环节结束后，立即切换，语气明快、有推动力）\u003c/p>\u003cp>好，现在进入——规划你的行动环节。\u003c/p>\u003cp>请大家拿出便签，为自己制定一个未来一周的具体应用计划。\u003c/p>\u003cp>【核心指令】\u003c/p>\u003cp>请应用我们刚学的“如实记录”：时间和耗时 和“时间管理三步法”：记录、删除、授权。\u003c/p>\u003cp>为你下一周的工作制定一个计划：你预测会记录什么，大概需要多长时间？计划删除或授权哪类事项？一周后，你期望看到哪些可衡量的改变（比如：每天节省出1小时，或无效会议减少50%）？ \u003c/p>\u003cp>【时间控制】\u003c/p>\u003cp>大家只有 2分钟 来书写。现在开始！\u003c/p>\u003cp>（1分30秒时提醒）\u003c/p>\u003cp>还有30秒。\u003c/p>\u003cp>（2分钟到）\u003c/p>\u003cp>时间到！\u003c/p>\u003cp>今天我们所有的学习环节到此结束，感谢各位！”\u003c/p>\u003cp>我的A2：下周一我开始记录时间，大概需要30分钟，计划删除娱乐APP一个，授权接送孩子的节约一部分时间，预计每天节约2个小时的时间，用于书写二级拆书家的拆书稿。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1763441053000,"updated_at":1764542836000,"ria":true},{"id":19330,"topic":"善用上司长处 管理卓有成效","learn_goal":"","remark":"德鲁克告诉我们管理的本质是激发人的长处，包括你的上司。从盲目努力到让的上司成为你的业绩燃料，从被动领受任务到主动寻求上司的价值输出，从抱怨短板到向上司借力达成目标，本培训分享可能完全颠覆你的认知。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"杏芙姐","city":""},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>各位爱拆书的小伙伴们，大家晚上好，感谢大家的参与！为了方便后面的讨论和分享，根据今天的到场人数，我们把学习者分为两个组。\u003c/p>\u003cp>今天分享的是《卓有成效的管理者》。先借助FAB法介绍一下。\u003c/p>\u003cp>F特征：本书的作者是现代管理学之父彼得﹒德鲁克，是大师中的大师。他一生写了39本著作，很多被翻译成多国语言，我手上这本是他最具影响力的代表作，畅销近60年的管理经典著作。\u003c/p>\u003cp>A特征：本书不是教科书式的理论说教，它通俗易懂，兼具了理论的深度和实践的指导性，是管理者的案头必备和精选。本书思想对很多商业领袖，如通用电气的杰克韦尔奇、微软的比尔盖茨等，都产生了深远的影响。\u003c/p>\u003cp>B特征：本书将帮助管理者学会掌握自己的时间、发挥人的长处、贡献价值、聚焦要事和有效决策，从而实现卓有成效的管理。而拆页片段将告诉你发挥上司长处的心法和技法。如果你工作敬业、努力，总是凭一己之力去“搞定”工作，但个人发展和业绩总又不尽人意，相信能从今天的拆解中得到启发，懂得向上借力，提升个人和团队绩效。\u003c/p>\u003cp>（按照《成长手册》P36要求，介绍图书）\u003c/p>","ratings_count":1,"texts":[{"id":23688,"quote":"\u003cp>【主题】：善用上司长处，管理卓有成效 \u003c/p>\u003cp>【片段来源】：《卓有成效的管理者》P69-70\u003c/p>\u003cp>【R】环节：拆页，大家手中已经有了，请大家花1分钟时间阅读一下。\u003c/p>\u003cp> 原书拆页：\u003c/p>\u003cp>运用上司的长处，也是下属工作卓有成效的关键。只有如此，身为下属者才能将精力集中在自身的贡献上，完成自己想做的工作，取得希望取得的成就。\u003c/p>\u003cp>要使上司能够发挥其所长，不能靠唯命是从，应该从正确的事情着手，并以上司能够接受的方式向其提出建议。\u003c/p>\u003cp>有效的管理者了解他的上司也是人。上司既然是人，所以肯定有其长处，也肯定有其短处。若能在上司的长处上下功夫，协助他做好想做的工作，便能使上司有效，下属也才能有效。反之，如果下属总强调上司的短处，那就像上司强调下属的短处一样，结果将一无所成。所以，有效的管理者常问：“我们上司究竟能做些什么？他曾经有过什么成就？要使他发挥他的长处，他还需要知道些什么？他需要我完成什么？”至于上司不能做些什么，就不必细究了。\u003c/p>","explains":"\u003cp>【I】环节（讲解引导）：（按照《拆书家成长手册》P37页要求）\u003c/p>\u003cp> 【学习目标】：通过本次拆书，学习者在以后的工作中，不是自顾自的埋头苦干，而是能应用今天介绍的四个建议，加工出行动方案，充分运用和发挥上司的长处，取得希望取得的成就。（按《成长手册》P35要求，设定学习目标）\u003c/p>\u003cp> WHAT（知识点）：拆页阐述了有效的管理者要设法发挥上司的长处。\u003c/p>\u003cp>WHY（前因后果说明）：现实中，我们大多数的人如果领受了一项任务，或需要完成一项工作，我们通常是会尽自己的本分，在职权职责范围内设法去完成，即使遇到困难，要么不敢找领导支持帮助，担心给领导造成无能的影响，或者不好意思找领导支持，担心打扰领导，被嫌麻烦。（按照《成长手册》P38页要求，了解人们的通常做法）\u003c/p>\u003cp>这样做，于你个人，你失去了一次与上司沟通合作的机会，可能完成任务的质量不高，或者进度缓慢，进而影响你的绩效和上司对你的评价；于上司，不利于资源的有效利用；于公司，不利于组织整体效能的发挥，损害集体利益。\u003c/p>\u003cp>（按照《成长手册》P38页要求，分析常见做法的坏处和后果）\u003c/p>\u003cp>比如，我部门几年前为公司一位资深的生产技术骨干申报“常德工匠”称号，这对公司对个人都是一项荣誉。当时我们没有去找领导，也没和评审部门联系，就对照通知要求，按自己的理解，加班加点准备材料。后来反馈说材料不符合要求，结果错失了这次机会。（按照《成长手册》P38要求，列举一个反例）\u003c/p>\u003cp>而今天介绍的新方法，将有助于建立团队信任，达成团队共识和目标，提高资源效用，提升个人绩效和团队的协同效率等。\u003c/p>\u003cp>How（行动建议和行动步骤）：（按照《成长手册》P38页要求，拆页需包含的HOW的内容）\u003c/p>\u003cp>片段在最后，针对如何发挥上司长处，作者说有效的管理者要常问：“我们上司究竟能做些什么？他曾经有过什么成就？要使他发挥他的长处，他还需要知道些什么？他需要我完成什么？”这既是方法论，又是行动建议：\u003c/p>\u003cp>1、了解上司的长处：通过观察了解上司擅长的领域，拥有的核心资源。 \u003c/p>\u003cp>2、了解上司曾经有过的成就：通过了解他过往的成功案例，分析是否可以用来复制经验。\u003c/p>\u003cp>3、为使上司发挥他的长处，向他提供需要的信息。\u003c/p>\u003cp>4、为使上司发挥他的长处，配合他完成相关的工作：明确分工和职责，除了上司长处这一核心资源外，其他人财物的协调，以及落地执行都需要你配合完成。\u003c/p>\u003cp>学习了拆页后，针对原来申报失败的反例，我们在后来另一位核心生产技术人员申报“常德工匠”时，我们就应用了拆页的建议。\u003c/p>\u003cp>1、了解上司长处：我们了解到上司的长处有人脉广，经过询问，他在“常德工匠”申报评审的对接部门可以找到对应的人员；\u003c/p>\u003cp>2、了解上司成就：上司正是借助这一人脉资源，帮公司成功申报了湖南省和全国和谐劳动关系模范企业的荣誉；\u003c/p>\u003cp>3、提供相关信息：我们向上司汇报了“常德工匠”申报的具体要求，以及上次申报时经验不足，组织材料存在缺失等情况，请示他能否借助人脉资源，对接评审专家，为申报材料把把关；\u003c/p>\u003cp>4、协助配合相关工作：我们为上司编辑了请求该人脉资源给予帮助支持的信息，请上司修订后转发；关系对接上以后，我们几次听取专家的意见，针对他的指导意见，优化了材料，获得了申报成功。（同上，把反例变成正例）\u003c/p>\u003cp>WHERE（适用边界）：发挥上司的长处，本书是针对知识工作者、经理和专业人员；如作扩展，适用于所有组织中有上级且负有一定职责的人员，在可以寻求组织资源支持的工作场合中适用，但常规、流程性、无需创新和主观能动性发挥的工作一般不适用。\u003c/p>","interaction":"\u003cp>【A1】环节（激活学习者经验）：\u003c/p>\u003cp>一个显像提问：（按照《成长手册》P39要求，一个显像提问）\u003c/p>\u003cp>各位，过去你有没有因为忽略了上司的长处，造成工作被动？当时发生了什么？比如，你的上司是一个很会共情的领导，你的团队最近增加了临时任务，压力有点大，有两位伙伴因为工作分工发生争执，你作为经理没有做干预和调和，也没有运用上司的长处，做疏导工作，造成沟通不畅，工作衔接不好，降低了工作效率，团队氛围也受到影响。 或者过去因某项工作利用、发挥了上司的长处，而使团队受益的例子？具体是什么？比如，上次一项某高校校园招聘工作，你了解你的领导是这所高校毕业的，经领导协调，运用他的校友资源助力，现场招聘会开的很成功，校招效果超出预期，为公司储备了新生力量。\u003c/p>\u003cp> 请大家在小组内进行分享，每人1分钟。请一位小伙伴分享一下过去的经历或经验。大家的讨论非常热烈，下面有请喻娟伙伴给出她的分享：\u003c/p>\u003cp> 喻娟：我在市图书馆工作，之前我部门有做过一个文献资源展，当时我们整个部门只知道自己埋头苦干，没有和领导沟通反映，做了以后只是通过微信转发的形式进行传播宣传，影响力不怎么大，参与的人不多，在这个过程当中我们没有去借助好领导的优势，导致文献展的效果和影响力不怎么好。\u003c/p>\u003cp> 喻娟伙伴分享了一个过往经历的一个反面例子，谢谢她将自己的真实发生分享出来。\u003c/p>\u003cp>【A1+】环节（学习者反思加工经验）：（按照《成长手册》P39-40要求）\u003c/p>\u003cp>下面环节，请大家想一想自己过往相关的工作经历，如果今天回到当时的情境，你再运用今天拆页所建议的管理方法，你可以怎么去做去加以改进。请大家组内每个人都分享一下，然后我们请一位伙伴来分享。还是有请喻娟伙伴接着分享她在过去案例基础上如何应用：\u003c/p>\u003cp> 喻娟：按照刚学的善用领导资源，我们了解我们馆的领导不仅有自己馆内资源，和别的馆也熟悉，资源也能利用。不仅如此，他还有媒体资源。我们领导不久前主导了一个简牍展，得到了上级领导的好评；要发挥领导的长处，我们要让他了解相关信息，知道文献资源展的主题是什么，受众是怎样的？以及目前我们拥有哪些 文献资料；为了完成好这个项目，我们要进行明确的分工，文献组做好资源整合，阅读推广组做好活动策划，工作计划发给领导，让他了解。\u003c/p>\u003cp> 谢谢伙伴的分享，讲述很好很全面 。 \u003c/p>\u003cp>各位伙伴，今天的学习，我们了解了善用上司资源的好处和坏处，学习了了解上司的长处和他曾经的成就，以及充分发挥上司的资源效用需为他提供相关的信息，并协助完成相关的工作等方法，相信通过现场学习，并把新知运用起来，能大大提升我们工作绩效、助力上司获得更大的成就感，实现我们卓有成效的管理。再次感谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1758615187000,"updated_at":1758704231000,"ria":true},{"id":19328,"topic":"掌控时间“三步走”","learn_goal":"","remark":"有效的管理者着手工作时常常从时间安排上入手，管理者常不善于管理自己的时间，不知道时间是如何溜走的，时间掌控三步走，告诉我们如何记录时间、管理时间，消除时间黑洞，集中时间在要事上，为组织绩效创造更大的价值","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"杏芙姐","city":""},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>各位爱拆书的小伙伴们，大家晚上好！感谢大家的参与！\u003c/p>\u003cp>我是杏芙姐，三个标签介绍一下自己。我是德鲁克卓有成效管理的践行者。我从一名国企下岗人员到一个中外合资药企的中高管，20多年是遵循德鲁克的教导不断前行；我是你身边爱分享的知心姐姐，私下里伙伴们有意愿，非常乐意分享些管理经验，给到大家一些赋能。第三个标签是新手拆书家，希望经过升级打怪，成为一名三级拆书家！\u003c/p>\u003cp>今天分享的片段来自《卓有成效的管理者》，现代管理之父彼得•德鲁克的经典之作，它首次出版至今59年，但经久不衰，是管理者的案头必备、可以反复研读的书。作者不是居高临下的说教，而是用具象化的通俗语言，告诉我们管理者唯一的贡献就是卓有成效，而且卓有成效是可以学得会的。\u003c/p>\u003cp> 今天学习后面有讨论环节，为了提高效率，我们分为2组，左边为一组，右边为一组。\u003c/p>","ratings_count":2,"texts":[{"id":23686,"quote":"\u003cp>\u003cstrong>主题\u003c/strong>：掌控时间“三步走”\u003c/p>\u003cp>\u003cstrong>片段来源\u003c/strong>：《卓有成效的管理者》P19-20片段\u003c/p>\u003cp>\u003cstrong> 〔R〕环节\u003c/strong>：请在座各位阅读一下你手上拿到的原书拆页，给到1分钟时间。读完的伙伴请用眼神或点头示意我一下。\u003c/p>\u003cp> 原文拆页：\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手，他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础。\u003c/p>\u003cp>•记录时间；       •管理时间；         •统一安排时间。\u003c/p>","explains":"\u003cp>\u003cstrong>〔I〕环节：\u003c/strong>\u003c/p>\u003cp>一、What：拆页讲述了有效的管理者在搬砖前会从时间安排上着手，他们清楚自己的时间用在了哪里，会管理自己的时间，减少非生产性时间的浪费，并且善于把零碎时间整合成连续大块，投入到重要的事上，也就是掌控时间的三步：记录时间、管理时间和统一安排时间，这是管理有效性的基础。\u003c/p>\u003cp>二、Why：时间是有限的不可再生的资源，时间没有弹性，没有替代品。现在有句话，凡是能用钱解决的问题都不是问题，而时间是用钱买不到的。所以说它是最稀缺的资源，干任何事情都少不了；而且最要命的是管理者都不善于管理时间，还说不清自己时间都去哪里了，正如十年前在春晚上唱红的那首歌的歌名“时间都去哪儿了”。而管理者如果能掌控时间，消除低效内耗，集中时间在要事上，就能为组织绩效贡献更大的价值（好处）。否则，整日繁忙，结果却是碌碌无为、质效低下（坏处）。\u003c/p>\u003cp>三、How：\u003c/p>\u003cp>1、记录时间。我们可以用电子表格，以一天、一周、一个月，连续三个月为时段，每项事情做完后及时记录。一个时段结束后，再根据记录自行检讨。当然，为了便于检讨，我们可以将任务或事情进行分类。\u003c/p>\u003cp>2、有了时间记录后，如何展开检讨和时间管理呢？拆页告诉了我们：\u003c/p>\u003cp>（1）先将非生产性的和浪费时间的活动找出来，尽可能在时间表上排除掉。怎么排除，用反向思维法，这件事如果不做，会有什么后果？如果是“没有任何影响”，那就排除，比如书中说的那位天天有应酬的总经理，在经过记录和检讨后，发现至少有1/3的宴请根本没必要参加。\u003c/p>\u003cp>（2）再检讨哪些活动是可以由别人代替而又不影响的？比如我们部门月度例会，会前有议题，会后有会议纪要和追踪表，授权部门经理组织召开就OK了，无需自己每次到场，每次1个小时时间很浪费。\u003c/p>\u003cp>（3）浪费别人的时间也要排除。我们可以问问下属，我是否有安排哪些浪费你时间而完全没必要的事情？回答如果是肯定的，且双方协商达成一致了，就果断决然的在以后的排期上删除掉。\u003c/p>\u003cp>3、统一安排时间。经过前面记录和检讨，以及调整后，我们是不是会多出来些可自由支配的时间。那如何“化零为整”，把碎片化的时间整合起来？我们可以根据工作性质和习惯，把重要的、需要大块时间去思考、沟通、完成的时间预留出来，其他的时间用来处理流程上的例行事项和一些杂事。\u003c/p>\u003cp>四、Where（适用边界）：\u003c/p>\u003cp>所有的管理者，包括知识工作者、经理和专业人员、希望成为有效管理者，或者提升个人效能的人，这三步都适。用特别是身为管理者，如果你感到迷茫、困惑，整日疲于奔命又缺价值感，那更是适合。同时，适用时间，无论是一天、一周、一个月、一年都是可以的。\u003c/p>\u003cp>\u003cstrong>我的实例：\u003c/strong>\u003c/p>\u003cp> 这是我去年设计和使用的一个时间记录表。可以看一下，使用时段是2024年7月1日-7月31日，一个月周期。每天记录，日清月结，月末检讨。我把工作做了分类，如制度类、上市相关、外联、内协、会议、参训、自我学习、上级沟通、下属沟通、闲谈、休息及其他。月末，对照浪费时间的事、授权别人也能做好的事、浪费别人时间的事三点检讨、消除，持续不断的优化，使自己时间更聚焦要事，聚焦贡献和问题解决。\u003c/p>","interaction":"\u003cp>\u003cstrong>〔A1〕环节：\u003c/strong>\u003c/p>\u003cp>下面的A1环节，请大家以小组的形式开展讨论。\u003c/p>\u003cp>各位读过拆页，听了讲解后，想想自己过往有没有经历类似情境？时间是如何安排？时间管理做得怎样？是如何做的？下面开始组内分享，每人1分钟，这个环节总共4分钟。小组分享完了请用眼神或点头示意我一下，谢谢。\u003c/p>\u003cp>时间差不多了，大家交流的氛围很热烈，很投入，做了充分的分享。下面有请一位小伙伴上台分享。\u003c/p>\u003cp> 莞尔老师分享：在时间管理上，以往每到周末，自己的想法是准备看看书，找一下合适的拆页，为写拆书稿做准备。但想归想，很多时间去看视频，刷起手机，一下过去两三个小时，这就是没有时间管理的意识，没有去把握和充分利用好时间。\u003c/p>\u003cp> 感谢莞尔的积极分享，她非常真实的分享了过往的做法。谢谢！\u003c/p>\u003cp>\u003cstrong>〔A2〕环节：\u003c/strong>\u003c/p>\u003cp>通过观察刚刚大家的分享，看来大家在时间管理上，或多或少都存在优化空间。现在请大家花1分钟时间在便签纸上写出自己未来一周，或者一个月把控时间的应用规划或行动步骤，请注意一下在这里不需要表决心，但要有具体的做法、时限和预期结果，结果是要可衡量、能观测到的。好了，现在开始吧！虽然我们还意犹未尽，但时间关系，今天的分享要接近尾声了。\u003c/p>\u003cp>莞尔老师：学习了时间管理掌控“三步”，我准备规划一下周末时间。\u003c/p>\u003cp> 记录：先记录这周末的时间活动，晚上睡觉前对一天的活动用手机APP记录；\u003c/p>\u003cp> 检讨：周日晚上对两天的活动进行检讨，哪项是不需要做的？哪些浪费自己也浪费别人时间的？哪些是可以让别人去做的？筛选出来后删除；\u003c/p>\u003cp> 统一安排时间：下周末腾出大块的时间后，再重新安排自己做两项自己一直想干的事，比如看望家里长辈、看两个小时书。\u003c/p>\u003cp> 感谢莞尔应用今天所学，对自己未来周末的时间进行了一个新的规划和管理，非常棒。以后也希望得到大家更多的实践反馈。\u003c/p>\u003cp> 各位，我们平常说时间花在哪里，花儿就开在哪里。我们只有掌控了时间，才能实现有效的管理，掌控自己的人生。祝愿我们让花儿开遍拆书帮，都成为时间的主人！\u003c/p>\u003cp>再次感谢观察家、感谢主持人、感谢小伙伴们的聆听和支持！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1758610075000,"updated_at":1758787876000,"ria":true},{"id":18456,"topic":"在职场时间管理主要在于少做事、集中做重要事","learn_goal":"","remark":"强调通过这三个问题帮助找到浪费时间活动以提高效率，并让大家针对分享者演讲提出自己的评价","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"郭世真无锡","city":"无锡市"},"club":{"name":"无锡太湖分舵","city":"无锡"},"prologue":"\u003cp>大家好，我叫郭世真，主业是一名医生，业余时间喜欢读书，尤其喜欢阅读经济、历史、科学方面的书，目前是拆书帮的一级拆书家，我非常认可人要持续学习这件事，希望通过拆书找到趣味相投的朋友。\u003c/p>","ratings_count":1,"texts":[{"id":22744,"quote":"\u003cp>\u003cstrong>阅读拆页《卓有成效的管理者》\u003c/strong> \u003cstrong>P53-59 作者：彼得.德鲁克\u003c/strong>\u003c/p>\u003cp>管理者实现卓有成效的第一步是记录实际的时间使用情况。记录时间使用情况之后的下一步是进行系统性的时间管理。我们必须找到无益的、浪费时间的活动，并尽可能清除掉。这样的诊断要求问自己一些问题。\u003c/p>\u003cp>1. 首先，管理者要努力找出并消除那些根本不需要做的事，有些事纯粹是浪费时间、没有产生任何成果的事。为了找出这些事，管理者要就时间记录中的所有活动进行提问：“\u003cstrong>如果根本不做这件事会如何？\u003c/strong>”如果答案是“没什么影响”，那显然应该停止做这件事。\u003c/p>\u003cp>2. 下一个问题是：\u003cstrong>“我做的所有事情中，哪些如果让别人来做可以做得更好，或者至少是同样好？\u003c/strong>”管理者正在做的大量工作可以由其他人轻松完成，因此应该由其他人来做。习惯上使用的“授权”一词是一种误解，而且可以说是误导。不过，管理者确实需要摆脱可以由他人完成的事情，从而可以真正从事自己该干的工作而不必委派他人——这样做是在卓有成效上的重大改进。\u003c/p>\u003cp>3.造成时间浪费的一个常见原因，是管理者浪费了别人的时间。这在很大程度上受管理者控制，并且可以由他来消除。这个问题没有单一症状，但仍可以通过一个简单的方法来发现。那就是去问别人。卓有成效的管理者已经学会了系统地、大胆地提问：“\u003cstrong>我做的哪些事是在浪费你的时间，对你毫无贡献？\u003c/strong>”提出这个问题，并且不惧怕真相，是卓有成效的管理者的标志之一。\u003c/p>\u003cp>事实上，一个管理者砍掉太多工作内容的风险不大。我们通常倾向于高估而不是低估自己的重要性，认为有太多的事情只能由自己来做。即使是非常有成效的管理者，也会做很多不必要的、无益的事情。\u003c/p>","explains":"\u003cp> What其实我们在时间管理上有一个很大的误区，就是我们会认为时间管理的目的是要我们做更多的事，日程表排的满满的。 \u003c/p>\u003cp> Why但其实在职场上时间管理的精髓是少做事，集中精力做重要的事，把这些事做成有代表性的案例，更能够增加职场竞争力。那么哪些事是应该少做的呢？\u003c/p>\u003cp>how这个拆页就教会我们how通过问自己三个问题来判断当下这件事应不应该做。第一个问题：“\u003cstrong>如果根本不做这件事会如何？\u003c/strong>当你这样问自己时也许会发现不用做的事多得令人吃惊。比如说很多仪式活动、吃饭宴请，这些事既花费时间，也对自身没有任何贡献，那么我们就要学会说“不”。第二个问题：\u003cstrong>“我做的所有事情中，哪些如果让别人来做可以做得更好，或者至少是同样好？\u003c/strong>”。如果你感到自己没有足够的时间去做自己认为重要的事情、自己想做的事情以及自己承诺要做的事情，那么唯一的办法就是把可以由别人完成的事情交给别人。我们应该授权或委托给员工或者其他专业人事来做这件事件，或者是现在的很多AI工具助理，也可以完成一些任务，并且做的更好，比如整理会议纪要，图片美化、表格制作。第三个问题是“\u003cstrong>我做的哪些事是在浪费你的时间，对你毫无贡献？\u003c/strong>”也就是我们常说的“一将无能累死三军”，有时候管理者出的一些政策会给员工执行带来很多不必要的麻烦，这时候也应该听一下一线员工的声音，从而改进工作。通过对这三个问题的思考来帮助我们必须找到无益的、浪费时间的活动，并尽可能清除掉。\u003c/p>\u003cp>Where这个时间诊断的方法适合我们在给日程复盘的时候使用\u003c/p>\u003cp>举反例：我曾经就不注意这样问题，不擅长把事情委托给别人，总喜欢一个人把事情做完，但医疗上的工作量很大，很多事又不得不做，这些事情做的太多导致我没有精力去学习更重要的手术技能，已经影响到我的职业发展。后来我发现我其实可以把身边的一些人力资源利用起来。比如医院有进修医生，也有实习医生，我开始把一些相对简单的医疗操作教会他们，然后很多这些重复的工作就交给他们去做，这样我就可以腾出时间来做重要的事了。\u003c/p>","interaction":"\u003cp>那么，现在请大家想象一个忙碌的一天的场景，比如我可能会这样度过一天：早上要参加晨会，给员工分配工作。然后上午就是一连串的会议：项目进度讨论、团队绩效回顾、跨部门协作沟通。下午有一些员工向我求助，他们有一些项目不清楚流程及具体做法，而这种项目近期已经做过3次了；晚上下班后我还要准备向上级汇报的材料。我感很忙碌，但又没有得到自己满意的成果，还有一些我认为很重要的事务，但我却没有时间开展。那么现在，你能否使用刚才学的方法问自己一个或者几个时间诊断的问题来改善自己的工作，从而省下时间做你想做的事。\u003c/p>\u003cp>好的，那么你们在工作或者生活中有没有遇到过类似的问题，你能否根据刚才拆页中的方法处理你遇到的那种问题？大家可以先组内讨论5分钟，每个人都尽量表达一下。最后我请各组出一名代表，给大家分享一下你们组的精彩案例。\u003c/p>\u003cp>谷博士分享乐周末送孩子上课的案例，通过委托给家人接送，从而节约时间来做一些更有意义的事情。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1734272226000,"updated_at":1734746399000,"ria":true},{"id":18415,"topic":"要事第一","learn_goal":"","remark":"学习如何设定优先事项和劣后事项的方法，用来解决在管理任务和决策时如何有效分配资源和注意力的问题","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"郭世真无锡","city":"无锡市"},"club":{"name":"无锡太湖分舵","city":"无锡"},"prologue":"\u003cp>介绍自己和书：大家好，我叫郭世真，主业是一名医生，业余时间喜欢读书，尤其喜欢阅读经济、历史、科学方面的书，目前是拆书帮的新手拆书家。\u003c/p>\u003cp>这次我拆页的书是《卓有成效的管理者》，是管理学大师彼得·德鲁克的经典著作。在这本书里，德鲁克讨论作为管理者，要如何自我管理，才能够做到卓有成效？他重新定义了“管理者”，提出管理者的首要任务就是管理好自己，也就是现在所说的“每个人都应该是自己的 CEO”。那么管理可以学会吗？好消息是管理并不复杂，他是一组为数不多的可学习的一组实践。今天我们一起来学习其中的一项：要事第一。\u003c/p>","ratings_count":1,"texts":[{"id":22710,"quote":"\u003cp>\u003cstrong>阅读拆页《卓有成效的管理者》\u003c/strong> \u003cstrong>P142-143 作者：彼得.德鲁克\u003c/strong>\u003c/p>\u003cp>把一项任务设定为劣后事项不是件愉快事，因为每一个劣后事项都是其他某人的优先事项。更容易的事情是拟订一个优先事项清单，但同时作为对冲，把清单之外的每件事情也做上“一丁点儿”。这样做让每个人都高兴，而唯一的缺点则是一事无成。\u003c/p>\u003cp>对优先事项的分析，可以说上很多内容。然而，就设定优先和劣后事项而言，最重要的不是智识上的分析，而是勇气。\u003c/p>\u003cp>下面是一些设定优先事项的真正重要的规则，其中起作用的主要不是分析，而是勇气：\u003c/p>\u003cp>●选择未来，而非过去\u003c/p>\u003cp>●聚焦于机会，而非问题\u003c/p>\u003cp>●选择自己的方向，而非随大流\u003c/p>\u003cp>●设定能够带来改变的、高远的目标，而非“安全”与容易的目标\u003c/p>\u003cp>许多研究发现，科学家的成就，至少在爱因斯坦（Einstein）、尼尔斯·玻尔（Niels Bohr）或马克斯·普朗克（Max Planck）这些天才之下的成就，与其说取决于他们的研究能力，不如说取决于他们追求机会的勇气。科学家如果选择那些更能快速成功而非挑战更大的研究项目的话，不太可能取得卓越的成就。他们可能会取得大量的鸡毛蒜皮的成果，但不太可能有新的物理学定律和概念以他们的名字命名。卓越成就将归于那些根据机会选择研究项目的科学家，对他们来说，其他标准会影响某个项目是否入围，但不会决定某个项目是否获选。\u003c/p>\u003cp>同样，在商业领域，成功的公司不是那些致力于在其已 有产品线中开发新产品的，而是那些瞄准新技术或新业务进行创新的。一般来说，如果是做新的事情，做小事和做大事的风险性、艰巨性和不确定性其实差不多。转化机会比解决问题能带来更大的成果，因为解决问题最多只是恢复到之前的水平。\u003c/p>\u003cp>■优先与劣后事项必须根据现实进行调整。例如，没有一位美国总统能够在事态变化之下坚持不变自己的优先事项。事实上，一个人完成某个优先事项之后，其他事项的优先级通常会改变。\u003c/p>\u003cp>换句话说，卓有成效的管理者只全力以赴投入他现在聚焦的一项任务。然后，他评估形势，选择当前最重要的下一项任务。\u003c/p>","explains":"\u003cp>I便签：3W1H\u003c/p>\u003cp>1.What这个片段主要讲述了如何设定优先事项和劣后事项的方法，用来解决在管理任务和决策时如何有效分配资源和注意力的问题。\u003c/p>\u003cp>2. \u003cstrong>Why 我为什么要学这个方法？\u003c/strong>相信大家对四象限时间管理这个工具并不陌生，学习这个方法是因为可以帮助管理者，能够区分哪些是真正重要的任务，哪些可以暂时放一放，对于提高效率和达成目标至关重要。\u003c/p>\u003cp>3. \u003cstrong>How 具体怎么做呢？\u003c/strong>\u003c/p>\u003cp>选择未来而非过去、聚焦于机会而非问题、选择自己的方向而非随大流、设定能够带来改变的高远目标而非安全容易的目标。\u003c/p>\u003cp>\u003cstrong>4.Where 适用场合和不适用场合\u003c/strong>\u003c/p>\u003cp>这个方法适用于需要进行战略决策和优先级排序的场合，如企业管理、个人职业规划等。\u003c/p>\u003cp>不适用于那些需要即时反应和处理紧急情况的场景，因为这些场景可能需要更灵活和即时的决策。\u003c/p>","interaction":"\u003cp>我在做医生的过程中就曾经吃过做事不分主次的亏，那时候工作很忙也很累，但是感觉自己没有太大的进步，后来反思发现做的大部分都是不重要的工作，主要就是一些医疗文书，和流程性的工作，没有掌握核心手术技术。后来就给自己定下目标开始一个手术一个手术的学习，开始可以做一些简单手术。\u003c/p>\u003cp>反思：当我现在仍然做的不好，主要就是没有自己擅长的特色技术并且有一定名气，我也一直在思考，要集中自己精力发展一项具有特色，并在未来有较大增长空间的技术。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1733236459000,"updated_at":1733539164000,"ria":true},{"id":18212,"topic":"职场如何高效管理时间","learn_goal":"","remark":"无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"郝致暐","city":""},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>请问观察家老师拿到观察家记录表、晋级准备表了吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请问各位小伙伴都准备好了吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>好，现在正式开始今天的晋级。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位小伙伴，大家好，我是郝致暐。\u003c/p>\u003cp>我的三个标签是：桃桃爸爸，建筑行业的坚持者，知行合一的践行者。\u003c/p>\u003cp>桃桃是我们家小孩，今年五岁半，马上就要上小学了，和所有的家长一样，都有学前焦虑，最近在看书，研究如何让小孩自发的、有兴趣的学习，这个标准有点高，有兴趣的可以下来一起交流。\u003c/p>\u003cp>第二关于行业，我在在建筑行业从事成本相关工作已经10来年了，有幸在好的时候见证了一些优秀的企业是怎么运作的，在不好的时候也只能多修炼内功，等待下一次机会。\u003c/p>\u003cp>第三关于知行合一,我是18年加入的拆书帮，这几年在外地也一直在学习，但是效果不大好，就是看书的时候感觉都知道了，关上书啥改变没有，上个月把“这样读书就够了”找出来看了一遍，有一种“众里寻他千百度，那人却在灯火阑珊处”的感觉，这次回来参加线下晋级，希望能通过晋级督促自己，通过读书，点亮生活。\u003c/p>\u003cp>今天是我第一次参加拆书帮晋级的日子，首先给小伙伴们解释一下什么是【拆书法】，拆书并不是把书撕了的意思，也不是传统意义的以知识为中心进行学习，而是强调把书本里的知识转化为学习者的能力，以提升能力、解决问题为目标进行学习。\u003c/p>\u003cp>拆书又分个人学习和组织学习两种方式，个人学习是个人在读一本书时不仅仅是是学到书本里的知识，还要将书本里的知识用自己的话描述出来，同时回顾过往经验反思做得好或者不好的地方，以及未来的适用场景怎么调整，通过这样的过程让你的学习和参加一场主题培训有一样的效果。组织学习是由拆书家带领大家，引导一群人把知识拆为己用，就像今天这样。\u003c/p>\u003cp>\u003cbr>【拆书帮】是拆书法学习爱好者的社群，表现为各地的拆书帮分舵也叫拆书帮俱乐部。拆书帮分舵是非营利性组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":2,"texts":[{"id":22485,"quote":"\u003cp>图书选自《卓有成效的管理者了》作者： 彼得·德鲁克  P54-55页（必填）\u003c/p>\u003cp>管理者取得有效性的\u003cstrong>第一步是记录时间的真实使用情况\u003c/strong>。有些管理者是自己做，有些是让秘书做（就像前面提到的那位董事长），但真正重要的是记录下来，而且是“实时”记录，也就是在事件发生之时做记录，而不是事后凭记忆补录。\u003c/p>\u003cp>许多有效管理者会持续记录，每个月定期回顾，最少也是连续记录三四周，每年定期做两次。每次记完，他们都会重新思考和安排自己的日程表。然而，6个月之后，他们无一例外都会发现“漂移”，也就是在一些琐事上面浪费时间。虽然只要这样去做就能改善对时间的利用，但只有持续努力才能避免这种“漂移”发生。因此，接下来就是系统地管理时间。\u003cstrong>管理者要把那些没有成效和浪费时间的活动找出来，尽最大努力把它们砍掉\u003c/strong>。\u003c/p>\u003cp>为此，要回答几个诊断问题。\u003c/p>\u003cp>1.首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录表拿出来，逐项逐项地问：“这件事如果不做，会有什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>2.第二个该问的问题是：“时间记录表上的哪些活动可以由别人代为参加而又不影响效果？”\u003c/p>\u003cp>3.还有一项浪费时间的因素，是管理者自己可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间\u003c/p>\u003cp>实际上，管理者即使砍得太狠，也不会有太多风险。人们通常会高估，而不是低估自己的重要性，于是得出结论，认为太多的事只有自己才做得了。就算是那些非常有效的管理者，也会做大量不必要和无成效的事。\u003c/p>","explains":"\u003cp>好，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>【WHY】: \u003cbr>在职场中，许多有效管理者觉得自己的时间不够用，这类管理者往往把自己的日程表排得满满的，对外宣称“没有功劳也有苦劳”，然而，他们无一例外都会在一些没有成效的琐事上面浪费时间，要想真正提高管理者的时间利用率，我们需要系统地管理时间。\u003c/p>\u003cp>【WHAT】：\u003c/p>\u003cp>管理者需要记录时间的真实使用情况，然后把那些没有成效和浪费时间的工作找出来，尽最大努力把它们砍掉。\u003c/p>\u003cp>【HOW】：\u003c/p>\u003cp>第一步，记录近一周时间的真实使用情况\u003c/p>\u003cp>第二步，通过以下三个问题判断把那些没有成效浪费时间的工作找出来。\u003c/p>\u003cp>1.首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录表拿出来，逐项逐项地问：“这件事如果不做，会有什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>2.第二个该问的问题是：“时间记录表上的哪些活动可以由别人代为参加而又不影响效果？”\u003c/p>\u003cp>3.还有一项浪费时间的因素，由别人在做，同时是管理者自己可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间 \u003c/p>\u003cp>第三步，将这些没有成效浪费时间的工作从自己的日程表里抹去。 【WHERE】：\u003c/p>\u003cp>这种方法适用于所有在职场中觉得时间不够用的管理者。\u003cbr>\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>分完完拆页的内容，我立即联想到发生在我身上的一个经历（故事）：\u003cbr>刚被派到外地区域第一周主要工作时间统计：\u003c/p>\u003cp>1、12小时参加公司相关会议；\u003c/p>\u003cp>2、7.5小时施工单位结算交底培训，答疑；\u003c/p>\u003cp>3、5小时项目分包招标采购；\u003c/p>\u003cp>4、3小时做子公司部门制度建议PPT。\u003cbr>\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>因时间安排不合理，导致第四项工作完成度不高，被上级领导批评要求重新做。鉴于已经做了主要事项的时间记录，需要把没有成效浪费时间的活动找出来：如第二项工作基于目前公司的资金情况及群里的资料下发情况，本周不做也不会有任何影响，可以取消掉；第三项工作可以交给新同事做，最后在把这些事项从自己的日程表里砍掉，就有更多的时间做第四项工作，大大的提升自己的时间利用率。\u003c/p>\u003cp>A2\u003c/p>\u003cp>\u003cu>目标：\u003c/u>\u003cbr>用时间记录工作表记录下周工作日的时间真实使用情况，周六把那些没有成效和浪费时间的工作找出来，周末将这一类工作砍掉70%以上。\u003cbr>\u003cu>行动计划：\u003c/u>\u003c/p>\u003cp>1、建立工作时间记录表，放在桌面显眼位置。\u003c/p>\u003cp>2、每日工作事项完成后及时记录工作事项及完成时间。\u003c/p>\u003cp>3、周六根据记录表逐条筛选三个问题：这件事如果不做，是否不会有什么后果？这个活动是否可以由别人代为参加而又不影响效果？这项工作是否在浪费别人的时间？\u003c/p>\u003cp>周天将回答为“是”的工作汇总起来，砍掉70%以上的工作。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1729498865000,"updated_at":1731490056000,"ria":true},{"id":18144,"topic":"聚焦“要事”，做时间和任务的主人","learn_goal":"","remark":"无","level":"TF1-2","duration":15,"status":19,"type":0,"chaishujia":{"username":"Ethan","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>大家好，我是徐毅，感谢大家抽出宝贵的时间，陪伴我参加1-2的晋级。我用三个标签介绍我自己：\u003c/p>\u003cp>（1）学习者（2）管理者（3）运动爱好者\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>由于今天有讨论环节，所以我根据现场人数进行分组：左手边一组，右手边一组。\u003c/p>\u003cp>今天给大家带来的这本书，是《卓有成效的管理者》 作者：彼得·德鲁克。\u003c/p>\u003cp>F-feature他是管理学学科的开创者，1966年写下了这本书，总结了管理者想“卓有成效”必需的五大特点：时间管理、聚焦贡献、有效决策、用人之长和要事优先。\u003c/p>\u003cp>A-advantage比尔盖茨曾经说过：“在所有的管理学书籍中，德鲁克的著作对我影响最深。”而在德鲁克的众多管理学著作当中，这本书是他最著名的著作。一般的管理学书籍都在告诉你怎么管理你的下属，而这本书，还告诉了你怎么管理你自己。\u003c/p>\u003cp>B-benefit相信大家都读过时间管理、刻意练习甚至包括你熟知的1w小时定律等等相关的知识，那么我负责任的告诉大家，这本书正是这些知识的本源。\u003c/p>\u003cp>总之，如果你想要变得“卓有成效”，多读几遍这本书，会让你在面对变幻莫测的社会环境中变得更游刃有余。\u003c/p>","ratings_count":1,"texts":[{"id":22402,"quote":"\u003cp> 关于怎样设定优先任务的分析有很多，但对于区分优先任务和延迟任务，最重要的不是高超的分析，而是勇气。\u003c/p>\u003cp> 设定优先任务需要遵循一些真正重要的法则，对这些法则起决定作用的因素是勇气，而不是分析。这些法则包括：\u003c/p>\u003cp> 重视将来，而不是重视过去\u003c/p>\u003cp> 专注于机会，而不是专注于问题\u003c/p>\u003cp> 选择自己的方向，而不是随波逐流\u003c/p>\u003cp> 目标高远，做可以带来不同的事，而不是但求&quot;安全&quot;，做容易的事\u003c/p>\u003cp> 很多科学家的事迹表明，（至少是爱因斯坦的相对论、玻尔的原子结构、普朗克的量子理论那样的天才级成果以下的）科研成就更多地取决于追逐机会的勇气，而不是开展科研的能力。科研工作者如果只想选最有可能快速出成果的项目，而不是选最具挑战性的难题，就不可能成为杰出的科学家。他们也许可以产生大量可以列入科学史脚注的成果，但不会有某个物理学定理或某个新概念以他们的名字命名。伟大的成就属于这样的人：根据机会确定研究的优先任务，把其他标准只当限制因素而非决定性因素的人。\u003c/p>\u003cp> 同样，成功的企业不是那些只想着为现有业务线开发新产品的企业，而是那些以发明新技术和开创新业务为目标的企业。通常，只要是做新的事情，无论大小，都是风险一样大，费力一样多，不确定性一样强。但是，把机会转化为成果带来的收效要大于解决问题带来的收效﹣﹣解决问题不过是恢复昨日的平衡而已。\u003c/p>\u003cp>优先任务和延迟任务必须不断根据实际情况加以审视和调整。例如，美国的历任总统没有一个是可以坚持自己最初提出的优先任务清单，而不被某些事件打乱的。实际上，完成当前的优先任务之后，优先任务和延迟任务清单本身就会因此改变。\u003c/p>\u003cp> 换句话说，有效管理者会全力以赴去完成当前聚焦的那一项任务。在完成该项任务之后，他再对形势做评估，确定接下来哪一项任务最重要。\u003c/p>\u003cp> 聚焦就是有勇气对什么是真正重要和优先的事项做出自己的决策，并据此使用自己的时间。它是管理者成为时间和任务的主人，而不受其驱使的唯一希望。\u003c/p>","explains":"\u003cp>拆页告诉我们选择“要事”需遵循的四个重要法则，我总结为：\u003cu>瞻未来、定方向、追卓越、拒平庸\u003c/u>。咋一听感觉像是喊口号，稍微有点抽象。\u003c/p>\u003cp>我们以人的一生为背景来阐述。在人生的历史长河里，我们在社会中均扮演着各种各样的角色，比如说我作为孩子的父亲、夫人的丈夫、父母的儿子、公司部门的经理等等，每个角色都有很重要的事情要做。那具体到某一角色，根据上面的四原则我们应该如何去做呢？我梳理了下面3个步骤来实施（称为“要事三步法”）：\u003c/p>\u003cp>\u003cstrong>1.书写愿景：明确我们的角色，书写个人的使命愿景。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.确定方案：按可观察的、可量化的原则，确定与使命愿景相关联的行动方案。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3.执行计划：根据所制定的方案，确定具体的行动计划，并执行。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>愿景\u003c/strong>：当一个孝顺父母的儿子\u003c/p>\u003cp>方案一：每周与父母视频两次，每次20分钟\u003c/p>\u003cp>行动计划一：\u003c/p>\u003cp>1：问问父母身体是否健康\u003c/p>\u003cp>2：问问家里有什么东西需要购买\u003c/p>\u003cp>3：告知父母自己在哪里出差，家庭和工作情况\u003c/p>\u003cp>方案二：每年为父母准备礼物至少6次\u003c/p>\u003cp>行动计划二\u003c/p>\u003cp>1：传统节日、父母生日及换季时候送礼物\u003c/p>\u003cp>2：可以采用网购快递方式\u003c/p>\u003cp>3：以实物和传统物品为主\u003c/p>\u003cp>方案三：每年安排父母体检\u003c/p>\u003cp>行动计划三\u003c/p>\u003cp>1：提前购买老人体检套餐\u003c/p>\u003cp>2：带父母去体检中心\u003c/p>\u003cp>3：帮父母解读体检报告\u003c/p>\u003cp>方案四：每年带父母旅游两次\u003c/p>\u003cp>行动计划四\u003c/p>\u003cp>1：安排行程，以近郊和舒适游为主\u003c/p>\u003cp>2：注意老人身体状况，多带备用品，如药品\u003c/p>\u003cp>3：多拍照片，与亲友分享幸福时刻\u003c/p>","interaction":"\u003cp>A1：分享完我的案例，接下来请小伙伴们回想一下，使用上面的“要事三步法”，选定一个角色，用一句话概括你的使命愿景，并确定你的方案及实施计划，可以给我举手示意或者直接说出来。\u003c/p>\u003cp>现在，请大家用2分钟的时间思考并在小组内按顺序一一进行分享，稍后邀请一位伙伴给我们分享下他的经历。\u003c/p>\u003cp>好，时间到，哪位小伙伴愿意分享一下自己的经历呢？\u003c/p>\u003cp>下面我们请这位伙伴进行分享，大家欢迎。\u003c/p>\u003cp>A2：好，非常感谢这位小伙伴的分享。接下来，我们就规划一下：在未来的一年，运用今天学习的“要事三步法”确认自己的“要事”和行动方案。\u003c/p>\u003cp>我会给大家2分钟的时间，把具体的目标和行动规划写到便签纸上。\u003c/p>\u003cp>注意要符合以下格式：\u003c/p>\u003cp>我作为什么角色，在什么时间期限内，什么样场景，运用“要事三步法”去干什么，想要达到什么样的效果。\u003c/p>\u003cp>好，鉴于时间关系，今天就不再邀请小伙伴们分享自己的目标和行动了。如果愿意的话，后面可以单独与我分享。 \u003c/p>\u003cp>【总结】\u003c/p>\u003cp>以上就是我今天TF1-2拆书分享的全部内容，感谢观察家，感谢各位小伙伴的陪伴。希望大家可以将今天学的《聚焦“要事”，做时间和任务的主人》用到自己日常的工作中，从而让我们的工作变得更高效。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1727878450000,"updated_at":1729669154000,"ria":true},{"id":17907,"topic":"卓有成效的管理者之时间管理","learn_goal":"","remark":"卓有成效的管理者之时间管理","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"承哥","city":"安顺市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>不破不立，不拆不成器，拆书帮让你把知识拆为己用。\u003c/p>\u003cp>大家好，我叫周继承，是一个商业运营和物业经理人，也是学习成长者，更是您身边的知心朋友。\u003c/p>\u003cp>分组（根据人数分）（现场实际到场人数7人，分成2个小组，我的右手边4个人为一组，左手3个人为一组）\u003c/p>\u003cp>接下来是我的1-2过级，我要拆解的片段是选自《卓有成效的管理者》，这本书是由美国管理学家\u003ca href=\"https://baike.baidu.com/item/%E5%BD%BC%E5%BE%97%C2%B7%E5%BE%B7%E9%B2%81%E5%85%8B/6906406\">彼得·德鲁克编著的一部管理学著作，是管理学类图书中非常畅销及实用的一本，犹如良师益友，是因为虽然我们面对的是相似的情形，却能从不同的角度说出你不曾觉察到的理念，常有茅塞顿开之感。他教导我们如何设定明确的目标、有效规划时间、构建高效的团队，以及如何在不断变化的环境中取得成功。无论您是企业领袖、还是创业者，还是追求卓越的个人，在这本书里面都会在其中找到实用的管理和自我提升策略。\u003c/p>\u003cp> \u003cstrong>有关书籍的介绍就到这里，接下来请大家花1分钟时间看下我分发的拆页\u003c/strong>\u003c/p>","ratings_count":3,"texts":[{"id":22148,"quote":"\u003cp>《卓有成效的管理者》第35-37页\u003c/p>\u003cp>如何诊断自己的时间\u003c/p>\u003cp>经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免再回到浪费的状态上去。\u003c/p>\u003cp>因此，第二个步骤就是要做有系统的时间管理。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以试问自己下列几个问题。\u003c/p>\u003cp>1．首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>2．第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果？”\u003c/p>\u003cp>3．还有一项时间浪费的因素，是管理者自己可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/p>\u003cp>\u003cstrong>好，看到大部分已经阅读完拆页了，还没看完的请跟着我的思路继续分享今天的拆页。\u003c/strong>\u003c/p>","explains":"\u003cp>what\u003c/p>\u003cp>这个片段提供了管理者想要做到“减少对关键性结果无意义的时间投入”，可以从3个方面入手找出浪费时间的活动。\u003c/p>\u003cp>why\u003c/p>\u003cp>大部分人能够成为管理者，或者说做了一段时间管理工作后，或多或少会有工作前先规划自己时间的意识和行动。规划时间之后，有时发现每件事情都是影响关键性结果的的事情，无法割舍，自己最终还是忙忙碌碌，结果不尽如人意。这就需要我们具有识别对关键性结果无意义的事情的方法，掌握了这些方法，我们可以把排满的时间表，腾出一些时间来，给关键性结果有意义的事情多些时间，不必让自己过于忙碌，无暇思考，让自己的管理更高效。\u003c/p>\u003cp>howt \u003c/p>\u003cp>方法一，对照时间记录找出根本不必做的事情。对照事项逐项进行判别，每项都问自己：“这件事情对我现阶段想要的结果能起到关键的作用吗？如果不做，会有什么后果？这件事跟另外一件事对比，哪个更重要？”。自己反复对话自己，如果得出“不做不会有任何影响”，那么这件事就可以从时间表上剔除。\u003c/p>\u003cp>方法二，不影响效果的事情由别人代为参加。遇到当下阶段需要完成，且需要占用时间的事情，可以问自己：“这个事情必须我自己亲自去做吗？我不能亲自去做，他人代替我去做，有什么影响吗？没有影响，谁可以代我去做？”\u003c/p>\u003cp>方法三，不要浪费别人的时间。管理者管理时间的时候，在自己非常忙碌的情况下，运用前面两个方法，可以找出浪费时间的事情。有时自己没那么忙碌，会开始给自己找事情做，比如跟下属开个会，讨论下某个方案。这会陷入不经意间浪费了下属的时间，使组织的效率受到影响，从而影响关键性结果。\u003c/p>\u003cp>where\u003c/p>\u003cp>掌握诊断时间表上的每项事情的方法，可以让管理者的时间管理可以更好的执行落地，而不是停留在记录规划了时间，能够更高效的利用自己的时间。\u003c/p>\u003cp>案例\u003c/p>\u003cp> 我绝大多数工作是做物业管理工作，到了月初特别忙碌，有围绕日常维护和服务开展的既定工作，也有一些临时性的工作。遇到这种情况，我需要先用方法一“对照时间记录找出根本不必做的事情”，需要我做分析，做决策的，比如对当月催费结果分析总结，进而制订下月收费计划，以及配套的培训和目标制定，是我必须要做的事情。而工作内容确定后，工作方案文件的整理，以及临时的工作内容，下属工作心态访谈，是相对来说不必做的事情。然后会用到方法二“不影响效果的事情由别人代为参加”比如隔级下属培训管理，我的直接下属已经可以做了，我只是综合考察下价值观，匹配度，可以要求直接下属安排。除了催费工作，团队也在忙着日常的管理工作和服务行为，我告诉自己“不要浪费下属的时间”，除了必须的事情，其他的时间留给团队做好日常工作，他们也想努力做好自己的工作，想让自己的工作不留遗憾，就用到了方法三。\u003c/p>","interaction":"\u003cp> A1\u003c/p>\u003cp> 以上就是我对这个拆页的理解和思考了，接下来请每个人想一个你过往经历过的“很忙碌，但却做了浪费时间的事情”的案例，然后在小组内轮流进行分享，这个环节我们给大家4分钟的时间。分享的具体要求：\u003c/p>\u003cp>1、故事：时间、地点、人物、事件起因、经过、结果（饱含情感/情绪、关键细节/行为）\u003c/p>\u003cp>2、反思：哪些地方做得不好/不够好，哪些地方可以如何做得更好。小组内分享结束后，我会邀请一位伙伴给大家分享。好的，现在开始。\u003c/p>\u003cp> 好的，美好的时光总是那么短暂，4分钟过去了，每个小组的分享应该也完成了，\u003c/p>\u003cp>下面请周老师给大家分享下。\u003c/p>\u003cp> 周老师分享：关于写拆页和过级浪费时间的事，生活中我们经常会浪费很多时间，比如昨天晚上就打游戏打到两点，这样就浪费了很多时间，导致今天过级的准备不足，因为准备不足会让自己紧张，如果昨天晚上不玩游戏，而是利用玩游戏的时间写拆页，多练习几遍拆页的内容，今天就不会那么紧张，而且玩游戏没有什么意义，是真正的浪费时间，我们在生活中浪费时间的事会经常发生，通过今天的拆页，我们在以后日常生活和工作中，应该合理的规划利用好自己的时间。\u003c/p>\u003cp>周老师的分享给了我们一个很好的案例，在现实的生活中，我们经常会用宝贵的时间去做一些没有意义和不紧急的事，所以我们需要合理利用我们的时间。\u003c/p>\u003cp> A2 \u003c/p>\u003cp> 好的，咱们今天已经学习了从3个方面入手找出浪费时间的活动的方法，学以致用才能真正地收获。各位可以思考一下在自己未来1周，1个月，或3个月内，生活或工作当中，可能出现的忙碌场景，而出现这种情况后，自己可以如何使用今天学习的方法来处理？此计划不能仅是表决心，要是具体的做法，明确的时限，和可衡量的结果。请大家用一分钟写在便签上。写完后给到我，现在开始写吧。\u003c/p>\u003cp> 以上是我今天分享的内容，希望大家能通过我的介绍了解到拆书的一些内容，谢谢大家。\u003c/p>\u003cp>学习者分享\u003c/p>\u003cp>1、明天上班第一件事，把自己一周内要做的事情先在一张纸上。\u003c/p>\u003cp>2、把紧急的必须要自己处理的事情和不紧急可以让下属代替自己做的事情分开。\u003c/p>\u003cp>3、紧急和必须自己做的事情，自己亲自处理。\u003c/p>\u003cp>4、可以让下属代替做的事情，安排下属处理，并要求下属处理后进行汇报，自己监督事情处理的结果即可。\u003c/p>\u003cp>5、每周循环坚持做上面的四件事，直到形成习惯。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":22149,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1722254097000,"updated_at":1723045928000,"ria":true},{"id":17707,"topic":"卓有成效的管理者常用的关注人的长处和贡献的全新考评方式","learn_goal":"","remark":"暂无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"Minch明奇","city":"无锡市"},"club":{"name":"无锡太湖分舵","city":"无锡"},"prologue":"\u003cp>\u003cstrong>技能点：介绍”拆书“和”拆书帮“\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】1分钟\u003cbr>\u003c/strong>亲爱的伙伴们，大家晚上好，欢迎来到今天的拆书活动现场。我是拆书帮无锡太湖分舵的闵文超，如有记不住我的名字，就记一句话：门里门外超有文化。用三个标签介绍我自己：第一个标签，我是一名新手拆书家。第二个标签，我是一名IT创业者，专注于为制造型企业提供管理软件解决方案，愿景是帮助300位实体企业家落地数智化系统，提升信息价值。第三个标签，我有两个上小学的女儿，作为爸爸，家庭教育和个人成长是我持续学习的课题。\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】2分钟\u003c/strong>\u003c/p>\u003cp>我曾经花了很多时间读书但没有太多成果，只到了解到拆书帮，这刷新了我对学习力的认知。下面我介绍一下拆书帮。\u003c/p>\u003cp>拆书的拆是指转化和内化。拆书是成人学习方法论，适用于将提升能力、解决问题和理论类书籍，与学习者的经验、目标、行动关联起来。拆书法分两种：一种适合个人学习，即使用RIA便签法读完一本书，输出一组或多组便签，包含选定R拆页，I便签重述原文，A1关联经验，A2思考目标和行动。个人拆书相当于参加完一场培训，达到了学以致用的效果。另一种适合组织或团队，围绕一本书展开一次现场学习，拆书家甚至超过培训师，引导学习者参与互动，把书拆为己用。\u003c/p>\u003cp>拆书帮是基于学习爱好者的社群，分布在全国多个城市的近80个分舵。分舵是非营利性质，是青年自行组织和运营。拆书帮的使命是，培养拆书家，释放学习能量，助人达己。拆书帮的价值观是，陪伴赋能、拆为己用、反求诸己、持续精进、共同成长。\u003c/p>","ratings_count":1,"texts":[{"id":21921,"quote":"\u003cp>\u003cstrong>【R原文片段】摘自《卓有成效的管理者》P107-P108\u003c/strong>\u003c/p>\u003cp>我们能衡量的，只有绩效。我们应该衡量的，也只有绩效。这是把职位设计得大且富有挑战的另一个原因，也是必须思考清楚人要对所在组织的成果和绩效做出什么贡献的原因。这是因为，只有对照具体的绩效目标，才能去衡量一个人的绩效。\u003c/p>\u003cp>管理者总归需要某种形式的考评，否则就要临到填补职位空缺的时候才去对人员做出评价——这个时机是错的。于是有效管理者通常会想出全然不同的考评形式。考评首先是列出期望考评对象在旧职和现职做出什么样的重大贡献，以及对照这些目标取得的绩效，然后思考以下四个问题：\u003c/p>\u003cp>（1）他在哪个方面已经做得很好？\u003c/p>\u003cp>（2）所以他可能在哪个方面做得很好？\u003c/p>\u003cp>（3）他要想充分发挥长处还需要学会哪些东西？\u003c/p>\u003cp>（4）如果我有儿女，愿意送到他手下去工作吗？\u003c/p>\u003cp>1）如果愿意，为什么？\u003c/p>\u003cp>2）如果不愿意，为什么？\u003c/p>\u003cp>这种考评显然比普通考评要挑剔得多，但它关注的是人的长处，是从这个人能做好什么事开始的，将其短处则视为充分发挥长处以及取得成就、取得有效性和实现目标所面临的局限。\u003c/p>","explains":"\u003cp>现在就由我来带领大家拆解一下今天的片段。这是选自《卓有成效的管理者》一书，该片段摘自“让长处富有成效”，介绍了应重点关注人的长处和已知贡献，从过去经历推断是否能胜任新岗位，是一种全新的考评形式，可能在工作中应用。\u003c/p>\u003cp>下面我们花2分钟的时间看一下原文片段，看完后抬头示意我一下。\u003c/p>\u003cp>What：这个拆页德鲁克先生分享了他对管理者考评下属或绩效谈话的想法。他认为，从过去经历推断是否能胜任新岗位，是一种全新的考评形式。“找缺点”是不可取，而应该努力“助发展”。\u003c/p>\u003cp>How：按四个步骤依次提问：\u003c/p>\u003cp>1，他在哪个方面已经做得很好？有什么成果和证据？\u003c/p>\u003cp>2，推断他可能在哪个方面做得很好？认同他的哪种胜任能力？\u003c/p>\u003cp>3，需要公司支持哪些资源来强化他的长处？为了扬长和助发展管理者能帮助他什么？\u003c/p>\u003cp>4，有哪些长处和品质值得人向他学习？\u003c/p>\u003cp>Where：该考评方法可用于对现有下属进行考评，月度总结会议上的绩效总结，调岗决策的步骤之一，也适用于应聘者自我反思。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>最近有一个小伙伴正在面对裁员的坏消息。从与他的交流中得知，起因有3点，一是他经常在朋友圈晒周末或过节出去旅游的照片，让领导认为他不缺钱，或者让领导觉得他重心不在工作上。二是他朋友圈经常有喝酒聚餐或爬山到深夜的场景，而第二天还能在客户那正常打卡，领导怀疑他的考勤打卡是假的。三是他可能花了别人两倍的时间才交付完几个项目，让领导觉得他能力不能胜任。其实按照领导的考评方式来分析，他的前两个猜测是多虑的，领导并没有因为他的缺点而决策，而是考虑到他没有在哪些方面做得好，没有成果或工作并不有效。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>这个月有一位同事提交了转正申请，但是经大家讨论，对他过往的情况进行了复盘，决定延迟一个月转正。复盘过程中应用了上述片段中的考评方式。首先他曾经做了会计岗位表现很不错，学习能力也较强，因而推断他可能在与企业财务部门对接时能做好，推断他能胜任软件实施工程师岗位。但是管理软件的实施工作需要编程和系统知识，因此为了扬长和发展他的优势，公司派他继续学习和认证工程师评级。他的踏实好学值得其他同事向他学习。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1717748548000,"updated_at":1717767277000,"ria":true},{"id":17618,"topic":"晋级","learn_goal":"","remark":"无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"汪教在路上","city":"乌鲁木齐市"},"club":{"name":"乌鲁木齐筹备分舵","city":"乌鲁木齐"},"prologue":"\u003cp>大家好，我是来自新疆乌鲁木齐分舵的汪军，汪洋大海上的军人，是我最崇敬的人。\u003c/p>\u003cp>我的三个标签\u003c/p>\u003cp>我的第一个标签是体验式培训师，从事18年体验式培训，服务企业超500家。研发设计了一团火高绩效训练营和实景沙盘体验营，并落地实施上百场。\u003c/p>\u003cp>我的第二个标签是个人成长教练，12年-21年一直致力于性格分析和团队角色的应用学习实践，分析实践案例超1000例。\u003c/p>\u003cp>我的第三个标签是终身学习实践者，“学无止境，格物致知”是我的座右铭。所以，拆书家，我来了\u003c/p>","ratings_count":1,"texts":[{"id":21815,"quote":"\u003cp>片段来源《卓有成效的管理者》彼得·德鲁克（著）P87-88\u003c/p>\u003cp>一套适当的考评方式，毕竟是不可少的。否则，当一个职务需要某人来承担时，就没办法对他做出正确的评价。因此，有效的管理者，通常总有他自己的一套与众不同的考评方式。这套方式，第一步是列出对某人过去职务和现任职务所期望的贡献，再把某人的实际绩效记录与这项期望贡献相对照，然后检讨下面的四个问题：\u003c/p>\u003cp>（1） 哪方面的工作他确实做得很好？\u003c/p>\u003cp>(2）因此，哪方面的工作他可能会做得更好？\u003c/p>\u003cp>（3）为了充分发挥他的长处，他还应该再学习或获得哪些知识？\u003c/p>\u003cp>（4）如果我有个儿子或女儿，我愿意让我的子女在他的指导下工作吗？\u003c/p>\u003cp>a如果愿意，理由是什么？\u003c/p>\u003cp>b如果不愿意，理由是什么？\u003c/p>\u003cp>这样的考评方式，显然与通常的做法不同。这套方式以当事人的长处为重心，以当事人能做些什么开始\u003c/p>","explains":"\u003cp>便签I:\u003c/p>\u003cp>what:片段阐述了以当事人长处和能做什么为主的一套很棒的考评方式，通过过去和现在，实际与期望的对照，以检讨四个方面的问题来达到对当事人选择某个职务的考评。清晰明了准确的去对当事人以理性的方式做出评估和考量。\u003c/p>\u003cp>why:\u003c/p>\u003cp>我们在一个职务需要某人去承担时往往以感觉和喜好去判断，无法做出客观和正确的评价。而用一套以个人长处为重心且前后对照的价值贡献为基础，检讨四个牵引问题能够帮助我们客观的考评一个能否承担某职务的当事人。\u003c/p>\u003cp>how:\u003c/p>\u003cp>通过前后价值对比后，检讨的包含四个问题\u003c/p>\u003cp>1.本身做的好的工作\u003c/p>\u003cp>2.哪方面还可以做得更好\u003c/p>\u003cp>3.为发挥长处需要再次补充精进学习的部分是什么\u003c/p>\u003cp>4.如果我的子女在他的指导下工作的话，我们自己愿意吗？理由分别是什么！\u003c/p>\u003cp>Where:\u003c/p>\u003cp>这种考评方式在评价一个职务需要某人来承担或者是晋升，亦或在做任务分配和岗位调整时的职场非常适用。在非正式的交谈和聚会闲聊时可能并不适用。\u003c/p>","interaction":"\u003cp>A1联系具体经验】1-2分钟\u003c/p>\u003cp> 今年1月份我在给一家企业做顾问时，在开2024年战略规划会议时有一项组织架构调整的议题。需要对三位管理层人员在总经理、生产经理、营销经理的岗位做明确分工，起初他们各自对自己能否做好的信心都不是很充足，对岗位胜任力也显得比较迷茫。而我通过多年的顾问经验，适用了类似四个检讨问题的前三个，分别说了他们三位各自的优势部分，可提升的部分，为能更好的胜任需要学习补充的部分。当给三位分析完之后，三位管理人员对自己的岗位胜任力充满信心，值得高兴的是他们还主动的为自己的成长规划做了更多的补充。\u003c/p>\u003cp>回顾片段中的考评方式，让我看到了以人的优势及能做什么为出发点对一个管理者来说，不仅能对当事人做出评价，还能够激发当事人挑战优秀和卓越。有效的管理者不能仅靠直觉和感觉，更具科学性的评价和促进能大大提高管理效能。\u003c/p>\u003cp>同时，片段中的第四个问题也让我意识到，如果能够感同身受的举出自己的孩子愿不愿意在对方的领导下工作，并说出理由，则会更贴切，更具感染力。\u003c/p>\u003cp>【A2具体应用】3分钟\u003c/p>\u003cp>计划5月13日与门店新晋店长做一次考评并使用片段中所检讨的四个问题。\u003c/p>\u003cp>第一步:5.11日确定当事人在5.13号上午11点面谈时间。\u003c/p>\u003cp>第二步:5月11日下午15:00-17:00在办公室罗列四个问题的内容。\u003c/p>\u003cp>第三步:根据片段中的how的部分，将内容设定为1.他在洗护技术和客户维护方面做得非常好表示肯定。2.因此，在店面层面的质量保证和客勤关系方面一定会做得更棒。3.为了充分发挥其长处，还应该学习一些店面运营和线上运营的知识，以加强对店面管理的有效性。4.会告诉他，如果是我的孩子，我会非常愿意在他的领导下工作，因为他的责任心和上进心都是可以带给人进步和成长的。\u003c/p>\u003cp>第四步:5.13日上午11点用40分钟时间与店长面谈。\u003c/p>\u003cp>第五步:考评面谈结束后，听取当事人的反馈并做记录。\u003c/p>\u003cp>第六步:形成书面文字记录并存档。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1716041789000,"updated_at":1716080863000,"ria":true},{"id":17531,"topic":"摆脱惯性思维","learn_goal":"","remark":"摆脱惯性思维","level":"TF1-1","duration":12,"status":30,"type":0,"chaishujia":{"username":"周云香","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>不破不能立，不拆不成器！拆书帮把知识拆成能力！欢迎大家参加拆书帮贵阳黔灵分舵线上拆书练级活动。我是今天的领拆人周云香，周瑜的周，白云的云，吃饭香喷喷的香，大家可以叫我云香姐。我给自己的三个标签是：终身学习成长者、预备拆书家、乐观主义者。\u003c/p>\u003cp>说到拆书不得不提到《这样读书就够了》这本书，看过这本书后可以更好的了解拆书和拆书法。拆书的“拆”不是“拆散”，是转化和内化。“拆书”，就是强调把图书的知识转化为学习者的能力，拆书法特别适合“一学就会，一做就废”的学习者。拆书法分为应用于个人学习的拆书帮便签读书法，和应用于组织学习的拆书帮现场学习法（也叫RIA现场学习法）。\u003c/p>\u003cp>RIA现场学习法也加RIA便签学习法，用于个人学习法的场景为：R是书中的原文片段，I是用自己的语言转述原文中的R片段，A是分为A1和A2,A1对应的是自己过去的经验和反思，A2是规划自己未来的目标和行动。\u003c/p>\u003cp> 应用于组织的学习法，就是在个人学习拆书法的基础上，由一位拆书家用一本书或者是一个知识点，组织一场学习，引导和促进一群人把知识内化拆为己用的过程，是一种很好的学习方法。\u003c/p>\u003cp> 拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是非营利性青年自组织，使命是释放学习促进者的能量，帮助更多学习爱好者成为拆书家。拆书帮正式分舵及筹备分舵覆盖全国28个省、直辖市，56个城市，截止2022年11月，55家正式分舵，16家筹备分舵，会员人数1581。现在拆书帮在日本也有分舵了，我们贵阳黔灵分舵也是今年正式成立的。\u003c/p>","ratings_count":1,"texts":[{"id":21716,"quote":"\u003cp>我今天给大家带来的R是出自，由著名的管理学大师彼得·德鲁克（Peter Drucker）所著《卓有成效的管理者》中的“摆脱昨天”片段，请大家用2分钟时间看一下我给大家准备的手稿内容，阅读完毕后打个1示意我，我们接着进行后面的内容。\u003c/p>\u003cp>\u003cstrong>《卓有成效的管理者》P100-P102\u003c/strong>\u003c/p>\u003cp>管理者专心一志，第一项原则是要摆脱已经不再有价值的过去。有效的管理者必须经常检讨他们和同事的工作计划，他们会问：“如果我们还没有进行这项工作，现在我们该不该开始这项工作？”如果不是非办不可，他们就会放弃这项工作，或者会将它搁置起来。至少他们不会再将资源投入不再产生价值的过去。而对于已经投入的最佳资源，尤其是非常匮乏的人力资源，他们会立即抽调出来，转而投入未来的新机会。\u003c/p>\u003cp>但是一位管理者往往不可能完全摆脱过去，这真是无可奈何的事。所以今天，乃是昨天所做决策和所采取行动的结果。人终归是人，有谁能够遇见未来？昨天的决策和行动，不论当时看起来如何勇敢、如何睿智，都有可能形成今天的困难和危机，甚至被证明是愚蠢的行动。不管是政府、企业，还是其他机构，管理者的一项具体任务就是要把今天的资源投入创造未来中去。换句话说，每一位管理者都必须不停地花费时间、精力和才智，来弥补及跳出昨天的行动和决策。不论昨天的行动和决策是他自己做的，还是前任做的，他都得弥补和抛开。事实上他在这方面所耗的时间，应该比其他任何任务所耗的时间都多。\u003c/p>\u003cp>但是我们至少可以把昨天遗留下来的、不能再产生成果的工作量减少。\u003c/p>\u003cp>人遭遇了重大的失败，改正并不太难，他们能检讨自己。可是昨天的成功，却能留下无尽的影响，远超出成功的有效期。尤其危险的是，有些活动本应该产生良好的效果，但是由于一些原因却没能产生效果。过去的成功或者活动，往往演变成“经营管理上的自我主义的资产”，并且是神圣不可侵犯的。但是，这些过去的成功和活动最需要无情的检讨，否则组织的血液都流失到这种自我之中了。而且这种“经营管理上的自我主义的资产”，往往用了组织中最能干的人，却还说那是“值得的”。\u003c/p>\u003cp>还有30秒，看完了请打个1示意我一下，好，时间到，没有看完的小伙伴可以跟随我对这个片段讲解再继续来看。\u003c/p>","explains":"\u003cp>【what】 这个片段告诉我们，管理者需要摆脱过去的惯性思维和做法，来适应当下和未来的挑战。 \u003c/p>\u003cp>【why】过去的成功方法不一定适用于现在和未来的环境，所以我们需要摆脱过去的惯性思维和做法，拥抱变化，并学会适应和应对不断变化的市场、技术和社会环境，以及新的挑战和机遇。\u003c/p>\u003cp>【how】那我们要如何才能做到摆脱过去的惯性思维和做法，来适应未来和挑战呢？\u003c/p>\u003cp>不妨从以下几点试试： \u003c/p>\u003cp>第一，审视过去的做法：反思过去的做法，识别哪些是不再有效的，需要改变的地方； \u003c/p>\u003cp>第二，接受变化：接受变化是不可避免的，主动寻找变化带来的机会，并做好应对准备； \u003c/p>\u003cp>第三，持续学习：反复检讨学习，保持与时俱进，不被固化的思维束缚。\u003c/p>\u003cp>【where】这个理念适合在各种管理和领导场合中应用，特别是在面临快速变化和不确定性的行业和环境中，比如政府政策的制定和执行、教育培训、技术研发、企业管理、市场营销和广告等方面。但是在文化遗产保护、法律法规的遵循、传统手工艺等方面是不合适用的。\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp>为了帮助大家更好的理解这个片段，分享一个我自己的工作正面案例\u003c/p>\u003cp>\u003cstrong>故事：\u003c/strong>\u003c/p>\u003cp>记得2013年5月22日，我受理了1个小区违章搭建的客诉，客户说给区域管家反应了好几次，都没有处理，是不是要等违章搭建建好了都不管。于是我就向管家了解情况，他说当天他接到客户的反映就去现场看了，但是后来因为事情太多就把这事忘了，第二天这个客户又没给他打电话让他去处理，因为客户告知他房号的时候是记录在一个便签纸上的，便签弄丢了，因为怕被那个客户骂，也不敢打电话问，所以就一直处理。\u003c/p>\u003cp> 这个客诉到底是应该追究管家的工作失职还是我作为直接领导管理不到位。我认真的审视了这个客诉的经过，再查看了管家那几天的工作情况。确实那段时间每天受理的客户报事、报修、投诉都在10多件。我发现我们的管理服务机制严重滞后。\u003c/p>\u003cp> 服务户数越来越多，客户需求增加的同时还各种各样，传统的人盯人已经不能适应管理规模的增加。于是我开始咨询了解我们物业管理行业的管理软件，准备往数字化方向提升我们的管理服务效率。2013年8月，我们启用了思源管理软件，这个系统统虽然可以让工程留痕，但是操作流程很麻烦。2015年12月，我们淘汰了思源软件启用了功能更好的乐软，从此所有的服务记录都在云上，不会因为忘记或者人员离职导致工作未做。2017年12月，重新选用更先进的富其系统。2019年1月，改用可以实现物联智能化管理的易软系统。我们通过不断地探索管理的数字化转型，在人员的合理配置、管理服务的提升方面得到了极大的改善，目前仍然还在对系统的更多功能不断地的优化升级中。\u003c/p>\u003cp>\u003cstrong>反思：\u003c/strong>\u003c/p>\u003cp>回头看看我们从客诉的处理到管理系统升级，传统的手工作业和人盯人的管理方式已经跟不上客户的需求和公司的发展，亟需改变。我们主动从根源上找问题，寻求更好的解决方案，将近11年来，我们试用了4种系统管理软件，不断的优化使用过程的BUG，迭代更新到目前可以实现物联的智能管理系统，紧跟时代科技化发展步伐。才有了服务管理逐步规范的今天，这也是我们持续不断的学习，主动接受变化的一个很好的体现。\u003c/p>\u003cp> A2:\u003c/p>\u003cp>所以我决定把今天学到的“摆脱昨天”这个理念方法用到我的读书学习中来，之前读过的书基本上都是只记得书名，这也许就是读了很多书，依然过不好这一生的原因吧。我接下来的目标就是：提升读书的方法\u003c/p>\u003cp>【目标】：提升读书的方法\u003c/p>\u003cp>我准备用两个月时间（2024年4月15日至2024年6月15日），用拆书学习法改变提升自己的读书方法，具体为《胖东来向善而生》这本书，每周用RIA便签法刻意练习，两个月完成8次训练。 \u003c/p>\u003cp>【行动】：\u003c/p>\u003cp>不再让读过的书只记得标题，实现“提升读书的方法”，让读书从“心有所动”到“真能运用”我决定在两个月内按照拆书学习法读完《胖东来向善而生》，并决定按照以下三点行动步骤执行： \u003c/p>\u003cp>第1点,回顾之前的读书方法：第一周每天用30分钟总结2023年读过的所有书，看看自己记得有那几本，里面的内容消化了多少，有多少是用在工作和生活中的。\u003c/p>\u003cp> 第2点，使用新办法：坚持用拆书学习法读书。 \u003c/p>\u003cp>第3点，坚持学习：RIA便签学习法每周完成一次训练，坚持完成8次。\u003c/p>\u003cp> 奖惩：如果我实现了这个目标，我就奖励自己一次两日成都游。\u003c/p>\u003cp> 今天拆书/拆书帮介绍、便签学习法、讲解引导、拆为己用四个部分和大家分享了拆书法，希望能给大家一些启发，也请大家鼓励我达成我的目标。谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1713929521000,"updated_at":1713930048000,"ria":true},{"id":17486,"topic":"摆脱过去惯性思维","learn_goal":"","remark":"摆脱过去惯性思维","level":"TF1-1","duration":10,"status":19,"type":0,"chaishujia":{"username":"周云香","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":null,"ratings_count":1,"texts":[{"id":21670,"quote":"\u003cp>\u003cstrong>《卓有成效的管理者》P100-P102\u003c/strong>\u003c/p>\u003cp>管理者专心一志，第一项原则是要摆脱已经不再有价值的过去。有效的管理者必须经常检讨他们和同事的工作计划，他们会问：“如果我们还没有进行这项工作，现在我们该不该开始这项工作？”如果不是非办不可，他们就会放弃这项工作，或者会将它搁置起来。至少他们不会再将资源投入不再产生价值的过去。而对于已经投入的最佳资源，尤其是非常匮乏的人力资源，他们会立即抽调出来，转而投入未来的新机会。\u003c/p>\u003cp>但是一位管理者往往不可能完全摆脱过去，这真是无可奈何的事。所以今天，乃是昨天所做决策和所采取行动的结果。人终归是人，有谁能够遇见未来？昨天的决策和行动，不论当时看起来如何勇敢、如何睿智，都有可能形成今天的困难和危机，甚至被证明是愚蠢的行动。不管是政府、企业，还是其他机构，管理者的一项具体任务就是要把今天的资源投入创造未来中去。换句话说，每一位管理者都必须不停地花费时间、精力和才智，来弥补及跳出昨天的行动和决策。不论昨天的行动和决策是他自己做的，还是前任做的，他都得弥补和抛开。事实上他在这方面所耗的时间，应该比其他任何任务所耗的时间都多。\u003c/p>\u003cp>但是我们至少可以把昨天遗留下来的、不能再产生成果的工作量减少。\u003c/p>\u003cp>人遭遇了重大的失败，改正并不太难，他们能检讨自己。可是昨天的成功，却能留下无尽的影响，远超出成功的有效期。尤其危险的是，有些活动本应该产生良好的效果，但是由于一些原因却没能产生效果。过去的成功或者活动，往往演变成“经营管理上的自我主义的资产”，并且是神圣不可侵犯的。但是，这些过去的成功和活动最需要无情的检讨，否则组织的血液都流失到这种自我之中了。而且这种“经营管理上的自我主义的资产”，往往用了组织中最能干的人，却还说那是“值得的”。\u003c/p>","explains":"\u003cp>【what】 这个片段告诉我们，管理者需要摆脱过去的惯性思维和做法，来适应当下和未来的挑战。 \u003c/p>\u003cp>【why】过去的成功方法不一定适用于现在和未来的环境，所以我们需要摆脱过去的惯性思维和做法，拥抱变化，并学会适应和应对不断变化的市场、技术和社会环境，以及新的挑战和机遇。\u003c/p>\u003cp>【how】那我们要如何才能做到摆脱过去的惯性思维和做法，来适应未来和挑战呢？\u003c/p>\u003cp>不妨从以下几点试试： \u003c/p>\u003cp>第一，审视过去：反思过去的做法，识别哪些是不再有效的，需要改变的地方； \u003c/p>\u003cp>第二，接受变化：变化是不可避免的，主动寻找变化带来的机会，并做好应对准备； \u003c/p>\u003cp>第三，持续学习：不断学习新知识、新技能，保持与时俱进，不被固化的思维束缚。\u003c/p>\u003cp>【where】这个理念适合在各种管理和领导场合中应用，特别是在面临快速变化和不确定性的行业和环境中，比如政府政策的制定和执行、教育培训、技术研发、企业管理、市场营销和广告等方面。但是在文化遗产保护、法律法规的遵循、传统手工艺等方面是不合适用的。\u003c/p>","interaction":"\u003cp>为了帮助大家更好的理解这个片段，我分享一个我自己工作中的亲身经历\u003c/p>\u003cp>\u003cstrong>故事：\u003c/strong>\u003c/p>\u003cp>记得2013年5月22日，我受理了1个小区违章搭建的客诉，客户说给区域管家反应了好几次，都没有处理，是不是要等违章搭建建好了都不管。于是我就向管家了解情况，他说当天他接到客户的反映就去现场看了，但是后来因为事情太多就把这事忘了，第二天这个客户又没给他打电话让他去处理，因为客户告知他房号的时候是记录在一个便签纸上的，便签弄丢了，因为怕被那个客户骂，也不敢打电话问，所以就一直处理。\u003c/p>\u003cp> 这个客诉到底是应该追究管家的工作失职还是我作为直接领导管理不到位。我认真的审视了这个客诉的经过，再查看了管家那几天的工作情况。确实那段时间每天受理的客户报事、报修、投诉都在10多件。我发现我们的管理服务机制严重滞后。\u003c/p>\u003cp> 服务户数越来越多，客户需求增加的同时还各种各样，传统的人盯人已经不能适应管理规模的增加。于是我开始咨询了解我们物业管理行业的管理软件，准备往数字化方向提升我们的管理服务效率。2013年8月，我们启用了思源管理软件，这个系统统虽然可以让工作留痕，但是操作流程很麻烦。2015年12月，我们淘汰了思源软件启用了功能更好的乐软，从此所有的服务记录都在云上，不会因为忘记或者人员离职导致工作未做。2017年12月，重新选用更先进的富其系统。2019年1月，改用可以实现物联智能化管理的易软系统。我们通过不断地探索管理的数字化转型，在人员的合理配置、管理服务的提升方面得到了极大的改善，目前仍然还在对系统的更多功能不断地的优化升级中。\u003c/p>\u003cp>\u003cstrong>反思：\u003c/strong>\u003c/p>\u003cp>回头看看我们从客诉的处理到管理系统升级，传统的手工作业和人盯人的管理方式已经跟不上客户的需求和公司的发展，亟需改变。我们主动从根源上找问题，寻求更好的解决方案，将近11年来，我们试用了4种系统管理软件，不断的优化使用过程的BUG，迭代更新到目前可以实现物联的智能管理系统，紧跟时代科技化发展步伐。才有了服务管理逐步规范的今天，这也是我们持续不断的学习，主动接受变化的一个很好的体现。\u003c/p>\u003cp>所以我决定把今天学到的“摆脱昨天”这个理念方法用到我的读书学习中来，之前读过的书基本上都是只记得书名，这也许就是读了很多书，依然过不好这一生的原因吧。我接下来的目标就是：提升读书的方法\u003c/p>\u003cp>【目标】：提升读书的方法\u003c/p>\u003cp>我准备用两个月时间（2024年4月15日至2024年6月15日），用拆书学习法改变提升自己的读书方法，具体为《胖东来向善而生》这本书，每周用RIA便签法刻意练习，两个月完成8次训练。 \u003c/p>\u003cp>【行动】：\u003c/p>\u003cp>不再让读过的书只记得标题，实现“提升读书的方法”，让读书从“心有所动”到“真能运用”我决定在两个月内按照拆书学习法读完《胖东来向善而生》，并决定按照以下三点行动步骤执行： \u003c/p>\u003cp>第1点,回顾之前的读书方法：第一周每天用30分钟总结2023年读过的所有书，看看自己记得有那几本，里面的内容消化了多少，有多少是用在工作和生活中的。\u003c/p>\u003cp> 第2点，使用新办法：坚持用拆书学习法读书。 \u003c/p>\u003cp>第3点，坚持学习：RIA便签学习法每周完成一次训练，坚持完成8次。\u003c/p>\u003cp> 奖惩：如果我实现了这个目标，我就奖励自己一次两日成都游。\u003c/p>\u003cp> 我今天的分享到此结束，希望能给大家带来一些启发，谢谢倾听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1713069234000,"updated_at":1713272320000,"ria":true},{"id":17201,"topic":"勇气与选择：在变化中优先排序的艺术","learn_goal":"","remark":"在这个快节奏、不断变化的社会中，如何有效地处理日常生活和职场中的复杂的任务成为了我们每个人的挑战。这篇文章可以让我们一起学习如何在快节奏的世界中做出明智的决策，它不仅仅是关于时间管理和任务优先级的排序，更是关于如何在决策过程中展现勇气和洞察力。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"嫄","city":""},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是今天过TF1-2的萌新拆书家 薛嫄，大家可以叫我“嫄”；“嫄”这个字最大的特点就是“纯粹”只做人名使用没有其他意思。亦如我这个人，在投入做一件事情的时候就会心无旁骛非常纯粹的投入。\u003c/p>\u003cp>下面我通过三个标签来介绍一下我自己。\u003c/p>\u003cp>第一个标签：自学绘画爱好者，我是从绘画0基础然后自学并且坚持200天每天一幅小画。\u003c/p>\u003cp>第二个标签：素食爱好者，我茹素5年，独自举办线下5场“随手素食”的公益活动。\u003c/p>\u003cp>第三个标签：模型思维的探索者，探究并实践在生活、职场上必备的模型思维并加以应用。\u003c/p>\u003cp>希望对素食养生及模型思维探索感兴趣的朋友与我共同交流。\u003c/p>\u003cp>【分组】那么现在呢。请在座的各位分一下组，我们两个人一组。\u003c/p>\u003cp>【图书介绍】那今天我为大家带来的是《卓有成效的管理者》这本 书。这是一本具有深远影响的管理学经典，是现代管理学之父彼得·德鲁克的巨著。他在书中为个人、自我管理者提供了宝贵的指导。他教导我们如何设定明确的目标、有效规划时间、构建高效的团队，以及如何在不断变化的环境中取得成功。无论您是企业领袖、还是创业者，还是追求卓越的个人，在这本书里面都会在其中找到实用的管理和自我提升策略。\u003c/p>","ratings_count":1,"texts":[{"id":21369,"quote":"\u003cp>我已经把片段发给各位了，那请各位阅读一下。阅读完的小伙伴呢。嗯，跟我示意一下。好吧。大概用一分钟左右的时间。 \u003c/p>\u003cp>【R】关于管理者理任务的讨论，一般都从如何做计划说起，这样看来很合乎逻辑。可惜的是管理者的工作计划，很少真正发生作用。计划通常只是纸上谈兵，或只是良好的意愿而已，很少能够真正实现。\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会以时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\u003c/p>\u003cp>•记录时间：\u003c/p>\u003cp>•管理时间：\u003c/p>\u003cp>•统一安排时间。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>What（片段讲的是什么）\u003c/p>\u003cp>这段文字讲述的是有效管理者在处理工作任务时不应只依赖于计划，而是首先应该专注于时间管理。提到了三个关键步骤：记录时间、管理时间、统一安排时间。\u003c/p>\u003cp>Why（为什么要这么做）\u003c/p>\u003cp>那为什么要这么做呢？这么做的原因其实在于许多计划通常难以实际执行，可能只是理论上的规划或者有着美好的愿望。但是通过关注时间的管理，管理者可以更有效地识别和减少不必要的活动，从而提升工作效率和成效。\u003c/p>\u003cp>How（怎么做？具体步骤）\u003c/p>\u003cp>那么具体怎么做呢？\u003c/p>\u003cp>首先第一点 记录时间：我们可以用一些工具详细的追踪工作的活工作活动，记录每项任务所花费的时间。。\u003c/p>\u003cp>第二点 管理时间：通过我们记录的时间，分析时间记录，识别可以减少或者去除的非生产性的工作\u003c/p>\u003cp>第三点，统一安排时间：将零碎的时间集中安排，创造出连续的大块时间，用于处理更重要的任务。\u003c/p>\u003cp>Where（什么情况下适用，什么情况下不适用）\u003c/p>\u003cp>那像这个是什么情况可以适用呢？\u003c/p>\u003cp>比较适用于项目经理，这种方法就非常适用。项目经理需要处理多个任务，通过有效的时间管理，他们可以更好地协调不同任务，可以确保项目按时完成。另一个例子就是像是创业者，他们也是通常需要在有限的时间内处理多样化的事务，有效的时间管理可以帮助他们更好地平衡各种职责，推进业务发展。\u003c/p>\u003cp>不适用情况是对于像流水线工人或客户服务代表，他们的工作是由固定流程和严格的时间表控制的，所以时间管理方法可能就不那么适用。这种时间管理方法在他们的日常工作中可能不会带来特别好的效果。\u003c/p>","interaction":"\u003cp>【A1】激活经验\u003c/p>\u003cp>讲一个我自己亲身的例子吧。\u003c/p>\u003cp>在去年初，上半年春天，我作为市场开发经理，我忙于一个比较大的项目，经常频繁出差，而且应酬特别多，基本上无暇顾及家庭。而且在这期间，我的时间规划管理不是特别好，也没有做很好的记录时间，也没有特别明确的去规划好日程。导致我孩子的舞蹈课的表演我没有参与，错过了女儿期待已久的舞蹈表演。当时她的表演结束的时候，我过去看到她的时候，她真的是非常的失望，而且也非常的埋怨我。我对于这个事情也感到特别的愧疚。\u003c/p>\u003cp>【\u003cem>反思\u003c/em>】这个事情呢让我意识到了有效的时间记录、管理还有统一安排对于平衡工作和家庭是非常的关键的。这不仅仅是职场上的效率问题，而且是家庭的责任和个人承诺的一个体现。\u003c/p>\u003cp> 现在请大家在各位各自的小组里面，我们大家分享一下有没有按照记录时间、管理时间、统一安排时间，这几方面没有做到。然后导致到我们生活中有哪些让我们觉得失败的例子。大家分享一下。然后给大家两分钟左右的时间吧。\u003c/p>\u003cp> 好，看来大家都已经讨论完了，哪位小伙伴来分享一下？小福泥你来分享吧。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp> 【\u003cem>小福泥\u003c/em>】我在1月7号的时候，忘了干啥了，然后就给忘了，（朋友）他1月7号的时候结婚。本来邀请我当伴娘的我都（忘了），连份子子都忘了。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp> 小福泥这个案例非常的有代表性啊。那么我们现在还是有一个小挑战：那么通过小福妮的分享以及我们刚才提出的这个时间的规划管理，记录时间，管理时间，统一安排时间。那么大家可以使者来去写一写我们下面对于我们的生活或者工作，某一项针对于这3点提出自己的一个计划和安排。那记住一点，我们这个计划安排一定是要有行性，来给大家两分钟的时间来去想一想我们生活或者工作什么样的计划需要用这种时间管理方式来去做……\u003c/p>\u003cp> 我看小伙伴们应该都已经写完了，哪个小伙伴来分享一下？小福泥可以吗？那你继续分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp> 【\u003cem>小福泥\u003c/em>】我分享一下，我日常的生活会有一些比如说发工资，还有交社保，还有一些公积金，这些固定的时间然后记录了一下，先把时间记录下来，分配到日历上，然后这样的话就可能就会减少到就是有可能会漏掉的这种情况，然后统一的时候比如说会再提前就确保这些时间事件已经完成了。我不知道是不是符合这个状态。\u003c/p>\u003cp> 【\u003cem>嫄\u003c/em>】好，我觉得很好啊，首先你说的用工具把这个时间记录下来，这一点其实就已经开展了我们的这个步骤了。那么记录时间之后呢，我们再来去规划我们的这个时间。规划完了时间以后，我们就可以剔除到可能浪费掉的时间有哪些。我们在整合时间，着重想要去完成我们更重要或者是说我们更在意的一些事情。\u003c/p>\u003cp>结束语：\u003c/p>\u003cp> 那么今天，我的这个拆页分享其实已经结束了。在今天的这个分享中咱们共同探索了我们在快节奏的多变的现代生活中怎么可以有效的管理时间。这个步骤，它不仅仅是可以帮助我们提升我们的工作效率，更重要的是它可以帮助我们在繁忙之中的生活呢到平衡。我希望我们每个人都可以成为自己时间的主宰，而不是被时间所驱使。再次感谢各位朋友来去听我这一次拆页的分享，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1705347440000,"updated_at":1705912455000,"ria":true},{"id":17127,"topic":"五个习惯养成卓有成效的管理者","learn_goal":"","remark":"当下是个快速变化、充满焦虑的时代，我们在工作、生活中都可能会成为管理者。在工作中想要提高成就，就需要更有成效。想要生活的更加美好亦是如此。想要“卓有成效”不需要特殊的天赋，是可以通过五个习惯的养成就可以达到。本次分享将为大家讲解下，哪五种习惯的养成可以将我们培养成卓有成效的管理者。\n","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"嫄","city":""},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>&lt;自我介绍&gt;\u003c/p>\u003cp>大家好，我是今天过TF1-1的萌新拆书家 薛嫄，大家可以叫我“嫄”；“嫄”这个字最大的特点就是“纯粹”只做人名使用没有其他意思。亦如我这个人，在投入做一件事情的时候就会心无旁骛非常纯粹的投入。\u003c/p>\u003cp>下面我通过三个标签来介绍一下我自己。\u003c/p>\u003cp>自学绘画爱好者：我是从绘画0基础然后自学并且坚持200天每天一幅小画。\u003c/p>\u003cp>素食爱好者：我茹素5年，独自举办线下5场“随手素食”的公益活动。\u003c/p>\u003cp>模型思维的探索者：探究并实践在生活、职场上必备的模型思维并加以应用。\u003c/p>\u003cp>希望对素食养生及模型思维探索感兴趣的朋友与我共同交流。\u003c/p>\u003cp>&lt;拆书法&amp;拆书帮介绍&gt;\u003c/p>\u003cp>接下来，我介绍一下拆书法和拆书帮。在介绍拆书法和拆书帮之前我想问问大家。我们有没有过一些情况，比如说面对通读整本书的压力？有没有看到精彩的片段，会心动，会划线，会摘抄转发……然后就没了……有没有看完的书还是书却没能解决自己的问题？\u003c/p>\u003cp>我认为成人的学习问题：需要以实际需求出发，解决问题，提升自己能力。“拆书法”是一种以“学习者为中心”的方法论，不用把书全部通读完，选择原书的一两页，通过个人学习的RIA便签法，和拆书家引导学习的现场学习法可以有效的把图书的知识转化为学习者的能力，“拆为己用”可以很好的解决成人学习的问题。\u003c/p>\u003cp>详细来说“拆书法”主要通过：\u003c/p>\u003cp>R：阅读原书的拆页\u003c/p>\u003cp>I便签：用自己的语言诠释拆页的内容\u003c/p>\u003cp>A1便签：联系自己经历，激活学习者的经验。\u003c/p>\u003cp>A2便签：制定实践计划，以后如何使用，催化学习者应用。\u003c/p>\u003cp>这三个步骤将知识拆为己用。\u003c/p>\u003cp>“拆书帮”是基于拆书方法论的学习爱好者社群，它是非营利性的，公益性的青年自组织。表现为各地区的拆书帮分舵（也是拆书俱乐部），目前全球58个正式分舵，17个筹备分舵。在分舵里有一群志同道合的学习爱好者，释放学习促进者能量，陪伴赋能，帮助更多的学习爱好成为拆书家。\u003c/p>\u003cp>我今天给大家选取的拆页片段，来自管理学科的开创者 彼得·德鲁克所著的《卓有成效的管理者》。\u003c/p>\u003cp>请大家阅读一下我选取的拆页。大概两分钟左右，插页文字有点多，大家阅读完了以后，给我一个提示，我们再往下进行。\u003c/p>","ratings_count":1,"texts":[{"id":21299,"quote":"\u003cp>\u003cstrong>片段来自《卓有成效的管理者》P22-P23\u003c/strong>\u003c/p>\u003cp>记得小时候我的钢琴老师告诉我：“你弹莫扎特的曲子时，也许不可能像钢琴家施纳贝尔演奏得那样好，但是并没有理由说，你不必像施纳贝尔那样地练习音阶。”回想起来，我的钢琴老师显然少说了一句：最伟大的钢琴家，如果不肯辛勤演练，也一定无法演奏莫扎特的曲子。\u003c/p>\u003cp>也就是说，没有任何理由不让普通人通过练习来获得胜任某项工作的能力。当然，若要把什么东西演练到炉火纯青的地步是很不容易的，那也许需要有特殊的天赋。但卓有成效所要求的只是能够胜任，只是能演奏出音阶来。\u003c/p>\u003cp>下列五项是要成为一个卓有成效的管理者，必须在思想上养成的习惯：\u003c/p>\u003cp>1.有效的管理者知道他们的时间用在什么地方。他们所能控制的时间非常有限，他们会有系统地工作，来善用这有限的时间。\u003c/p>\u003cp>2.有效的管理者重视对外界的贡献。他们并非为工作而工作，而是为成果而工作。他们不会一接到工作就一头钻进去，更不会一开头就探究工作的技术和手段，他们会首先自问：“别人期望我做出什么成果？”\u003c/p>\u003cp>3.有效的管理者善于利用长处，包括自己的长处、上司的长处、同事的长处和下属的长处。他们还善于抓住有利形势，做他们想做的事。他们不会把工作建立在自己的短处上，也绝不会去做自己做不了的事。\u003c/p>\u003cp>4.有效的管理者集中精力于少数重要的领域，在这少数重要的领域中，如果能有优秀的绩效就可以产生卓越的成果。他们会按照工作的轻重缓急设定优先次序，而且坚守优先次序。他们知道：要事第一。重要的事先做，不重要的事放一放，除此之外也没有其他办法，否则反倒会一事无成。\u003c/p>\u003cp>5.最后，有效的管理者必须善于做有效的决策。他们知道有效的决策事关处事的条理和秩序问题，也就是如何按正确的次序采取正确的步骤。他们知道一项有效的决策，总是在“不同意见讨论”的基础上做出的判断，它绝不会是“一致意见”的产物。他们知道快速的决策多为错误的决策，真正不可或缺的决策数量并不多，但一定是根本性的决策。他们需要的是正确的战略，而不是令人眼花缭乱的战术。\u003c/p>\u003cp>以上这些就是管理者卓有成效的要素，也是本书的主题。\u003c/p>","explains":"\u003cp>我看到已经有小伙伴已经看完了。那我们现在继续往下进行？我会从四个维度阐述一下这个片段。\u003c/p>\u003cp>\u003cstrong>&lt;What（片段讲的是什么）&gt;\u003c/strong>\u003c/p>\u003cp>首先这个片段主要讲的是想要成为卓有成效的管理者需要在思想上养成五个习惯。\u003c/p>\u003cp>\u003cstrong>&lt;Why（为什么要这么做）&gt;\u003c/strong>\u003c/p>\u003cp>当下是快速变化，充满焦虑的时代，我们在工作生活中都有可能成为管理者。在工作中想要提高成就，就需要你更有成效。在想要生活更美好也亦是如此。想要卓有成效，不需要特殊的天赋，可以通过五个习惯养成就可以达到。\u003c/p>\u003cp>\u003cstrong>&lt;How&gt;（具体行动步骤）\u003c/strong>\u003c/p>\u003cp>1、管理、控制、善用时间：我们可以通过APP或者表格的记录自己的2,3周时间使用情况，通过记录分析时间应用情况，根据自己不同的需求调整时间的使用。\u003c/p>\u003cp>2、重视贡献，重视成果：做事情一开始就要考虑我能做出什么贡献？这个事情可以达到什么成果，以终为始，用结果为做事的导向。\u003c/p>\u003cp>3、善用长处：评估自己的优势、他人的优势。结合身边人的长处与优势，利用相关的人脉、资源推动事情的完成。\u003c/p>\u003cp>4、要事第一：在处理多重事务时要有轻重缓急，先后顺序。集中精力放在做重要的事情上。\u003c/p>\u003cp>5、利用不同意见做有效决策：有效的决策不是拍脑门的一言堂，是需通过不同的意见做充分的思考，有效的决策在精而不在多。\u003c/p>\u003cp>这五个习惯共同的目标都是“成效”，彼此之间是相互促进、互相依附的关系。\u003c/p>\u003cp>\u003cstrong>&lt;Where&gt;（适用的边界）\u003c/strong>\u003c/p>\u003cp>那这五个习惯的养成是适用于大多数的企业管理者，知识工作者，自我管理者的培养。不太适用于单纯的体力劳动者。需要思考决策时的使用。不适合休闲放松的状态。\u003c/p>","interaction":"\u003cp>通过这个片段，让我想到了我最近发生的一个事情。\u003c/p>\u003cp>\u003cstrong>&lt;A1便签&gt;\u003c/strong>\u003c/p>\u003cp>我去年参与了一个信息化资质的认证准备工作。这个筹备工作是从前年年底开始，而我参与到在这个工作是从去年的8月到10月。在我参与的这2个月中经历了2次开会开到凌晨，可还没有解决资料准备的问题。更有2个周末通宵加班梳理流程制度。但是筹备了这么久，资料和其他硬件条件还是没能上交审核……\u003c/p>\u003cp>通过对这个片段的学习我反思了这次工作没有达到目的得问题。\u003c/p>\u003cp>[反思]\u003c/p>\u003cp>1、“时间管理”有问题：这个筹备工作进行了近1年的时间，日常工作时间跟筹备工作时间严重冲突，像拍脑袋似的想起来就急忙开会，集同工作。\u003c/p>\u003cp>2、“重视成果”做的很不好：完成要比完美更重要，没有以结果做导向，没有明确完成的时间、完成形式，导致筹备了近1年还是没能达到评审条件。\u003c/p>\u003cp>3、没做到“善用长处”：没有找到已经过审的兄弟单位帮忙，自己摸索做了工作，导致不符合评审要求。\u003c/p>\u003cp>4、没有做到要事第一：没有重要紧急先行，没有排做事优先级，导致筹备工作混乱。\u003c/p>\u003cp>这些就是导致这次信息化资质没能上交审核的主要原因。\u003c/p>\u003cp>\u003cstrong>&lt;A2便签&gt;\u003c/strong>\u003c/p>\u003cp>经过了这一个片段的学习，我想到了下一步，我可以怎么改善我的工作。今年3月还有质量体系资质需要过.为了有成效完成质量体系资质认证过审，我们应围绕四个核心方面：时间管理、重视成果、善用团队长处和优先处理关键任务来做一个计划。\u003c/p>\u003cp>1.时间管理方面，从1月15日至1月29日详细记录团队的工作时间，制定具体时间节点，确保所有关键任务在3月25日之前完成。\u003c/p>\u003cp>2.在重视成果上，计划邀请经验丰富的兄弟单位的专家，明确关键过审条件和注意事项，为每个任务设定具体的完成标准。\u003c/p>\u003cp>3.善用团队成员长处，根据每个成员的专长和经验合理分配任务，确保每个人都能在其擅长领域内贡献力量，同时保证任务与过审目标紧密相关。\u003c/p>\u003cp>4.优先处理关键任务，按照紧急和重要性对任务进行分类，并为每类任务设定明确的完成日期。\u003c/p>\u003cp>\u003cstrong>&lt;强有力的结束语&gt;\u003c/strong>\u003c/p>\u003cp>今天我的分享就结束了。我选择这个《卓有成效的管理者》的片段，我在熟读了之后，我个人觉得它对我们的生活、对我们的工作其实有很大的一个指导作用。比如说在“时间管理上面”，在“要事第一”上面，在“善用他人长处这方面”。只要我们把这些能够很好的使用，结合到我们的生活，工作中，那对于我们的效率，它会有一个特别大的提升。而且对于这个结果贡献程度，重视结果的这一个层次，那么以结果做导向的话，也可以让我们无论做什么事情。导向度完整度。真正可以成事儿的状态也都会大幅的提高。我是希望通过片段的拆解，希望可以给小伙伴们带来生活上面和工作上面更有成效的一点建议。然后大家也可以通过这些片段，自己更深层的思考一下，我们自己觉得缺少效率，需要有改进的可以用到这哪些方面上面，我觉得只要能够有一点点的收获，一点点的体会。那也是觉得这个能够给我们带来最好的收获。\u003c/p>\u003cp>特别感谢大家今天能够一起来对聆听对于这一个片段的分享，也是希望在今后的工作和生活中，可以给大家的提升效率变得更加的卓有成效。能带来更好的这种收获。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1704518789000,"updated_at":1705294305000,"ria":true},{"id":16893,"topic":"如何管理好上司","learn_goal":"","remark":"如果能管理好自己的上司，\n即可以获得更多的资源支持，\n又能更好地明确自己的工作目标和重点，\n让个人的工作更有成效。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"张瑛","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>一、自我介绍\u003c/strong>\u003c/p>\u003cp>大家好！我是张瑛\u003c/p>\u003cp>通常初次见面会问对方“您贵姓”，对方会回应“免贵”，\u003cstrong>张\u003c/strong>姓是唯一一个不用说“免贵”的姓，因为张姓是第一贵姓；\u003cstrong>瑛\u003c/strong>，是指玉的光芒，寓意美丽温柔。名字听上去很\u003cstrong>儒雅\u003c/strong>，实际上我的性格豪爽\u003cstrong>大气\u003c/strong>。我是生活在江南20年的东北人张瑛，很高兴认识大家。\u003c/p>\u003cp>三个标签介绍下我自己：\u003c/p>\u003cp>1. 我是\u003cstrong>拆\u003c/strong>书帮新会员，拆书家新晋起跑者；\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>本职\u003c/strong>工作是人才测评咨询师、培训师，可以提供用测评工具识人识己的专业服务、帮助大家更好地认知自己和他人，取长补短地提升能力；\u003c/p>\u003cp>3. 我会持续\u003cstrong>致力\u003c/strong>于职场人士思维升级和能力提升，助力职场人士解决各种职场难题。\u003c/p>\u003cp>\u003cstrong>二、拆书和拆书帮介绍\u003c/strong>\u003c/p>\u003cp>“拆书”的“拆”不是“拆散”，而是“拆为己用”，它是解决成人如何学以致用的\u003cstrong>方法论\u003c/strong>，强调成人学习要对\u003cstrong>学习者的目标和要解决的问题\u003c/strong>负责，而不是对知识负责。\u003c/p>\u003cp>“拆书法”分为\u003cstrong>个人学习拆书法\u003c/strong>和\u003cstrong>组织学习拆书法\u003c/strong>：\u003c/p>\u003cp>个人学习方面是RIA便签法，R即书中片段原文，I即用自己的话对原文理解重述，A即通过关联自身经验、反思针对原文片段中的技能规划使用目标和落地行动计划；\u003c/p>\u003cp>组织学习方面是拆书家现场引导组织的人员对书中知识进行转化应用，以解决工作生活中的问题，效果相当于一场培训师的培训课程。\u003c/p>\u003cp>“拆书帮”是爱学习的\u003cstrong>青年人士基于拆书法组建的社群\u003c/strong>，全国各地有多个\u003cstrong>分舵\u003c/strong>，以\u003cstrong>非营利\u003c/strong>的形式帮助运用拆书法的学习爱好者一步步提升能力并成长为拆书家。\u003c/p>\u003cp>\u003cstrong>基于以上\u003c/strong>，如果你想提高自己的学习效果，建议了解和使用个人学习拆书法；如果你想通过自身促进他人学习并更好地落地转化应用，建议通过学习成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":21017,"quote":"\u003cp>那现在就由我来带领大家拆解一下今天的片段。\u003c/p>\u003cp>摘自《卓有成效的管理者》P91 第四章“如何发挥人的长处”之如何管理上司 \u003c/p>\u003cp>下面我们花1分钟时间看一下原文片段，看完后请抬头示意我一下。\u003c/p>\u003cp>有效的管理者了解他的上司也是人（然而年轻的下属却不容易有hx 了解）。上司既然是人，所以肯定有其长出，也肯定有其短处。若能在上司的长处上下功夫，协助他做好想做的工作，便能使上司有效，下属也才能有效。反之，如果下属总强调上司的短处，那就像上司强调下属的短处一样，结果将一无所成。\u003c/p>\u003cp>所以，有效的管理者常问：“我的上司究竟能做些什么？他曾有过什么成就？要使他发挥他的长处，他还需要知道些什么？他需要我完成什么？”至于上司不能做些什么，那就不必细究了。\u003c/p>","explains":"\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>职场中学会“如何管理上司”是个非常重要的技能，拆页片段给我们提供了一个“列优势、明目标、写计划”的方法，可以解决职场人士不知如何管理上司的问题。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>我们要知道，上司作为我们的上级，他（她）的视野和思考维度更多时候会高于我们，作为下级如果不能“管理好上司”，不能很好地理解上级的目标和要求，按照自己的理解去做，很可能个人的目标和上司所要求的目标是不一致的，导致自己瞎忙一场却拿不到好的结果，浪费了自己的时间精力，长此以往，非常不利于个人的职业发展。如果能管理好自己的上司，既可以获得更多的资源支持，同时也能保证自己的工作目标和重点与上司一致，使自己的工作更有成效。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>如何管理好上司呢？通常可以这样做：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>列优势\u003c/strong>\u003c/p>\u003cp>列出自己上司的成就和优势。\u003c/p>\u003cp>如：我的上司曾在行业前三的公司担任过技术总监，他对公司产品和技术有非常高的专业度，因此在商务展示时给客户的体验感非常好。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>明目标\u003c/strong>\u003c/p>\u003cp>明确上司近期要实现的工作目标。\u003c/p>\u003cp>如：作为上海销售公司的老大，上司希望我们的销售团队能用专业度吸引打动更多大客户，拿下集团年度销售冠军。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>写计划\u003c/strong>\u003c/p>\u003cp>写出自己为了协助上司达成工作目标所能实施的工作计划。\u003c/p>\u003cp>如：我要向上司请教如何在1个月之内快速提升自己的专业度；盘点手上大客户，制定并推进大客户的开发计划，邀请上司协助拜访客户高层。\u003c/p>\u003cp>通过以上一系列步骤，可以将自己和上司的目标紧密关联，保持高度协同，让自己的工作更有成效，同时也可以拉近和上司的关系，让上司看到你积极的工作态度。 \u003c/p>\u003cp>\u003cstrong>Where\u003c/strong>\u003c/p>\u003cp>这样一种管理上司的方法，适用于职场中绝大多数情况下和上司的相处及协同，但同时也要根据上司的不同风格在方式上灵活运用，比如上司特别强调授权，喜欢下属独立完成工作，就要注意和上司请教及邀请上司协助的频次和时机的问题。同时，明确目标时，要注意确认目标的准确性，当自己拿不准时，要想办法和上司确认共识。\u003c/p>","interaction":"\u003cp>记得初入职场第二年，有一天约了一个跟进了很久的客户要去面谈，这时上司要临时召集销售部门开会，我当时觉得客户为大，而且我是提前一天就和客户约好了的，我可以不参加公司临时会议，但绝不能耽误和客户的会面。正准备出门时，上司突然板着脸过来，声音很大地说：“过来开会！’，我理直气壮地说：“我约了客户！”“约了客户也不行！”，会议上上司非常 生气地批评了我的行为，我当时真是觉得很尴尬，心里也火大得不行，心想：会议重要还是客户重要？ 自那以后，和上司的关系也一直不是很融洽。\u003c/p>\u003cp>\u003cstrong>反思：\u003c/strong>\u003c/p>\u003cp>现在想想，当时自己的行为是很不成熟的，也是很不正确的。\u003c/p>\u003cp>1. 作为下属，和上司当面顶撞是不职业的表现；\u003c/p>\u003cp>2. 自己认为客户最重要，但那个时刻上司一定是有比某个客户更重要的事，我考虑的是我个人，而上司是站在整个部门的角度，我没有以上司的目标为自己的目标；\u003c/p>\u003cp>3. 没有根据上司要实现的目标开展自己的工作，而是以自己的理解去开展工作，即使自己认为很努力，但依然得不到上司的认可。\u003c/p>\u003cp>基于这样管理上司的步骤方法，我准备接下来这样做：\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>\u003c/p>\u003cp>11月5日之前和黄老师沟通确认2023年最后2个月市场活动计划\u003c/p>\u003cp>\u003cstrong>行动计划：\u003c/strong>\u003c/p>\u003cp>1．11月1日依据黄老师在管理咨询中的核心优势，结合当下客户痛点，梳理罗列出优势课题；\u003c/p>\u003cp>2．11月2日和黄老师沟通确认工作室明年的发展目标；\u003c/p>\u003cp>3．根据发展目标制定出11月-12月的市场活动规划；\u003c/p>\u003cp>4．11月4日和黄老师确认工作室市场活动规划；\u003c/p>\u003cp>5．11月5日基于11月-12月市场活动规划，制定个人详细工作计划。\u003c/p>\u003cp>6．完成此目标及计划，周日晚上吃火锅庆祝。\u003c/p>\u003cp>我今天的分享就到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1699939255000,"updated_at":1700096018000,"ria":true},{"id":16695,"topic":"卓有成效的管理","learn_goal":"","remark":"晋级","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"陈璐","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>请问观察家老师拿到记录表、准备表了么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>好，现在正式开始今天的拆解。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>自我介绍\u003c/strong>：\u003c/p>\u003cp>感谢大家抽出宝贵时间陪我晋级2-3，我是陈璐，我用三个标签介绍自己。\u003c/p>\u003cp>爱旅游、爱学习、爱分享。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>由于今天有讨论环节，所以我等会会根据现场人数进行分组。\u003c/p>\u003cp>图书介绍\u003c/p>\u003cp>\u003cstrong>Feature：特征\u003c/strong> \u003c/p>\u003cp>今天给大家带来的是彼得·德鲁克《卓有成效的管理者》，这本书已被翻译成二十多种语言，是世界上众多企业管理者的必读书籍。\u003c/p>\u003cp>\u003cstrong>Advantage：优势 \u003c/strong>\u003c/p>\u003cp>与其他的管理书籍相比它非常实用，书中的内容来自现实生活中的案例，诠释的却是鲜活的思想，读起来让人非常的享受，爱不释手。\u003c/p>\u003cp>\u003cstrong>Benefit：价值\u003c/strong> \u003c/p>\u003cp>每个人都想成为卓有成效的管理者，那成为卓有成效的管理者要学会管理自己的时间，很多人一年到头在年终述职时，发现年初制定的目标没有达成，却每天异常的忙碌，到底是那里出了问题，看了这本书你都可以从书中找到问题的症结。\u003c/p>\u003cp>在工作和生活中，不知道大家是不是有过这样的感受：时间经常感觉不够用，每天忙忙碌碌，甚至有时候焦头烂额，可是也没见自己忙出什么结果。在遇到这些情况的时候，我们利用书中的时间管理四步法，可以帮助我们有效管理时间。\u003c/p>\u003cp>学习目标：\u003c/p>\u003cp>在跟随我完成本次现场学习后，学习者能够在忙碌的工作中，不是花时间在毫无成效的事物上，而是在未来一周使用1次时间管理四步法提升工作效率。\u003c/p>","ratings_count":1,"texts":[{"id":20813,"quote":"\u003cp>拆解片段来自书籍《卓有成效的管理者 》---本次主题《掌握自己的时间 》。\u003c/p>\u003cp>作者：彼得.德鲁克   页码（P24）\u003c/p>\u003cp>【R：阅读原文片段】\u003c/p>\u003cp>关于管理者任务的讨论，一般都从如何做计划说起。这样看来很合乎逻辑。可惜的是管理者的工作计划，很少真正发生作用。计划通常只是纸上谈兵，或只是良好的意愿，很少能够真正实现。\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：记录时间；管理时间；统一安排时间。\u003c/p>","explains":"\u003cp>好，我看到大家已经示意我看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个方法是教大家如何管理自己的时间，以便提升工作效率。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>因为零散的时间是不足以解决重要的问题的，只有做好时间管理，才能集中时间和精力专注做事，才能更好的完成组织目标。\u003c/p>\u003cp>如何更好的掌握时间管理的方法呢？根据拆页中作者的建议细化成四个步骤：\u003c/p>\u003cp>\u003cstrong>【细化步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>①记录时间\u003c/strong>\u003c/p>\u003cp>需要花一段时间跟踪自己在工作期间的时间，并且最好以0.5小时为单位，记录每个时间段做的事情；\u003c/p>\u003cp>\u003cstrong>②分析时间\u003c/strong>\u003c/p>\u003cp>分析目前的时间安排的现状是怎么样的：分析用在工作中的时间的占比，哪些工作是被别人打断导致断断续续的做的，哪些是用连续的大块时间完成的，哪些是琐事，哪些是与工作无关的事儿，比如：聊天、刷短视频、刷微博；生理需求时间如喝水、上厕所等；\u003c/p>\u003cp>\u003cstrong>③管理时间\u003c/strong>\u003c/p>\u003cp>减少跟工作无关的时间，就是说对工作成果没有帮助的就需要减少，但是正常的生理需求时间或者临时的突发状况除外；\u003c/p>\u003cp>\u003cstrong>④安排计划\u003c/strong>\u003c/p>\u003cp>将节省的零碎时间集中成大块和连续性的时间，根据工作计划在这个时间段内专注的做重要的事情。 \u003c/p>\u003cp>连续性大块时间书中作者的解释是：1.5个小时是比较合理的时段值。 \u003c/p>\u003cp>\u003cstrong>【举个正向成功的例子】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>①记录时间\u003c/strong>\u003c/p>\u003cp>记录一周的工作期间的时间安排：\u003c/p>\u003cp>打印表格打印给大家：\u003c/p>\u003cp>\u003cstrong>②分析时间\u003c/strong>\u003c/p>\u003cp>1.目前的时间安排现状是：\u003c/p>\u003cp>一周下来\u003cstrong>工作\u003c/strong>时间占比仅仅33.75%，开会22.5%，非工作时间（发呆、改逐字稿）11.25%，与同事&amp;领导闲聊10.63%，生理需求6.88%，短视频6.25%；\u003c/p>\u003cp>2.重要的事情是：\u003c/p>\u003cp>工作时间占比33.75%所做的工作就是重要的事；\u003c/p>\u003cp>3.接着找出大块时间花在哪些地方：\u003c/p>\u003cp>这周我的大块连续的时间占比27.5%，开会7小时、工作2小时、培训2小时；但是用于工作中的仅仅5%，所以需要增加大块连续时间；\u003c/p>\u003cp>\u003cstrong>③管理时间\u003c/strong>\u003c/p>\u003cp>减少跟工作无关的时间：\u003c/p>\u003cp>A. 可以做到直接不看短视频，减少时间2.5小时；\u003c/p>\u003cp>B. 减少与同事和朋友聊天的时间，由2.5减至1.5小时，节约1小时；\u003c/p>\u003cp>C. 可以减少非工作时间里面的改逐字稿，节约1.5小时；\u003c/p>\u003cp>这里一共节省了5小时。\u003c/p>\u003cp>\u003cstrong>④安排计划\u003c/strong>\u003c/p>\u003cp>将上个步骤中节省的时间，安排成大块连续的时间，重新调整安排工作计划，集中时间专注的做事。\u003c/p>\u003cp>1.每天与同事朋友闲聊的时间段可以放在11：30-12：00期间；\u003c/p>\u003cp>2.那原本与朋友和同事闲聊的时间段就可以连成大块的时间，用于专注的做重要的事；\u003c/p>\u003cp>3.原本工作期间改逐字稿的时间就是大块连续的时间，可直接用于工作；\u003c/p>\u003cp>经过调整后，具体安排如下：\u003c/p>\u003cp>打印表格打印给大家：\u003c/p>\u003cp>使用时间管理四步法调整之后，工作时间环比上升46%，大块连续工作时间环比上升525%。闲聊、非工作时间、短视频时间环比降低。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>① 可能有的伙伴有疑问了，我不是管理层适用这个方法吗？原文作者提到的“管理者”不仅包括公司管理层，还包括普通员工或者其他个体，只要我们与人交流沟通、社会上做事儿，就具备“自我管理”的条件，就是一个“管理者”；\u003c/p>\u003cp>② 有的人先做工作计划，也能很好的完成组织目标。当然做计划可以完成目标，但两者并不矛盾，时间管理好，效率会更高。\u003c/p>\u003cp>③ 有的小伙伴会说，我知道“时间安排”很重要，可按你的方法，这也太麻烦了。常言道磨刀不误砍柴工，有了详细的时间记录，通过简单的分析，就能知道怎样合理安排时间，提高做事效率。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>时间管理方法适用于很多场合，比如职场管理者与普通员工、生活规划、家庭安排等，都是跟时间管理息息相关，所以都可以对时间进行有效管理。\u003c/p>","interaction":"\u003cp>\u003cstrong>【场景描述】\u003c/strong>\u003c/p>\u003cp>那我们如何把这时间管理四步骤用起来呢，今天我设计了一个场景：\u003c/p>\u003cp>某公司的小美每天的工作都很多，她感觉自己每天茫茫碌碌，可是经常只能把事情匆忙做完而没有做好，甚至有时候都完成不了所以很焦虑。\u003c/p>\u003cp>\u003cstrong>【A3指令】\u003c/strong>\u003c/p>\u003cp>任务：小美如何使用时间管理四步法有效管理自己的时间。因为使用这个方法需要长期记录一段时间，今天由于时间关系，只提供记录了三天的数据。\u003c/p>\u003cp>假设学习者杜开心是小美，大家讨论小美的时间管理出了哪些问题，结合今天现场学到的知识点-时间管理四步法，给出一个解决方案。请大家在小组内讨论一下，如何使用今天我给大家拆解的四个步骤管理时间呢？讨论的时间是7分钟，讨论结束后请一位小伙伴上来给大家进行分享-解决方案。\u003c/p>\u003cp>好，现在开始邀请一位伙伴来进行分享。\u003c/p>\u003cp>杜开心：\u003c/p>\u003cp>分析时间：\u003c/p>\u003cp>占比最大的是非工作占比20.8%，占比第二的是工作19.7%，占比第三的是闲聊15.6%，其次是刷微博和开会各12.5%。\u003c/p>\u003cp>管理时间：\u003c/p>\u003cp>减少刷微博和同事闲聊的时间；\u003c/p>\u003cp>安排计划：\u003c/p>\u003cp>把事项调整顺序，让连续工作的时间更长一点，比如把10点到11点的时间砍掉。\u003c/p>\u003cp>感谢今天所有人的分享，通过大家的实践，我们更加清晰的掌握时间管理四步骤，首先要记录自己较长周期内的时间，其次再分析目前对时间安排的现状是怎么样的，找出重要的事情；然后再减少与工作无关的时间；最后集中精力和时间专注的做事。\u003c/p>\u003cp>以上就是我今天TF2-3拆书分享的全部内容，感谢观察家，感谢各位小伙伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1695732188000,"updated_at":1696840528000,"ria":true},{"id":16331,"topic":"认识你的时间","learn_goal":"","remark":"认识你的时间，做时间的主人。","level":"TF1-1","duration":30,"status":19,"type":0,"chaishujia":{"username":"英英2003","city":"珠海市"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>&lt;自我介绍&gt;\u003c/p>\u003cp> 大家好，我叫英英，古诗词里译作轻盈明亮的样子。\u003c/p>\u003cp>用三个标签介绍自己。\u003c/p>\u003cp>1. 我是学前教育工作者，专注培养祖国花朵20年。\u003c/p>\u003cp>2.拆书帮东莞乐享分舵的会员，准拆书家。\u003c/p>\u003cp>3.志愿成为学习促进者，提升专业能力。\u003c/p>\u003cp>&lt;拆书帮介绍&gt;\u003c/p>\u003cp> “拆书”一词，最早源于赵周老师的畅销书《这样读书就够了》，“拆”不是“拆散”是转化和内化。\u003c/p>\u003cp> “拆书法”是赵周老师通过自己不断的实践总结出来的一种适用于成年人阅读图书的知识拆页转化为学习者的能力学习方法。拆书法强调以学习者为中心，用知识关联学习者的经验，规划具体的运用场景。分为运用于个人学习的“RIA便签读书法”和应用于组织学习的“RIA现场学习”法。\u003c/p>\u003cp>【R】 【I】 【A】\u003c/p>\u003cp>Reading-Interpretation-Appropriation\u003c/p>\u003cp>【R】 环节是阅读原书拆页 \u003c/p>\u003cp>【I】 环节是拆书家对原文知识拆页的讲解和对现场学习者的引导 \u003c/p>\u003cp>【A】 环节是拆为己用\u003c/p>\u003cp> 个人学习通过运用RIA便签学习法，让人读一本致用类图书就能达到参加同主题培训的效果。\u003c/p>\u003cp> 组织学习依靠RIA现场学习，由拆书家将一本书加工成一场现场培训，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp> “拆书帮”是基于拆书法的学习爱好者社群，表现为各地拆书帮分舵（也称为拆书帮俱乐部）。拆书帮分舵是由青年自发组织的非营利性组织。\u003c/p>\u003cp>拆书帮的使命\u003c/p>\u003cp>培养拆书家，“释放学习促进者的能量”，帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>拆书帮的愿景\u003c/p>\u003cp>帮助拆书家们升级学习力和促进他人学习的能力，影响身边的人，让世界变得更好一点。\u003c/p>\u003cp>拆书帮的价值观\u003c/p>\u003cp>倡导陪伴赋能、拆为己用、反求诸己、持续精进、共同成长的价值观。\u003c/p>","ratings_count":1,"texts":[{"id":20439,"quote":"\u003cp>来自彼得·德鲁克的《卓有成效的管理者》第41页\u003c/p>\u003cp> 认识你的时间\u003c/p>\u003cp>谈到管理者的任务，很多讨论都是建议从做工作计划入手。这听起来特别有道理，但唯一不对劲的地方就是这么做很少管用。计划总是停留在纸上，始终只是良好的愿望，很少兑现。\u003c/p>\u003cp>依我的观察，有效管理者不是从工作任务入手，而是从时间入手。他们首先做的不是制订工作计划，而是弄清楚自己的时间都花在了什么地方。然后，他们努力管好自己的时间，拒绝那些不会带来成效的时间要求。最后，他们把自己的“可支配时间”集中成尽量大块的连续时段。这个三步法包括：\u003c/p>\u003cp>·记录时间\u003c/p>\u003cp>·管理时间 \u003c/p>\u003cp>·集中时间\u003c/p>","explains":"\u003cp>&lt;What(知识点和相关了理念介绍)&gt;\u003c/p>\u003cp>这段话讨论了管理者仅仅依赖于工作计划，很难提高工作效率。有效的管理者首先要了解自己的时间都花在了哪些地方，然后努力管理好自己的时间，拒绝那些不会带来成效的时间要求。最后，他们将自己的可支配时间集中成尽量大块的连续时段来提高效率。\u003c/p>\u003cp>&lt;Why（前因后果、为什么要这么做，不这么做会有哪些糟糕的后果等）&gt;\u003c/p>\u003cp>为什么需要用这个三步法管理时间？\u003c/p>\u003cp>因为时间是管理者最宝贵的资源，也是管理者最容易浪费的资源。通过记录时间、管理时间和集中时间，管理者可以更好地掌控自己的时间，提高工作效率，实现目标。\u003c/p>\u003cp>&lt;Where（适用边界）&gt;\u003c/p>\u003cp>时间管理三步法适用于有意向珍惜时间，合理运用时间、提高时间有效性的每个人。\u003c/p>\u003cp>&lt;How&gt;\u003c/p>\u003cp>如何做到有效管理时间呢？\u003c/p>\u003cp>片段中提到了三个步骤：\u003c/p>\u003cp>第一步：记录时间\u003c/p>\u003cp> 首先，记录时间是管理者有效管理时间的第一步。通过记录时间，管理者可以了解自己每天都在做些什么，哪些活动占据了大部分时间，哪些活动是浪费时间的。这样的记录可以帮助管理者认识到自己的时间分配是否合理，有针对性地进行时间管理。可以借助日历或计划表手机或电脑上的应用程序如幕布记录时间。\u003c/p>\u003cp>第二步：管理时间 \u003c/p>\u003cp> 其次，管理时间是有效管理者的核心能力之一。管理者可以运用效能分析四象限将工作任务分类成重要且紧急、重要但不紧急、不重要但紧急、不重要且不紧急分为四类，确保首先处理重要且紧急和紧急且重要的任务，并在时间有限的情况下合理安排其他任务。将时间花在对组织和团队有最大价值的事情上。管理时间还有很重要的一点是，停止做浪费别人时间的事。\u003c/p>\u003cp>第三步：集中时间\u003c/p>\u003cp> 集中时间是管理者有效利用时间的关键。管理者在这里推荐时间分块法将时间划分为特定的时间段，并为每个时间段分配特定的任务或活动。这种方法可以帮助我们集中精力并避免在不同任务之间分心。帮助管理者进入工作状态，集中精力完成任务，提高效率和工作质量。在实际运用中，我们可以根据自己的情况对其进行调整，自己的时间自己做主。\u003c/p>","interaction":"\u003cp>&lt;A1便签&gt;\u003c/p>\u003cp> 对于幼教工作者来说，时间不够用，每天有忙不完的事，检查班本主题框架，班级材料投放、跟老师讨论班本主题方案，各种计划……我真的恨不得像孙悟空那样，拔几根头发出来，变出多几个分身来。我反思，是什么原因导致我这么忙？并下决心我要提升时间管理能力，我尝试着翻看彼得·德鲁克的《卓有成效的管理者 》，他在书中写到管理者可以用三步法认识自己的时间，清楚自己的时间花在哪里。从2月份开始，我有意识地去记录了20个工作日的下班的时间和导致没有准时下班的事由。3月份记录了17个工作日，4月份记录了6个工作日，5月份记录了5个工作日，6月份记录了3个工作日。记录的时间跨了5个月，每月记录的天数是坐滑梯的下降的。当时还没有接触拆书，不知道拆书帮，只会照本宣科的用幕布记录。一些事情。6月底加入了拆书帮，开始升级打怪之旅，我再找出了这本书，选择了这个片段，去准备拆书预备表，分析拆页里的时间管理三步法，我之只做了记录时间，记录的时间跨度大，很难坚持下来。记录的内容不够全面，导致我难以了解时间都花在了什么地方，更谈不上运用效能分析四象限去厘清事情的轻重缓急，将时间进行集中管理，找到我的大块连续可支配时间了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":20440,"quote":"\u003cp>来自彼得·德鲁克的《卓有成效的管理者》第41页\u003c/p>\u003cp> 认识你的时间\u003c/p>\u003cp>谈到管理者的任务，很多讨论都是建议从做工作计划入手。这听起来特别有道理，但唯一不对劲的地方就是这么做很少管用。计划总是停留在纸上，始终只是良好的愿望，很少兑现。\u003c/p>\u003cp>依我的观察，有效管理者不是从工作任务入手，而是从时间入手。他们首先做的不是制订工作计划，而是弄清楚自己的时间都花在了什么地方。然后，他们努力管好自己的时间，拒绝那些不会带来成效的时间要求。最后，他们把自己的“可支配时间”集中成尽量大块的连续时段。这个三步法包括：\u003c/p>\u003cp>·记录时间\u003c/p>\u003cp>·管理时间 \u003c/p>\u003cp>·集中时间\u003c/p>","explains":"\u003cp>&lt;What(知识点和相关了理念介绍)&gt;\u003c/p>\u003cp>这段话讨论了管理者仅仅依赖于工作计划，很难提高工作效率。有效的管理者首先要了解自己的时间都花在了哪些地方，然后努力管理好自己的时间，拒绝那些不会带来成效的时间要求。最后，他们将自己的可支配时间集中成尽量大块的连续时段来提高效率。\u003c/p>\u003cp>&lt;Why（前因后果、为什么要这么做，不这么做会有哪些糟糕的后果等）&gt;\u003c/p>\u003cp>为什么需要用这个三步法管理时间？\u003c/p>\u003cp>因为时间是管理者最宝贵的资源，也是管理者最容易浪费的资源。通过记录时间、管理时间和集中时间，管理者可以更好地掌控自己的时间，提高工作效率，实现目标。\u003c/p>\u003cp>&lt;Where（适用边界）&gt;\u003c/p>\u003cp>时间管理三步法适用于有意向珍惜时间，合理运用时间、提高时间有效性的每个人。\u003c/p>\u003cp>&lt;How&gt;\u003c/p>\u003cp>如何做到有效管理时间呢？\u003c/p>\u003cp>片段中提到了三个步骤：\u003c/p>\u003cp>首先，记录时间是管理者有效管理时间的第一步。\u003c/p>\u003cp>通过记录时间，管理者可以了解自己每天都在做些什么，哪些活动占据了大部分时间，哪些活动是浪费时间的。这样的记录可以帮助管理者认识到自己的时间分配是否合理，有针对性地进行时间管理。可以借助日历或计划表手机或电脑上的应用程序如幕布记录时间。\u003c/p>\u003cp>第二步：管理时间 \u003c/p>\u003cp> 其次，管理时间是有效管理者的核心能力之一。管理者可以运用效能分析四象限将工作任务分类成重要且紧急、重要但不紧急、不重要但紧急、不重要且不紧急分为四类，确保首先处理重要且紧急和紧急且重要的任务，并在时间有限的情况下合理安排其他任务。将时间花在对组织和团队有最大价值的事情上。管理时间还有很重要的一点是，停止做浪费别人时间的事。\u003c/p>\u003cp>第三步：集中时间\u003c/p>\u003cp>集中时间是管理者有效利用时间的关键。管理者在这里推荐时间分块法将时间划分为特定的时间段，并为每个时间段分配特定的任务或活动。这种方法可以帮助我们集中精力并避免在不同任务之间分心。帮助管理者进入工作状态，集中精力完成任务，提高效率和工作质量。在实际运用中，我们可以根据自己的情况对其进行调整，自己的时间自己做主。\u003c/p>","interaction":"\u003cp>&lt;A1便签&gt;\u003c/p>\u003cp> 对于幼教工作者来说，时间不够用，每天有忙不完的事，检查班本主题框架，班级材料投放、跟老师讨论班本主题方案，各种计划……我真的恨不得像孙悟空那样，拔几根头发出来，变出多几个分身来。我反思，是什么原因导致我这么忙？并下决心我要提升时间管理能力，我尝试着翻看彼得·德鲁克的《卓有成效的管理者 》，他在书中写到管理者可以用三步法认识自己的时间，清楚自己的时间花在哪里。从2月份开始，我有意识地去记录了20个工作日的下班的时间和导致没有准时下班的事由。3月份记录了17个工作日，4月份记录了6个工作日，5月份记录了5个工作日，6月份记录了3个工作日。记录的时间跨了5个月，每月记录的天数是坐滑梯的下降的。当时还没有接触拆书，不知道拆书帮，只会照本宣科的用幕布记录。一些事情。6月底加入了拆书帮，开始升级打怪之旅，我再找出了这本书，选择了这个片段，去准备拆书预备表，分析拆页里的时间管理三步法，我之只做了记录时间，记录的时间跨度大，很难坚持下来。记录的内容不够全面，导致我难以了解时间都花在了什么地方，更谈不上运用效能分析四象限去厘清事情的轻重缓急，将时间进行集中管理，找到我的大块连续可支配时间了。\u003c/p>\u003cp>&lt;A2便签&gt;\u003c/p>\u003cp>目标：\u003c/p>\u003cp>在2023年8月28至9月30日期间24个工作日里以周为单位，学习运用时间三步法记录时间、管理时间、集中时间，提高工作效率。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>首先，记录时间。\u003c/p>\u003cp>了解自己在每天工作中花费的时间是至关重要的。这里以教学周为单位，制定了记录时间和管理、集中时间的安排。借助幕布记录第一周至第周五各项任务和所花费的时间。\u003c/p>\u003cp>第二步是管理时间。\u003c/p>\u003cp>一旦我们了解了自己的时间使用情况，就可以开始优化和管理时间。每周六，即计划里的9月2日、9日、16日、23日和30日，儿子上兴趣班的四个小时里，运用效能分析四象限将当周记录的内容分为重要且紧急、重要但不紧急、不重要但紧急、不重要且不紧急分为四类。\u003c/p>\u003cp>1. 重要且紧急的事\u003c/p>\u003cp>我们要非常重视，并立即去做，直到问题解决或任务完成时止。这有助于避免重要事项被忽视或延迟处理，保证组织的正常运转。\u003c/p>\u003cp>2.重要不紧急的事\u003c/p>\u003cp>对组织的长期发展和目标实现至关重要，提前规划，用更长时间完成。合理安排时间和资源，管理者可以确保这些任务得到充分关注和处理。\u003c/p>\u003cp>3.不重要但紧急的事\u003c/p>\u003cp>这类事务也需要管理者赶快处理，但不宜花去过多的时间，最好是委派给其他人处理。把别人能做的事，全部分出去，把时间留下来做自认为重要的、自己想做的、自己有义务去做的各种事情。\u003c/p>\u003cp>4.不重要不紧急的事\u003c/p>\u003cp>识别先想一想：这件事如果根本不去理会，会出现什么情况呢？如果答案是“什么事都没发生。”，证明这些活动对组织的发展和绩效没有实质性的贡献，因此应该尽量避免或减少。\u003c/p>\u003cp> 浪费别人时间的事，如手工制作背景墙，无意义的文案撰写，不去做。\u003c/p>\u003cp> 第三步：集中时间\u003c/p>\u003cp> 集中时间是管理者有效利用时间的关键。利用时间分块法，可以集中大块的时间。如以65分钟为单位切分工作时间。前60分钟，集中精力做好一项工作，由于工作的特殊，第一个周期用15分钟来吃早餐并跟园长沟通各项事宜。第二周期，第三周期休息5分钟，第四周期完成后，刚好到下班时间。如在一个周期里，不用60分钟就完成了工作，可以先休息5分钟，然后复盘待完成事项清单，挑选新任务，重新使用时间分块法完成新任务。下午的大家看看，就不详细说明了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":20441,"quote":"\u003cp>来自彼得·德鲁克的《卓有成效的管理者》第41页\u003c/p>\u003cp> 认识你的时间\u003c/p>\u003cp>谈到管理者的任务，很多讨论都是建议从做工作计划入手。这听起来特别有道理，但唯一不对劲的地方就是这么做很少管用。计划总是停留在纸上，始终只是良好的愿望，很少兑现。\u003c/p>\u003cp>依我的观察，有效管理者不是从工作任务入手，而是从时间入手。他们首先做的不是制订工作计划，而是弄清楚自己的时间都花在了什么地方。然后，他们努力管好自己的时间，拒绝那些不会带来成效的时间要求。最后，他们把自己的“可支配时间”集中成尽量大块的连续时段。这个三步法包括：\u003c/p>\u003cp>·记录时间\u003c/p>\u003cp>·管理时间 \u003c/p>\u003cp>·集中时间\u003c/p>","explains":"\u003cp>&lt;What(知识点和相关了理念介绍)&gt;\u003c/p>\u003cp>这段话讨论了管理者仅仅依赖于工作计划，很难提高工作效率。有效的管理者首先要了解自己的时间都花在了哪些地方，然后努力管理好自己的时间，拒绝那些不会带来成效的时间要求。最后，他们将自己的可支配时间集中成尽量大块的连续时段来提高效率。\u003c/p>\u003cp>&lt;Why（前因后果、为什么要这么做，不这么做会有哪些糟糕的后果等）&gt;\u003c/p>\u003cp>为什么需要用这个三步法管理时间？\u003c/p>\u003cp>因为时间是管理者最宝贵的资源，也是管理者最容易浪费的资源。通过记录时间、管理时间和集中时间，管理者可以更好地掌控自己的时间，提高工作效率，实现目标。\u003c/p>\u003cp>&lt;Where（适用边界）&gt;\u003c/p>\u003cp>时间管理三步法适用于有意向珍惜时间，合理运用时间、提高时间有效性的每个人。\u003c/p>\u003cp>&lt;How&gt;\u003c/p>\u003cp>如何做到有效管理时间呢？\u003c/p>\u003cp>片段中提到了三个步骤：\u003c/p>\u003cp>第一步：记录时间\u003c/p>\u003cp> 记录时间是管理者有效管理时间的第一步。通过记录时间，管理者可以了解自己每天都在做些什么，哪些活动占据了大部分时间，哪些活动是浪费时间的。这样的记录可以帮助管理者认识到自己的时间分配是否合理，有针对性地进行时间管理。可以借助日历或计划表手机或电脑上的应用程序如幕布记录时间。\u003c/p>\u003cp>第二步：管理时间 \u003c/p>\u003cp> 其次，管理时间是有效管理者的核心能力之一。管理者可以运用效能分析四象限将工作任务分类成重要且紧急、重要但不紧急、不重要但紧急、不重要且不紧急分为四类，确保首先处理重要且紧急和紧急且重要的任务，并在时间有限的情况下合理安排其他任务。将时间花在对组织和团队有最大价值的事情上。管理时间还有很重要的一点是，停止做浪费别人时间的事。\u003c/p>\u003cp>第三步：集中时间\u003c/p>\u003cp> 集中时间是管理者有效利用时间的关键。管理者在这里推荐时间分块法将时间划分为特定的时间段，并为每个时间段分配特定的任务或活动。这种方法可以帮助我们集中精力并避免在不同任务之间分心。帮助管理者进入工作状态，集中精力完成任务，提高效率和工作质量。在实际运用中，我们可以根据自己的情况对其进行调整，自己的时间自己做主。\u003c/p>","interaction":"\u003cp>&lt;A1便签&gt;\u003c/p>\u003cp> 对于幼教工作者来说，时间不够用，每天有忙不完的事，检查班本主题框架，班级材料投放、跟老师讨论班本主题方案，各种计划……我真的恨不得像孙悟空那样，拔几根头发出来，变出多几个分身来。我反思，是什么原因导致我这么忙？并下决心我要提升时间管理能力，我尝试着翻看彼得·德鲁克的《卓有成效的管理者 》，他在书中写到管理者可以用三步法认识自己的时间，清楚自己的时间花在哪里。从2月份开始，我有意识地去记录了20个工作日的下班的时间和导致没有准时下班的事由。3月份记录了17个工作日，4月份记录了6个工作日，5月份记录了5个工作日，6月份记录了3个工作日。记录的时间跨了5个月，每月记录的天数是坐滑梯的下降的。当时还没有接触拆书，不知道拆书帮，只会照本宣科的用幕布记录一些事情。6月底加入了拆书帮，开始升级打怪之旅，我再找出了这本书，选择了这个片段，去准备拆书预备表，分析拆页里的时间管理三步法，我之只做了记录时间，记录的时间跨度大，很难坚持下来。记录的内容不够全面，导致我难以了解时间都花在了什么地方，更谈不上运用效能分析四象限去厘清事情的轻重缓急，将时间进行集中管理，找到我的大块连续可支配时间了。\u003c/p>\u003cp>&lt;A2便签&gt;\u003c/p>\u003cp>目标：\u003c/p>\u003cp>在2023年8月28至9月30日期间24个工作日里以周为单位，学习运用时间三步法记录时间、管理时间、集中时间，提高工作效率。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>首先，记录时间。\u003c/p>\u003cp>了解自己在每天工作中花费的时间是至关重要的。这里以教学周为单位，制定了记录时间和管理、集中时间的安排。借助幕布记录第一周至第周五各项任务和所花费的时间。\u003c/p>\u003cp>第二步是管理时间。\u003c/p>\u003cp>一旦我们了解了自己的时间使用情况，就可以开始优化和管理时间。每周六，即计划里的9月2日、9日、16日、23日和30日，儿子上兴趣班的四个小时里，运用效能分析四象限将当周记录的内容分为重要且紧急、重要但不紧急、不重要但紧急、不重要且不紧急分为四类。\u003c/p>\u003cp>1. 重要且紧急的事\u003c/p>\u003cp>我们要非常重视，并立即去做，直到问题解决或任务完成时止。这有助于避免重要事项被忽视或延迟处理，保证组织的正常运转。\u003c/p>\u003cp>2.重要不紧急的事\u003c/p>\u003cp>对组织的长期发展和目标实现至关重要，提前规划，用更长时间完成。合理安排时间和资源，管理者可以确保这些任务得到充分关注和处理。\u003c/p>\u003cp>3.不重要但紧急的事\u003c/p>\u003cp> 这类事务也需要管理者赶快处理，但不宜花去过多的时间，最好是委派给其他人处理。把别人能做的事，全部分出去，把时间留下来做自认为重要的、自己想做的、自己有义务去做的各种事情。\u003c/p>\u003cp>4.不重要不紧急的事\u003c/p>\u003cp>识别先想一想：这件事如果根本不去理会，会出现什么情况呢？如果答案是“什么事都没发生。”，证明这些活动对组织的发展和绩效没有实质性的贡献，因此应该尽量避免或减少。\u003c/p>\u003cp> 浪费别人时间的事，如手工制作背景墙，无意义的文案撰写，不去做。\u003c/p>\u003cp>第三步：集中时间\u003c/p>\u003cp> 集中时间是管理者有效利用时间的关键。利用时间分块法，可以集中大块的时间。如以65分钟为单位切分工作时间。前60分钟，集中精力做好一项工作，由于工作的特殊，第一个周期用15分钟来吃早餐并跟园长沟通各项事宜。第二周期，第三周期休息5分钟，第四周期完成后，刚好到下班时间。如在一个周期里，不用60分钟就完成了工作，可以先休息5分钟，然后复盘待完成事项清单，挑选新任务，重新使用时间分块法完成新任务。下午的大家看看，就不详细说明了。\u003c/p>\u003cp>&lt;强有力的结束语&gt;\u003c/p>\u003cp>最后总结一下今天的拆书：时间对于我们每个人来说都是宝贵的资源。无论是在个人生活中还是在工作中，通过记录时间、管理时间、集中时间三步法能够更好地了解和掌握我们的时间，从而更加高效地完成工作任务。这将带来众多积极的成果，包括更好的时间管理技巧、更高的工作效率、和更好的工作生活平衡。\u003c/p>\u003cp>出于目标达成和可操作考虑，本次制定的一个月时间的目标，要成功地实施这个三步法达到有效的管理时间，需要在往后的每个月持之以恒的坚持，和保持灵活性和开放性，并不断调整自己的时间管理方式。只有这样，我们才能在工作中取得长远的进步。我今天的分享就到此结束了，希望这个片段会对各位小伙伴有帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1690783482000,"updated_at":1691119247000,"ria":true},{"id":14684,"topic":"卓有成效的五步法","learn_goal":"","remark":"无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"吕十七","city":""},"club":{"name":"苏州阅苏分舵","city":"苏州"},"prologue":"\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp>大家好，我是今天的拆书人十七，下面将开始我的1-1练级，本次练级将会分为两部分，如大家看的目录\u003c/p>\u003cp>现在我会通过三组短语介绍自己，\u003c/p>\u003cp>1 拆书新人，正在开始初级通关，想要成为一个引导者，2我是一名HR从业者，如果有人力相关想要咨询的欢迎交流和咨询\u003c/p>\u003cp>3慢热\u003c/p>\u003cp>这就是我\u003c/p>\u003cp>跟大家介绍下接下来我要拆的书，一本经典管理学书籍，作者被誉为现代管理学之父；相信大家对这本书不会太陌生，或多或少在学习或者工作场合都有听过或翻过这个本书吧\u003c/p>\u003cp>好啦，书籍先简单说到这里，下面我们来看看什么是拆书\u003c/p>\u003cp>\u003cstrong>拆书&amp;拆书帮介绍\u003c/strong>\u003c/p>\u003cp>大家看这个标题，发现他们有什么共同之处？对了，共有“拆“，何为拆？给大家看一组字体演变图，后面逐渐演化为我们常见的楷体字；看最左边，手&amp;斥，手斥合体意为”开“，听到这里大家有没有觉得的这个字形很眼熟，拆书帮的手势\u003c/p>\u003cp>说完拆字，我们来看看什么是拆书和拆书帮；\u003c/p>\u003cp>\u003cstrong>拆书：\u003c/strong>简单来说就是把书拆开，那要怎么拆呢？当然是选择自己需要的一部分拆开下来方变使用，这里开个玩笑不是说拆书就是撕书哈；\u003c/p>\u003cp>但是通过这个可以看出来\u003cstrong>，拆书是一种成人学习的方法论，用以提升能力，解决问题；是以学习者为中心，而非以知识为中心（应试）；需要讲知识关联学习者的经验，规划并运用\u003c/strong>；\u003c/p>\u003cp>形式， 1 个人拆书学习（RIA便签法，R是阅读原文片段，I 根据自己的语言重组拆页，A1 激活过去的经验，A2 未来可以落地的行动规划），2组织学习（一本书现场加工一场学习）——一群人拆为己用；\u003c/p>\u003cp>拆书帮：基于拆书法的学习爱好者联盟，非盈利性青年自组织；\u003c/p>\u003cp>使命：致力于培养拆书家、释放拆书家的能力，相互陪伴、助己达人\u003c/p>\u003cp>价值观：陪伴赋能，拆为己用，反求诸己，持续精进，共同成长\u003c/p>\u003cp>通过刚刚的介绍，大家对拆书有了一定了解，下面我们进入到拆书环节\u003c/p>","ratings_count":2,"texts":[{"id":18704,"quote":"\u003cp>请大家阅读屏幕文字，阅读完成后请打字示意；\u003c/p>\u003cp>p22-23 ：\u003c/p>\u003cp>下面五项是要成为一个卓有成效的管理者，必须在思想上养成的习惯：\u003c/p>\u003cp>1、有效的管理者知道他们的时间用在什么她功。他们所能控制的时间非常有限，他们会有系统地工作，来善用这有限的时间。\u003c/p>\u003cp>2、有效的管理者重视对外界的贡献，他们并非为工作而工作。而是为成果而工作。他们不会一接到工作就一头钻进去，更不会一开头就探究工作的技术和手段，他们会首先自向：“别人期望我做出什么成果，”\u003c/p>\u003cp>3、有效的管理者善于利用长处，包括白己的长处、上司的长处、同事的长处和下属的长处。他们还善于抓住有利形式，做他们想做的事。他们不会把工作建立在自己的短处上，也绝不会去做自己做不了的事\u003c/p>\u003cp>4、有效的管理者集中精力于少数重要的领域，在这少数重要的领域中，如果能有优秀的绩效就可以产生卓越的成果。他们会按照工作的轻重缓急设定优先次序，而且坚守优先次序。他们知道：要事第-一。重要的事先做，不重要的事放一放，除此之外也没有其他办法，否则反倒会一事无成。\u003c/p>\u003cp>5、最后，有效的管理者必纳善于做有效的决策。他们知道有效的决策事关处事的条理和秩序向题，也就是如何按正确的次序采取正确的步骤。他们知道一项有效的决策，总是在“不同意见讨论” 的基础上做出的判断，它绝不会是“一致意见”的产物。他们知道快速的决策多为错误的快策，真正不可或缺的决策数量并不多，但一定是根本性的快策。他们需要的是正确的战略，而不是令人眼花缭乱的战术。\u003c/p>","explains":"\u003cp>我们来看看这段内容讲了什么？，会从4个维度阐释\u003c/p>\u003cp>Ø \u003cstrong>WHAT\u003c/strong>（片段讲的是什么）：\u003c/p>\u003cp>想要成为卓有成效的管理者，思想上必须养成的5个习惯。\u003c/p>\u003cp>Ø \u003cstrong>WHY（为什么要这么做）\u003c/strong>\u003c/p>\u003cp>想在工作上提高绩效和成就，让工作达到令人满意的程度，唯一可行的办法就是提高有效性。\u003c/p>\u003cp>想让生活更美好，也是一样，否则碌碌无为，很难达到理想的状态\u003c/p>\u003cp>Ø \u003cstrong>HOW （怎么做，加工出具体行动步骤）\u003c/strong>\u003c/p>\u003cp>如何成为卓有成效的管理者呢，或者怎样才能离卓有成效更近呢，通过这几个步骤，可以养成好的思维习惯\u003c/p>\u003cp>1 管理时间，借用工具记录时间（app或者笔记本等），知道自己的时间用在了哪里，变成时间的掌舵者\u003c/p>\u003cp>2 重视产出结果，在事情开始做之前询问事情发起者，期望我能产出什么结果？\u003c/p>\u003cp>3 识别并善用优势，通过测评或者绩效反馈找到自己的手势，善于借用同事，领导，下属等的推动事情\u003c/p>\u003cp>4 聚焦，对手中的事情进行分类，区分那些是必要的自己做的，哪些是可以他人做的；\u003c/p>\u003cp>5 善做决策，找到事情条理和秩序，按照正确的顺序采取正确的步骤\u003c/p>\u003cp>Ø \u003cstrong>WHERE（什么情况下适用，什么情况下不适用）\u003c/strong>\u003c/p>\u003cp>大部分的情况下都是适用的，当你在一堆事情中打转没有头绪，当你想要变得更好的时候都是可以使用的；但当你想让自己放空，不去思考的时候，比如 冥想 睡觉 瑜伽等就不再适用啦\u003c/p>","interaction":"\u003cp>读完这段内容，想到了过去的一段经历\u003c/p>\u003cp>\u003cstrong>A1（自己的相关经历）\u003c/strong>\u003c/p>\u003cp>在今年4-6月份的工作中，常会陷入一种，忙但不知忙什么，并且忙完一件事情之后又不知道要做什么了，每周到写周报的时候久特别头疼，写的特别空洞：1、2 、3、4....罗列常规事项,并且有的时候也没有完全罗列，只是把手边的事抓一抓就放进去；汇报的时候领导就会问的比较细致，项目进展到什么阶段，整体状态是否delay，项目效果如何；一问一答；但总感觉自己好像这周没干啥也没法像其他同事一样讲那么多。\u003c/p>\u003cp>由此进行了反思，\u003c/p>\u003cp>A1反思\u003c/p>\u003cp>1 管理时间，日常并没有记录时间使用在了哪里，导致到周会的时候感觉自己好像没做什么\u003c/p>\u003cp>2 对领导当下周会关注的事项并不太清楚，导致领导在询问项目情况\u003c/p>\u003cp>3 识别优势这块暂未体现\u003c/p>\u003cp>4 没有对手头中的工作做细分，导致遇到什么抓什么，很多时间花在了非必要紧急的事上\u003c/p>\u003cp>5 对于周报的条理不够清晰，才会每次写的很空洞\u003c/p>\u003cp>基于拆页所学的内容，我对后续的事项做了一个初步规划\u003c/p>\u003cp>\u003cstrong>A2（规划自己的运用）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>对下次周会的汇报做了一个初步规划：\u003c/strong>\u003c/p>\u003cp>1 管理时间：记录时间并提前规划好时间，安装一个记录时间的APP，对每小段时间耗费做上记录，连续两周记录并观察时间花费的地方，并在每周日将一周内记录的，不重要时间花费标注，在对比后，设置第三周的时间安排；\u003c/p>\u003cp>2 重视产出结果，在周会前一天，提前了解领导关注的事项，并以此生成周报主要内容\u003c/p>\u003cp>3 本周三之前完成与朋友对话，进一步找到自己在生活和工作中，性格和处事方式的三个优点及缺点\u003c/p>\u003cp> 4 周三前对手上的事情按照四象限划分为轻重缓急，对不重要也不紧急的事情转交他人或者直接剔除\u003c/p>\u003cp> 5 周四前重新整理周报的逻辑，并应用在最新的汇报中\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1669618273000,"updated_at":1673932972000,"ria":true},{"id":14682,"topic":"掌握时间三步法","learn_goal":"","remark":"无","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"吕十七","city":""},"club":{"name":"苏州阅苏分舵","city":"苏州"},"prologue":"\u003cp>【开场】\u003c/p>\u003cp>大家好，我是今天的新手拆书家十七 ，欢迎大家参加我们的拆书过级练习\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>在我们正式开始拆书之前，我想先请在做的伙伴相互认识一下，那我按照我的顺序点名依次来介绍下自己\u003c/p>\u003cp>听完大家的介绍，\u003c/p>\u003cp>我用三组短语来做一个简单的自我介绍。\u003c/p>\u003cp>第一个，我是一名新苏州人，来苏州3个多月了\u003c/p>\u003cp>第二个，我是一名HR，之前在企业内部从事人力相关工作\u003c/p>\u003cp>第三个，我是一个探索者，喜欢尝试新的事物。\u003c/p>\u003cp>这就是现在的我。\u003c/p>\u003cp>【\u003cstrong>分组】\u003c/strong>\u003c/p>\u003cp>为了方便大家稍后练习演练，下面我们在场的小伙伴分为两组，方便大家讨论。大家可以在腾讯会议中看到分组情况，有不清楚的可以打字或语音示意；\u003c/p>\u003cp>\u003cstrong>【书籍介绍】\u003c/strong>\u003c/p>\u003cp>右边是此次所拆的书，现代管理学之父-皮特德鲁克 所著的《卓有成效的管理者》，被誉为现代管理第一书，出版50多年，至今仍被广泛阅读，今年恰是此书出版第55周年；借此机会和大家一起再度学习\u003c/p>","ratings_count":1,"texts":[{"id":18702,"quote":"\u003cp>下面我会带领大家走进TF1-2的练级环节，\u003c/p>\u003cp>今天分享的主题是，如何通过三步掌握时间\u003c/p>\u003cp>请大家花1分钟的时间阅读分发的拆页，阅读完成的伙伴举手示意。\u003c/p>\u003cp>\u003cstrong>R（原文片段）\u003c/strong>\u003c/p>\u003cp>关于管理者理任务的讨论，一般都从如何做计划说起，这样看来很合乎逻辑。可惜的是管理者的工作计划，很少真正发生作用。计划通常只是纸上谈兵，或只是良好的意愿而已，很少能够真正实现。\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会以时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\u003c/p>\u003cp>•记录时间：\u003c/p>\u003cp>•管理时间：\u003c/p>\u003cp>•统一安排时间。\u003c/p>","explains":"\u003cp>片段阅读完的伙伴请举手示意\u003c/p>\u003cp>好，都读完了，我们来看下这个片段讲了什么，将通过3W1H来讲解\u003c/p>\u003cp>\u003cstrong>I（重述原文）\u003c/strong>\u003c/p>\u003cp>What（片段讲的是什么）：\u003c/p>\u003cp>这个拆页讲得是有效的管理者通常通过三个步骤来掌握时间。\u003c/p>\u003cp>Why（为什么要这么做）\u003c/p>\u003cp>为什么要这么做，因为时间是有限且不可再生的，我们的日常工作、生活都会受到时间的制约 \u003c/p>\u003cp>How（怎么做，加工出具体行动步骤）\u003c/p>\u003cp>那我们要怎么做呢\u003c/p>\u003cp>第一步：记录，借助笔记本或APP等工具，找出非生产性和浪费时间的活动，了解时间是怎样耗用的。\u003c/p>\u003cp>第二步：剔除，找出非生产性活动和浪费时间的活动，尽可能地从时间表减少并剔除这部分\u003c/p>\u003cp>第三步：统一安排，化零为正，将零散的时间整合成为大块连续的时间\u003c/p>\u003cp>Where（什么情况下适用，什么情况下不适用）\u003c/p>\u003cp>整个方法适用性广泛，当你出现以下几种情况，觉得时间不够用，晕头转向却没有成就感，某天突然回首感觉自己碌碌无为的时候…，它就很适合\u003c/p>\u003cp>\u003cstrong>案例：\u003c/strong> \u003c/p>\u003cp>我前段时间离开忙碌的工作状态，变成一个闲散的待业人员，刚开始很随性的使用时间，刷剧，跑步，闲逛，某天早晨突然发现这段时间好像什么也没做，时间哗哗地溜走了；焦虑恐慌，强迫自己坐在书桌前，整理待办事项，今天要做什么，明天要做什么但效果平平。开始想知道每天的时间都去哪了？\u003c/p>\u003cp>反思：\u003c/p>\u003cp>1 对时间没有记录，不知道时间用在那里了\u003c/p>\u003cp>2 花费的时间中哪些是非生产性活动？没有意识到浪费时间的事情\u003c/p>\u003cp>3 时间零零散散的用掉，想到哪个事情就做哪个事情\u003c/p>","interaction":"\u003cp>\u003cstrong>A1 自己的相关经验\u003c/strong>\u003c/p>\u003cp>我们刚学习了整个拆页，了解到如何掌握时间 \u003c/p>\u003cp>现在请大家回顾下过往经历，是否有过类似的情景，你当时是怎么做的呢？请在小组内分享，每人1-2分钟，3min后请并一位代表与大家分享\u003c/p>\u003cp>组员1：周末早上有时候起的挺早的，6：30起床到9点，现在回想感觉好像啥也没干，可能做了，早餐，刷刷朋友圈等等，原本计划是锻炼一会，冥想，看书；可以利用管理时间的三步法重新规划周末的时间。\u003c/p>\u003cp>组员2：孩子，工作占了很大一部分时间，却没有自己成长的时间，也不知道自己的时间都用在哪里了；开始把时间等分并且记录都做了什么，晚上睡前进行复盘，今天做了哪些，哪些没做，明天的计划等等\u003c/p>\u003cp>\u003cstrong>A2行动计划\u003c/strong>\u003c/p>\u003cp>通过刚刚的分享，我们进一步掌握了时间管理的步骤，请大家设想一下，在未来一周或者一个月内，哪些场景会用到这个方法呢？比如（清除计划清单，成功减脂）\u003c/p>\u003cp>请大家根据自己的场景在便签上写一个计划，要符合SMART法则！\u003c/p>\u003cp>给大家3分钟时间，写完后请小伙伴来分享！\u003c/p>\u003cp>组员3：计划在接下来的周末尝试使用时间管理的步骤\u003c/p>\u003cp>1 记录：记录周六的时间都花在哪里了，做了哪些时间\u003c/p>\u003cp>2 剔除：周日对周六的时间使用进行筛选，剔除不必要的选项，比如刷手机的时间等\u003c/p>\u003cp>3 统一安排：将零散的时间整合为整片的时间，晚上的时间用来准备英语稿子等\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1669607861000,"updated_at":1671632187000,"ria":true},{"id":14644,"topic":"做自己时间的主人","learn_goal":"","remark":"【主题介绍】\n大家有没有过整天感觉忙忙碌碌，但实际上没做出什么事情的时候？那你要好好思考你的时间都去哪了？本次拆书，将带领大家学会关注时间资源，学做时间的主人。\n【书籍介绍】\n本书是管理学大师彼得德鲁克教授的经典之作，是世界上众多企业管理者的必读书籍，也是管理实践指导者如何做到卓有成效的指南。这本书已经被译成37种语言，畅销全世界130多个国家。针对如何卓有成效，德鲁克提出了五点要求：善用时间、讲求贡献、善用人才、要事优先和有效决策。在实现“有效性”的这些方式中，人作为能动的主体是唯一可以直接增加自身价值的资源。","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"玄夕","city":"南宁市"},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>嗨，大家上午好！欢迎大家来参加今天的拆书过级活动，我是今天的拆书过级者玄夕。请允许我用三个标签给大家做个自我介绍吧。第一个标签：大学思政课教师；第二个标签：正在升级打怪的一级拆书家；第三个标签：青创繁星的学习者。\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>今天，我将带领大家学习的内容来自《卓有成效的管理者》中的一个片段：【掌握自己的时间】 ，期望现场的各位伙伴在学习完这个片段后，能运用我们今天学习的时间管理三步骤，有效管理和利用自己的时间，避免无时间可用的情况。在开始学习之前，我想先让现场的小伙伴分一下组，便于学习中进行讨论。自愿原则，选择今天你想一起讨论学习的小伙伴，坐到他的身边。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>接下来，我再介绍一下今天要学习的图书《卓有成效的管理者》 \u003c/p>\u003cp>F（特征）:这本书的作者是一代管理学宗师德鲁克教授，自1966年首次出版以来，已被翻译成二十多种语言，是世界上众多企业管理者的必读书籍，也是管理实践中指导管理者如何做到卓有成效的指南。\u003c/p>\u003cp> A（优势）:这本书最吸引我的地方，就是书中的方法论并非是作者的主观臆断，而是作者通过大量的管理实践总结出来的，可以说本书是一本实战类的指导书籍。\u003c/p>\u003cp> B（利益）: 在工作和生活中，不知道大家是不是有过这样的感受：时间经常感觉不够用，每天忙忙碌碌，甚至有时候焦头烂额，可是也没见自己忙出什么结果。在遇到这些情况的时候，可能脑子里会冒出“我的时间都去哪里了？”这样的问题，甚至有些小伙伴们还会感觉到焦虑，我曾经就有这样的强烈的感受。其实对于时间，我们可以把它看作自己的资源去管理，利用《卓有成效的管理者》中的时间管理三步法，可以帮助我们有效管理和利用各种时间。\u003c/p>","ratings_count":2,"texts":[{"id":18661,"quote":"\u003cp>\u003cstrong>R “掌握自己的时间” 片段来源《卓有成效的管理者》（微信读书电子书）P73\u003c/strong>\u003c/p>\u003cp>第2章 掌握自己的时间\u003c/p>\u003cp>关于管理者任务的讨论，一般都从如何做计划说起。这样看来很合乎逻辑。可惜的是管理者的工作计划，很少真正发生作用。计划通常只是纸上谈兵，或只是良好的意愿，很少能够真正实现。\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\u003c/p>\u003cp>记录时间；\u003c/p>\u003cp>管理时间；\u003c/p>\u003cp>统一安排时间。\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>这个片段告诉我们有效的管理者，他们工作开始的着手点并不是计划，而是时间安排。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>因为只有掌握有效的时间管理方法，计划才不会只是纸上谈兵或者良好的愿望。懂得时间管理的方法，才能有助于我们的目标达成。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>那么我们如何才能做到有效管理时间呢？片段中提到了三个步骤：\u003c/p>\u003cp>第一步：记录时间。（动手）\u003c/p>\u003cp>在这一步我们还可以进行细化具体怎么做：\u003c/p>\u003cp>1、把要做的事情列出一张清单；\u003c/p>\u003cp>2、在每一项事情后面标注所需要花费的时长。\u003c/p>\u003cp>第二步：管理时间。（思考）\u003c/p>\u003cp>如何实现管理，我建议大家可对时间先进行分类，再进行管理。\u003c/p>\u003cp>1、分类。可控时间、不可控时间；整段时间、碎片化时间。\u003c/p>\u003cp>2、管理时间。思考什么样的事情适合用什么样的时间做。\u003c/p>\u003cp>第三步：统一安排时间。（行动）\u003c/p>\u003cp>不同的时间段做什么事，体现有效分配。\u003c/p>\u003cp>给大家举个我自己的例子吧，这是我的效率手册，其实是我的时间管理工具。每天我的第一步是围绕今天要实现的目标写下要完成的所有事项。（列清单）每一项事项我都会预估一下需要花费的时间。\u003cstrong>这就是第一步：记录时间。\u003c/strong>\u003c/p>\u003cp>接下来我会思考哪些时间是整段时间，哪些时间是碎片化时间。然后大致想一下列出的这些事项需要怎么类型的时间配置给它。\u003cstrong>这就是第二步：管理时间。\u003c/strong>\u003c/p>\u003cp>最后我会把所有事项都安排到这个时间轴上，按照刚才思考的管理思路进行安排，大家注意这一步是最体现有效性的，也是最能考验你是否是一个时间管理高手的检验场。\u003cstrong>那这就是第三步：统一安排时间。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>这个时间管理方法我觉得适用于很多场合，大家试想时间就是上天赐予我们每一个人最公平的财富，在职场上、在家庭中、关于孩子的学习、关于自己的学习成长，都是跟时间管理息息相关。所以对自己与生俱来的财富进行有效管理，能帮助我们更好的认识自己、规划自己，更好地实现自己的价值。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】角色扮演\u003c/strong>\u003c/p>\u003cp>那我们如何把这时间管理三步骤用起来呢，今天我们就进行实战演练。我设计了一个场景：\u003c/p>\u003cp>【场景设计】在一个知识服务平台工作的职场小白丽丽，每天的工作都很多：在网上宣传公司当日的直播信息、协助队长管理课程的陪伴营运营、管理课程后台网络情况、开会、写文案……，她感觉自己每天茫茫碌碌，可是经常只能把事情匆忙做完而没有做好，甚至有时候都完成不了，自己每天连吃饭、谈恋爱的时间都没有，而且自己的阅读计划都没有安排上，所以很焦虑。她打算找自己的老板张总聊一下，看看这个又忙又美的老板能不能给予一些帮助。\u003c/p>\u003cp>任务：张总用今天学习的时间管理三步法，教丽丽怎样有效管理自己的时间。\u003c/p>\u003cp>请大家在小组内进行角色分配和角色演练，大家练习的时间是4分钟。演练结束后请一组小伙伴上来给大家进行演绎展示。好，现在开始。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：小梁（饰丽丽），春华（饰张总）\u003c/strong>\u003c/p>\u003cp>丽丽：张总，你有时间吗？我进公司的这段时间工作感觉很糟糕，想找你聊一聊。\u003c/p>\u003cp>张总：可以的，进来坐。跟我具体说说你的情况。\u003c/p>\u003cp>丽丽：是这样的，张总，你看我现在每天的工作有直播、宣传、协助运营、还要开会、写文案……，我感觉每天都很忙，可是有时候还是不能很好的完成工作，甚至都没有时间做自己的事情，比如谈恋爱啊、阅读啊，我感觉好抓狂。\u003c/p>\u003cp>张总：哦，原来是这样，那我想问问你，你是否对你每天的时间进行过管理吗？\u003c/p>\u003cp>丽丽：管理？怎么管理？\u003c/p>\u003cp>张总：你看，我们首先可以进行记录时间。我们先把今天你要做的事情都列出来，然后大概想一下每件事情需要花多长时间才能完成。接着我们对自己的时间进行个大致的分类，比如我们的上班时间是不可控时间，下班时间是可控时间。还有什么时候是一整段的时间，什么时候是碎片化时间。然后我们就思考刚来列的要完成的事情我们要用什么样的时间去做。最后，我们给这些事情安排合适的时间去做，比如开会、直播这类事情是提前固定时间的，我们就把他们放进指定时间段就可以了，网络宣传和协助运营是可以运用上班期间的碎片化时间分几次可以完成的，比如吃中餐的时候抽空转发相关宣传信息到朋友圈，社群有需要解答的问题就及时回复，自己定几个小时段进行集中处理社群信息就可以了。写文案需要整段的时间会更高效，所以你看看你一天的时间什么地方可以空出一两个小时的时间专门完成这件事情。至于私事，只要你把工作都安排在上班时间完成，那么下班时间都是你的可控时间，就可以轻松安排上了。其实就是要学会记录时间、管理时间和安排时间。你看我这样说你是否明白？\u003c/p>\u003cp>丽丽：哦，原来我每天一团乱是因为我没有对自己的时间进行管理和安排。听你这么说，我感觉清晰很多，而且应该也能完成这些事情了，谢谢张总教了我时间安排的三步骤，以后我就用这个时间安排工作和生活。十分感谢。\u003c/p>\u003cp>非常感谢小伙伴的精彩表演。大家通过实战演练之后，我相信对今天学习的时间管理三步法如何使用应该有了更清晰的认识，这三个步骤我们再回顾一下，就是记录时间、管理时间、统一安排时间。我希望大家能把这三步法带到自己生活的每一天中去运用，把时间管理变成一种习惯，别忘了时间就是金钱，我们要把它用在刀刃上！\u003c/p>\u003cp>好，今天的分享就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1669156970000,"updated_at":1669959069000,"ria":true},{"id":14362,"topic":"管理自己时间的前提是-诊断自己的时间","learn_goal":"","remark":"每一位管理者要提高管理的有效性，一定是管理好自己的时间，而管理好时间的前提时，一定要诊断出自己的时间都用在了那里，并做好有系统的时间管理。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"孟欣","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>学习目标\u003c/p>\u003cp>今天的分享，是希望和在坐的伙伴们在今天20多分钟的拆书学习后，掌握诊断自己的时间的方法。初步学会记录并分析时间的使用情况。\u003c/p>\u003cp>分组：我叫孟欣，大家可以叫我欣欣。我的三个标签是HR、教练、终身学习者。今天拆书级别是TF2-1，稍后会有小组讨论环节，所以我们请左边伙伴为一组，右边的伙伴为一组。\u003c/p>\u003cp>图书介绍 \u003c/p>\u003cp>今天我要给大家分享的内容来自《卓有成效的管理者》这本书。 \u003c/p>\u003cp>【F】这本书是管理类实用性书籍，作者是彼得.德鲁克，是当代著名思想家，一代管理学宗师。书中提到每一位知识工作者都是管理者，而管理者要做到卓越有效就必须要：管理时间、关注成果、善用人才、要事优先、有效决策。 \u003c/p>\u003cp>【A】这本书相对于其他的管理书籍来说，它是管理学类图书中非常畅销的实用性强的书籍。本书是很多概念的提出者，而很多的公司基于德鲁克的提出的理论进行了实践，书中的内容来自现实生活中的案例，诠释的却是鲜活的思想，与你面对相同的事实，却从不同的视角说出了你不曾想到的新理念。读起来让人非常的享受，爱不释手。\u003c/p>\u003cp>【B】（B1）每个人都想成为卓有成效的管理者，那成为卓有成效的管理者要学会管理自己的时间，很多人一年到头在年终述职时，发现年初制定的目标没有达成，却每天异常的忙碌，到底是那里出了问题，看了这本书你都可以从书中找到问题的症结。（B2）今天我分享内容来自管理时间的这个片段，能帮助你记录并分析时间的使用情况。从而帮你知道时间花在哪，根据分析来提升你的时间使用效率，所以必须学会诊断自己的时间。\u003c/p>","ratings_count":1,"texts":[{"id":18372,"quote":"\u003cp>\u003cstrong>【R 阅读原文】   管理自己时间的前提是-诊断自己的时间P34-36节选\u003c/strong>\u003c/p>\u003cp>要提高管理者的有效性，\u003cstrong>第一步就是记录其时间的实际情形\u003c/strong>。重要的是，必须在处理某一工作的“当时”立即加以记录，而不能事后凭记忆补记。\u003c/p>\u003cp>许多有效的管理者都经常保持这样一份记录，每月定期拿出来检讨。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间使用得很乱，浪费在种种小事上。经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免回到浪费的状态上去。\u003c/p>\u003cp>第二步就是要做\u003cstrong>有系统的时间管理\u003c/strong>。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以问自己下列几个问题：\u003c/p>\u003cp>\u003cstrong>1.首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果?”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/strong>\u003c/p>\u003cp>许多大忙人，天天在做一些他们觉得难以割舍的事，比如应邀讲演、参加宴会、担任委员和列席指导之类，不知占去了他们多少时间，而这些工作，他们本身既不感兴趣，做得也根本不够精彩。然而他们得承受这些负担，一年又一年，就像从天而降的灾难一样躲也躲不了。其实，对付这类事情，只要审度一下对于组织有无贡献，对于他人有无贡献，或是对于对方的组织有无贡献。如果都没有，只要谢绝就可以了。\u003c/p>\u003cp>2.第二个该问的问题是：“\u003cstrong>时间记录上的哪些活动可以由别人代为参加而又不影响效果?”\u003c/strong>\u003c/p>\u003cp>多年来在管理方面都在研究授权问题。任何组织，几乎每一位主管人员都接到过上级有关做好授权的指示，而且他们本人也曾屡屡对其下属阐明授权的重要。但是这样的告诫是否产生效果，实在令人怀疑。原因非常简单，只是因为没有完全明了授权的意义。授权的意思应该是可由别人做的事情交付给别人，这样才能做真正应由自己做的事。\u003c/p>\u003cp>我却从来没见过一位管理者，在检讨过自己的时间记录后，还不改变自己的习惯，将不必亲自处理的事情交给别人。其实他如果真的想有所作为，只要将可由别人做的事交给别人就得了。\u003c/p>\u003cp>参加会议也是问题，虽然会议本来并没有什么别人处理不了的大事，但管理者总得出席，管理者往往要花上好几个小时参与讨论。\u003c/p>\u003cp>\u003cstrong>3.还有一项是时间浪费的因素，是管理者可以控制并且可以消除的，这项因素是：\u003c/strong>管理者在浪费别人的时间。\u003c/p>\u003cp>这种现象并不明显，但有一个简单方法可以诊断出来:\u003cstrong>去问问你的下属\u003c/strong>。即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。\u003c/p>\u003cp>许多管理者都意识到了哪些事情会浪费他们的时间，然而他们却不敢面对这个问题。他们怕因小失大，造成错误。殊不知即使有了错误，也可以很快弥补。一位管理者大刀阔斧减少不必要的工作，绝不会有太大的风险。人总有一种倾向，高估自己地位的重要性，认为许多事要事必躬亲不可。纵然是最有效的管理者，仍然免不了有许多不必要的和生产性的工作。大胆的减少工作，真会有问题吗？这种顾虑是多余的，我们要大胆的减少无谓的工作，绝对无损于有效性。\u003c/p>","explains":"\u003cp>好，请阅读完的伙伴们示意我一下，我来开始我今天的讲解。\u003c/p>\u003cp>What：\u003c/p>\u003cp>这个拆页讲了如何诊断自己的时间两个步骤和排除浪费时间的三个方法；\u003c/p>\u003cp>Why：我们为什么要诊断自己的时间？每个知识工作者都是管理者，每个管理者都想成为卓有有效的管理者，如果管理者不能管理好自己的时间，就很难保证自己的工作快速和高效。如果知道我们平时的工作都花在什么地方，诊断出那些应该可以提升时间效用的，就会对我们非常的有帮助。 如果我们不能分析自己的时间是浪费在那里的，就很难成为一名卓有成效的管理者。所以要对我们的时间进行诊断。知道时间都去哪了？\u003c/p>\u003cp>How：\u003c/p>\u003cp>两个步骤：\u003c/p>\u003cp>1.“做记录”第一步就是记录其时间耗用的实际情形。\u003c/p>\u003cp>2.“做管理”第二步就是要做有系统的时间管理：\u003c/p>\u003cp>（1）可以不做”找出哪些事情可以不做。\u003c/p>\u003cp>（2）“别人来做”找出哪些事情可以有别人来做。\u003c/p>\u003cp>（3）“不去浪费”不去浪费别人的时间。\u003c/p>\u003cp>Where:可以适用于所有的工作者想提升自己的时间管理，不用于体力工作者对于时间的诊断。\u003c/p>\u003cp>不这么做的坏处：\u003c/p>\u003cp>如果不做时间的诊断，会有哪些坏处：\u003c/p>\u003cp>第一，时间耗用混乱，浪费在小事上，重要的事情工作没开呢，产生的价值比较小，浪费时间本身就是浪费生命;\u003c/p>\u003cp>第二，可交由别人事情，自己确在做，耽误让别人得到更好成长;\u003c/p>\u003cp>第三， 浪费别人的时间会让下属或同事的工作非常低效；\u003c/p>\u003cp>\u003cstrong>第一步：做记录：（第一步就是记录其时间耗用的实际情形。)\u003c/strong>\u003c/p>\u003cp>我是人力资源部的经理，整天自己的工作非常忙，坐在椅子那基本只有中午吃饭时间站起来，其它时间都一直在忙，忙忙碌碌到头来没效率，自己也非常的困惑，觉得自己每天那天努力，到底是为什么？为了找出原因，我针对自己一周（45小时）的工作内容进行记录，并进行分析，看看时间都用在了那里：\u003c/p>\u003cp>1. 总部会议，部门会议一天（8小时）。\u003c/p>\u003cp>2. 与各位业务园长电话沟通与处理人事问题（10小时）\u003c/p>\u003cp>3. 处理相关的流程的审批（1小时）。\u003c/p>\u003cp>4. 部门工作的协调事项。（3小时）\u003c/p>\u003cp>5. 解答相关的政策问题。（5小时）\u003c/p>\u003cp>6. 自己重点工作推进。（6小时）\u003c/p>\u003cp>7. 每周周报和日志。（5小时）\u003c/p>\u003cp>8. 其它临时和突发紧急事情（4小时）\u003c/p>\u003cp>\u003cstrong>第二步：做管理：有系统的时间管理：\u003c/strong>\u003c/p>\u003cp>（1）可以不做”找出哪些事情可以不做：    无\u003c/p>\u003cp>（2）“别人来做”找出哪些事情可以有别人来做：    2. 5\u003c/p>\u003cp>（3）“不去浪费”不去浪费别人的时间： 1. 4\u003c/p>","interaction":"\u003cp>【A1显像提问】\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>接下来请回顾，我们工作日当中最精典的工作日的一天，我们来进行一天的罗列，我们一起来分享这一天当中你都做了什么，用了多少的时间？现场的伙伴们可以试想自己，那时候你是否有对自己的时间进行过诊断，现在小组内讨论。每个伙伴都尽量的分享和发言，稍后我们有请一位小伙伴来分享一下。\u003c/p>\u003cp>学习者：小爱的分享\u003c/p>\u003cp>6：00 起床\u003c/p>\u003cp>7：00-7：30 做早餐吃早饭\u003c/p>\u003cp>7：30-8：00 送娃上学\u003c/p>\u003cp>8：00-9：00上班路上。（用来读书）\u003c/p>\u003cp>9：00-11：00 维修电脑资料。\u003c/p>\u003cp>11：00-12：00 自己的工作安排\u003c/p>\u003cp>12：00-13：00 午餐时间\u003c/p>\u003cp>13：00-15：00部门会议\u003c/p>\u003cp>15：00-18：00 自己工作时间\u003c/p>\u003cp>18：00-19：00 回家路上（用来看书）\u003c/p>\u003cp>19：00-21：00 吃晚餐+辅导孩子功课\u003c/p>\u003cp>21：00-22：00 自己休息时间\u003c/p>\u003cp>22：00-22：30 睡觉\u003c/p>\u003cp>非常感谢小爱的分享，他给我们阐述了记录了她的时间使用情况的。看起来小爱的工作一天也是真的非常的忙碌。 \u003c/p>\u003cp>【A1+反思加工】\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>拆书家：接下来我们借着小爱所提供的案例，结合今天我们一起学习的知识点，如何诊断自己的时间，再次组内讨论，我们想像下通过今天学习的如何诊断时间步骤，回到过去，我们来诊断一下典型工作的一天的话，你会怎么分析自己的时间使用情况。现在用2分钟的时间组内讨论。\u003c/p>\u003cp>学习者：\u003c/p>\u003cp>我们有请小爱就她的典型的一天进行分享：\u003c/p>\u003cp>小爱记录了自己一天的时间。\u003c/p>\u003cp>小爱管理了自己的时间：\u003c/p>\u003cp>小爱说:\u003c/p>\u003cp>1. 可不做：她自己可不用做的事情：做早餐和送娃去学校，交由别人做。\u003c/p>\u003cp>2. 他人做：电脑子的维修是可以由别人来做的。\u003c/p>\u003cp>3. 不浪费：她分析了一下，只有别人浪费了她的时间，她是没有浪费别人时间的。\u003c/p>\u003cp>非常感谢小爱的分享，通过如何记录自己的时间，并学会了分析自己的时间，学会了诊断自己时间。他今天的案例非常匹配今天的学习目标。大家通过诊断自己的时间，从而管理好自己的时间，提升了自己的效率。非常的开心，今天我的分享就到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1665897659000,"updated_at":1666312282000,"ria":true},{"id":14349,"topic":"高效会议3步法","learn_goal":"","remark":"拆页片段介绍了卓有成效的管理者召开有效会议的3步法。","level":"TF2-1","duration":18,"status":30,"type":0,"chaishujia":{"username":"光子","city":"福州市"},"club":{"name":"福州筹备分舵","city":"福州"},"prologue":"\u003cp>大家早上好，我是今天的拆书人光子。我先给今天参加拆书活动的观察家分一下小组。\u003c/p>\u003cp>本次的学习目标是帮助学习者掌握高效开会的方法，引导学习者在现场学会应用会议三步法，然后鼓励大家把这个方法运用到实际工作过程中。\u003c/p>\u003cp>【F】今天我要给大家拆的书是这本《卓有成效的管理者》，这本书的作者是\u003ca href=\"https://baike.baidu.com/item/%E5%BD%BC%E5%BE%97%C2%B7%E5%BE%B7%E9%B2%81%E5%85%8B/6906406\">彼得·德鲁克，被誉为现代管理学之父，在这本书当中，作者深入浅出地解读了5项成为卓有成效的管理者的要素。\u003c/p>\u003cp>【A】这本书是现代管理学当中的一部经典著作，影响了数代追求创新以及最佳管理实践的学者和企业家们。\u003c/p>\u003cp>【B】作为一名管理者，您有没有遇到过要做的事情一大堆，不知道从何下手，这本书将教会您如何集中精力在少数重要的领域，做到要事第一；您的企业有没有遇到过无人可用，招不到好的人才的窘境，这本书告诉您如何善于利用员工的长处，让他们扬长避短，解决企业的人才困境；您是不是在管理工作当中疲于奔命，总觉得时间不够用，这本书能够让您善用有限的时间，掌控时间，真正做到高效能。在管理过程当中遇到的种种挑战，这本书都可以给到您启发和解决问题的方法论，成为真正卓有成效的管理者，是任何一位管理者的必读书籍。\u003c/p>","ratings_count":1,"texts":[{"id":18358,"quote":"\u003cp>\u003cstrong>片段来自管理类经典书籍彼得.德鲁克的《卓有成效的管理者》。现在我把片段内容发给大家（发复印好的内容），请大家花2分钟时间来阅读手上的片段，阅读完的小伙伴可以举手示意我一下。\u003c/strong>\u003c/p>\u003cp>有效的管理者在会议开始时，会先说明会议的目的和要求达成的贡献。同时，他还要设法让会议紧紧围绕着主题。他绝不会使会议成为一次摆龙门阵的机会，任大家随便发言。当然，如果会议的目的是在激发大家的思想和创见，他也不会仅让某一个人滔滔不绝。他会刺激每一位与会人员的发言兴趣。但是在会议结束之前，他会回到开场所介绍的主题，使会议获得的结论与主题相符。\u003c/p>","explains":"\u003cp>\u003cstrong>接下来，我给大家分享一下这个片段的I便签。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】：\u003c/strong>\u003c/p>\u003cp>这个片段介绍了卓有成效的管理者召开有效会议的3步法。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【Why】：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不这样做的坏处：\u003c/strong>我们经常会碰到一些冗长无聊的会议，甚至有些会议根本和自己没有关系，参加这样的会议不仅不能帮到管理者卓有成效，还会浪费宝贵的时间资源。\u003c/p>\u003cp>\u003cstrong>反例：\u003c/strong>我记得曾经参加过一次会议，说好是项目招商会，结果会议从参会人自我介绍开始就变成聊天会了，最后的项目招商草草结束，我来了解项目的目的根本没有实现，浪费了我半天的时间。\u003c/p>\u003cp>所以，非常有必要来掌握如何高效开会的3步法。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【How】：\u003c/strong>\u003c/p>\u003cp>有效的管理者召开有效的会议分成3步走：\u003c/p>\u003cp>首先，会议开始时，明确说明会议的目的，也就是为什么要召开这次会议；\u003c/p>\u003cp>其次，在会议过程当中，设法让会议紧紧围绕主题，而不是漫无目的，随便发言；\u003c/p>\u003cp>最后，在会议结束之前，回到会议的主题，确保会议得到的结论与主题相符，从而实现会议的目的。\u003c/p>\u003cp>\u003cstrong>反例重塑\u003c/strong>：在上面那个反例中，按照3步法，可以这样做：\u003c/p>\u003cp>首先，主持人一开始就要明确今天会议的目的是项目介绍和招商；\u003c/p>\u003cp>其次，在会议过程当中，对于跑题的主持人予以明确制止，紧紧围绕项目介绍来展开；\u003c/p>\u003cp>最后，在会议结束之前，重申和强调本次会议的招商目的。\u003c/p>\u003cp>这样开会，会议就不会出现上面的情况。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【Where】:\u003c/strong>\u003c/p>\u003cp>任何形式的会议包括家庭会议，家长会等等，为了保证有成果，都可以参照以上3步来召开，此外，任何沟通场景也可以使用这个方法，比如和某人沟通，也需要在沟通之前清楚目的；沟通过程中围绕主题，不跑题，不瞎聊；沟通结束之前呼应主题，这样的沟通才能卓有成效。\u003c/p>","interaction":"\u003cp>\u003cstrong>接下来，让我们一起进入A便签的A1环节，我邀请大家回忆一下在您工作的过程当中，是否遇到过这样的会议：\u003c/strong>\u003c/p>\u003cp>某个与会者滔滔不绝讲了好久，但是不知所云，和会议没有任何关系；\u003c/p>\u003cp>或者某次会议开了几个小时，其实都是在摆龙门阵，会议结束以后根本没有任何结果；\u003c/p>\u003cp>或者某次会议其实和您关系不大，但是您也不得不参加，陪同开会，浪费您不少时间。\u003c/p>\u003cp>\u003cstrong>如果您曾经遇到过类似的会议，好好回忆一下当时开会的情形，我给大家两分钟时间做一下回顾，完成的小伙伴举手示意一下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接下来，我想邀请大家一起来反思一下，您曾经遇到的糟糕的会议如果运用卓有成效的管理者召开有效会议的3步法，应该如何调整呢？或者近期如果您个人要召开一次会议，您会怎么运用这个3步法，确保会议的效能和品质。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我给大家5分钟时间进行小组内分享讨论，结束以后我将邀请两位小伙伴分享一下讨论结果，每人1分钟时间。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>组员1：杨青\u003c/strong>\u003c/p>\u003cp>学校每周一的例会，存在几个问题：1、主题不清晰；2、会议无针对性，与会人员和讨论内容不相关。3、会议时长冗长。\u003c/p>\u003cp>根据今天所学的卓有成效的管理者召开有效会议3步法，我想学校的例会流程可以做以下调整：\u003c/p>\u003cp>首先，会议的目的进和议题流程可以由主持人事先在校群告知与会教师。相关的会议材料可以先准备。\u003c/p>\u003cp>其次，在会议过程中，相关教师要紧扣主题展开会议讨论，对于跑题的，主持人可以明确制止提醒，为增效我们需要围绕主题。\u003c/p>\u003cp>最后，在会议结束前，主持人或与会教师可以强调本次例会的重点内容，尤其是需要注意的事情，需要特别重申。\u003c/p>\u003cp>\u003cstrong>组员2：黄雨杭\u003c/strong>\u003c/p>\u003cp>我是一名老师，我们常常在学科组内做教学教研会议的时候会遇到一些问题：\u003c/p>\u003cp>在组内开会时大家进入状态比较慢；\u003c/p>\u003cp>有时候讨论了很多但是都不在重点上；\u003c/p>\u003cp>在开会结束后往往什么也没带走。\u003c/p>\u003cp>在学习了今天的开会三步法后，我决定在下次的会议上这样子组织：\u003c/p>\u003cp>首先，一开始就要有主题感和意识感，将今天开会的目标和主要内容展示在PPT上面，并且做好主持的工作；\u003c/p>\u003cp>其次，在开会过程中要把握讨论的方向，如果跑题要及时制止，并提醒回归主题，做好与自己相关内容的记录和思考，及时提出疑问；\u003c/p>\u003cp>最后，在会议结束呼应主题，将每一个内容让相对应的老师重述一遍，确保能带走东西。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1665651220000,"updated_at":1669863835000,"ria":true},{"id":14220,"topic":"一个卓有成效的管理者如何掌握自己时间的3个步骤","learn_goal":"","remark":"这个片段介绍了一个卓有成效的管理者如何掌握自己时间的3个步骤，而这3个步骤是管理者有效性的基础。","level":"TF1-2","duration":14,"status":30,"type":0,"chaishujia":{"username":"光子","city":"福州市"},"club":{"name":"福州筹备分舵","city":"福州"},"prologue":"\u003cp>大家早上好，我是今天的拆书人光子。阳光的光，孔子的子。我现在经营一家30年的老书店-城市绿洲，也是一名资深阅读者和全民阅读推广者，被评为福州的阅读明星。如果您有关于阅读的任何问题，我都是您寻找答案的不二人选。\u003c/p>\u003cp>我还是一名经验丰富的读书会组织者和讲书人，为企事业单位和个人举办各类型阅读活动超过百场。拆书对于我来说是一种全新的学习方法，活到老学到老，我特别期待未来和大家共同学习和成长。谢谢！\u003c/p>\u003cp>接下来，我要给今天的参加者分一下小组。\u003c/p>\u003cp>今天我要给大家拆的书是这本《卓有成效的管理者》，是被誉为现代管理学之父的\u003ca href=\"https://baike.baidu.com/item/%E5%BD%BC%E5%BE%97%C2%B7%E5%BE%B7%E9%B2%81%E5%85%8B/6906406\">彼得·德鲁克编著的一部管理学经典著作。\u003c/p>\u003cp>书中提到，每一位知识工作者其实都是管理者，一位卓有成效的管理者要重视目标和绩效，要做正确的事和最重要的事。在工作中，他知道自己所能做出的贡献，他只做有效的决策。 \u003c/p>\u003cp>这本书的独到之处在于对管理者的概念进行了重新界定，而且奠定了从行为角度研究管理者的现代领导学的学科基础，是任何一位管理者的必读书籍。\u003c/p>","ratings_count":1,"texts":[{"id":18238,"quote":"\u003cp>\u003cstrong>片段来自管理类经典书籍彼得.德鲁克的《卓有成效的管理者》。现在我把片段内容发给大家（发复印好的内容），请大家花2分钟时间来阅读手上的片段，阅读完的小伙伴可以举手示意我一下。\u003c/strong>\u003c/p>\u003cp>关于管理者任务的讨论，一般都从如何做计划说起。这样看来很合乎逻辑。可惜的是管理者的工作计划，很少真正发生作用。计划通常只是纸上谈兵，或只是良好的意愿，很少能够真正实现。\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础。\u003c/p>","explains":"\u003cp>\u003cstrong>接下来，我给大家分享一下这个片段的I便签。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】：\u003c/strong>\u003c/p>\u003cp>这个片段介绍了一个卓有成效的管理者如何掌握自己时间的3个步骤，而这3个步骤是管理者有效性的基础。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【Why】：\u003c/strong>\u003c/p>\u003cp>做任何事情都少不了时间，而时间又是管理者最稀有的资源，他没有替代品，没有供给的任何弹性，无法用钱买到，昨天的时间过去了，永远不再回来。\u003c/p>\u003cp>一个管理者只有懂得掌控时间，学会善用时间才能发挥有效性。才有可能在有限的时间资源里实现工作的有效性。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【How】：\u003c/strong>\u003cbr> 如何掌握自己的时间呢，分成3步：\u003c/p>\u003cp>第一步：就是要清楚知道自己的时间到底用在什么地方，用了多少，并且详细记录下来，比如自己的时间用于拜访客户，每拜访一个客户需要用多少时间；\u003c/p>\u003cp>第二步：就是管理自己的时间，对于非生产性的工作所占用的时间予以减少，非生产性的工作就是没有产生成效的工作，比如市场拓展人员在去拜访客户的通勤过程当中，刷手机视频就属于没有产生成效的工作；\u003c/p>\u003cp>第三步：就是把自己可自由运用的碎片化时间进行整合成大块连续性的时间，比如市场拓展人员拓展市场的过程当中有相当多的碎片化时间，比如等待客户的时间，拜访客户通勤的时间，还有甚至吃早餐的时间，这些零碎的时间都可以想方设法进行整合成大块时间用于更有成效的工作，比如是否可以早一点到客户处，既可以避免交通高峰期浪费大把时间在通勤上面，又把等待客户的时间和消耗在高峰期的通勤时间整合成大块的时间完成需要大块时间才能完成的有成效的工作。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【Where】:\u003c/strong>\u003c/p>\u003cp> 时间管理对于管理者的工作成效来讲是极其重要的，毕竟管理者的时间资源是有限的，越能够掌握时间的去向，有意识地管理自己的时间，才能够在单位时间内价值最大化。\u003c/p>\u003cp>我其实一直都知道时间管理的重要性，但是也发现自己确实经常碰到做事情做了一半被打扰的情况，比如某天上午计划要完成一个策划文案，写了10几分钟，突然就被别人打断工作，不得不去处理的情况，等我处理完回来，写作的思路又得重新开始。这个时候原来的写作灵感已经消失了，还得重新思考，浪费了不少思考的时间。\u003c/p>\u003cp>同样的，在个人的非工作时间的管理上面也同样可以适用，比如很多人都会出现刷手机视频一下子就过去几个小时，结果其他事情都拖延了，以为自己是有拖延症导致，其实是因为不善于管理自己的时间，没有意识到自己的时间都花在什么事情上面。\u003c/p>\u003cp>因此，非常有必要按照3步骤来重新观察和梳理一下自己在一天当中的时间的真实使用。\u003c/p>","interaction":"\u003cp>\u003cstrong>接下来，让我们一起进入A便签的A1环节，我邀请大家想想自己在时间管理方面有没有经历过类似的情境或者相关的经验，请大家互相讨论一下，时间3分钟，讨论结束以后，我会邀请1位小伙伴给我们分享一下，时间2分钟。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>组员1A1：\u003c/strong>\u003c/p>\u003cp>反观自己之前工作的过程中，非生产性工作所占用的时间较少，工作的时候基本不玩手机，不进行工作以外的事情，这可以使自己保持专注，不分心。\u003c/p>\u003cp>这一点做得很好，要继续保持。\u003c/p>\u003cp>\u003cstrong>组员2A1：\u003c/strong>\u003c/p>\u003cp>回顾我的时间安排，我习惯于从年计划拆解到月计划，再到日程表，然后按照日程表实施计划。但对于具体每项工作的用时缺乏记录，对于非生产性事项的管理我做得还可以，工作时不会被无关事情干扰，零碎时间用得比较合理，但没有像这里所学的那样把零碎时间进行规整。对照今天所学，时间管理上还是有值得优化的地方的。\u003c/p>\u003cp>\u003cstrong>最后在A2环节，我邀请在座的小伙伴在您面前的便签纸上写下如何具体应用这个片段知识点的学习，大家需要写下具体的目标和行动计划，目标需要包括具体的时限和可衡量的结果。现在给大家3分钟时间来完成。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>组员1A2：\u003c/strong>\u003c/p>\u003cp>目标：在未来一周内，将完成某项事务需要的时间规划的更加精准。\u003c/p>\u003cp>行动：当我要规划某项事务时，要仔细思考事务背后需要完成的每一件事情，并规划好总时长。\u003c/p>\u003cp>\u003cstrong>组员2A2：\u003c/strong>\u003c/p>\u003cp>我计划在接下来的一周尝试使用这种时间管理法安排我的工作。具体如下：\u003c/p>\u003cp>【记录时间】先用表格记录下周所有日程上的重点工作的用时。\u003c/p>\u003cp>【管理时间】监测非生产性时间的使用情况。\u003c/p>\u003cp>【整合时间】尝试将零碎时间整合成连续性时段。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1663725055000,"updated_at":1663725108000,"ria":true},{"id":13956,"topic":"卓有成效的管理者","learn_goal":"","remark":"片段来自管理类经典书籍彼得.德鲁克d 《卓有成效的管理者》。这个片段介绍了要成为一个卓有成效的管理者，在思想上面需要培养的5个习惯的第3个习惯，就是：\n善于利用自己和他人的长处，做自己擅长做的事情；做自己能做的事情，不要在自己的短处和不擅长的工作上面花费时间精力，更不要去做自己没有能力做到的事情。","level":"TF1-1","duration":14,"status":30,"type":0,"chaishujia":{"username":"光子","city":"福州市"},"club":{"name":"福州筹备分舵","city":"福州"},"prologue":"\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp> 大家早上好，我是今天的拆书人光子。阳光的光，孔子的子。我现在经营一家30年的老书店-城市绿洲，也是一名资深阅读者和全民阅读推广者，被评为福州的阅读明星。如果您有关于阅读的任何问题，我都是您寻找答案的不二人选。\u003c/p>\u003cp> 我还是一名经验丰富的读书会组织者和讲书人，为企事业单位和个人举办各类型阅读活动超过百场。拆书对于我来说是一种全新的学习方法，活到老学到老，我特别期待未来和大家共同学习和成长。谢谢！\u003c/p>\u003cp>\u003cstrong>拆书法/帮介绍：\u003c/strong>\u003c/p>\u003cp>什么是拆书呢？“拆”，不是把书拆散，而是把知识内化、拆为己用；“拆书”是一种学习方法，适用于以提升能力、解决问题为目标的成人学习。它强调以学习者为中心，而不是以知识为中心，要求把知识关联学习者的经验、规划具体的运用。\u003c/p>\u003cp>拆书法分为个人学习的拆书法和组织学习的拆书法。个人学习的拆书法，也叫RIA便签法。R指的是阅读书中的原文片段，I就是用自己的语言重述对原文拆页的理解，A一般分为A1和A2，A1便签是针对过去，反思自己过去的相关经验，A2则是面向未来，规划自己的运用。个人通过拆一本书可以达到参加同主题培训的效果。\u003c/p>\u003cp>组织学习的拆书法，是指拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。一位拆书家创造的学习价值不亚于一位培训师。\u003c/p>\u003cp>拆书法的学习爱好者组成的社群，就是“拆书帮”。它是非营利性的青年自组织，表现为各地的拆书帮分舵，目前覆盖全国28个省47座城市；它的使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":17963,"quote":"\u003cp>\u003cstrong>R便签：\u003c/strong>\u003c/p>\u003cp>片段来自管理类经典书籍彼得.德鲁克d 《卓有成效的管理者》。\u003c/p>\u003cp>下列5项是要成为一个卓有成效的管理者，必须在思想上养成的习惯。\u003c/p>\u003cp>（1）省略\u003c/p>\u003cp>（2）省略\u003c/p>\u003cp>（3）有效的管理者善于利用长处，包括自己的长处、上司的长处、同事的长处和下属的长处。他们还善于抓住有利形势，做他们能做的事。他们不会把工作建立在自己的短处上，也绝不会去做自己做不了的事。\u003c/p>\u003cp>（4）省略\u003c/p>\u003cp>（5）省略\u003c/p>","explains":"\u003cp>\u003cstrong>I便签：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】：\u003c/strong>\u003c/p>\u003cp>这个片段介绍了要成为一个卓有成效的管理者，在思想上面需要培养的5个习惯的第3个习惯，就是：\u003c/p>\u003cp>善于利用自己和他人的长处，做自己擅长做的事情；做自己能做的事情，不要在自己的短处和不擅长的工作上面花费时间精力，更不要去做自己没有能力做到的事情。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【Why】：\u003c/strong>\u003c/p>\u003cp>这是一个焦虑和快速变化的时代，企业处于这样的时代，面临发展的巨大挑战和压力。对于企业管理者来说，付出自己的知识和才干，却没有成效，意味着个人时间精力的投入、企业人力物力财力的投入没有产出结果，没有得到反馈，那么管理者的个人价值和组织价值就无法实现。个人和企业的发展也无从谈起。\u003c/p>\u003cp>这5大习惯的第3个习惯着眼于自己和他人擅长的事情，同样一件事，擅长的人做可以产生更大的成效和反馈，好的反馈同样会激励做事的人更加投入和努力。而对于企业和组织来讲，投入同样的时间和人力，交给擅长的人做，产出也更大。成效是卓有成效管理者和企业的终极目标。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【How】：\u003c/strong>\u003cbr> 如何培养这个思维习惯，在这个片段当中没有特别明确的描述，但是依然可以找到可执行的方法。不妨可以这样问问自己，自己和他人的优势是什么呢？最擅长做的是什么事情呢？所谓最擅长的事其实就是同样一件事，同样的投入，你如果比别人更有成效就是你比别人擅长做这件事。\u003c/p>\u003cp>所以，这个思维习惯的养成首先是了解自己的长处。不妨拿出一支笔，在一个安静的环境下面，思考一下自己的长处，然后和了解自己的朋友讨论一下是否属实，再结合具体的工作进行能力配比思考，必然更加清楚地了解自己最擅长的是什么？\u003c/p>\u003cp>至于其他人的长处和最擅长的工作，也同样可以参考以上的方法来尝试找出。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【Where】:\u003c/strong>\u003c/p>\u003cp> 这个思维习惯不仅仅用于企业管理者培养有效性，对于个人的自我管理也同样适用，很多中年危机的产生就是因为同时做很多事情，每一样事情都不专精，结果看上去很忙碌，做了很多事情，却不能产出期待的结果。\u003c/p>\u003cp>毕竟一个人的时间精力有限，聚焦在自己最擅长的事情上面，才可能在人生的各个方面比如财务，健康等等上面有自知之明，产出最大化。没有结果的努力都是低水平的奋斗，其实本质上就是没有在自己的长处方面下功夫。\u003c/p>\u003cp>当然，在团队的合作上面也是可以通过每一个人的长处分析来进行团队组建，每一个人都做自己最擅长的事情，整个团队的绩效才能最大化。\u003c/p>","interaction":"\u003cp>\u003cstrong>A便签：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这一片段内容让我联想：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1相关经历】：\u003c/strong>\u003c/p>\u003cp>我和我的合伙人在一起共事的时候，经常会责备他，比如考虑不周全，不注意细节，沟通喜欢打断别人，没有同理心等等，而且是当着其他人的面批评他。我的合伙人脾气比较好，也没有和我反驳，就是笑笑。\u003c/p>\u003cp>特别有一次，是一个月之前，我们搬到新的办公地点，由于没有书架，我的书就放在我自己的办公桌上面，结果合伙人三番五次地建议我不要把书放在桌子上。我觉得很烦，后来实在受不了，就发火了，干脆把书都拿回家了。\u003c/p>\u003cp>这个事件搞得我很不痛快，一度不想和合伙人共事，也不想交流，我觉得他没有同理心，有强迫症的倾向。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【A1反思】： \u003c/strong>\u003c/p>\u003cp>卓有成效的管理者要善于利用别人的长处这个思想习惯给我很大的启发。我一直看别人的短处对于公司的发展其实没有任何帮助，反而会打击别人的做事积极性，虽然对方嘴上不说，但是公司的业绩确实受到影响。更不用说自己也不痛快，心情不好有压力，怎么可能有热情做事呢？\u003c/p>\u003cp>\u003cstrong>【A2目标】：\u003c/strong>\u003c/p>\u003cp> 给自己设定一个目标，用两周时间不再挑合伙人的短处，而且发现他的长处并且鼓励他去做擅长的事情。\u003c/p>\u003cp>\u003cstrong>【A2行动】：\u003c/strong>\u003c/p>\u003cp>为了实现这个目标，我打算采取以下行动：\u003c/p>\u003cp>第一步，从下周一开始，一周时间内从实际工作当中观察、发现和总结合伙人的长处。\u003c/p>\u003cp>第二步，和第一步同时做，把合伙人当下的工作内容做一个梳理，列出他现阶段的工作内容；\u003c/p>\u003cp>第三步，从第二周开始，评估一下合伙人的长处是否用到了他的工作内容上面，或者说是否有一些工作内容不能发挥他的长处\u003c/p>\u003cp>以上行动都用笔记录下来，两周以后，和合伙人做一次沟通，对于长处和工作的匹配度和合伙人进行深度沟通，达成共识，进而更加有效地利用合伙人的长处匹配适合的工作。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1660392578000,"updated_at":1662885444000,"ria":true},{"id":13570,"topic":"如何诊断自己的时间","learn_goal":"","remark":"我们或多或少有工作前先规划自己时间的意识和行动。规划时间之后，有时发现每件事情都是影响关键性结果的的事情，无法割舍，自己最终还是忙忙碌碌，结果不尽如人意。这就需要我们具有识别对关键性结果无意义的事情的方法\n","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"张海燕","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>\u003cstrong>【开场】自我介绍和图书介绍 1.5分钟\u003c/strong>\u003c/p>\u003cp>感谢各位伙伴的耐心陪伴！接下来是我的1-2过级，带领大家拆解的片段仍然是选自《卓有成效的管理者》，这本书是由美国管理学家\u003ca href=\"https://baike.baidu.com/item/%E5%BD%BC%E5%BE%97%C2%B7%E5%BE%B7%E9%B2%81%E5%85%8B/6906406\">彼得·德鲁克编著的一部管理学著作，距今已经有五十多年的时间，到现在仍然被管理者广为传阅，内容之经典大家可想而知。\u003c/p>\u003cp>《卓有成效的管理者》成为管理学类图书中非常畅销及实用的一本，犹如良师益友，是因为虽然我们面对的是相似的情形，却能从不同的角度说出你不曾觉察到的理念，常有茅塞顿开之感。\u003c/p>\u003cp>我们通过前面的学习或多或少有了规划自己时间的意识和行动，规划时间之后发现仍然有事情做不完，自己处于忙碌中，这是什么原因呢？这就需要我们具有识别对关键性结果无意义的事情的方法。\u003c/p>\u003cp>\u003cstrong>有关书籍的介绍就到这里，接下来请大家花1分钟时间看下我分发的拆页。\u003c/strong>\u003c/p>","ratings_count":2,"texts":[{"id":17598,"quote":"\u003cp>\u003cstrong>【R原文片段】阅读原书拆页1分钟\u003c/strong>\u003c/p>\u003cp>《卓有成效的管理者》第35-37页\u003c/p>\u003cp>如何诊断自己的时间\u003c/p>\u003cp>经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免再回到浪费的状态上去。\u003c/p>\u003cp>因此，第二个步骤就是要做有系统的时间管理。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以试问自己下列几个问题。\u003c/p>\u003cp>1．首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>2．第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果？”\u003c/p>\u003cp>3．还有一项时间浪费的因素，是管理者自己可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/p>","explains":"\u003cp>\u003cstrong>【I环节】拆书家讲解引导4.5分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>好，看到大家已经阅读完拆页了，接下来开始分享今天的拆页。\u003c/strong>\u003c/p>\u003cp>（What）这个片段提供了管理者想要做到“减少对关键性结果无意义的时间投入”可以从3个方面入手找出浪费时间的活动。\u003c/p>\u003cp>（Why）多数人能够成为管理者，甚至于做了一段时间管理工作，或多或少会有工作前先规划自己时间的意识和行动。规划时间之后，有时发现每件事情都是影响关键性结果的的事情，无法割舍，自己最终还是忙忙碌碌，结果不尽如人意。这就需要我们具有识别对关键性结果无意义的事情的方法，掌握了这些方法，我们可以把排满的时间表，腾出一些时间来，给关键性结果有意义的事情多些时间，不必让自己过于忙碌，无暇思考，让自己的管理更高效。\u003c/p>\u003cp>（How）\u003c/p>\u003cp>方法一，对照时间记录找出根本不必做的事情。对照事项逐项进行判别，每项都问自己：“这件事情对我现阶段想要的结果能起到关键的作用吗？如果不做，会有什么后果？这件事跟另外一件事对比，哪个更重要？”。自己反复对话自己，如果得出“不做不会有任何影响”，那么这件事就可以从时间表上剔除。\u003c/p>\u003cp>方法二，不影响效果的事情由别人代为参加。遇到当下阶段需要完成，且需要占用时间的事情，可以问自己：“这个事情必须我自己亲自去做吗？我不能亲自去做，他人代替我去做，有什么影响吗？没有影响，谁可以代我去做？”\u003c/p>\u003cp>方法三，不要浪费别人的时间。管理者管理时间的时候，在自己非常忙碌的情况下，运用前面两个方法，可以找出浪费时间的事情。有时自己没那么忙碌，会开始给自己找事情做，比如跟下属开个会，讨论下某个方案。这会陷入不经意间浪费了下属的时间，使组织的效率受到影响，从而影响关键性结果。\u003c/p>\u003cp>（Where）掌握诊断时间表上的每项事情的方法，可以让管理者的时间管理可以更好的执行落地，而不是停留在记录规划了时间，能够更高效的利用自己的时间。\u003c/p>\u003cp>（Example）\u003c/p>\u003cp>我绝大多数工作是做运营管理工作，到了月底月初特别忙碌，有围绕业绩开展的既定工作，也有一些临时性的工作。遇到这种情况，我需要先用方法一“对照时间记录找出根本不必做的事情”，需要我做分析，做决策的，比如对当月业绩分析总结，进而制订下月计划，以及配套的营销活动方向，是我必须亲自做的事情。而活动方向确定后，活动方案的整理审批，以及临时的招聘复试，下属工作心态访谈，是相对来说不必做的事情。然后会用到方法二“不影响效果的事情由别人代为参加”比如隔级下属复试，我的直接下属已经觉得OK，我只是综合考察下价值观，匹配度，可以请人力资源总监（之前做过运营，懂业务）代我复试，月初活动方案，已经讨论出来的，需要整理成档，签字审批，交代给我直接下属中一个文字能力强，条理性好的同事，她整理后，我只要稍微看下就可以了。这种忙碌的时间，通常销售团队也在忙着盘点资源，冲刺业绩，我告诉自己“不要浪费下属的时间”，除了必须的事情，其他的时间留给团队冲刺业绩，他们也想这个月给自己的辛苦画上一个圆满的句号，想让自己的绩效不留遗憾，就用到了方法三。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1环节】分享各自过往经验5分钟\u003c/strong>\u003c/p>\u003cp>以上就是我对这个拆页的理解和思考了，接下来请每个人想一个你过往经历过的“很忙碌，但却做了浪费时间的事情”的案例，然后在小组内轮流进行分享，这个环节我们给大家4分钟的时间。分享的具体要求：1、故事：时间、地点、人物、事件起因、经过、结果（饱含情感/情绪、关键细节/行为）2、反思：哪些地方做得不好/不够好，哪些地方可以如何做得更好。小组内分享结束后，我会邀请一位伙伴给大家分享。好的，现在开始。\u003c/p>\u003cp>好的，美好的时光总是那么短暂，4分钟过去了，请周老师给大家分享下。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>周老师：某一天晚上，自己在没有完成既定工作的情况下，去看了一场自己不是特别满意的电影，电影结束后回家辗转反侧，最终决定进行工作补救，到凌晨两三点才完成，并且第二天早上面临迟到的危险。回顾这次经历，自己很忙碌，但仍然做了浪费时间的事情。\u003c/p>\u003cp>感谢周老师的分享。\u003c/p>\u003cp>\u003cstrong>【A2环节】写下各自应用1分钟\u003c/strong>\u003c/p>\u003cp>好的，咱们今天已经学习了从3个方面入手找出浪费时间的活动的方法，学以致用才能真正地收获。各位可以思考一下在自己未来1周，1个月，或3个月内，生活或工作当中，可能出现的忙碌场景，而出现这种情况后，自己可以如何使用今天学习的方法来处理？此计划不能仅是表决心，要是具体的做法，明确的时限，和可衡量的结果。请大家用一分钟写在便签上。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>程老师背景，一名初中英语老师，最近自己在准备示范课，白天学校事情多，家中小孩晚上和周末学习需要陪伴，之前跟邻居闺蜜有晚饭后一起散步的习惯。\u003c/p>\u003cp>目标：顺利完成示范课准备。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1.今天跟闺蜜发消息说明最近时间紧张，晚饭后散步暂停一周。\u003c/p>\u003cp>2.今天回去跟先生商量6月17日完成示范课之前，晚上和周末的时间由他陪伴孩子学习和玩耍。\u003c/p>\u003cp>3.明天（6月10日）开始，晚饭后集中40分钟把家务收拾完毕。\u003c/p>\u003cp>4.周五晚上8:00-11:00，集中准备示范课课件，周六全天打磨细节，进行一遍演练。这样不用浪费年级主任帮忙打磨课件的时间，她的工作也很忙。\u003c/p>\u003cp>5.周日请年级主任帮忙现场听一遍，记录改进点。\u003c/p>\u003cp>6.周一至周三每天晚上花2个小时，自己练习，揣摩，周四好好休息。\u003c/p>\u003cp>7.周五（6月17日）完成示范课。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1655098713000,"updated_at":1655957007000,"ria":true},{"id":13569,"topic":"掌握自己的时间","learn_goal":"","remark":"作者彼得.德鲁克被称为管理学大师。 这本书是他的经典著作，本书从5个方面介绍了如何卓有成效，分别是掌握自己的时间、把眼光聚焦在贡献上、发挥人的长处、要事优先、有效决策。不管你是一位管理者，还是一位职员，是否有过手忙脚乱，工作一天下来，上厕所是一路小跑完成的，吃饭是狼吞虎咽完成的经历？今天“掌握自己的时间”让你告别忙乱\n","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"张海燕","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>\u003cstrong>【自我介绍】1分钟\u003c/strong>\u003c/p>\u003cp>大家好，我是海燕。很开心能够在这个合适的时间，遇见优秀的各位，感谢各位参加拆书帮今天的活动。\u003c/p>\u003cp>通过工作、生活、学习三个标签介绍我自己，分别是：\u003c/p>\u003cp>教育工作者：12年成人职业教育培训，1年早幼教培训；其中11年运营管理经验，2年人力资源工作经验\u003c/p>\u003cp>偶尔鸡娃的妈妈： 儿子6岁，专注力较强，可以持续拼搭积木4小时以上，生活常用汉字基本认识；由于我工作忙下班晚，过去半年时间，古诗背诵仍停留在一级水平，如果有充足时间鸡娃，预计可以达到三级\u003c/p>\u003cp>爱折腾的学习者：个人学历、证书、技能方面有诸多浅尝辄止，今年目标是拿下三级拆书家，SYB师资认证，将标签改写为“终身学习者”\u003c/p>\u003cp>\u003cstrong>【拆书和拆书帮是什么】1.5分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>进行正式拆书之前，对于拆书法和拆书帮做个简短的介绍。\u003c/strong>\u003c/p>\u003cp>“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习\u003c/p>\u003cp>者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学\u003c/p>\u003cp>习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到参加同\u003c/p>\u003cp>主题培训的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进\u003c/p>\u003cp>一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一\u003c/p>\u003cp>位培训师。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部）\u003c/p>\u003cp>拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>\u003cstrong>拆书法具体是怎样的呢？请跟随我的指引和展示来感受。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>刚才有给各位分发一张原文片段，请大家花1分钟时间阅读原文片段。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":17597,"quote":"\u003cp>\u003cstrong>【R原文片段】阅读原书拆页1分钟\u003c/strong>\u003c/p>\u003cp>《卓有成效的管理者》第24页\u003c/p>\u003cp>掌握自己的时间\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\u003c/p>\u003cp>●记录时间；\u003c/p>\u003cp>●管理时间；\u003c/p>\u003cp>●统一安排时间。\u003c/p>","explains":"\u003cp>\u003cstrong>【I便签】是用自己的语言重述知识 \u003c/strong> \u003cstrong>3分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>有看到各位给我的非语言表达的反馈，已经阅读完原文片段了。接下来各位可以结合原文片段，认真倾听我的分享。\u003c/strong>\u003c/p>\u003cp>（What）原文片段告诉了我们管理者有效性的基础的三个步骤。\u003c/p>\u003cp>（Why）作为一个管理者是通过管理向团队拿结果的，多数管理者会面临自己的时间不够用，忙碌起来连吃饭、上厕所的时间可能都没有，有时结果也不尽如人意。学习了今天这个片段后，知道了管理者想要有效进行管理，要能够掌握自己的时间，把时间花在生产性工作上，这样管理者的有效性得以保障。\u003c/p>\u003cp>（How）\u003c/p>\u003cp>第一，规划自己的时间。作为管理者即使有再多的事情需要处理，需要解决，工作之前不要急于着手工作，可以从时间出发，记录自己什么时候做什么事情，这是管理者有效性基础的第一个步骤。\u003c/p>\u003cp>第二，减少对关键性结果无意义的时间投入。管理者需要对很多事情负责，每个阶段有每个阶段的侧重点，不能眉毛胡子一把抓，当下这个阶段想要达成的关键性结果是什么，影响关键性结果的事情可以多花时间，对关键性结果无意义的时间在当下这个阶段要减少时间投入。\u003c/p>\u003cp>第三，零星时间重组再安排。经过对自己的时间规划表进行删减调整后，时间表会出现零星可自由运用的时间，零星的碎片时间可以解决碎片的事情，管理者时间有效性要结果，光有碎片时间是不够得，需要有连续性的集中时间段，这时可以将零星时间重新组合，调整事情安排顺序，获得大块时间段，更有助于管理有效性的达成。\u003c/p>\u003cp>（Where）掌握自己时间的3个步骤，任何一个人想高效利用自己的时间，在有限的时间内获得更大的成效都可以使用这3个步骤，管理者更需要使用这3个步骤。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1便签】自己的相关经验 \u003c/strong> \u003cstrong>3分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>说到这里，联想到一个发生在我身上的经历。事情是这样的…\u003c/strong>\u003c/p>\u003cp>五一假期前，4月27日，周三的晚上我有5分钟左右处于焦虑时间的状态，想到周四、周五已经4月28日29日有几件事情需要做，为时间赶到焦虑了5分钟之后，我妥善的安排好了接下来两天的时间计划，心里敞亮了很多。 \u003c/p>\u003cp>反思：之前只是以为自己计划性强，条理性好，学习了这个片段发现是做到了掌握自己时间的三个步骤。\u003c/p>\u003cp>1、规划自己的时间。在脑海里面把以下需要做的事情按照时间顺序进行了简单的排序，29日下午1点出发去面试，儿子在幼儿园过生日相关准备，现有工作交接，29日中午前做核酸检测以备30日出结果作为出行凭证，面试前的知识准备，拆书训练营的28日29日应完成作业，五一长途出行前的采买。\u003c/p>\u003cp>2、减少对关键性结果无意义的时间投入。儿子在幼儿园过生日，周三晚上当时就联系老师，沟通什么时间可以庆祝（因为儿子生日是5月2日，他想跟同学一起庆祝，5月2日是放假中，所以28日29日哪天都可以），老师回复可以，并且批准了可以带的食物，协调沟通周五下午庆祝，儿子庆祝生日的相关准备跟我当下阶段其他事情相比就属于无意义的时间投入了，就安排先生跟老师对接，准备食物。其他必须我亲自完成，其他人不可替代，就是对关键性结果有必要的时间投入。\u003c/p>\u003cp>3、零星时间重组再安排。之前是deadline完成拆书作业，决定28日晚上把28日29日作业都完成，29日晚就不用惦记作业了，可以准备采买了。把分散在2天的作业，一天完成，为29日晚上采买也腾出了大段时间。\u003c/p>\u003cp>\u003cstrong>【A2便签】规划自己的运用 \u003c/strong> \u003cstrong>1分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>鉴于这次时间管理的成功经验，我结合拆页提出的方法为自己做出了行动规划 \u003c/strong>\u003c/p>\u003cp>目标：教会儿子早上起床至上学前可以掌握自己的时间。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1、5月4日晚上跟儿子分享自己上面的经历，讲解沟通掌握自己时间的意义。\u003c/p>\u003cp>2、跟儿子一起制定早上起床后到上学前自己的时间规划。\u003c/p>\u003cp>3、5月5日早上执行计划的时候，他出现对关键性结果无意义的时间投入，及时给他进行分析，指导进行时间重组再安排。\u003c/p>\u003cp>4、坚持1周每天都重复上面的步骤。\u003c/p>\u003cp>以上就是我给大家分享的来自经典书籍《卓有成效的管理者》中的一个片段，希望通过这个片段，大家可以对掌握自己时间有效性有进一步的理解和应用。\u003c/p>\u003cp>好的，我今天的讲解就到这里。最后，感谢大家的参与聆听，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1655097687000,"updated_at":1655098988000,"ria":true},{"id":13487,"topic":"卓有成效的管理者","learn_goal":"","remark":"卓有成效的管理者","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"席路","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>大家好，我是蜗牛路小路，对，就像蜗牛一样，在成长的路上走得很慢，但每一步都坚实无比，小小的身躯，依旧有大大的梦想。\u003c/p>\u003cp>今天要给大家分享的拆页片段，来自现代管理学之父彼得·德鲁克的经典之作《卓有成效的管理者》。这本书的独特之处在于它所面向的对象并非仅仅是我们通常所理解的企业管理者，而是个人。这本书将帮助每个渴望追求卓越的人变得卓有成效。\u003c/p>\u003cp>在跟随我完成本次RIA学习以后，学习者能够开始管理自己的时间，迈出卓有成效的第一步。咱们今天将以小组的形式来进行学习，左手边的伙伴为一组，右手边的为一组。\u003c/p>","ratings_count":2,"texts":[{"id":17508,"quote":"\u003cp>摘自《卓有成效的管理者》第二章-掌握自己的时间 P28\u003c/p>\u003cp>关于管理者任务的讨论，一般都从如何做计划说起，这样看来很合乎逻辑。可惜的是管理者的工作计划，很少真正发生作用。计划通常只是纸上谈兵，或只是良好的意愿，很少能够真正实现。\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\u003c/p>\u003cp>记录时间\u003c/p>\u003cp>管理时间\u003c/p>\u003cp>统一安排时间\u003c/p>","explains":"\u003cp>好，我看到大家已经看完拆页了，接下来开始分享今天的拆页。\u003c/p>\u003cp>【WHY】:不知大家是否遇到过以下几种场景？想读书，但总觉得没有时间，1个月过去了，还停留在第一页；想锻炼，当想起来时，健身卡早就过期了；想来拆书帮晋级，看书、写稿、背稿，但总是遇到各种状况而推迟，正如我现在一样，半年了还停留在TF1-1。\u003c/p>\u003cp>我们好像很忙，但好像也没有做成什么事。\u003c/p>\u003cp>【WHAT】：可你是否见过很多牛人，他们可以同时做很多事情，而且拿到成果。比如一年看100本书；半年跑1000公里；3个月拿下项目管理证书。你可能会好奇他们怎么有那么多时间？今天，我们就通过拆页中给我们提供的“时间管理三步法”来一窥时间管理牛人的秘密。\u003c/p>\u003cp>【HOW】：分享三个步骤。\u003c/p>\u003cp>\u003cstrong>第一步是记录时间。\u003c/strong>把每天做了什么事，每件事花了多少时间记录下来。为了更方便地进行时间记录。我们可以运用一些时间管理工具，比如番茄To Do或是Forest专注森林对时间进行标签化管理。像每天阅读1个小时，运动30分钟，刷抖音3小时等等。\u003c/p>\u003cp>\u003cstrong>第二步是管理时间。\u003c/strong>识别高低价值活动，并根据活动的重要程度，删除低价值的活动。比如阅读、运动就是高价值活动，它能产生有价值的成果；而无目的的刷抖音，就是低价值活动。我们常常流连于抖音、快手而无法自拔，尽管已经刷了好几个小时，但仍旧停不下来。如果去掉刷抖音的活动，或者大幅度减少此类活动的时间，比如原先你是刷3个小时，你可以给自己做一项规定，允许自己在晚上8点-8点半这个时间段刷半个小时的短视频。像这样，你就能解放出大量时间，做你想做的事情。\u003c/p>\u003cp>基本上一天做好三件事，工作量就已经非常饱和了。所以一定要有思考，让真正重要的事情浮出水面。时间管理牛人通常都有成本思维，低价值的活动不做，自己不擅长的事情请别人做，一旦理解了不同的人、不同用途的时间所产出的价值是不一样的。删除低价值活动，你会开始学会做重要的事。\u003c/p>\u003cp>\u003cstrong>第三步是统一安排时间\u003c/strong>。在第二步中，我们通过删除低价值活动，聚焦有价值产出的重要事情。但还不够。我们还需要对重新解放出来的时间进行统一规划。一方面可以在固定的时间做固定的事情，比如像我每天早上5：50-6：50雷打不动地参与演讲直播练习，破除公众演讲的紧张；6：50-7：10跟随健美操教练运动，保持身体健康；另一方面，可以将零星的时间汇聚成块。因为完整的时间对于专注做一件有价值的事情非常重要。\u003c/p>\u003cp>【WHERE】：当然时间管理三步法不局限于个人日常生活的时间管理，也适用在工作中，如果你正好是一名管理者，也可以通过此方法去诊断、筛选并运用你的时间。减少不必要的会议，减少不必要的社交，提高工作效率。\u003c/p>\u003cp>大家之所以称一个人为时间管理牛人，并不是亲眼看到这个人时间利用效率很高，而是发现这个人在同样的时间内，产出的成果远远超出他们自己。把时间尽可能多地分配到少数有产出的事情上，而不是让自己的注意力漂移不定，这就是成为时间管理牛人的秘密。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活旧知\u003c/strong>\u003c/p>\u003cp>好的，现在请每个人先回忆自己曾经是否有过“感觉自己很忙，但没有产出成果”的经历，然后在小组内轮流进行分享，每个人一分钟，这个环节我们给大家4分钟的时间。然后我会请一位伙伴为大家进行分享。好的，现在开始。\u003c/p>\u003cp>【现场案例】\u003c/p>\u003cp>平成有很多事情想做，一会做这个一会做那个，但做的过程中，前面所做的额事情会被打断。就会让人觉得，虽然事情做了很多，但是效果没有提升，时间没有管理好。\u003c/p>\u003cp>时间：最近一周\u003c/p>\u003cp>地点：健身房\u003c/p>\u003cp>人物：现场一位伙伴\u003c/p>\u003cp>事件：我花钱报了一个健身班，之前还是会经常去。但最近一周的时间由于各种事情，比如来拆书帮等等不同的事情，就会打断健身的计划，感觉好像很忙，但是确实也没拿到实际的成果。\u003c/p>\u003cp>\u003cstrong>【A2】学以致用\u003c/strong>\u003c/p>\u003cp>好的，咱们今天既然学习了这个方法，而学以致用才能真正地收获。\u003c/p>\u003cp>各位可以思考一下在自己未来1周，1个月，或3个月内，生活或工作当中，可能忙而无果的场景？而出现这种情况后，自己可以如何使用今天学习的“时间管理三步法”来处理？此计划不能仅是表决心，要是具体的做法，明确的时限，和可衡量的结果。请大家用一分钟按照为大家提供的“时间管理三步法”写在便签上。\u003c/p>\u003cp>【现场案例】\u003c/p>\u003cp>下周时间安排\u003c/p>\u003cp>一、记录时间\u003c/p>\u003cp>二、保留重要事情\u003c/p>\u003cp>三、统一安排时间\u003c/p>\u003cp>1、安排6点早起听课\u003c/p>\u003cp>2、上班时间提前半小时，来提前安排当天地工作事项\u003c/p>\u003cp>4、晚上锻炼半小时，每周三次\u003c/p>\u003cp>3、周三下午三点，联系客户节前事宜\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1653877473000,"updated_at":1654666471000,"ria":true},{"id":13098,"topic":"卓有成效的管理者","learn_goal":"","remark":"卓有成效的管理者","level":"TF1-2","duration":15,"status":19,"type":0,"chaishujia":{"username":"任静","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp> 大家好，我是任静。接下来我将通过三个标签来请大家进一步认识我，分别是爱学习、企业培训老人、拆书帮新人。\u003c/p>\u003cp>首先是爱学习，工作之余我做的最多的事情就是看书、学习，学习使我获得的最大收获是：遇到过很多厉害的前辈，帮我开拓视野，指点迷津；通过学习使我在很多领域有了更系统的知识储备，在需要的时候可以随时取用。\u003c/p>\u003cp>其次是企业培训老人，我从13年毕业至今9年时间一直从事企业内人才赋能及人才发展工作。目前在阿里本地生活做培训经理。\u003c/p>\u003cp> 最后，作为一名拆书帮新人，希望能有更多学习机会，向各位前辈们交流学习。虽然今天是我第一次参加拆书帮认证，但我有信心也有决心自己一定可以坚持到三级拆书家认证，谢谢大家。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>Feature：\u003c/p>\u003cp>今天要带大家拆的这本书是《卓有成效的管理者》，是由美国管理学家\u003ca href=\"https://baike.baidu.com/item/%E5%BD%BC%E5%BE%97%C2%B7%E5%BE%B7%E9%B2%81%E5%85%8B/6906406\">彼得·德鲁克编著的一部管理学著作，1966年首次出版。距今已经有56年的时间，到现在仍然被管理者广为传阅，内容之经典大家可想而知。\u003c/p>\u003cp>Advantage： \u003c/p>\u003cp>书中提到，每一位知识工作者其实都是管理者，而且卓有成效是每个管理者必须做到的事。\u003c/p>\u003cp>书中认为所有负责行动和决策而且能够提高组织工作效率的人，都应该像管理者一样工作和思考。\u003c/p>\u003cp>所以，我一直认为这本书对于提升普通员工的认知和引导员工认清自己所做事情的价值上有非常重要的作用。\u003c/p>\u003cp>Benefit： \u003c/p>\u003cp>这本书最独到之处不仅仅在于对管理者的概念进行了重新界定，而且奠定了从行为角度研究管理者的现代领导学的学科基础。\u003c/p>","ratings_count":1,"texts":[{"id":17077,"quote":"\u003cp>有关书籍的介绍就到这里，接下来请大家花2分钟时间看下我发给大家的拆页。请大家主要阅读有背景颜色的部分，完成阅读的小伙伴请在聊天框中发送数字“1”\u003c/p>\u003cp> 拆页原文：片段来自《卓有成效的管理者》\u003c/p>\u003cp> 根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\u003c/p>\u003cp> · 记录时间；\u003c/p>\u003cp> · 管理时间；\u003c/p>\u003cp> · 统一安排时间。\u003c/p>\u003cp> 有效的管理者知道，时间是一项限制因素。任何生产程序的产出量，都会受到最稀有资源的制约。而在我们称之为“工作成就”的生产程序里，最稀有的资源，就是时间。\u003c/p>\u003cp> 时间也是最特殊的一项资源。在其他各项主要资源中，资金一项实际上是相当充裕的。我们很久以前就已经了解到，制约经济增长与经济活动的，并不是资金的供给不足，而是对资金的需求不大。此外另一个限制因素是人力，但总还是可以雇到人才，尽管要雇用到足够的优秀人才并不容易。只有时间，是我们租不到、借不到，也买不到，更不能以其他手段来获得的。\u003c/p>\u003cp> 时间的供给，丝毫没有弹性。不管时间的需求有多大，供给绝不可能增加。时间的供需没有价格可资调节，也无法绘制边际效用曲线。而且，时间稍纵即逝，根本无法贮存。昨天的时间过去了，永远不再回来。所以，时间永远是最短缺的。\u003c/p>\u003cp> 时间也完全没有替代品。在一定范围内，某一资源缺少，可以另觅一种资源替代。例如铝少了，可以改用铜；劳动力可以用资金来替代。我们可以增加知识，也可以增加人力，但没有任何东西可以替代已失去的时间。\u003c/p>\u003cp> 做任何事情都少不了时间，时间是必须具备的一个条件。任何工作都是在时间中进行的，都需要耗用时间。但是对这项最特殊的、无可替代的和不可或缺的资源，绝大多数人却都以为可以取用不竭。有效的管理者与其他人最大的区别，就是他们非常珍惜自己的时间。\u003c/p>","explains":"\u003cp>【WHAT】这段文字向我们说明了管理者有效性的基础是管理好自己的时间，并介绍了管理时间的三步骤。\u003c/p>\u003cp>【WHY】时间是我们做事情必须具备的一个条件，是一项稀有资源，没有替代品。管理好自己的时间是我们成为有效的管理者的基础。 \u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>1、\u003cstrong>记录时间：\u003c/strong>首先清楚自己的时间都用在了什么地方，可以通过记录的方式对时间进行统计。\u003c/p>\u003cp>2、\u003cstrong>要事第一：\u003c/strong>减少非必要花费时间的事务，让自己的时间能够用在重要的事情上。\u003c/p>\u003cp>3、\u003cstrong>化整为零：\u003c/strong>将零散的时间集中成连续性的时间，用来处理一些重要不紧急的事务。 \u003c/p>\u003cp>【WHERE】\u003c/p>\u003cp> 本书中一直提到的管理者，并非通常意义的“有下属的人”才是管理者，管理者泛指知识工作者、职业经理人和专业人员。由于其职位和知识，他们必须在工作中做影响整体绩效和成果的决策。综上，以上介绍的掌握时间的三步骤主要适用于知识工作者、职业经理人和专业人员。\u003c/p>\u003cp> 不适用于偏体力工作的人员，例如工厂中操作机器的工人，他们的工作性质是流水线的工作，工作内容固定单一，每天的时间花费都固定在单一的事务上，不适用于以上的步骤。\u003c/p>\u003cp>【EXAMPLE】\u003c/p>\u003cp> 举个我自己的小例子，我之前参加AACTP讲师大赛，其中有一道笔试题是有关于我业余时间如何分配。我记得我当时回复的是60%的时间用于陪伴孩子、30%用于个人学习提升、10%用于运动追剧等个人娱乐。这是我的主观感受，更多的可能是我的理想中的计划。当我真正记录时间时会发现，我其实有80%以上的时间都在陪孩子，留给自己的学习提升、休闲娱乐的时间少之又少。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp> 请每个人想一个你过往经历过的时间管理的实例，可以是成功的或失败的都可以，并在小组内分享。分享环节4分钟。\u003c/p>\u003cp>具体要求：\u003c/p>\u003cp>1、故事：时间、地点、人物、事件起因、经过、结果（饱含情感/情绪、关键细节/行为）\u003c/p>\u003cp> 2、反思：哪些地方做得不好/不够好，哪些地方可以如何做得更好。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp> 今天我们学习了掌握时间的三步骤，请每个人写一下接下来的应用计划。\u003c/p>\u003cp> 那么，我要温馨提示下大家，做计划≠表决心，需要符合SMART原则呦，稍后我会将SMART原则发给大家，如果有不清楚这个原则的小伙伴们可以做参考。\u003c/p>\u003cp> 这个环节的时间我们计划用3分钟。\u003c/p>\u003cp> 我们请1位同学做分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1646209833000,"updated_at":1646706894000,"ria":true},{"id":13097,"topic":"卓有成效的管理者","learn_goal":"","remark":"卓有成效的管理者","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"任静","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp> 大家好，我是任静。接下来我将通过三个标签来请大家进一步认识我，分别是爱学习、企业培训老人、拆书帮新人。\u003c/p>\u003cp>首先是爱学习，工作之余我做的最多的事情就是看书、学习，学习使我获得的最大收获是：遇到过很多厉害的前辈，帮我开拓视野，指点迷津；通过学习使我在很多领域有了更系统的知识储备，在需要的时候可以随时取用。\u003c/p>\u003cp>其次是企业培训老人，我从2013年毕业至今9年时间一直从事企业内人才赋能及人才发展工作。目前在阿里本地生活做培训经理。\u003c/p>\u003cp> 最后，作为一名拆书帮新人，希望能有更多学习机会，向各位前辈们交流学习。虽然今天是我第一次参加拆书帮认证，但我有信心也有决心自己一定可以坚持到三级拆书家认证，谢谢大家。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>刚刚我有提到过，今天是我第一次参加拆书帮晋级的日子，首先给小伙伴们介绍一下什么是【拆书】，拆书的拆并不是拆散的意思，而是强调把书本里的知识转化为学习者的能力。\u003c/p>\u003cp>“拆书”是一种学习方法论，适用于以能力提升、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，更不是以引导者讲授者为中心，要把知识关联学习者的经验、规划具体的应用。\u003c/p>\u003cp>拆书法分为个人学习的拆书法和组织学习的拆书法；个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果；组织学习的应用是一位拆书家将一本书加工出一场现场学习，引导和促进一群人把知识拆为已用。\u003c/p>\u003cp>所以，从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp> 接下来，我再给大家介绍一下拆书帮，【拆书帮】是拆书法学习爱好者的社群，表现为各地的拆书帮分舵也叫拆书帮俱乐部。拆书帮分舵是公益性青年自组织，它的使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":17076,"quote":"\u003cp>关于拆书帮就介绍到这里，现在步入主题，请大家花2分钟时间看下我发给大家的拆页，拆页片段来自《卓有成效的管理者》，主题是卓有成效的管理者的5个习惯。请大家主要阅读有背景颜色的部分，完成阅读的小伙伴请在聊天框中发送数字“1”\u003c/p>\u003cp> 拆页原文：\u003c/p>\u003cp> 片段来自《卓有成效的管理者》\u003c/p>\u003cp> 记得小时候我的钢琴老师告诉我：“你弹莫扎特的曲子时，也许不可能像钢琴家施纳贝尔演奏得那样好，但是并没有理由说，你不必像施纳贝尔那样地练习音阶。”回想起来，我的钢琴老师显然少说了一句：最伟大的钢琴家，如果不肯辛勤演练，也一定无法演奏莫扎特的曲子。\u003c/p>\u003cp> 也就是说，没有任何理由不让普通人通过练习来获得胜任某项工作的能力。当然，若要把什么东西演练到炉火纯青的地步是很不容易的，那也许需要有特殊的天赋。但卓有成效所要求的只是能够胜任，只是能演奏出音阶来。\u003c/p>\u003cp> 下列五项是要成为一个卓有成效的管理者，必须在思想上养成的习惯：\u003c/p>\u003cp> 1.有效的管理者知道他们的时间用在什么地方。他们所能控制的时间非常有限，他们会有系统地工作，来善用这有限的时间。\u003c/p>\u003cp> 2.有效的管理者重视对外界的贡献。他们并非为工作而工作，而是为成果而工作。他们不会一接到工作就一头钻进去，更不会一开头就探究工作的技术和手段，他们会首先自问：“别人期望我做出什么成果？”\u003c/p>\u003cp> 3.有效的管理者善于利用长处，包括自己的长处、上司的长处、同事的长处和下属的长处。他们还善于抓住有利形势，做他们想做的事。他们不会把工作建立在自己的短处上，也绝不会去做自己做不了的事。\u003c/p>\u003cp> 4.有效的管理者集中精力于少数重要的领域，在这少数重要的领域中，如果能有优秀的绩效就可以产生卓越的成果。他们会按照工作的轻重缓急设定优先次序，而且坚守优先次序。他们知道：要事第一。重要的事先做，不重要的事放一放，除此之外也没有其他办法，否则反倒会一事无成。\u003c/p>\u003cp> 5.最后，有效的管理者必须善于做有效的决策。他们知道有效的决策事关处事的条理和秩序问题，也就是如何按正确的次序采取正确的步骤。他们知道一项有效的决策，总是在“不同意见讨论”的基础上做出的判断，它绝不会是“一致意见”的产物。他们知道快速的决策多为错误的决策，真正不可或缺的决策数量并不多，但一定是根本性的决策。他们需要的是正确的战略，而不是令人眼花缭乱的战术。\u003c/p>\u003cp> 以上这些就是管理者卓有成效的要素，也是本书的主题。\u003c/p>","explains":"\u003cp> 好的，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>【WHAT】：\u003c/p>\u003cp>这个片段给我们介绍了：一个管理者如果要做到卓有成效，必须要在思想上养成的5个习惯。\u003c/p>\u003cp>【WHY】: \u003c/p>\u003cp>卓有成效的要求并不高，主要是能够胜任。养成这5个习惯可以帮助管理者更好的胜任工作。\u003c/p>\u003cp>【HOW】：\u003c/p>\u003cp>1、管理时间：管理者的时间经常会被各种会议、临时事务所占用。有效的管理者要善于利用自己有限的时间，清楚知道自己的时间都用在了什么地方。\u003c/p>\u003cp>2、重视成果：有效的管理者在接到工作任务时，要清楚任务的最终成果和要求是什么，再以终为始进行工作的计划和落地推动。\u003c/p>\u003cp>3、善用长处：善用自己和身边同事的长处，在有利的形势下，做自己想做并且能做成的事。\u003c/p>\u003cp>4、要事第一：将有限的精力聚焦在少数重要的领域，力求产生卓越的成果。将工作进行重要性的排序，先做重要的事情，谨记要事第一。\u003c/p>\u003cp>5、有效决策：有效的决策会关系到接下来要做的事情的正确步骤，所以决策的确定非常重要。有效的决策需要建立在充分讨论的基础上，绝不是一拍脑门就出来的，需要一定的时间来判断，最终产出的决策数量不宜多，而在于是否是根本性的决策。 \u003c/p>\u003cp>【WHERE】：\u003c/p>\u003cp>首先需要跟大家澄清一个定义，这里指的管理者，并非通常意义的“有下属的人”才是管理者，管理者泛指知识工作者、职业经理人和专业人员。由于其职位和知识，他们必须在工作中做影响整体绩效和成果的决策。\u003c/p>\u003cp>举个例子：以我做培训工作为例，培训运营同学基本是在以培训项目的方式向下落地工作，可能没有下属，但由于工作中会做影响整体绩效和成果的决策。所以，他们也属于管理者。综上，以上介绍的卓有成效的管理者主要适用于知识工作者、职业经理人和专业人员。\u003c/p>\u003cp> 不适用于偏体力工作的人员，例如工厂中操作机器的工人，他们的工作性质是流水线的工作，工作流程固定单一，不适用于以上的5个习惯。\u003c/p>","interaction":"\u003cp>看完拆页的内容，我立即联想到发生在我身上的一个经历，从影响整体绩效和成果来说算是一次卓有成效的经历。\u003c/p>\u003cp>【经历】\u003c/p>\u003cp>在去年的10月份，我所在的业务面临组织升级，为了应对组织升级带来的挑战，培训部需要帮助基层管理人员尽快提升管理意识和能力，我们参考了集团的三板斧内容内化出一版适用于我们这块业务的提升项目。\u003c/p>\u003cp>在整个项目过程中，我作为培训团队leader，主要负责内容的输出和方向的把控，团队内一位小伙伴作为项目负责人主要进行项目的落地和执行。通过我们两人的通力合作，项目最终的学员满意度评分为满分，在项目结束后的几个月里还经常能够听到学员正面反馈。\u003c/p>\u003cp>同时，我们有合作的外包职场，外包业务的leader看到了本次培训的效果，还申请希望我们将课程能够复制给外包职场的管理者。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>接下来我将以卓有成效的5个习惯来对案例进行复盘反思：\u003c/p>\u003cp>1、管理时间：准备课程内容的过程中，正值上半年绩效考核期，对我个人而言，因为涉及到培训团队同学的考核评定等工作，事情会比较多。我会利用上午10-12点及下午3-5点，这两个头脑相对清醒的时间段来进行课程的开发，效率及时间利用率更高。\u003c/p>\u003cp>2、重视成果：这块做的稍显不足，这次项目更多的成果衡量是从课程评估满意度的维度，如果重新来做，那么我会去访谈下业务一号位对于项目的期待，增加一些从业务数据角度的衡量指标。\u003c/p>\u003cp>3、善用长处：项目一共有4门课程，我分别邀请到我这块业务的几位高级别的leader过来担任讲师。一方面因为学员基本都是他们的直接下属，所以借助他们的职级为项目站台；另一方面根据他们所擅长的内容来做对应课程内容的邀约和匹配。充分运用了他们的长处来为项目助力。\u003c/p>\u003cp>4、要事第一：这块我和项目负责人做的都比较好，同时段的其他事情，会排列优先紧急，协调其他同学来做或延后做。\u003c/p>\u003cp> 5、有效决策：这块业务前期有针对管理层培养的课程内容，但内容偏HR体系的招聘、绩效、晋升等，当时我做了一个很重要的决策，就是放弃既有的一套内容，我们要基于更成熟的管理三板斧的课程内化和开发我们业务自己版本的课程。虽然过程中意味着我们要付出更多的时间来从0到1准备，但从成果来说是值得的。\u003c/p>\u003cp>【目标】\u003c/p>\u003cp>近期正在规划培训部的2023财年目标。我的行动目标是：在3月25日前输出一份包含所有业务关键leader及部分员工主管的培训需求访谈报告，这份报告将为新财年制定出“能产生更多业务成果”的培训目标做有力参考。\u003c/p>\u003cp>【行动】\u003c/p>\u003cp>1、管理时间\u003c/p>\u003cp> 3月15日前，主要完成需求访谈工作；3月25日前，基于访谈记录进行最终的访谈报告梳理。\u003c/p>\u003cp> 2、重视成果\u003c/p>\u003cp> 在访谈过程中，我会更关注被访人对培训的期待，以及希望在新财年能够输出什么样的成果。\u003c/p>\u003cp> 3、善用长处 \u003c/p>\u003cp>由于访谈对象包括业务关键leader及部分员工主管，涉及人数较多，我会协调组内沟通能力较好的同学一同参与访谈，运用同学们的长处协助我完成此项工作。\u003c/p>\u003cp>4、要事第一\u003c/p>\u003cp>由于需求访谈工作的重要性，我会将日常业务授课的部分工作交接给其他讲师，为此项工作预留更多的时间精力，做到要事第一。\u003c/p>\u003cp>5、有效决策\u003c/p>\u003cp> 访谈记录会由很多内容堆砌，在最终做报告整理时，需要做取舍，保留关键及共性的需求，最终形成有价值的参考报告。\u003c/p>\u003cp> 以上就是我给大家分享的来自经典书籍《卓有成效的管理者》中的一个片段，希望通过这个片段，大家可以对卓有成效管理者的5个习惯有进一步的理解和应用。那我们再次回顾一下5个习惯的内容：管理时间、重视成果、善用长处、要事第一、有效决策。\u003c/p>\u003cp> 好的，我今天的讲解就到这里。最后，感谢大家的参与聆听，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1646209404000,"updated_at":1646706413000,"ria":true},{"id":12909,"topic":"集中精力只做好一件事","learn_goal":"","remark":"当你在处理纷杂整务时，你将如何管理自己的时间，让自己变得更加卓有成效？请学习集整块连续时间集中精力一次只做好一件要事。\n通过学习你能够在整块时间内集中精力，攻坚克难，提高时间的利用效率和产出。","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"国子监","city":"廊坊市"},"club":{"name":"廊坊风陵分舵","city":"廊坊"},"prologue":"\u003cp>为了便于接下来的学习讨论，我们以办公桌中间为界分成两个学习小组。\u003c/p>\u003cp>大家好，我是热爱运动健身和读书分享，以及追求卓有成效的晋级拆书家郭建，今天和大家一起拆解《卓有成效的管理者》。\u003c/p>\u003cp>首先我们了解所谓管理者：就是一个人能够凭借知识和技能，肩负公司责任，对公司产生实际影响，那么他就是一位管理者。请大家也思考一下，自己算不算是管理者。\u003c/p>\u003cp>有效—就是我们要按时做完该做的事情。如果要做到“卓有成效”那就要求必须自觉地管理好自己，自觉地完成任务，自觉地追求工作效益。而管理我们自己首先要管理的就应该是我们的时间。\u003c/p>\u003cp>\u003cstrong>【总学习目标】\u003c/strong>跟随我完成今天的片断学习后，学习者能够依照（行为）“时间安排四步骤”（澄清），把自己的时间集成整块时间统一安排（界定）。而后学习者在处理多项事务时，运用（行为）“集中精力工作法”（澄清），在一整块时间内只安排做好一件要事。（界定）\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003cstrong>话说\u003c/strong>春节期间同学小聚，我和老班长挨着坐，所以聊的比较多。他去年到一家私企任高管，据说混的还不错。\u003c/p>\u003cp>我问：“老班长，祝贺高升啊，工作还顺利吧，听说待遇不错啊。”\u003c/p>\u003cp>班长回答：“怎么说呢，钱儿是多挣了点儿，可是工作也不轻松啊！就说去年吧，要做好防疫工作，还要实现全年增长15%，然后就是加大客户拜访力度，这还不算各种的应酬、会议、培训等等。”\u003c/p>\u003cp>我说：“你这也不容易啊。”\u003c/p>\u003cp>班长说：“可不是嘛，每天都是焦头烂额的，到公司就一个事接着一个事儿啊。有时候还要双管齐下，两三件事一块干，就这还得经常加班呢，老婆都有意见了。哎！不说这个了，干一杯吧。”\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>各位的小伙伴，你们是不是也经常遇到这样的事呢？天天加班加点，时间总是不够用，事儿也总是安排不开？有时候忙起来一眨眼的功夫时间就没了。等哪天忽然闲下来对自个儿来个灵魂拷问：时间都去哪儿了？你会不会大脑短路，一脸茫然呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>试想长期这样下去，我们一定会感到焦虑紧张，身心疲惫。对时间失去了感觉，事儿也做不到合理分配。甚至对自己的能力产生怀疑，生活目标渐渐模糊，工作热情消耗殆尽。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>那么，我们怎么做才能摆脱这种不利局面呢？好，今天我专门为大家带来了这本《卓有成效的管理者》。本书作者彼得·德鲁克，被尊为“现代管理学之父”是“大师中的大师”。这是他最著名的管理学著作之一，对各企事业、各培训机构乃至对中国的改革开放事业等都产生了极深远的影响。\u003c/p>\u003cp>当然在指导个人如何做好自我管理，任务管理，提高工作效益等方面也非常实用。今天我只选了其中两个片断，就可以有效解决你所遇到的时间和事务等方面的困扰。教你如何诊断时间，把时间管理起来，最终收集成由自己支配的连续的整块时间，把我们首要事务安排进去，并集中精力干好它，从此让我们变得更加的卓有成效。\u003c/p>\u003cp>\u003cstrong>【R1学习目标】\u003c/strong>跟随我完成今天的片断1学习后，学习者能够依照（行为）“时间安排四步骤”（澄清），把自己的时间集成整块时间统一安排（界定）。\u003c/p>","ratings_count":4,"texts":[{"id":16880,"quote":"\u003cp>请大家用1-2分钟来阅读手中的原文片断，读完请举手示意。\u003c/p>\u003cp>片段1：《卓有成效的管理者》P28 \u003c/p>\u003cp>第2章 掌握自己时间\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时间。\u003c/p>","explains":"\u003cp>好，大家都已经读完了，我来为大家讲解。\u003c/p>\u003cp>\u003cstrong>【互动】\u003c/strong>\u003c/p>\u003cp>拆书家：我们一起来回顾一下，大家说片断中所讲的有效的管理者并不是一开始就着手工作，而是往往从哪里着手呢？\u003c/p>\u003cp>学习者：时间安排；\u003c/p>\u003cp>拆书家：他们并不以计划为起点，而是以什么为起点呢？\u003c/p>\u003cp>学习者：认识清楚自己的时间用在什么地方为起点；\u003c/p>\u003cp>拆书家：好，不错。有效的管理者，最后，就是将自己“可自由运用的时间”，由零星的时间怎么样呢？\u003c/p>\u003cp>学习者：集中成大块连续性的时间。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>这个片断讲述的是有效的管理者一开始都是从时间安排上着手，如此看来这个问题是非常重要，也是值得我们探讨的。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>大家可以想一想，其实我们每个人都是时间的消费者，而时间的供给，没有丝毫的弹性，又稍纵即逝，根本无法贮存。时间管理大师们往往都是能掌握自己时间的高手，他们总是清楚知道自己的时间去向，并能合理收集与分配时间。\u003c/p>\u003cp>而大多数普通工作者对自己的时间概念比较模糊，对时间的认识和分配上没有轻重缓急，觉着自己反正天天都在忙着，日复一日，年复一年……\u003c/p>\u003cp>\u003cstrong>【举个反例】\u003c/strong>\u003c/p>\u003cp>说到这儿，我们回过头来想一想，我开头举的老班长的例子，他的工作状态说明了什么？是不是他对自己时间的掌握存在不足之处呢？\u003c/p>\u003cp>\u003cstrong>【概念讲解】\u003c/strong>\u003c/p>\u003cp>我们一起读完片段，大家有没有发现，真正有效的管理者在工作的着手点上，是出乎我们意料的。工作伊始他们并不是从惯常的工作计划开始，而是“从时间安排上着手”。\u003c/p>\u003cp>这个“从……上着手”好理解，就是“从……开始”。\u003c/p>\u003cp>而“时间安排”这一概念，我们还真不一定明白，当然要求我们做到就更难了。那么，接下来我们就用几个案例把“时间安排”这个概念辨别清楚。\u003c/p>\u003cp>\u003cstrong>\u003cem>[概念折返1]:\u003c/em>\u003c/strong> 王队一上任就定目标、列计划，投入紧张工作。每天都是深陷一连串的工作之中，事无巨细总也干不完。可是过段时间再看，办公桌上被搁置的计划越积越多，急得他总是抱怨：这事怎么越干越多啊，时间都上哪儿呢？\u003c/p>\u003cp>请问这是“时间安排”么？\u003c/p>\u003cp>学习者：不是。\u003c/p>\u003cp>拆书家：大家回答的很好，不是的。“时间安排”不是茫然不知地投入工作，而是清楚地知道时间的用处。比如，王队可以先做好时间的跟踪记录，弄清楚自己的时间都被什么事情占用了，然后再做下一步的统一安排。\u003c/p>\u003cp>\u003cstrong>\u003cem>[概念折返2]:\u003c/em>\u003c/strong>再看个例子 ，李总在担任公司总经理的两年中，除了元旦和春节两天，每天晚上都有应酬。凡是宴会必须作陪，每次都得花几个小时。不管是欢送老同事退休，还是宴请政府官员，他都要出席。其实这种饭局无助于公司和自我发展，主办方也只是例行公事而已。而有关公司发展的大事他却没有时间处理。请问这是做到“时间安排”么？\u003c/p>\u003cp>学习者：不一定。\u003c/p>\u003cp>拆书家：对啊，真的不一定。“时间安排”不是对时间和精力的浪费，而是要专注有成果的生产性事务。比如，李总通过分析，可将不必做的事取消，将不必亲自处理的事交给别人，以此削减大量无谓工作，用整块时间处理要事。\u003c/p>\u003cp>\u003cstrong>\u003cem>[概念折返3]:\u003c/em>\u003c/strong>再看一个例子：王秘书负责为领导写报告材料，写作期间经常被中断或打扰，时间变得零零散散难以集中精力，虽然加在一起总用时也不算少，但交不出能让领导满意的稿子。请问这是做到“时间安排”么？\u003c/p>\u003cp>学习者：不是。\u003c/p>\u003cp>拆书家：对啊，因为“时间安排”不是被打成碎片，这样其实就等于没有时间；而应该集中起整块时间来自由支配。比如，王秘书应分析并找出原因，向领导说明情况，合理安排后，用足够的大块时间来写重要材料。\u003c/p>\u003cp>\u003cstrong>\u003cem>[强化讲解概念的I]:\u003c/em>\u003c/strong>通过以上案例，我们可以看出，“时间安排”不是每天焦头烂额的忙忙碌碌，一头陷进流水账般的工作里；而是，分清时间都去哪儿了，然后再收集成连续整块时间干重要的事。所以有效的管理者做事都是先从“时间安排”上着手，他们深知只有掌握了时间才能做好工作，高效完成任务，取得成果。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>我们清楚了什么是“时间安排”以及“从时间安排上着手”的重要性，那如何做到呢，通过以上，我们可以提炼出“时间安排四步骤”：\u003c/p>\u003cp>为了方便大家学习，你可以对照手中\u003cstrong>\u003cu>我的实际案例（第2页）\u003c/u>\u003c/strong>边看边听。\u003c/p>\u003cp>\u003cstrong>步骤一：记录时间\u003c/strong>\u003c/p>\u003cp>连续记录1周时间的实际耗用情况，注意事做完了“当时”就记，别等一天忙完了再记，那样你脑子记不详细。我们根据自己的实际工作情况，可半年进行一次。\u003c/p>\u003cp>例如：我记录了某一天和一个周末的时间使用情况。\u003c/p>\u003cp>\u003cstrong>步骤二：去除不必做的事，节省时间\u003c/strong>\u003c/p>\u003cp>找出不必做的事，对着时间记录逐项问：不做也没有任何影响的事，便立刻取消，节省下来时间，归入整块时间。\u003c/p>\u003cp>\u003cstrong>步骤三：找出别人可替做的事，分派出去\u003c/strong>\u003c/p>\u003cp>在时间记录中找出可由别人替做的事，由别人代为参加或处理，也不影响效果的事，便分派给他人，调整出来的时间，归入整块时间。\u003c/p>\u003cp>例如：表格右边第2列，就是我的诊断情况。\u003c/p>\u003cp>\u003cstrong>步骤四：集中时间\u003c/strong>\u003c/p>\u003cp>最后将可自行支配的零碎时间，集中成连续的整块时间，统一安排。\u003c/p>\u003cp>例如我一天中收集成约三块可自己支配的时间，共约400多分钟，周末每天收集成约两块可自己支配的时间，每天共约240分钟，这组数字真的让人大吃一惊。\u003c/p>\u003cp>｛举例验证：放在How中讲｝\u003c/p>\u003cp>\u003cstrong>【预防性异议】\u003c/strong>有的小伙伴会说，我知道“时间安排”很重要，可按你的方法，要记录、分析、归纳，这也太麻烦了。常言道磨刀不误砍柴工，有了详细的时间记录，通过简单的分析，就能得出时间究竟应该怎样合理安排，所以，请相信当你做完以后肯定会大有收获。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>这个方法适合新上岗或想改变工作状态的朋友，因为他们想按时做好该做的事情，想使自己变得更高效，更有成果。比如从事管理、专业人员、知识工作者等。而工作单一、生活简单又觉得时间充裕的伙伴就不太合适了。当然，你还可以学会这个方法后去输出，帮助孩子、爱人、朋友和同事等。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2 】催化应用\u003c/strong> \u003c/p>\u003cp>\u003cstrong>【显像提问】（编写剧本）\u003c/strong>\u003c/p>\u003cp>接下来就请大家以小组为单位编一个小剧本（也就是小故事）。假如下周的某一天，在某地和朋友聊天，他遇到时间管理方面的问题，比如：工作压力大，每天总是忙忙碌碌，忙的连时间都不知道去哪了，休息也受影响，但效率并不高……\u003c/p>\u003cp>正好你今天学到的这个“时间安排四步骤”正好能帮到他。于是，你耐心地为他一一指点……\u003c/p>\u003cp>好，请大家写清楚具体的时间、地点、人物、和情景对话，内容中要有“四步骤”：记录时间、去除不必做事、别人可替做的事、集中时间。大家可以参考手中第2页模板，把小剧本情节要点写下来。时间5分钟，然后邀请小组代表来做分享。现在开始……\u003c/p>\u003cp>好，接下来我们邀请哪一组的代表来分享你们的小剧本，时间2分钟。\u003c/p>\u003cp>\u003cstrong>【点评】反馈\u003c/strong>\u003c/p>\u003cp>好，感谢小刘的小剧本，大家掌声送给他。剧本中有时间、地点、人物、场景、对话等，非常生动，还用到了“时间安排四步骤”，很棒。\u003c/p>\u003cp>请问大家对时间四步骤还有不清楚的吗？刚才有没有哪一步介绍的不够精确呢？\u003c/p>\u003cp>希望大家将来工作生活中常运用这个方法，做好个人的时间安排，那么自己的时间掌握在自己手里。\u003c/p>\u003cp>好，我们通过第一个片断的学习，大家学会了从时间安排着手的方法，“方法”固然很重要，那大家说更重要的是什么呢？学到了，就要把它怎么样……\u003c/p>\u003cp>学习者：用起来。\u003c/p>\u003cp>接下来，集中出来的这些时间如何使用，有些人是做着一件事还放不下另外一件事，结果一定会产生新问题。好，接下来我们进入第二片断的学习：如何集中精力干好一件事。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":16881,"quote":"\u003cp>\u003cstrong>【学习目标R2】\u003c/strong>跟随我完成今天拆页2的学习，学习者在处理多项事务时，运用（行为）“集中精力做事的方法”（澄清），在一整块时间内只安排做好一件要事。（界定）\u003c/p>\u003cp>请大家先完成一个集中精力干事情的自测题，请仔细阅读以下5个题目，根据自己的实际情况为自己打分， 1代表完全不符合，6代表非常符合。大家最后加出总分。\u003c/p>\u003cp>\u003cstrong>【I】解释自测题\u003c/strong>\u003c/p>\u003cp>通过这个量表自测，我们来了解集中精力干好一件事情的现状。测评结果不是唯一的标准和一成不变的，只是当下的一种反映。\u003c/p>\u003cp>有没有总分在25分以上的小伙伴？那说明在集中精力做事情方面做的还是比较好的，在接下来的互动环节，你要多多介绍你的宝贵经验。\u003c/p>\u003cp>有没有15-25分的伙伴？说明你具有一定的集中精力做事情的能力，如果好上加好，还会有提升的空间；\u003c/p>\u003cp>15分以下的伙伴呢？今天你来对了，马上就可以收获集中精力做事情这项技能，让自己的思路越来越清晰。\u003c/p>\u003cp>接下来先用2分钟阅读片段2，请完成的伙伴举手向我示意。现在开始！\u003c/p>\u003cp>\u003cstrong>片段2：《卓有成效的管理者》P122-123\u003c/strong>\u003c/p>\u003cp>一个人如何能够完成这么多的大事，而且是这样艰巨的大事，“秘诀”尽在其中：每次只集中精力干好一件事。而结果是，他们所用的时间总比别人少的多。\u003c/p>\u003cp>有些人一事无成，而实际上他们却做得很吃力。第一，他们低估了完成一件任务所需的时间。他们总以为万事顺利，却总不免有出乎意料的情况发生。然而每个管理者都知道，没有任何事情会是一帆风顺。其实，所谓意料之外者，正应该在我们意料之中。而所谓意料之中，往往从来没有令人愉快的意外。所以，有效的管理者对时间需求的估计宁可有余，而不可不足。第二，一般的管理者（往往也是不大有效的管理者）总喜欢赶工--而赶工的结果，总不免使进度更加落后。有效的管理者不愿赛跑，他们按部就班，稳定前进。第三，一般的管理者喜欢同时着手几件要事，结果对每一件事，他们都无法获得足够的最少整块时间。只要任何一件事情受阻，全部事情也都会跟着受阻了。\u003c/p>\u003cp>有效的管理者知道他们必须要完成许多工作，并且要有效地完成。因此，他们在一段时间内只集中努力做好一件事--集中他们本人的时间和精力，以及整个组织的时间和精力。他们坚持把重要的事情放在前面先做，而每次只做好一件事。\u003c/p>","explains":"\u003cp>有小伙伴已经读完了，注意力回到我这里，继续讲解。\u003c/p>\u003cp>\u003cstrong>【互动】\u003c/strong>\u003c/p>\u003cp>1.拆书家：大家跟随我一起来回顾一下片断内容\u003c/p>\u003cp>一个人如何能够干成一件件大事，有一个“秘诀”是什么呢？\u003c/p>\u003cp>学习者：集中精力做好一件事。\u003c/p>\u003cp>2.拆书家：有些人一事无成，第一个原因是对完成一件任务所需的时间，高估还是低估呢？\u003c/p>\u003cp>学习者：他们低估了。\u003c/p>\u003cp>3.拆书家：好，我们继续看。第二个原因，一般的管理者总喜欢赶工，那赶工是让进度提前了还是更加落后呢？\u003c/p>\u003cp>学习者：落后了。\u003c/p>\u003cp>拆书家：“好，大家回答的非常好”。 \u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>我们多数人即使在同一时间内专心致志只做一件事，也不见得真能做好；如果想在同一时间内做两件事，那就更不必谈了。所以要有效地利用我们的才能，最好的办法，莫过于集中个人所有的才能于一件要务上。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>我们明白了把一件事做的又快又好，那你必须每次只集中精力干好一件事，那具体怎么去做呢，我们来看“集中精力工作法”：\u003c/p>\u003cp>\u003cstrong>第1步\u003c/strong> \u003cstrong>专注于一：\u003c/strong>一次只给自己安排一件重要的事情，并且将连续整块的时间安排给这件事。集中精力做好一件，再去做下一件。俗话说：一心不能二用，就是这个道理。\u003c/p>\u003cp>\u003cstrong>第2步\u003c/strong> \u003cstrong>留足时间：\u003c/strong>集中精力做一件要事之前，一定要充分考虑到事情进程中，难免会有意想不到的情况发生，提前预留好充足的时间，以免让你措手不及，打乱你的节奏。毛主席教导我们说：不打无准备之仗。\u003c/p>\u003cp>\u003cstrong>第3步\u003c/strong> \u003cstrong>按计划行：\u003c/strong>准备就绪，开始集中精力做事，就是要踏踏实实按照事先做好的计划，按部就班、循序渐进，逐步进行。不要盲目的赶工、抢先，跟别人打比赛。常言道：慢就是快。\u003c/p>\u003cp>\u003cstrong>【举个反例】\u003c/strong>\u003c/p>\u003cp>我一直向往着能过上衣食无忧，每天读书的生活。我想干脆把未来十年的梦想，集中在一两年内，一下子把衣食无忧的问题解决了不就行了嘛。当时就在工作繁忙的情况下，同时又加盟了一家火锅连锁，两件大事同时进行。可哪儿成想，招工难、内部矛盾、不懂经营等等一系列意想不到的问题频频出现，最终创业失败，让我负债累累，几乎是一蹶不振。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>“集中精力工作法”可以用于组织、家庭或个人的工作、学习等重要事务安排。如果只是鸡毛蒜皮的小事，就不用这样去做了。\u003c/p>\u003cp>\u003cstrong>【预防性异议】\u003c/strong>有的小伙伴会说，这个道理听起来没有多难啊，就是一次只做一件事、事前要做好充分的准备、事中要按部就班。但仔细想，既然彼得·德鲁克先生用这么长的篇幅来讲这个道理。同时我们从古至今又有很多古圣先贤不断地告诫我们这个道理，证明它虽然简单但并不容易做到啊。\u003c/p>","interaction":"\u003cp>\u003cstrong>【微行动学习】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一、【引导讨论问题】｛发散｝\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接下来我们开始进入微行动学习的环节：\u003c/strong> \u003c/p>\u003cp>拆书家：讲到这里，我大脑里想起自己在以前的工作、学习和生活上确实犯过很多类似错误。那接下来，请大家回想在你以往的实际工作、学习或生活中，关于“集中精力做好一件事”的问题，是否也掉过坑呢？你觉得平时哪些做事习惯与之最不相符呢？把它写在纸上。或者在将来运用的时候，你觉得哪一步最难呢？都可以写下来。\u003cstrong>｛请大家按开始的分组进行讨论，时间5分钟｝\u003c/strong>\u003c/p>\u003cp>（……小组讨论……）\u003c/p>\u003cp>第1组：小伙伴认为第1步最难，无法专注于一件事。\u003c/p>\u003cp>第2组：小伙伴也认为第1步最难，无法专注于一件事。\u003c/p>\u003cp>两个小组的小伙伴都认为第1步最难，那我们请出哪位小伙伴说一说你亲身经历的故事，来描述一下，你遇到了什么事件，而觉着这个问题最难呢？\u003c/p>\u003cp>\u003cstrong>方向讲了他的案例：\u003c/strong>\u003c/p>\u003cp>在3月21日的时候，安徽客户现场有一件重要的事儿。公司孙总直接给我打电话，说设备出现故障，影响较大，所以直接派我去现场处理问题。我到达现场处理一半的时候，又来了一个集团客户的电话。我手里干着现场的活儿，又解答着客户电话。两边都不舍得放下，结果不但手上的工作出现差错，电话里的客户领导见我回答的不认真，也开始责备。\u003c/p>\u003cp>拆书家回应：通过方向的分享，他阐述了自己无法专注做一件事，所以大家往往都是因为着急而同时做两件事，而两件事都做不好。\u003c/p>\u003cp>拆书家回应：那好，我问一下1组的小伙伴，你们还有什么案例要分享吗？是否有补充的呢？\u003c/p>\u003cp>第1组小伙伴：方向的案例很好，能代表他们的意见。\u003c/p>\u003cp>\u003cstrong>【明确问题】｛收敛｝\u003c/strong>\u003c/p>\u003cp>拆书家：好，通过大家的理解，最终我们明确为讨论一个问题：无法专注于一件事。\u003c/p>\u003cp>\u003cstrong>二、【讨论本质】｛发散｝\u003c/strong>\u003c/p>\u003cp>拆书家：大家小组讨论，是什么引发出这样一个问题呢？这个问题是由什么原因造成的？根源是什么？这个问题的本质是什么？\u003c/p>\u003cp>\u003cstrong>｛现在开始小组讨论，时间5分钟｝\u003c/strong>\u003c/p>\u003cp> （……小组讨论……）\u003c/p>\u003cp>经两个小组不断追问，共讨论出四个本质原因，列出来：\u003c/p>\u003cp>辉辉：你为什么要选择同时做两件事呢？为什么不一件一件干呢？\u003c/p>\u003cp>方向：我觉得是我低估了现场事件的难度；\u003c/p>\u003cp>辉辉：你是不是感觉自己能力特别强，能同时把两件事都干好呢？\u003c/p>\u003cp>方向：当时接到客户电话，我觉得能同时干好这件事。还是对自己的能力有高估。\u003c/p>\u003cp>海啸：请问客户现场给的时间与你去之前预计的有没有变化？\u003c/p>\u003cp>方向：确实有变化，我觉得能够完成，赶一下就行了。\u003c/p>\u003cp>拆书家：那等于外界条件给你带来影响。\u003c/p>\u003cp>小刘：我想问，是不是因为是老板派的活儿，遇到什么情况也一定要干好。\u003c/p>\u003cp>方向：我想既然老板亲自安排的活儿，那一定就全力做好。\u003c/p>\u003cp>拆书家：请问大家还有没有提问呢?\u003c/p>\u003cp>学习者：没有了。\u003c/p>\u003cp>拆书家：那我们关于无法专注于一件事这一问题本质的追问，得出四个答案：\u003c/p>\u003cp>1、低估事件的难度；2、高估自己的能力；3、外界的干扰估量不足；4、想好好表现；\u003c/p>\u003cp>\u003cstrong>【明确本质】｛收敛｝\u003c/strong>\u003c/p>\u003cp>拆书家：关于提出的这四个本质都有道理，大家可以结合过往经验，继续追问来深入探讨，如果所有这些问题的本质原因，我们只解决一个，大家说最关键、最根本的是哪个呢？\u003c/p>\u003cp>拆书家：方向小伙伴你觉得是哪个呢？\u003c/p>\u003cp>方向：我觉得是高估自己。\u003c/p>\u003cp>拆书家：辉辉你的意见呢？\u003c/p>\u003cp>辉辉：我还是感觉他低估这个事件的难度。\u003c/p>\u003cp>海啸：我想问下你为什么会高估自己呢？不就是要表现吗？\u003c/p>\u003cp>方向：是啊，有这方面原因，当然我觉得自己也是有一定能力的。\u003c/p>\u003cp>小刘：你就是想表现自己。\u003c/p>\u003cp>拆书家反馈：总起来说我们要找最关键的原因，刚才海啸提的问题非常好，他直接问是内因问题，直达心灵深处，对不对？ \u003c/p>\u003cp>方向：老板亲自派的任务，我要是干好了，可以提高待遇，对我有利。\u003c/p>\u003cp>拆书家反馈：其实我们前面讲高估、低估以及外界干扰，最终，还是回到根本内因。\u003c/p>\u003cp>方向：对，还是想表现自己。\u003c/p>\u003cp>拆书家：好的，我们讨论出“想好好表现”是造成“无法专注于一件事”的问题本质，大家同意吗？\u003c/p>\u003cp>学习者：同意。\u003c/p>\u003cp>\u003cstrong>四、【讨论解决方案】｛发散｝\u003c/strong>\u003c/p>\u003cp>拆书家：那么接下来，我想问下方向（案主），问题的本质是“想好好表现”。那我们继续讨论，这个问题到什么程度，到哪一步，你认为就算解决了呢？就算有答案了呢？\u003c/p>\u003cp>方向（案主）：只要我能分出哪件在前面干，那个在后面干，就可以了。\u003c/p>\u003cp>拆书家反馈：那我理解着是不是，把事情能分出来前后主次，把这个步骤讨论出来，这样是不是就解决了这个问题？ \u003c/p>\u003cp>学习者：大家包括案主表示同意。\u003c/p>\u003cp>拆书家：那我们开始讨论有哪些具体的行动步骤\u003c/p>\u003cp>\u003cstrong>｛现在开始小组讨论，时间5分钟｝\u003c/strong>\u003c/p>\u003cp>第1组：1、做筛选； 2、列任务清单；3、分出紧急重要的事；\u003c/p>\u003cp>第2组：1、任务汇总；2、任务的排序；3、应急预案；4、合并同类；\u003c/p>\u003cp>拆书家：那我们先把这七步相同的步骤进行一下合并吧。\u003c/p>\u003cp>学习者积极配合，经大家一起商量，最终把两组的七个步骤，合并成四个步骤：\u003c/p>\u003cp>1、列任务清单；2、任务的排序；3、应急预案；4、合并同类；\u003c/p>\u003cp>拆书家：接下来我们把这四步按先后次序列出来\u003c/p>\u003cp>学习者：1、列任务清单；2、合并同类；3、任务的排序；4、应急预案；\u003c/p>\u003cp>拆书家：好，那请问方向，咱们通过一路追问，到现在我们把解决问题的步骤列出来四步，那请问能够解决你刚才的疑问吗？那如果还原到当初的现场你将怎么去做呢？\u003c/p>\u003cp>方向（案主）：嗯，可以解决我的问题。还原到现场：先分出主次，干眼前重要的工作，等这个工作干完之后，再静下来给客户回电话。\u003c/p>\u003cp>拆书家反馈：很好，刚才方向给我们做了还原分享。其实我们学习的是一种思维方法，事情出现，只要大脑有这么一个思维，那对我们眼前工作是有很大帮助的。\u003c/p>\u003cp>\u003cstrong>【讲解成果】｛收敛｝\u003c/strong>\u003c/p>\u003cp>拆书家：好，我来公布一下最终的讨论结果：\u003c/p>\u003cp>第1步：列任务清单\u003c/p>\u003cp>第2步：合并同类\u003c/p>\u003cp>第3步：任务的排序\u003c/p>\u003cp>第4步：应急预案\u003c/p>\u003cp>拆书家：感谢各小组的分享，大家表现非常好，充分发挥了我们的集体智慧，都做出了贡献，我们也收获了一个大家共同认可的结果。那给我们自己一个热烈的掌声吧！\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>布置作业\u003c/p>\u003cp>为了能让大家更好地应用这个方法，我给大家留个作业：大家从明天开始的工作中，请运用今天我们集体讨论的集中精力做好一件要事的方法，安排好自己的工作。还有呢，你可以把这个的方法介绍给同事、朋友或家人，让他们也能顺利地工作或学习，收获更多的结果。\u003c/p>\u003cp> (注意哟！时间、地点、你把这个经验介绍给谁了，你们是怎么对话的）。\u003c/p>\u003cp>回去进行实践和复盘，并将复盘内容发到大群里，拆书家可以点评。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>好，今天我们用了70多分钟的时间，学习了如何集整块连续时间集中精力一次只做好一件要事的理念和方法。认识到要想变得更加卓有成效，就需要这样去学习、工作。希望小伙伴们把它变成你的一种思维模式，相信你将会实现质的飞跃。\u003c/p>\u003cp>总之：时间在你手里，要事在你心中，你才是自己的管理者！\u003c/p>\u003cp>今天的学习课程结束。\u003c/p>\u003cp>\u003cstrong>方向的作业反馈:\u003c/strong>\u003c/p>\u003cp>时间：2022年4月24日\u003c/p>\u003cp>地点：家中\u003c/p>\u003cp>人物：我、爱人\u003c/p>\u003cp>背景：和爱人分享本次“专心做好一件事”的解决方案，并按照步骤做出自己一天的事务规划。\u003c/p>\u003cp>事件：\u003c/p>\u003cp>我：老婆，今天我们关于“专心做好一件事”这个问题做了讨论，并讨论出了解决方案，我今天跟你讲一下，咱们做个测试，或许我们需要相互的配合。\u003c/p>\u003cp>老小姐：说说看，有什么成果，怎么做呢\u003c/p>\u003cp>我：你慢慢听啊，我呢，依照讨论出的解决步骤，对我今天一天的事务做了安排：\u003c/p>\u003cp>第1步：列任务清单\u003c/p>\u003cp>先把一天中要做的事情全列出来：\u003c/p>\u003cp>1）计划五一前要办理的事项；\u003c/p>\u003cp>2）公园跑步；\u003c/p>\u003cp>3）送孩子去找同学；\u003c/p>\u003cp>4）收听演讲课程；\u003c/p>\u003cp>5）写字60分钟；\u003c/p>\u003cp>6）整理学习计划；\u003c/p>\u003cp>7）傍晚接孩子回家；\u003c/p>\u003cp>第2步：合并同类项\u003c/p>\u003cp>按照事情的地点和时间进行合并：\u003c/p>\u003cp>1）在家里办公：计划五一前要办理的事项；整理学习计划； \u003c/p>\u003cp>2）去市区：送孩子去找同学；\u003c/p>\u003cp>3）到公园：下午公园跑步；收听演讲课；傍晚接孩子回家；\u003c/p>\u003cp>4）写字60分钟；\u003c/p>\u003cp>第3步：排主次\u003c/p>\u003cp>按照事情重要和紧急程度、以及工作场景排出主次：\u003c/p>\u003cp>1）在家里办公：送孩子去小朋友家；\u003c/p>\u003cp>我：本来假期里孩子就是最重要的事，我想和你商量，你去送女儿，我呢，按照我的计划做事，等傍晚我去接她，你看可以吗？\u003c/p>\u003cp>老婆：当然可以\u003c/p>\u003cp>我：我继续讲啊\u003c/p>\u003cp>2）在家里办公：整理学习计划；计划五一要办理的事项； \u003c/p>\u003cp>3）到公园：公园跑步；收听演讲课；傍晚接孩子回家；\u003c/p>\u003cp>4）写字60分钟；\u003c/p>\u003cp>第4步：做最重要的事\u003c/p>\u003cp>预留上午5个小时的时间，只专心做一件事：整理学习计划；\u003c/p>\u003cp>其它事情再依次向后安排。\u003c/p>\u003cp>我：老婆，以上就是我按照步骤做的全天计划，你看好不好？\u003c/p>\u003cp>老婆：看起来非常不错哦。你先试用，明天我也按这个步骤给设计一下自己的时间和事务。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1641398078000,"updated_at":1651141654000,"ria":true},{"id":11488,"topic":"如何诊断自己的时间","learn_goal":"","remark":"拆书家杨颖春定级","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"杨颖春","city":"厦门"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>我叫杨颖春，我的3个标签是公司职员、生命舞者、一级拆书家，今天定级TF2-1，我们先分下组，左边一组右边一组，希望通过本次学习，学习者能够运用本拆知识诊断自己在某个事件/场景中的时间使用情况，并优化形成新的工作流程。\u003c/p>\u003cp>今天我要给大家分享的内容来自这本书《卓有成效的管理者》。\u003c/p>\u003cp>【F】这本书讲的是学习方法论，这本书《卓有成效的管理者》的作者是彼得.德鲁克，是一位著名的管理学家，书中重点阐述了成为一个卓有成效管理者的五项要素，包括：善用时间、关注结果、善用人才、要事第一、有效决策。\u003c/p>\u003cp>【A】这本书，是管理学类图书中非常畅销及实用的一本，仿如良师益友，虽然面对的是不同的事实，却能从不同的角度说出你不曾想、更不曾想到的理念，常有茅塞顿开之感。\u003c/p>\u003cp>【B】（B1）那么大家是否曾经苦恼过，为什么我的时间不够用，我都这么加班加点了，还是不能如期完成工作，时间都去哪了？还有就是我已经事先安排好做每件事的时间了，为什么到最后我自己的事一件没做，全部做的是别人的事等等这些问题，你都可以从书中找到启发。（B2）而今天我要分享的这个片段，能帮助你记录并分析时间的使用情况。\u003c/p>","ratings_count":2,"texts":[{"id":15407,"quote":"\u003cp>拆页来自彼得.德鲁克《卓有成效的管理》掌握自己的时间之如何诊断自己的时间P34-36节选\u003c/p>\u003cp>要提高管理理的有效性，\u003cstrong>第一步就是记录其时间的实际情形\u003c/strong>。设定时段（如3-4星期），强调记录。“当时”立即加以记录，不能事后凭记忆补记。\u003c/p>\u003cp>许多有效的管理者都经常保持这样一份记录，每月定期拿出来检讨。至少，有效的管理者往往以连续三四个星期为一个时段，每天记录，一年内记录两三个时段。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间使用得很乱，浪费在种种小事上。经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免回到浪费的状态上去。\u003c/p>\u003cp>\u003cstrong>第二步就是要做有系统的时间管理。\u003c/strong>我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。强调发现。形成新的工作流程，并在实践中去验证。要做到这一步，可以问自己下列几个问题：\u003c/p>\u003cp>定义\u003c/p>\u003cp>非生产性的和浪费时间活动\u003c/p>\u003cp>（1）找出哪些事情可以不做。\u003c/p>\u003cp>（2）找出哪些事情可以由别人来做。\u003c/p>\u003cp>（3）浪费别人的时间。 \u003c/p>\u003cp>\u003cstrong>1.首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果?”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/strong>\u003c/p>\u003cp>然而许多大忙人，天天在做一些他们觉得难以割舍的事，比如应邀讲演、参加宴会、担任委员和列席指导之类，不知占去了他们多少时间，而这些工作，他们本身既不一、感兴趣，做得也根本不够精彩。然而他们得承受这些负担，一年又一年，就像从天而降的灾难一样躲也躲不了。其实，对付这类事情，只要审度一下对于组织有无贡献，对于他人有无贡献，或是对于对方的组织有无贡献。如果都没有，只要谢绝就可以了。\u003c/p>\u003cp>\u003cstrong>2.第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果?”\u003c/strong>\u003c/p>\u003cp>多年来在管理方面都在研究授权问题。任何组织，几乎每一位主管人员都接到过上级有关做好授权的指示，而且他们本人也曾屡屡对其下属阐明授权的重要。但是这样的告诫是否产生效果，实在令人怀疑。原因非常简单，只是因为没有完全明了授权的意义。如果认为授权的意思是说：我的工作应由别人来做，那就错了；因为你既然拿了薪水，就该做你自己的工作。又有人认为：充分授权之后，最闲散的经理人便应该是最好的经理人。这样的看法不但荒唐，而且也是不道德的。\u003c/p>\u003cp>\u003cstrong>3.还有一项是时间浪费的因素，是管理者可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/strong>\u003c/p>\u003cp>这种现象并不明显，但有一个简单方法可以诊断出来: 去问问你的下属。即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。\u003c/p>\u003cp>许多管理者都意识到了哪些事情会浪费他们的时间，然而他们却不敢面对这个问题。他们怕因小失大，造成错误。殊不知即使有了错误，也可以很快弥补。能够大量消减不必要的和非生产性的工作，则工作就进行得快多了。\u003c/p>\u003cp>事实上，一位管理者大刀阔斧减少不必要的工作，绝不会有太大的风险。人总有一种倾向，高估自己地位的重要性，认为许多事百躬亲不可。纵然是最有效的管理者，仍然免不了有许多不必要的和生产性的工作。\u003c/p>","explains":"\u003cp>好，大家都阅读完了本片段，\u003c/p>\u003cp>What：这个拆页列举出了如何诊断自己的时间的二个步骤及三个方向；是管理者对时间加以记录，并且是“实时”的记录，以确保记录的准确性及做系统的时间管理将非生产性的和浪费时间的活动找出来。\u003c/p>\u003cp>Why：为什么要诊断自己的时间？由于组织本身的需要，处理人事问题的需要，以及创新和变革的需要，最终都是为了提高我们自身的工作效率，都使得我们不能不讲求时间的管理了。而要很容易掌控好时间，首先要了解自己是如何使用时间的，必须对时间进行诊断。\u003c/p>\u003cp>How：拆页里已经详细给出了二个步骤\u003c/p>\u003cp>1、第一步就是记录其时间耗用的实际情形。\u003c/p>\u003cp>2、第二步就是要做有系统的时间管理，三个方向 \u003c/p>\u003cp>\u003cstrong>不这么做的坏处：\u003c/strong>\u003c/p>\u003cp>如果不做时间的诊断，会有哪些坏处，\u003c/p>\u003cp>第一， 恶性循环，重复做着一件事； \u003c/p>\u003cp>第二， 浪费自己与他人的时间；\u003c/p>\u003cp>第三， 造成整体效率低下，同事间合作不愉快\u003c/p>\u003cp>\u003cstrong>【例子】\u003c/strong>\u003c/p>\u003cp>我是研发部的主管，整天忙下来没效率，又被上级K，要找出我当下的原因在哪，针对我一天的工作内容进行记录，我的时间的使用情况\u003c/p>\u003cp>1）跟进研发进度2）协调与其他部门的配合3）出差人员的确定4）别部门聚会邀请5）开会6）参加其他部门的会议\u003c/p>\u003cp>其中第1、2是下属就能做的事，而且他们会做得很好；第3、4项是不需做的事，别部门的邀请只是礼貌知会，并不是一定要我出席的，出差人员的确定，直接就可以敲定；第5、6项是浪费别人时间的事，会议，只要看会议记录就能完成。 \u003c/p>","interaction":"\u003cp>\u003cstrong>【A1显像提问】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>经过刚才对拆页片断的学习，大伙试想下在自己的生活和工作中，平常有觉得时间不够用，是否有对时间进行诊断呢；假如你是一个总经理助理，你需要从事的事务是非常多，如招聘、面试、协调等等这些事务，在你忙得焦头烂额，情绪暴涨，甚至非常愤怒的时候，你是否意识到你的时间不够用，当时你是否记录时间使用情况并事后尝试发现问题所在呢？现在在场的小伙伴可以试想下类似过往经历中是否有类似时间不够用或因时间使用情况造成不愉快情绪的，当时你是否记录时间使用情况并事后尝试发现问题所在呢？现在小组内讨论。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴的分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>小伙伴的工作是管理协调技师贴膜及和4S店对接，有一次，4S店反馈，昨天贴的车膜有出现卷边及起泡，里面还有一个小杂物，催着要贴模的技师去处理，当时我花了很多时间和4S店一直解释，这是什么情况，同时4S店一直催我让技师赶紧过去处理，我一听就一直催我的技师，你现在到哪里，4S店很急，最后因这个事故，整件事情处理起来很不愉快，技师也和我抱怨说你电话不要一直催，在路上堵车，最后和同事关系搞得很不好，自己的心情也不好，所有时间都浪费在和4S店沟通及催促技师上。\u003c/p>\u003cp>非常感谢这位小伙伴，现在我想问的是，当时你是否记录时间使用情况并尝试发现问题所在呢？\u003c/p>\u003cp>\u003cstrong>学习者回答：没有。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+反思加工】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>本拆中第一步强调的是当时记录，从刚才大家讨论中的案例，当时都没有记录，为了让大家更好的体验如何诊断，接下来，大家先将自己刚才的案例写在下列的表格中。写完后，想想看，根据本拆第二步的建议，最好怎样来处理你遇到的那个问题？给大家两分钟时间。最后请小伙伴来分享。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴的分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>运用今天所学方法进行诊断我的时间使用情况，第一步骤，事件已经发生，我要静下心来梳理，我对时间的分配进行诊断，我要记录下事件，我的时间主要使用在以下2个方面，1）4S和我反馈膜的情况，我要先安抚下他的情绪，解释说什么情况；2）我将信息反馈给贴膜的技师，让他到4S店看情况；对这2个时间进行诊断，1、找出什么事情根本不必做，不需要向4S店人员解释我们膜的情况，我只要说，我将情况向技师反馈，等技师看了情况会和你们沟通，不需要解释什么，不然造成4S店对接人员多虑；2、不要浪费别人的时间，我不需要去催技师，让他早点到，多打电话会影响技师的情绪，只要将情况告知技师即可；3、可以由他人处理的事，即现场情况由技师和4S店沟通就好，我不清楚现场，这不是我来做的；通过这个方法，进行时间诊断。\u003c/p>\u003cp>\u003cstrong>结束语，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>谢谢这位小伙伴的分享，他优化的案例非常契合我们今天的学习目标，如何诊断自己的时间，也希望今天学习的如何诊断自己的时间，能为大家带来提高工作效率。今天我的分享到此结束，谢谢大家！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1620252070000,"updated_at":1620560113000,"ria":true},{"id":10253,"topic":"有效授权","learn_goal":"","remark":"如何从繁忙的工作或家务中解脱出来。有更多自己可支配的时间，喝杯拿铁，看场电影，来次说走就走的旅行！让我们共同学习有效授权吧。","level":"TF3-1","duration":16,"status":29,"type":0,"chaishujia":{"username":"段志梅","city":"株洲"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>自我介绍+场景介绍法（1分钟）\u003c/p>\u003cp>大家好，我是段志梅。我的三个标签：二级拆书家；德鲁克的铁粉；旅游爱好者。\u003c/p>\u003cp>[场景法介绍]\u003c/p>\u003cp>事件：上周一位朋友向我抱怨到：工作特别忙，于是把一些工作授权给下属去做。可结果很让人很受伤，交代下去的工作不是没完成就是不了了之。到头来还要自己来处理。自己到底哪做错了呢？\u003c/p>\u003cp>提问：工作生活中你是否也遇到过类似问题：工作或事情明明授权下去了，结果不但不是自己想要的，甚至还会有撞墙的冲动，同时对方还感觉很委屈。你会如何做呢？有效“授权”就是解决此类问题的法宝。\u003c/p>\u003cp>影响：亲力亲为的行为，会让周边的人感到你不信任他们，严重影响他们的积极主动性和创造性，容易导致人际关系的破烈。凡事亲力亲为，我们就会身陷各种琐事之中，身心疲惫，自然无法兼顾工作和生活，也会严重影响到我们生活的幸福指数。\u003c/p>\u003cp>解决：今天要学习的片段就可以解决这个问题。现代管理学之父，大师中的大师彼得•德鲁克的《卓有成效的管理者》为我们非常清晰解读了什么是有效授权，以及如何实现有效授权。以改善提升我们管理的有效性。\u003c/p>","ratings_count":1,"texts":[{"id":14092,"quote":"\u003cp>R原文阅读（1分钟）\u003c/p>\u003cp>参加会议也是问题。虽然会议上本来并没有什么别人处理不了的大事，但管理者总得出席。在文件的初稿出来之前，管理者往往要花上好几个小时参与讨论。研究所为了发布研究成果的新闻，得由主持该项研究的高级研究员来撰写新闻稿。研究所里很多人都知道该项研究的经过，新闻稿如果由别人写，写出来一定文笔流畅、通俗易懂，而高级研究员却只能写出一些高深莫测的数学公式。总而言之，管理者所做的工作，确实许许多多可由别人去做，而且也应该由别人来做。\u003c/p>\u003cp>“授权”这个名词，通常都被人误解，甚至是被人曲解。这个名词的意义，应该是把可由别人做的事情交付给别人，这样才能做真正应由自己做的事——这才是有效性的一大改进。\u003c/p>","explains":"\u003cp>分享I便签（4分钟）\u003c/p>\u003cp>[学习目标]\u003c/p>\u003cp>在跟随我完成现场RIA学习之后,学习者能够运用授权四步法，按步骤制订出合理的授权方案，将某个任务分配给他人，减轻负担，提高效能。\u003c/p>\u003cp>[概念对比]\u003c/p>\u003cp>大家是不是想起了新闻里常讲的“简政放权”。 这里的“放权”是指上级掌控的权力交给下级，也就是权利下放。放权时掌握大方向即可，不必事事过问。\u003c/p>\u003cp>拆页中的“授权”是指上级把自己的职权授给下属，使下属拥有相当的自主权和行动权。\u003c/p>\u003cp>先来看个例子。\u003c/p>\u003cp>领导让小李负责公司5周年庆典活动，时间8/18日，预算15万，公司内部不对外。让小李根据这些计划和安排，不用事事报告。\u003c/p>\u003cp>请问这个是？\u003c/p>\u003cp>学习者：是放权。\u003c/p>\u003cp>时间，预算，不邀请外人，大方向领导交代的很清楚。根据这些计划和安排，不用事事报告，小李自己可以决定一些事情，正是权利的下放。\u003c/p>\u003cp>OK，再看另外一个例子。\u003c/p>\u003cp>领导对小王说：8月中旬和广西刘总的商务会议你去。张明比较了解刘总，他一块去；会议需要注意的几点，我邮件给你；开辆车过去方便些。你有不明白的，可随时打我电话。\u003c/p>\u003cp>请问这个是什么呢？\u003c/p>\u003cp>学习者：是授权。\u003c/p>\u003cp>对，是授权。会议需要注意的几点，我邮件给你，这是提供指导。开辆车过去方便些，提供了可用资源。\u003c/p>\u003cp>“授权”有什么特点呢？它是决策权力的下放过程，是职责的再分配过程；两者间信息和知识要共享；受权者要得到技术培训；授权是动态变化的。\u003c/p>\u003cp>“放权”是解除某种控制与责任，“授权”是指职责分解，指的是任务，并没有放弃控制与责任，这是两者本质区别。\u003c/p>\u003cp>OK，大家都清楚两者的区别了吗？\u003c/p>\u003cp>[How]\u003c/p>\u003cp>如何做才是有“有效授权”呢？请看下面的具体步骤。\u003c/p>\u003cp>1： 明确授权的范围\u003c/p>\u003cp>具体要授权的事件；要达到什么样的结果及截止时间。\u003c/p>\u003cp>2： 量才授权\u003c/p>\u003cp>根据下属能力大小、特长、知识水平合理授权。　　\u003c/p>\u003cp>3：提供可用资源或是指导\u003c/p>\u003cp> 事先告知被授权人可能遇到的障碍或困难，提供可使用的资源或是经验传授，好让被授权明白不是独自在奋斗。\u003c/p>\u003cp>4：明确利益和责任\u003c/p>\u003cp> 被授权人顺利完成可获得的利益；如完不成要承担的责任。\u003c/p>\u003cp> 例如：你收回这笔欠款，大家就可以准时收到工资了。\u003c/p>\u003cp> 你学会了炒这个菜，那你的菜单就更丰富了呀！ \u003c/p>\u003cp>看个例子哈。\u003c/p>\u003cp>7/10我让小李去武汉收款，让他开车过去的，并告诉他收回有5天假期。结果第10天才收回（7天就可完成）。　\u003c/p>\u003cp>在这里我没有明确授权的范围，所以超时了。\u003c/p>\u003cp>8/1我让小李去收款是这样讲的。小李岳阳的货款要8/7前收回（明确授权的范围）。相信你（量才授权）！支3000块备用（提供可用资源或是指导）。希望你成为“收款大拿”哟（明确利益和责任）。这次非常顺利，8/5就收回了。\u003c/p>\u003cp>一个超时，一个提前，可见“有效授权”的重要性。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>有效授权工作生活中都可使用。比如授权下属负责一个新项目，先生做饭等。\u003c/p>\u003cp>但要注意：有效授权一定在建立在充分了解被授权人情况下进行的，并在可控范围内。\u003c/p>\u003cp>为了方便A2的进行，我们两人一组。\u003c/p>","interaction":"\u003cp>【A 2催化应用】（10分钟）\u003c/p>\u003cp>请各位编一段小剧本，几百字即可，包括人物、背景、事情的起因、经过和结果以及人物之间的对话。要运用今天所学的有效果授权4个步骤，有可能是大家未来会遇到的场景，比如让小孩做饭，或是让下属独自负责一个项目等。\u003c/p>\u003cp>大家可以把故事的摘要写在纸上。4分钟后我们请两个小伙伴来讲讲各自编写的小剧本。下面请大家编写剧本。\u003c/p>\u003cp>学习者分享1\u003c/p>\u003cp>妈妈：儿子，你身上的红点和舌苔拍照给我，要拍的很清楚。吃喝拉撒也给我说下。这些晚上7点前要给到我（明确授权的范围）。我好找医生看下。\u003c/p>\u003cp>儿子：好的，可我没带手机呀！\u003c/p>\u003cp>妈妈：你可以找老师借下手机，或是让老师帮你拍下（量才授权，提供可用资源或是指导）。\u003c/p>\u003cp>儿子：恩，这个我可以做到。\u003c/p>\u003cp>妈妈：你早点给我，我找中医看下，你也快点好起来，不然长在身上好难受（明确利益和责任）。\u003c/p>\u003cp>学习者分享2\u003c/p>\u003cp>妈妈：你今天在家把卫生打扫干净，尤其是书柜上的书要整理好。我下班回到家要看到很干净，很舒服才行（明确授权的范围）。\u003c/p>\u003cp>大宝：放心，交给我吧。\u003c/p>\u003cp>妈妈：你干过的，可以打扫干净的。万一有不会弄的打电话给我，我教你(量才授权，提供可用资源或是指导)。\u003c/p>\u003cp>大宝：恩。\u003c/p>\u003cp>妈妈：如果你做的好，周末奖励你去看电影（明确利益和责任）。\u003c/p>\u003cp>大宝：太好了。\u003c/p>\u003cp>谢谢两位小伙伴的分享，有效授权四步骤用的很好。\u003c/p>\u003cp>结束语\u003c/p>\u003cp>希望通过今天的学习，能让你通过有效授权，提高工作效率；从繁忙的工作家务中解脱出来。有更多自己可支配的时间，喝杯拿铁，看场电影，来次说走就走的旅行！OK，我的拆解到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1596990265000,"updated_at":1598421888000,"ria":true},{"id":9871,"topic":"学会利用整块时间","learn_goal":"","remark":"管理者，就必须卓有成效。\n卓有成效是可以学会的！\n如此，一群平凡的人，就做出不平凡的事。\n书中，德鲁克集中论述了一个管理者如何做到卓有成效。这本书是德鲁克最著名的管理学著作之一，倾注了德鲁克极大的心血。","level":"TF1-2","duration":1515,"status":19,"type":0,"chaishujia":{"username":"黄胜","city":""},"club":{"name":"苏州阅苏分舵","city":"苏州"},"prologue":"\u003cp>大家好，我今天要带领大家一起进行《卓有成效的管理者》这本书的拆书练习，首先介绍一下我自己，我叫黄胜，未来的拆书家。我给自己的三个标签是：终身学习爱好者（拥有两个硕士学位），积极心理学推广者（我的心理学硕士学的是积极心理学这个方向），马拉松爱好者（全程马拉松最佳成绩是3小时49分钟）\u003c/p>\u003cp>选择这本书的原因是因为作者彼得.德鲁克是当代的管理学大师，人称“大师中的大师”和“现代管理学之父”，自己作为一名企业管理人员，也算是一名知识工作者，希望能从他的作品中得到启发，让自己的管理变得更加卓有成效，同时也希望把他作品的精髓通过拆书的方式，传递给在座的各位。\u003c/p>\u003cp>接下来，我们先分一下组，左边三个人一组，右边两个人一组这样便于讨论，让每个人都有发言的机会。\u003c/p>\u003cp>下面请大家用2分钟的时间阅读一下刚刚发的拆页。看完的小伙伴请给我一个眼神示意一下。\u003c/p>","ratings_count":1,"texts":[{"id":13704,"quote":"\u003cp>\u003cstrong>阅读原文：《卓有成效的管理者》\u003c/strong> \u003cstrong>P28页  \u003c/strong>\u003c/p>\u003cp>每一位管理者的时间,都有很大部分是被浪费掉的。表面上看起来,每件事似乎都非办不可,但实际上却毫无意义。 但是,即使是只想获得最低程度的有效性,管理者的绝大部分任务也需要相当多的整块时间。如果每一次所花的时间少于这个极限,事情就做不好,所花的时间就是浪费,再做就得从头开始。 \u003c/p>\u003cp>举例来说,写一份报告大概得花6~8小时才能完成初稿。如果说每次花15分钟,每天2次,一共花上2星期,虽然总时间也达到7小时,恐怕结果还是一张白卷。但是如果能够关起门来,切断电话,连续做上五六个小时,一份相当不错的初稿就应该差不多了。有了这份初稿,他才能做零星的补充,才能逐句逐段地润色、修改和整理科学实验工作也与此相似。起码需要5~12小时的整块时间才能把仪器调整妥当,做成一次实验。如果中间被打断,恐怕就得重新开始。\u003c/p>\u003cp>每一位知识工作者,尤其是每一位管理者,要想有效就必须能将时间做整块的运用。如果将时间分割开来零星使用,纵然总时间相同,结果时间也肯定不够。\u003c/p>","explains":"\u003cp>看到大家都已经看完了。\u003c/p>\u003cp>其实很多书本上都提到时间管理的重要性，但是如何进行时间管理，各种说法都不太一样，比如说番茄工作法，认为人的专注时间是有限的，所以最好是把专注的时间设定在25分钟左右，高效能人士的七个习惯里面则强调，要事第一，而我们拆书帮则提倡学会在移动信息时代，在日常生活中要学会碎片化时间来进行学习。\u003c/p>\u003cp>这本书则认为，对于管理人员来说，特别是知识管理者来说，在工作中学会将时间做整块的运用，将对管理工作的有效性产生很大的影响。针对于工作而言，这里说的整块的时间，十几二十分钟是肯定不够的，一般来说需要1小时以上，这样你才有可能真的静下心来投入到任务中，真的去影响别人或者与别人建立良好的关系。因为这么做可以避免每次的重新开始的过程，重新将思维定位到任务中的过程，就如机器的开机过程一样，反复开机的话，时间就被浪费了。\u003c/p>\u003cp>管理者如何做到花整块的、足够时间在任务中呢？管理者需要在处理重要工作时，注意力集中于单项任务，设定好目标，开始该任务后，尽量避免浪费时间在琐碎事情上面，避免琐碎事情的干扰和影响，这样才能以做到卓有成效的目的。\u003c/p>\u003cp>我发现如果我们能想办法避免各种干扰，做到注意力集中，时间也就能整块的使用。就如前些天，师父联系我说想拆一本管理方面的书，想和我交流一下，听听我的想法，在晚上6点左右，师父就把拆页的内容发给我了，同时也把要讨论的问题也告诉我了，我们约好晚上8点左右微信语音联系。在接下来的时间里面，我把注意力就集中在这件事情上，阅读原文，联系自己的工作实践，回顾过去的案例，发现自己效率就出奇的高，这次手机放旁边竟然也没有把我的注意力分散开。平时要做一个拆页便签，往往需要拖拉几个小时，有时候几天才能完成，而且内容，故事似乎很难找到。但是这一次，思如泉涌，两小时不到，就把需要和师父讨论的内容整理好了，做好了与师父进行拆页交流的准备工作。在这个例子里面，我就是把时间整段的利用起来了，所以效率特别的高。\u003c/p>","interaction":"\u003cp>在这里，我想请大家想一想，自己是否有过这样的经历，因为专注度不够，时间利用不好，效率没有达到自己的期望，自己觉得很不满意，很沮丧，希望以后能得到改善？ 这是些什么事情，当时的情景是怎么样的呢？\u003c/p>\u003cp>或者说曾经经历过的一些相反的事情，在某些状况下自己效率特别高，因为专注度很高，把时间整段的利用起来了，自己觉得很满意，很自豪？这又是一些什么样的事情，当时的情景是怎么样的？ 我想请大家用1分钟的时间回想和思考，4分钟的时间在小组里面分享自己的经验。\u003c/p>\u003cp>\u003cstrong>学习者经验分享：\u003c/strong>\u003c/p>\u003cp>我们有一个改善项目，从头到尾花了一年半的时间，效果也很好，被要求把改善的内容在两周之内呈现出来，让大家了解并参加评比。所以很希望自己能有整段的时间思考如何呈现，这需要安静的思考，但在公司里面敞开式的办公室，工作很容易被人打断，有时一整天都不能写出一页来，有时开头怎么都出不来，导致很焦虑。后来是带回家做的，因为在公司无法有整段时间这样的环境，不停的有电话和会议等。如果能用整块的时间，思绪是连贯的，容易产生心流状态，自己能够沉浸在那个环境中，自己是快乐的。所以整块时间确实是很重要的。\u003c/p>\u003cp> 谢谢，很好的分享，接下来，根据大家刚才回顾的经历和经验，请你整理一下自己的思路，看看日后计划如何把将时间做整块运用这个工具用好，帮助自己提升工作和日常生活的办事的效率。下面请大家用1分钟的时间，在便签纸上写下自己的应用或行动步骤。你的应用或行动步骤应该包括具体的做法，要有明确的时限，还要有可衡量或可观测的预期结果。\u003c/p>\u003cp>\u003cstrong>学习者行动应用分享：\u003c/strong>\u003c/p>\u003cp>我把今天的拆页内容和之前一次拆书活动的心得结合一下，就是上海分舵的前舵主崔律出新书的时候，就是精实力管理分享的要点，说要刻意规划出离线时间，就是切断与外界的联系，包括物理和网络联系，结合今天的整块时间利用，可以这么去规划，我下周要去做一个招标方案，我可以这么做，就是第一我预估这个方案需要的时间是一个小时，这一个小时我要集中精力其实什么事情都不做，尽量不让别人来找我，电话也不接，这一小时完全沉浸在这里面把它做完，时间空出来后，设定好开始的时间，比如说下午两点开始，到三点结束，不看手机，把手机静音，背面朝上，电脑关掉，到三点时候再来衡量结果，如果没有完成再重复这个步骤，这样应该能够比较高效的完成这个工作。\u003c/p>\u003cp>好了，谢谢大家的分享和参与，我今天的拆书练级活动到此结束，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1590838133000,"updated_at":1591149209000,"ria":true},{"id":9870,"topic":"卓有成效的管理5原则","learn_goal":"","remark":"管理者，就必须卓有成效。\n卓有成效是可以学会的！\n如此，一群平凡的人，就做出不平凡的事。\n书中，德鲁克集中论述了一个管理者如何做到卓有成效。这本书是德鲁克最著名的管理学著作之一，倾注了德鲁克极大的心血。","level":"TF1-1","duration":1515,"status":29,"type":0,"chaishujia":{"username":"黄胜","city":""},"club":{"name":"苏州阅苏分舵","city":"苏州"},"prologue":"把事先准备好的复印原书拆页发给现场学习者，人手一份。\r\n大家好，我今天要带领大家一起进行《卓有成效的管理者》这本书的拆书练习，首先介绍一下我自己，我叫黄胜，未来的拆书家。我给自己的三个标签是：终身学习爱好者（拥有两个硕士学位），积极心理学推广者（其中一个硕士学位是心理学硕士），马拉松爱好者（全程马拉松最佳成绩是3小时49分钟）\r\n那么，什么是拆书呢？拆书是一种学习方法论，是一种适用于以提升能力，解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验，规划出具体的运用。\r\n拆书法分为个人学习的拆书法和组织学习的拆书法。个人学习的拆书法叫便签法，让人读一本书就能达到参加同主题培训的效果，而组织学习的拆书法是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用，创造出不亚于培训师培训的学习价值。\r\n拆书帮是基于拆书法的学习爱好者社群，表现为各地拆书帮分舵，拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\r\n了解了什么是拆书和拆书帮后，我们开始今天的拆书活动，我们先分一下组，这样便于讨论，让每个人都有发言的机会。请大家阅读一下刚刚发的拆页，给大家两分钟的时间。看完的小伙伴请给我一个眼神示意一下。","ratings_count":2,"texts":[{"id":13703,"quote":"\u003cp>\u003cstrong>原文：《卓有成效的管理者》 P22 \u003c/strong>\u003c/p>\u003cp> 下列五项是要成为一个卓有成效的管理者,必须在思想上养成的习惯: \u003c/p>\u003cp>1.有效的管理者知道他们的时间用什么地方。他们所能控制的时间非常有限,他们会有系统地工作,来善用这有限的时间。 \u003c/p>\u003cp>2.有效的管理者重视对外界的贡献。他们并非为工作而工作,而是为成果而工作。他们不会一接到工作就一头钻进去,更不会一开头就探究工作的技术和手段,他们会首先自问:“别人期望我做出什么成果?” \u003c/p>\u003cp>3.有效的管理者善于利用长处,包括自己的长处、上司的长处、同事的长处和下属的长处。他们还善于抓住有利形势,做他们想做的事。他们不会把工作建立在自己的短处上,也绝不会去做自己做不了的事。 \u003c/p>\u003cp>4.有效的管理者集中精力于少数重要的领域,在这少数重要的领域中,如果能有优秀的绩效就可以产生卓越的成果。他们会按照工作的轻重缓急设定优先次序,而且坚守优先次序。他们知道:要事第一。重要的事先做,不重要的事放一放,除此之外也没有其他办法,否则反倒会一事无成。 \u003c/p>\u003cp>5.最后,有效的管理者必须善于做有效的决策。他们知道有效的决策事关处事的条理和秩序问题,也就是如何按正确的次序采取正确的步骤。他们知道一项有效的决策,总是在“不同意见讨论”的基础上做出的判断,它绝不会是“一致意见”的产物他们知道快速的决策多为错误的决策,真正不可或缺的决策数量并不多,但一定是根本性的决策。他们需要的是正确的战略,而不是令人眼花缭乱的战术。 \u003c/p>","explains":"\u003cp> 可能有人有过这样的经历：忙忙碌碌的过了一天，到晚上的时候，突然发现，好像自己并没有做什么事情，重要的事情还挂在那里，压在心头，日子过得并不充实，办事效率也不高，感觉自己的时间在忙碌中都荒废掉了。\u003c/p>\u003cp>那么，如何提升自己的办事效率，如何达到卓有成效的目的呢？这需要我们在自己的工作和生活中养成以下五个习惯：\u003c/p>\u003cp>1. 把时间用在合适的地方。时间是一种有限的资源，浪费掉的时间是无法追回来的，即使用金钱都无法买回来，所以我们需要有效的利用好自己的时间。\u003c/p>\u003cp>2. 重视对外界的贡献。我们经常整天忙忙碌碌，但是忘记了思考忙碌的意义和忙碌的目的，导致别人期望的目标和任务没有完成，别人对我们的工作不满意，我们自己也没有成就感。所以在把时间投入某项任务时，我们要问问自己：“别人期望我做出什么成果？”，我们要为成果而工作。\u003c/p>\u003cp>3. 善于利用和发挥优势。我们能在竞争中脱颖而出，往往是因为我们在某些方面要比别人强，成功往往是自己或团队优势发挥的结果。所以我们要学会因势利导，利用自己、他人的甚至是老板的长处去完成任务。\u003c/p>\u003cp>4. 集中精力于少数重要领域，要事第一。要事第一也是“高效能人士的七个习惯”里面的一个习惯，我们要把重要的事情放在第一位，把精力集中在少数重要领域，这样才可能产生卓越的成果。另外，重要的事情没有及时处理，会给我们带来很大的压力，让我们一直处于压力之下，带来不必要的心理负担。\u003c/p>\u003cp>5. 善于做有效的决策。我们生活中每时每刻都在做决策，今天大家来到这里参加这次拆书会，而不是把时间花在做别的事情上，我认为你就已经做了一个非常英明的决策。我们人生的轨迹就是由我们生活中一个又一个的大大小小的决策而形成的。所以做有效的决策对我们每一个人都很重要。\u003c/p>\u003cp>这五个习惯为了方便记忆，可以简单归纳为时间、贡献、优势、要事和决策。这五个习惯是相对独立的，但是也有一定的关联。比如说“把时间用在合适的地方”和“集中精力于少数重要领域”。我认为第五个习惯是关键习惯，因为它将决定我们是否关注到、是否采用前面的四个习惯。\u003c/p>","interaction":"\u003cp>\u003cstrong>我的A1便签：\u003c/strong>\u003c/p>\u003cp> 就拿最近一个周六上午发生在自己身上的例子来说吧，因为我们拆书练级训练营已经开始了，我的练级准备工作还没做好，所以我计划上午就做完这个拆书练级文稿。吃完早饭，翻开书，启动电脑，电脑启动期间，就顺便把手机拿过来，浏览一下微信订阅号，思绪马上就被当前疫情发展状况的相关新闻所吸引了，半个小时后，发现自己还没开始进行文稿整理，才翻开练级手册，准备先看看练级的步骤和技能要求，看了几分钟，觉得有点渴了，还是去泡一杯茶喝喝吧，然后起身泡茶，茶水泡好，回到座椅上，打开电脑文件，突然又想起还没有看看微信朋友圈呢，看看大家都发了些什么吧，哦，注意力一下子就被当前股市启动熔断机制的新闻给吸引过去了，哎，这个特朗普到底怎么回事，发了个言，一下子就蒸发了多少个亿的美金......不知不觉，竟然就到了中午了，该吃中饭了，一个上午怎么就这么过去了，回过头来看看，自己上午开始时设定的目标呢，几乎还在原来的状态，没有完成。\u003c/p>\u003cp> 反思：\u003c/p>\u003cp> 大家和我一起来看看上面这个案例，与卓有成效管理者的五个习惯比，我在哪些习惯上没做好？\u003c/p>\u003cp> 首先是把时间放在合适的地方这个习惯没做到，时间管理方面做得很不到位，浪费了很多时间。我想要做的是完成拆书练级文稿，但是时间却花在了看手机，看微信订阅号，喝茶，看朋友圈，关心疫情发展上去了。\u003c/p>\u003cp> 第二是重视对外界的贡献这个习惯没做到，我的错误就是没有考虑到对外界的贡献。我本来要做的是写出让大家满意的、精彩的拆书练级文稿，而我却把注意力关注在当下疫情的发展去了。\u003c/p>\u003cp> 第三是要事第一这个习惯没有做到位，没有把要事放在第一，拆书练级当然是我上午的要事，可惜因为习惯不好，时间和精力竟然被别的事情吸引过去了。\u003c/p>\u003cp> 第四是善于做出有效决策这个习惯没做到。我知道自己的注意力容易分散，却没有做出预防措施，比如说用番茄工作法，设定小闹钟，限制自己的注意力，学习时间到了后再轻松一下，做到学习娱乐两不误。\u003c/p>\u003cp>\u003cstrong>我的A2便签：\u003c/strong>\u003c/p>\u003cp> 目标：改变自己身上效率低下的习惯，通过每日自我检查和改善，来养成卓有成效管理者需要具备的五个习惯。\u003c/p>\u003cp> 行动：根据上述五个习惯，我画了一个实践对照表，把卓有成效管理者需要养成的五个习惯列入表格。计划每日下班后对照表格，填写自己当天在每一个习惯上的得分，进行现状描述，列出改善点，每天对照，每天改进，坚持21天，促使自己形成这些习惯。\u003c/p>\u003cp> 好了，谢谢大家的参与，我今天的拆书练级活动到此结束，谢谢\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1590835451000,"updated_at":1591423572000,"ria":true},{"id":9466,"topic":"有效的人际关系","learn_goal":"主管智慧三问 激活下属","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"陈洪琪","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>各位朋友，下午好！ \u003c/p>\u003cp>我是今天晋级1-1的陈洪其。 我先用3个标签介绍自己，分别是“教育工作者”、“快乐的学习者”和“教练型父母的践行者”。\u003c/p>\u003cp>我是一个喜欢分享的人，想让更多的人快乐地工作、快乐地生活，所以在近二十年职业发展中，越来越倾向于做一个知识的传播者、分享者和促进者，而这也是我加入拆书帮最主要的原因。\u003c/p>\u003cp>我所了解的“拆书帮”，是一个学习爱好者的社群，而它在全国各地设立的分舵，都是公益性的青年自组织，其使命是帮助更多的学习爱好者成长为拆书家，目前我们所在的地方就是成都的蜀汉分舵。\u003c/p>\u003cp>那拆书家又是一个什么样的角色呢？这就得先解释一下“拆书”是怎么回事——拆书是一种学习方法论。具体来说，是针对成年人以提升能力、解决问题为目标而实施的一种学习方法。把这种学习方法同我们从小所接受的教育比较，最大的区别就在于它是以学习者为中心，而不是我们熟悉的以知识为中心。“拆书”的“拆”不是“拆散”，而是转化和内化。 它强调在学习的过程中，一定要把知识关联学习者的经验，然后规划具体的应用，从而实现提升技能、改变行为、解决问题的目的。\u003c/p>\u003cp>拆书学习的方法分为两种，一种是针对个人学习的便签学习法——让人读一本书就能达到参加一场同主题培训的效果；另一种是针对组织学习的RIA现场学习法——一位拆书家用一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>回到刚才的问题，拆书家是一个什么样的角色呢？拆书家就是运用拆书法帮助和促进他人学习的人。如果从学习效果来衡量，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>按照拆书帮的规定，拆书家分为3个级别、9个档次。从最低的1-1到最高的3-3，拆书家需要通过现场带领拆书学习的方式来逐级晋升，大家把这个过程戏称为“打怪升级”。现在我正在进行的就是1-1的晋级。\u003c/p>","ratings_count":1,"texts":[{"id":13278,"quote":"\u003cp>“不破不能立，不拆不成器。”现在我就来演练一下便签学习法——\u003c/p>\u003cp>今天我要拆的这本书叫做《卓有成效的管理者》，作者是美国的彼得.德鲁克，被称为管理学大师。 这本书是他的经典著作，本书从5个方面介绍了如何卓有成效，分别是掌握自己的时间、把眼光聚焦在贡献上、发挥人的长处、要事优先、有效决策。\u003c/p>\u003cp>今天我要拆的片段，就是来自于这本书的第3章，“我能贡献什么”，就是本书5个内容之一——把眼光聚焦在贡献上，P64，正确的人际关系。\u003c/p>\u003cp>现在请大家阅读手中的拆页。读完以后请举手示意我一下，谢谢！\u003c/p>\u003cp>主管智慧三问&nbsp;&nbsp; 激活下属 \u003c/p>\u003cp>原来是我们一直把沟通当成是上对下的事，是主管对下属的事。仅靠上对下的单向关系，沟通永远不可能成功。这是我们从实际经验和沟通理论上得到的结论。上级对下属越想说得严厉，下属就越听不进去。下属要听的是自己想听的，而不是对方所说的。 \u003c/p>\u003cp>一位在工作中以贡献为重的管理者，通常期望其下属也能以贡献为重。因此，他肯定常常问他的下属：“我们的组织和我，应该期望你有怎样的贡献呢？我们该期望你做些什么？如何才能使你的知识和能力得到最大的发挥？”有了这样的检讨，才有沟通的可能性，也才容易成功。 \u003c/p>\u003cp>下属经过思考提出他认为可以做出的贡献之后，主管才有权利和责任对他提出的建议是否可行做出判断。 \u003c/p>\u003cp>我们都有这样的经验：由下属自己设定的目标，往往会出乎主管的意料之外。换言之，主管和下属看问题的角度往往极不相同。下属越能干，就越愿意自己承担责任，他们的所见所闻，所看到的客观现实、机会和需要，也越与他们的主管不同。下属的结论和主管的期望往往是明显对立的。 \u003c/p>\u003cp>出现这种分歧时，主管和下属双方究竟谁对，通常并不值得重视，因为上下双方已经建立了有效的沟通。 \u003c/p>","explains":"\u003cp>（Why）\u003c/p>\u003cp>不知道这里有多少朋友是做管理的，有没有发现，很多时候同下属沟通，明明提了要求，下属却执行不到位，甚至阳奉阴违？ 这是为什么呢？\u003c/p>\u003cp>这或许是因为你说的，是你想说的，而不见得是下属想听的；你说的，是你想要的，而不见得是下属想要的。\u003c/p>\u003cp>你还有没有发现，很多时候为了推动一项工作，办法都得你自己想，做事都得追着下属做。 这又是为什么呢？\u003c/p>\u003cp>这或许是因为下属看不到这项工作对他们可能产生的帮助和利益；又或许，下属认为凡事都是你说了算，从而没有参与的积极性。\u003c/p>\u003cp>那么作为主管，到底该怎样做呢？\u003c/p>\u003cp>(What)这个拆页就介绍了一个主管与下属有效沟通的方法——通过提出三个问题，激活下属的思想，调动下属的积极性，从而富有成效地推动工作。具体如何做呢？\u003c/p>\u003cp>（How）我将主管对下属的有效沟通方法总结为“智慧三问”：\u003c/p>\u003cp>一问，（启发贡献）“你觉得自己能为公司做出什么样的贡献？” 借助这个问题，激活下属对自己的期望。\u003c/p>\u003cp>二问，（明确行动）“你觉得自己具体可以做些什么，从而实现这种贡献？” 借助这个问题，激发下属思考自己的行动。\u003c/p>\u003cp>三问，（询问支持）“为了将自己的知识和技能得到最大限度的发挥，需要我和公司为你提供哪些支持？” 借助这个问题，促进下属为采取行动准备资源。\u003c/p>\u003cp>不管是主管与下属的沟通，还是其他关系的沟通，关系是进行有效沟通的重要基础，需要沟通者同步被沟通者，从而建立信任，有了信任就有如打开了心的大门，这是有效沟通的基础。\u003c/p>","interaction":"\u003cp>（A1）\u003c/p>\u003cp>关于沟通，我们每个人都有一些与工作有关的沟通经历，有达到成果的，也有毫无进展的，到底有哪些共同点呢？我来分享一个我的沟通经历吧。\u003c/p>\u003cp>2019年11月，我与品宣专员讨论11月30号活动简报的提纲，沟通目的是辅助品宣专员列出活动简报提纲。讨论一开始，我对活动提出了数条自己的看法和建议；随后，我让品宣专员说说她的建议或意见，她说“还没想出来”。我也不想所有的都是我想说的，都是我想做的，我希望她能主动去思考，并有自己的行动方案，所以，这次目标没有达成，我就让她再思考一下，定于12月6号下午再次沟通。\u003c/p>\u003cp>就这样，一个讨论变成了我的“独角戏”，沟通没有达到目的。操心的还是我，品宣专员没有真正参与进来。这是一次没有解决问题的无效沟通。\u003c/p>\u003cp>(A2)\u003cbr>\u003c/p>\u003cp>我学习了这个方法后，对工作关系的沟通有了更深一些的理解，准备2020年1月和教学主管就“2020年度教学质量管理体系升级”开启一轮探讨，用“智慧三问”,激活对方。 具体可以这样做：\u003c/p>\u003cp>一问， （启发贡献）“你希望自己能在2020年教学质量管理上做出一些什么成果？” 激活对方思考对这项工作的期望。\u003c/p>\u003cp>二问， （明确行动）“对于明年的教学质量管理体系，你确定几个重点贡献方面，准备采取哪些行动呢？”激发对方思考自己的行动。 \u003c/p>\u003cp>三问，（询问支持）“为了更好地将这些行动付诸实施，并最大限度地发挥你的能力，你希望我和学校做些什么呢？”鼓励对方梳理自己需要的资源，为接下来的行动做好准备。\u003c/p>\u003cp>通过“智慧三问”，以对方的立场考虑问题、提出问题、激发思考，才能有效地激活对方的思想和行动力，从而达成工作目标。 这也才是双向的、有效的沟通。\u003c/p>\u003cp>(小结)\u003c/p>\u003cp>最后，总结一下： \u003c/p>\u003cp>主管要就完成某项工作，同下属达成有效的沟通，可以采用“智慧三问”。 这三问分别是——\u003c/p>\u003cp>一问，（启发贡献）“你觉得自己能为公司做出什么样的贡献？”，去激活下属对自己的期望。\u003c/p>\u003cp>二问，（明确行动）“你觉得自己具体可以做些什么，从而实现这种贡献？”，激发下属思考自己的行动。\u003c/p>\u003cp>三问，（询问支持）“为了将自己的知识和技能得到最大限度的发挥，需要我和公司为你提供哪些支持？”，促进下属为采取行动准备资源。\u003c/p>\u003cp>其实这个“智慧三问”不仅可用于主管同下属的沟通， 这个沟通方法也适用于有共同目标的两个人之间的探讨。 祝愿大家都能借助这种沟通方式，收获更好的工作成果和人际关系。\u003c/p>\u003cp>这就是我采用便签学习法就“智慧三问”做的分享，谢谢各位的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1576334592000,"updated_at":1576490861000,"ria":true},{"id":8236,"topic":"学会诊断自己的时间，然后合理管理它","learn_goal":"学会诊断自己的时间，提高自己和团队的效率和成果","remark":"什么重要的事情没做，一天就过去了？\r\n        不管你是初入职场还是资深白领，相信你经常会有这感觉。\r\n        有效的管理者知道,时间是一项限制因素。任何生产程序的产出量,都会受到最稀有资源的制约。而在我们称之为“工作成就”的生产程序里,最稀有的资源,就是时间。时间也是最特殊的一项资源。在其他各项主要资源中,资金项实际上是相当充裕的。我们很久以前就已经了解到,制约经济增长与经济活动的,并不是资金的供给不足,而是对资金的需求不大。\r\n        时间的供给,丝毫没有弹性。不管时间的需求有多大,供给绝不可能增加。时间的供需没有价格可资调节,也无法绘制边际效用曲线。而且,时间稍纵即","level":"TF2-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"许娟","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家晚上好！我叫许娟。今天拆的片段是出自一本书，书名叫《卓有成效的管理者》，接下来我简单介绍一下这本书。&nbsp;\u003c/p>\u003cp>&nbsp;【F（特征）】：这本书作者彼得。德鲁克，是现代管理学之父，这本书从五个重要习惯养成，告诉我们如何使自己成为有效的管理者。\u003c/p>\u003cp>&nbsp;【A（优势）】：相比于其他同类书籍，本书已成为全球管理者必读的经典之作，豆瓣评分8.7。该书被译成37种语言，畅销全球130多个国家。&nbsp;\u003c/p>\u003cp>&nbsp;【B（利益/作用）】：&nbsp;\u003c/p>\u003cp>&nbsp;【B1这本书给学习者带来的好处】 如果你在管理中遇到感觉时间不是自己的，并且按照老套的方法开展工作总是出现各种不同的问题，管理无法更有效，对组织以外的情况不了解的情况时。这本书 不会代替你做出决策，制定方案，但是它会帮你理清思路，从任何新事变中发掘本质，找到它们的历史渊源。&nbsp;\u003c/p>\u003cp>&nbsp;【B2 原文拆页给学习者代来的好处】 是不是经常遇到一种情况，当你正专心写一个方案的时候，总是有其他部门的人来找你沟通一件你认为对你不重要的事，但是他认为 &nbsp;很重要呢？今天这个片段可以教你处理这种情况，让你为最重要的事付出从而得到你期待的结果。\u003c/p>\u003cp>&nbsp;【&nbsp;学习目标】 &nbsp; 具体 可衡量 \r\n跟我完成本次RIA现场学习后，学习者能够通过记录时间和系统管理时间的方法，能够改进各项工作的安排方式。\r\n首先呢我先给我们现场的小伙伴们分各组。（分组）\r\n请大家花1分钟的时间阅读完片段后向我举手示意，我们开始正式的拆书环节。（阅读原文拆页）\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":11853,"quote":"\u003cp>要提高管理理的有效性，第一步就是记录其时间的实际情形。重要的是，必须在处理某一工作的“当时”立即加以记录，而不能事后凭记忆补记。\u003c/p>\u003cp>许多有效的管理者都经常保持这样一份记录，每月定期拿出来检讨。至少，有效的管理者往往以连续三四个星期为一个时段，每天记录，一年内记录两三个时段。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间使用得很乱，浪费在种种小事上。经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免回到浪费的状态上去。\u003c/p>\u003cp>第二步就是要做有系统的时间管理。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以问自己下列几个问题：\u003c/p>\u003cp>1.首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果?”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>然而许多大忙人，天天在做一些他们觉得难以割舍的事，比如应邀讲演、参加宴会、担任委员和列席指导之类，不知占去了他们多少时间，而这些工作，他们本身既不一、感兴趣，做得也根本不够精彩。然而他们得承受这些负担，一年又一年，就像从天而降的灾难一样躲也躲不了。其实，对付这类事情，只要审度一下对于组织有无贡献，对于他人有无贡献，或是对于对方的组织有无贡献。如果都没有，只要谢绝就可以了。\u003c/p>\u003cp>2.第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果?”\u003c/p>\u003cp>多年来在管理方面都在研究授权问题。任何组织，几乎每一位主管人员都接到过上级有关做好授权的指示，而且他们本人也曾屡屡对其下属阐明授权的重要。但是这样的告诫是否产生效果，实在令人怀疑。原因非常简单，只是因为没有完全明了授权的意义。如果认为授权的意思是说：我的工作应由别人来做，那就错了；因为你既然拿了薪水，就该做你自己的工作。又有人认为：充分授权之后，最闲散的经理人便应该是最好的经理人。这样的看法不但荒唐，而且也是不道德的。\u003c/p>\u003cp>3.还有一项是时间浪费的因素，是管理者可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/p>\u003cp>这种现象并不明显，但有一个简单方法可以诊断出来:&nbsp;去问问你的下属。即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。\u003c/p>","explains":"\u003cp>\u003cstrong>I拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What\u003cstrong>】\u003c/strong> &nbsp;\u003c/strong>\u003c/p>\u003cp>这个片段主要讲得是如何记录时间以及记录后如何管理我们的时间。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【\u003c/strong>Why &nbsp;&nbsp;不这么做的坏处\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一般做法：大多数人都不会有刻意记录时间的习惯，认为做过一天的事情应该都知道，但是等你记录后才发现，自我感觉和实际发生的状况会有很大的差别\u003c/strong>\u003c/p>\u003cp>\u003cstrong>很多人也不会去刻意管理时间，往往是发生了什么事情就立马去做什么事情，不分主次\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样的后果是\u003c/strong>\u003cstrong>我们常常是感觉忙了一天，但是最重要的事往往感觉花的时间太少了，结果达不到我们的预期。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【\u003c/strong>反面案例：\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>举个例子。\u003c/strong>我日常开启一天工作的惯例\u003c/p>\u003cp>早上完成工作计划列出清单、部门工作安排部署、写方案，结果临时被其他部门的同事临时打断沟通一个项目的事情。下午又开始写方案、临时被领导叫去开了一个会，会后与部门的2个员工做沟通、并审核月报就下班了，然而清单上还有一项重要的事没有完成，导致部门的下属陪着我一起加班完成后才下班，所以我也听到了一些怨言和不满。由于我没有记录时间的习惯，也没有挑最重要的事来做，也没有适当的授权，让我也很有挫败感。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【\u003c/strong>正确的做法\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>How &nbsp;&nbsp;\u003c/strong>我想日常大家工作中经常遇到这样的情况，那我们看看片段里教给我们的方法，具体步骤如下\u003c/p>\u003cp>第一，如实记录我们的时间使用情况，并且当时立刻记录，不要过后记录。\u003c/p>\u003cp>第二，做好全面条理的时间管理，这里管理时间又分为三个小步骤\u003c/p>\u003cp>（1）看看哪些事情是可以不用做的，无助于成果。比如记录的每件事，你可以问问自己：“这件事如果不做，会有什么后果?”如果觉得“不会有任何影响”，那么这件事就不用做。\u003c/p>\u003cp>（2）哪些事可以别人做。比如哪些事可以授权下属来完成，哪些活动可以由其他人参加同样可以完成成果？\u003c/p>\u003cp>（3）哪些事浪费了别人的时间。比如过度开会，或者工作安排不合理导致效率低下等\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【\u003c/strong>我在学习到这个片段后，我是这么做的：\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>第一，如实记录我一天的工作：\u003c/p>\u003cp>上午 安排部门工作半个小时\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;向领导汇报工作半个小时\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;写方案1小时\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;其他跨部门协调沟通才艺大赛事宜一小时\u003c/p>\u003cp>下午\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;写方案1个半小时\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;开会 1个小时\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;与部门员工A沟通商学院培训方案半个小时\u003c/p>\u003cp>与部门员工B沟通钉钉月报汇总半个小时\u003c/p>\u003cp>下班后\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;审核修改员工A的培训方案1个半小时\u003c/p>\u003cp>每一个时间段完成了哪项工作，并且从开始完成这项工作就记录，到完成这项工作再次记录，依次记录我一天完成的所有工作。\u003c/p>\u003cp>第二，开始做时间管理\u003c/p>\u003cp>时间管理（1）看看哪些事情是可以不用做的，比如 其他部门找我沟通活动策划的事对我部门工作成果是没有影响的，不是一定需要我参与，所以我就从我的工作计划清单中拿掉了，以后类似的事情就直接以现在有其他重要工作完成拒绝了。\u003c/p>\u003cp>时间管理（2）哪些事可以别人做。审核部门2位员工的工作成果，前面几遍都可以交给她们自己检查，我只需要检查一遍，最终目的是保证结果，所以我从我的工作计划清单中拿掉\u003c/p>\u003cp>时间管理（3）哪些事浪费了别人的时间。比如我之前每天会给我们部门的2个下属开工作碰头会或早或晚，每天总结。基本上在半个小时，会耽误他们下班，还耽误他们正常完成工作的时间，所以我改为一周总结2次。\u003c/p>\u003cp>这样坚持一段时间后，我和我部门很少加班，而且感觉工作重心越来越明确，因为我们一直讨论后减少了不少不必要的工作，避免了不必要的时间浪费，并且我也对她们进行了适当的授权。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【\u003c/strong>适用边界】\u003c/strong>\u003c/p>\u003cp>该拆页适合于普通管理者和工作事务比较繁杂的工作者。不太适合，岗位事务固定，计划性很强的工作岗位。\u003c/p>","interaction":"\u003cp>\u003cstrong>A 学习者拆为己用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1显像提问法】\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>过去一周里\u003c/strong>，你的时间管理状况是什么样的呢？比如，周一你在办公室里做了哪些事情，或者你组织一场重大活动，或者周末与家人在一起经历什么事情？请回忆一下，与小伙伴具体分享一下。\u003c/p>\u003cp>请你想一想在过去的一周内，你有没有因为没有做时间管理，比如说上班一天忙到头但是最重要的事情却没有做，或者总是被他人打断效率很低，或者放假了一天无所事事就把时间浪费了，请你回顾那一天的时间你是如何度过的？后果如何？\u003c/p>\u003cp>请大家按照刚刚的分组，讨论时间1分钟。现在开始。\u003c/p>\u003cp>然后我们每组请一位小伙伴分享一下\u003c/p>\u003cp>【学习者案例分享】\u003c/p>\u003cp>讲一个我上周六一天的经历。早上我老婆要去打印室打印一个课题材料，让我陪她一起去，我就随口答应了，我预计最多也就个把小时吧，到了打印店老板说排版估计需要半个小时，所以我就坐在那里等了一会儿，半个小时过去了，老板又说这个有点复杂也有点多可能还需要一会儿，就这样拖一直耽误了2个多小时，而且我在旁边帮不上什么忙，而我自己又做不了自己想做的事，只能边等边看电影，而且也耽误了这一天的其他计划，感觉这一天啥也没干成时间都浪费了，而且原来定的计划全都打乱了，可能这也是因为没有做时间管理的原因吧。\u003c/p>\u003cp>\u003cstrong>【A1+ 学习者反思加工】\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>刚才你们讲的故事里，哪些属于浪费时间，哪些属于授权不够。如果，你回到过去，运用今天的时间管理方法，你会怎么改进呢？\u003c/p>\u003cp>如果回到过去，你想让这一天过得更有意义，或者效率更高吗？如果用今天的时间管理办法，你可以怎么去改进它呢？\u003c/p>\u003cp>同样的,给大家4分钟时间，进行小组讨论一会我会邀请1位伙伴进行分享。\u003c/p>\u003cp>一位小伙伴分享&nbsp;\u003c/p>\u003cp>【学习者案例分享】\u003c/p>\u003cp>如果回到过去，我整理下我的时间分配是这样的：上午陪老婆自己去打印文件路上半小时，等待2小时，这2个小时时间我等的无聊就在看电影，如果按照今天时间管理的方法，其中陪她去打印店是不用做的，因为我过去完全没有帮上忙，所以去打印店打印材料是可以授权我老婆自己做的，看电影等待的时间是浪费的。这样去掉了我不用做的事情，也找到了哪些事是可以我跟我老婆各自独立完成的，并且避免了互相浪费对方的时间，也腾出来了专门的时间我们单独相处，这样的一天会更有意义而且更有效率。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>好的，感谢我们小伙伴的分享，也感谢大家来参加我今天的拆书分享，今天给大家带的关于时间管理的方法相信给你带来了不一样的体验，今天我的拆书课就结束啦，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1561377893000,"updated_at":1561378484000,"ria":true},{"id":7645,"topic":"使用“掌控时间法”提升时间使用效率","learn_goal":"集中精力处理重要事务，提升工作效率","remark":"《卓有成效的管理者》是一本管理经典，作者是现代管理之父彼得·德鲁克。该书从五个维度讲解了如何提升管理者的有效性。这本书由海尔集团董事局主席和首席执行官张瑞敏、中国人民大学商学院教授包政等人推荐作序，豆瓣评分高达8.7分。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"阿风","city":"廊坊"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【技能点】学习目标包含了学习者可被观察到／被测量到的行为或动作。\u003c/p>\u003cp>学习者能够在做事效率低下的情况下（where），通过掌控时间法（澄清），合理规划（行为）自己的时间，高效完成任务（界定）。\u003c/p>\u003cp>【开场】个人介绍和图书介绍\r\n大家好，在我们正式拆书之前，我先做一个简单的自我介绍。我是今天的晋级拆书家王丽风，大家可以叫我阿风。接下来，我用三个标签来介绍自己：家校共育信奉者、英语启蒙领域创业者和旅游爱好者。&nbsp;\u003c/p>\u003cp>在拆书之前，我先给大家分一下组。左手边小伙伴一组，右手边小伙伴一组。&nbsp;\u003c/p>\u003cp>【F】特征：《卓有成效的管理者》是一本管理经典，作者是现代管理之父彼得·德鲁克。该书从五个维度讲解了如何提升管理者的有效性。\r\n【A】优势：这本书由海尔集团董事局主席和首席执行官张瑞敏、中国人民大学商学院教授包政等人推荐作序，豆瓣评分高达8.7分。\r\n【B】利益：\r\nB1：一群平凡人，能做出不平凡的事业吗？这是完全可以做到的。只要组织中的每一个人都能做到卓有成效。卓有成效可以学会吗？可以学会。《卓有成效的管理者》这本书就可以教会我们。\r\nB2：你是不是感觉一天总是忙忙碌碌，却没有什么成效，今天的拆页可以帮助你学会掌控时间法，合理规划自己的时间，从而高效完成任务。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":11134,"quote":"\u003cp>下面我给大家发一篇这本书的一张拆页，请大家仔细阅读，阅读完毕之后，请举手示意我。时间为1分钟。\u003c/p>\u003cp>\u003cstrong>【技能点】【\u003c/strong>\u003cstrong>R\u003c/strong>\u003cstrong>】所选拆页，包括\u003c/strong>\u003cstrong>how\u003c/strong>\u003cstrong>的内容；且总内容未超过\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>页图书内页\u003c/strong>\u003c/p>\u003cp>关于管理者任务的讨论，一般都从如何做计划说起。这样看来很合乎逻辑。可惜的是管理者的工作计划，很少真正发生作用。计划通常只是纸上谈兵，或只是良好的意愿而已，很少能够真正实现。\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方オ是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\u003c/p>\u003cp>•记录时间；\u003c/p>\u003cp>•管理时间；\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;•统一安排时间。\u003c/p>","explains":"\u003cp>时间到了，大家都看完了吧！好，下面我来和大家分享一下我对这段话的理解。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>：拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>时间都去哪儿了？你是不是也常有这样的感慨，时间匆匆如流水，人生一去不复回。如何充分利用有限的时间，实现自己的人生价值呢？\u003c/p>\u003cp>（what）原文拆页介绍了掌控时间的三个步骤。\u003c/p>\u003cp>（why）\u003cstrong>(\u003c/strong>\u003cstrong>不这么做的坏处\u003c/strong>\u003cstrong>)\u003c/strong>\u003cstrong>：\u003c/strong>每个人的一天都是24小时。除去三四个小时的吃饭时间，七八个小时的睡觉时间，每天可支配的时间达十二三个小时，可是我们总觉得时间不够用，忙乱了一天却没有什么成果。\u003c/p>\u003cp>举例：上周一，我开始筹备工作室事宜，可是到上周五的时候我才发现，自己的教案一个没写，房子也没找，教具什么的也没准备，家里呢！孩子也没怎么管，饭也没做。我不禁怀疑，我的时间都去哪儿了？ \u003c/p>\u003cp>（how）如何才能掌握好自己的时间呢？\u003c/p>\u003cp>1.记录时间。在一天开始时，用纸笔或手机，在处理每一工作的“当时”立即记录时间耗用的实际情形，连续记录一段时间，可以是三五天，也可以是三四个星期。\u003c/p>\u003cp>2.管理时间。在记录中找出不会产生成果的、浪费时间的活动，然后尽可能将这类活动从时间表上删除。\u003c/p>\u003cp>3.统一安排时间。将可自行支配的零碎时间集中起来，用以处理真正重大的事务。\u003c/p>\u003cp>&nbsp;如果再回到上周，我运用原文的办法即可这样做，在早起时即用纸笔记录自己一天的时间：7:00起床，7:00-7:30洗漱，7:30-8:30:陪儿子，8：30-9：00送儿子上学，9：00-10：00吃饭，10：00-11：30刷手机群、聊微信、写稿子，11：30—4：00吃饭哄老二，14：00-16：30睡觉、看手机，16：30-22：00接儿子、吃饭、陪儿子……(记录时间)，其中长时间刷微信群和朋友圈对我的工作和生活并没有什么益处，可以删除(管理时间)，最后把上午10:00-11:30的时间集中用于重要事务，如写教案、写预备稿等，下午的时间则用于处理零碎事情，如回复消息、网上购物等（统一安排时间）。这样每天一个半小时，至少能解决自己一个重要的事情，一周下来教案或预备稿至少也可以写好两篇了。\u003c/p>\u003cp>\u003cstrong>【预防异议】：\u003c/strong>听完后是不是觉得太麻烦了，我也觉得是。事实上，我们并不需要天天这么做。如果你的活动比较规律，记录两天就会发现时间都用在了什么地方。反之，如果不这么做会更麻烦，因为我们根本不知道自己的时间都去哪儿了，每天都在原地打转。总之，虽然麻烦，但是值得。有的小伙伴可能会说，我根本没法做到大段的时间不拿手机，万一有个重要客户找我呢！其实我们有点高估了自己及时回复的重要性，总统都无法做到事事及时回复，也没产生无法挽回的影响，我们会损失多少呢？而且，自己时间安排好了，可以提前告知重要客户，客户也好提前安排自己的时间与你沟通，沟通效率反而可能提高不少呢！\u003c/p>\u003cp>\u003cstrong>【好处】\u003c/strong>：通过不断练习这种方法，我们不仅会清楚自己的时间用在了什么地方，更重要的是，我们会把更多的时间用于正确的事情上。随着时间的积累，我们可能就会成为下一个斜杠青年。\u003c/p>\u003cp>（where）掌控时间法适用于迫切想要改变现状，追求效率和成果却总觉得时间不够用的个人，而对于追求慢生活的退休人员、坐月子的妈妈等，则不适用。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>\u003cstrong>【技能点】【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong>【分步催化应用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分步催化\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>：\u003c/strong>好了，我的讲解或许对你如何安排工作或生活有所启发，接下来，请跟我一起穿越到未来的一天。新的一天开始了，像往常一样，你开始了忙碌的一天，如果你是宝妈，你可能是这样的，穿衣服起床——准备早饭——叫孩子起床——送孩子上学……，或者你是上班族，你早起吃饭——坐公交或者开车——打开电脑准备工作……，你想象自己身上随时带着纸和笔，你做一项记一项，等到晚上该上床睡觉的时候，你的纸上都记录了哪些内容呢？注意，记录时请不要忘记那些看似不起眼，实际一天下来总计耗时比较多却无任何成果的项目，比如刷抖音、微信等。请大家用2分钟的时间想一下，把一天规律的活动和所用时间写在便签纸上。\u003c/p>\u003cp>\u003cstrong>分步催化\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>：\u003c/strong>接下来，我们看一下，上述事项中，哪些事情根本不必做，哪些事情可由别人做，哪些事情浪费了自己和别人的时间？请大家删掉不必要的以及不会产生成果的活动。最后，请大家用2分钟规划一下，未来如何集中自己可支配的时间处理剩下的重要事务，然后写在便签上。\u003c/p>\u003cp>时间到，请这位小伙伴分享一下他的案例。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>学习者案例记录（逐字稿）\u003c/p>\u003cp>分享者：黄英\u003c/p>\u003cp>记录时间：早上6:50-8:00 &nbsp; 起床，送孩子上学，8:00-9:00，吃早餐，收拾屋子刷朋友圈，9:00-11:00学英语，回微信，11：00-12：00发朋友圈，12：00-13：00午餐刷朋友圈，13：00-15：00陪孩子睡觉听音频书刷朋友圈，15：00-16：30学培训课，16：30-21：00陪娃，21：00-22：00点评代理朋友圈，内部培训，22：00-23：30洗漱睡觉看手机\u003c/p>\u003cp>管理时间：删除早、中、晚每次半小时的刷朋友圈\u003c/p>\u003cp>统一安排时间：6:50-8:00 &nbsp; 起床，送孩子上学，8:00-9:00，吃早餐，收拾屋子，9：00-10：00学习英语，10：00-12：00，学培训课，12：00-13：00午餐，13：00-15：00陪孩子睡觉听音频书，15：00-16：30学培训课，16：30-21：00陪娃，21：00-22：00点评代理朋友圈，内部培训，22：00-23：30洗漱睡觉看书\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>非常感谢小伙伴的分享。\u003c/p>\u003cp>每个人的一天都是24小时，除了必要的吃饭、睡觉时间，如果通过本文的掌控时间法，不断删除不必要的事务，我们就会花越来越多的时间用于正确的事情上。反之，时间利用率低下，则每天都会陷入焦头烂额的状态。希望大家以后能多多练习今天学到的掌控时间法，轻松掌控自己的工作和生活。\u003c/p>\u003cp>我今天的拆书到此结束，谢谢大家。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1555388751000,"updated_at":1556605565000,"ria":true},{"id":6729,"topic":"如何诊断自己的时间？","learn_goal":"学习运用画图—记录—分析涂色的方法帮助自己记录并分析时间","remark":"","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"陈慧卉","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"我是陈慧，我用3个标签介绍自己：一是二十四节气推广者，二是职业生涯规划讲师，三是小源流插花爱好者。很开心今天进行我TF2-1的拆书。\r\n图书介绍 \r\n今天我要给大家分享的内容来自这本书《卓有成效的管理者》。\r\n【F】这本书的作者是彼得.德鲁克，是一位著名的管理学家，书中重点阐述了成为一个卓有成效管理者的五项要素，包括：善用时间、关注结果、善用人才、要事第一、有效决策。\r\n【A】本书被誉为是启蒙中国现代管理第一书，是终生受用的案头必读书。相比市场上其他管理类书籍的定位，本书从每一个普通人出发，倡导每一个普通人也可以像管理者一样工作和思考。相对其他书籍的晦涩，本书更接地气，里面用了大量现实生活中的案例来诠释思想。\r\n【B】有没有觉得自己每天都很忙，但又没做成什么事？做事情杂乱无章，不知该如何安排？工作交给他人，又不知道给谁？本书从掌握自己的时间，怎样处理事情有效，如何选拔人才到怎样进行决策，用生动真实的故事与策略结合，有趣易懂可操作！而今天我要分享的这个片段，学习用画图—-记录—-分析涂色的方法帮助你记录并分析时间的使用情况，从而提高做事的效率。","ratings_count":1,"texts":[{"id":10078,"quote":"\u003cp>【R 阅读原文】拆页来自彼得.德鲁克《卓有成效的管理》掌握自己的时间之如何诊断自己的时间P34-36节选\u003c/p>\u003cp>要提高管理的有效性，第一步就是记录其时间的实际情形。重要的是，必须在处理某一工作的“当时”立即加以记录，而不能事后凭记忆补记。\u003c/p>\u003cp>许多有效的管理者都经常保持这样一份记录，每月定期拿出来检讨。至少，有效的管理者往往以连续三四个星期为一个时段，每天记录，一年内记录两三个时段。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间使用得很乱，浪费在种种小事上。经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免回到浪费的状态上去。\u003c/p>\u003cp>第二步就是要做有系统的时间管理。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以问自己下列几个问题：\u003c/p>\u003cp>1.首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果?”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>然而许多大忙人，天天在做一些他们觉得难以割舍的事，比如应邀讲演、参加宴会、担任委员和列席指导之类，不知占去了他们多少时间，而这些工作，他们本身既不一、感兴趣，做得也根本不够精彩。然而他们得承受这些负担，一年又一年，就像从天而降的灾难一样躲也躲不了。其实，对付这类事情，只要审度一下对于组织有无贡献，对于他人有无贡献，或是对于对方的组织有无贡献。如果都没有，只要谢绝就可以了。\u003c/p>\u003cp>2.第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果?”\u003c/p>\u003cp>“授权”这个名词，通常都被人误解了，甚至是被人曲解了。这个名词的意义，应该是把可由别人做的事情交付给别人，这样才能做真正应由自己做的事-----这才是有效性的一大改进。\u003c/p>\u003cp>3.还有一项是时间浪费的因素，是管理者可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/p>\u003cp>这种现象并不明显，但有一个简单方法可以诊断出来:&nbsp;去问问你的下属。即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。\u003c/p>\u003cp>事实上，一位管理者大刀阔斧减少不必要的工作，绝不会有太大的风险。人总有一种倾向，高估自己地位的重要性，认为许多事非躬亲不可。纵然是最有效的管理者，仍然免不了有许多不必要的和生产性的工作。\u003c/p>","explains":"\u003cp>好，大家都阅读完了本片段，这个拆页列举出了如何诊断自己时间的两个步骤及三个问题；是管理者对时间进行“实时”记录，以确保记录的准确性及做系统的时间管理，将不产生效益的和浪费时间的活动找出来。\u003c/p>\u003cp>为什么要记录和诊断自己的时间？记录时间耗用的实际情况，是磨刀不误砍柴工，记录后你会更明白时间的利用率。通过分析，我们能知道事情有可以不做的，有可以分派的，有必须做的。意识到事情有这几类，我们便能管理好时间。\u003c/p>\u003cp>负面一般的做法：\u003c/p>\u003cp>信息爆炸的时代，工作节奏的加快，我们每天都有做不完的事情，越来越多的人焦虑与没完没了的工作和时间都去哪了。当大量的工作来袭，如果你没有进行分析而是一股脑的接收了，那么所有的工作都会压在你身上，你将饱受工作的负荷而无法脱身。\u003c/p>\u003cp>这样做的坏处：\u003c/p>\u003cp>&nbsp; 为了完成这些工作，你可能会花大量的时间加班加点；你也可能因为工作牺牲掉个人自由时间；过度的工作可能会让你身心俱疲，影响你的工作效率和幸福指数。&nbsp;\u003c/p>\u003cp>【负面例子】\u003c/p>\u003cp>我作为学校德育部门的管理者，记录了自己一天时间耗用情形：\u003c/p>\u003cp>7:30--8:00 校门口值日\u003c/p>\u003cp>8：10——9:00语文组长邀请听教研课、交流\u003c/p>\u003cp>9:00---9:30工会主席邀请陪同接待工会考察\u003c/p>\u003cp>9：30--10:0 检查全校大课间\u003c/p>\u003cp>10：00--11:30 数学组长邀请参加数学教研组会议并发言\u003c/p>\u003cp>下课时间巡查学生课间活动情况并进行记录\u003c/p>\u003cp>13：00--14：00优化下午班主任培训的PPT\u003c/p>\u003cp>14:30--16:30 组织班主任老师培训\u003c/p>\u003cp>17:00--17:30 校门口值日\u003c/p>\u003cp>整天忙忙碌碌，总有处理不完的事情，连午休的时间都占用了，还经常加班。\u003c/p>\u003cp>【拆页行动建议】\u003c/p>\u003cp>如果你也是如此情形，那么要考虑换种方式来看待你的工作了，是完全由自己一个人来完成呢？还是有什么新方法？为了更高效的完成工作，我们有必要分析目前的工作任务，按照下面的三个步骤进行：\u003c/p>\u003cp>\u003cstrong>第一步：画图。\u003c/strong>画出每格为半小时的条状图。\u003c/p>\u003cp>8:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 9:00&nbsp;&nbsp;&nbsp;&nbsp; 10:00&nbsp;&nbsp;&nbsp;&nbsp; 11:00&nbsp;&nbsp;&nbsp;&nbsp; 12:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 14:00&nbsp;&nbsp;&nbsp;&nbsp; 15:00&nbsp;&nbsp;&nbsp;&nbsp; 16:00 &nbsp;\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>第二步：记录。\u003c/strong>将自己时间耗用情况如实记录。\u003c/p>\u003cp>7:30 8:00 &nbsp;9:00 9:30 10:00 &nbsp;11:30 13:0014:30 &nbsp; &nbsp; &nbsp; 16:30 17:0017:30&nbsp;\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>早上校门口值日\u003c/p>\u003c/td>\u003ctd>\u003cp>语文课\u003c/p>\u003c/td>\u003ctd>\u003cp>语文课\u003c/p>\u003c/td>\u003ctd>\u003cp>工会接待\u003c/p>\u003c/td>\u003ctd>\u003cp>大课间\u003c/p>\u003c/td>\u003ctd>\u003cp>数学会议组\u003c/p>\u003c/td>\u003ctd>\u003cp>数学组会议\u003c/p>\u003c/td>\u003ctd>\u003cp>数学组会议\u003c/p>\u003c/td>\u003ctd>\u003cp>优化培训 PPT\u003c/p>\u003c/td>\u003ctd>\u003cp>班主任培训\u003c/p>\u003c/td>\u003ctd>\u003cp>班主任培训\u003c/p>\u003c/td>\u003ctd>\u003cp>班主任培训\u003c/p>\u003c/td>\u003ctd>\u003cp>班主任培训\u003c/p>\u003c/td>\u003ctd>\u003cp>下课时间巡查\u003c/p>\u003c/td>\u003ctd>\u003cp>放学值守校门口\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>&nbsp; 第三步：分析涂色。\u003c/strong>\u003c/p>\u003cp>1. 放弃或拒绝---红色。找出浪费和被浪费的时间。找出哪些事情可以不做，“如果这件事情不做，也不会有任何后果”，那么就可以放弃；找出浪费别人的时间又不产生效果的事情，这个可以问问你的下属，用红色表示。还是用我刚才讲的一天来举例子。比如：听语文教研课，陪同接待工会考察，参加数学教研组会议并发言，这些事我不做，不会有什么后果，因为我是德育主任，不是教研主任，也不是工会主席，既不教语文，也不教数学。所以，涂红色。\u003c/p>\u003cp>2.分派---蓝色。找出哪些事情可以由别人来做，用蓝色表示。比如：我的一天工作中，优化班主任培训PPT这件事情是可以让下属做的事，而且他会做得很好。所以，涂蓝色。\u003c/p>\u003cp>3.必须做---绿色。哪些事情是必须自己做的，用绿色表示。比如：校门口值日，在下课时间巡查学生课间活动，检查全校大课间，组织班主任老师培训这是我必须要做的事情，因为这是我作为德育主任和值日行政的职责所在。\u003c/p>\u003cp>对时间诊断的这个方法不仅仅用于管理者，员工、妈妈、爸爸等身份都可以用。当然，你的工作是固定而且必须做的，这个方法就不适用了，比如，高速公路的收费员、银行窗口坐柜台的，只能坐在那个位置上干活，工作性质决定你没有分派和调整的时间.这个方法不光工作中可用，生活中也可用。\u003c/p>","interaction":"\u003cp>【A1显像提问】&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>拆书家：经过刚才对拆页片断的学习，小伙伴试想下在自己的生活和工作中，平常有觉得时间不够用的情形吗？在你忙得焦头烂额，情绪暴涨，甚至非常愤怒的时候，在你临要下班时，又接到同事递过来的文件，你是否意识到你的时间不够用，你是否对你的时间进行过诊断？请在场的小伙伴试想下过往经历中是否有因为没有对时间进行分析和诊断而感到时间不够用的情况，给大家2分钟在小组内讨论，等下我会请一位小伙伴分享。我们分下组，左边一组右边一组。\u003c/p>\u003cp>苏苏分享：\u003c/p>\u003cp>昨晚，要做一个开营PPT，先和别人聊了两小时的天，从晚上9点多才开始做，期间还点了烧烤，做到凌晨1点，这样耽误了睡眠。\u003c/p>\u003cp>非常感谢苏苏给我们阐述了她的时间使用情况。\u003c/p>\u003cp>【A1+反思加工】&nbsp;&nbsp;\u003c/p>\u003cp>拆书家提问设计\u003c/p>\u003cp>拆书家：如果有时光机，回到当时焦虑的情景，请你用今天所学的方法来做时间分析和诊断，你会怎么做呢？现在用3分钟的时间组内讨论。\u003c/p>\u003cp>苏苏的分享\u003c/p>\u003cp>17:00 18:00 19:00 &nbsp;20:00 &nbsp; 21:00 &nbsp;22:00 &nbsp; &nbsp;23:00 &nbsp; &nbsp;24:00 &nbsp; &nbsp;1:00\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>吃饭\u003c/p>\u003c/td>\u003ctd>\u003cp>吃饭\u003c/p>\u003c/td>\u003ctd>\u003cp>吃饭\u003c/p>\u003c/td>\u003ctd>\u003cp>回家路上\u003c/p>\u003c/td>\u003ctd>\u003cp>开会\u003c/p>\u003c/td>\u003ctd>\u003cp>微信聊天\u003c/p>\u003c/td>\u003ctd>\u003cp>微信聊天\u003c/p>\u003c/td>\u003ctd>\u003cp>微信聊天\u003c/p>\u003c/td>\u003ctd>\u003cp>微信聊天\u003c/p>\u003c/td>\u003ctd>\u003cp>做ppt\u003c/p>\u003c/td>\u003ctd>\u003cp>做ppt\u003c/p>\u003c/td>\u003ctd>\u003cp>做ppt\u003c/p>\u003c/td>\u003ctd>\u003cp>做ppt\u003c/p>\u003c/td>\u003ctd>\u003cp>做ppt\u003c/p>\u003c/td>\u003ctd>\u003cp>做ppt\u003c/p>\u003c/td>\u003ctd>\u003cp>做pp&nbsp;\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cbr>谢谢苏苏的分享，她分享的案例非常契合我们今天的学习主题，用画图—-记录—-分析涂色的方法诊断自己的时间，也希望今天学习的诊断自己时间的方法，能为大家提高工作效率。今天我的分享到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1544432834000,"updated_at":1544432834000,"ria":true},{"id":6482,"topic":"如何运用三步法表达反面意见？","learn_goal":"在他人提出观点或方案时，通过回应三步法，确定目的，多角度思考","remark":"回应他人是一种美德，但如果应用不当，容易被别误解为没想法或者爱挑刺，那么如何回应他人，能让对方更容易接受，使沟通更有效果呢？今天的我们要拆的这本书《卓有成效的管理者》，是一本管理类的经典书籍，通过管理学体系辅以丰富的案例，引导我们进行自我管理与思考！","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"绚绚","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家好，我叫绚绚，我的三个标签是项目管理工程师、拆书家和阅读爱好者。为了方便稍后的拆书过程中的分享交流，先为大家分组（每组3到6人）。&nbsp;\u003c/p>\u003cp>【事件场景】前几周部门例会上，我们需要做出一个决策，有同事提出了一个方案，我不是很认同，于是据理力争，说他的方案哪里哪里不好，导致会议上很长时间都是我们的争论，影响了会议的进度，最后也没有出结果。&nbsp;\u003c/p>\u003cp>【提问】如果别人提出一个方案，你每次都说好，对方会怎么想？（可能觉得你没想法）如果你每次都反对，对方又会怎么想？（可能觉得你挑刺）\r\n你说，那我学个乖，我换着来，有时同意，有时反对，那情况会发生什么变化呢？如果是你，你会因为他上次反对你，这次同意你，就觉得他的同意是有价值的，客观的吗？（不会）&nbsp;\u003c/p>\u003cp>【影响】所以，如果我们只是做出自己以为正确的回应，不去思考回应带来的结果，可能会人缘变差，变得可有可无，不受重视，前景堪忧，而自己却不清楚原因。&nbsp;\u003c/p>\u003cp>【解决】回应他人是一种美德，但如果应用不当，容易被别误解为没想法或者爱挑刺，那么如何回应他人，能让对方更容易接受，使沟通更有效果呢？今天的我们要拆的这本书《卓有成效的管理者》，是一本管理类的经典书籍，通过管理学体系辅以丰富的案例，引导我们进行自我管理与思考！今天的拆页学习，将教会学习者在他人提出方案时，通过回应三步法，确定目的，多角度思考问题，并提出替代方案。\r\n接下来给大家1分钟的时间阅读一下拆页，阅读完的伙伴请抬头示意我一下。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9793,"quote":"\u003cp>为什么该有反面意见,主要有三项理由。\u003c/p>\u003cp>第一,唯有反面意见,才能保护决策者不致沦为组织的俘虏。在一个组织中,所有人都必有求于决策者,每个人都各有所求,都希望主管的决策能对自己有利。上至美国总统如此,下至企业机构中一位初级工程师修改某一工程设计也是如此。\u003c/p>\u003cp>唯一能突破这一陷阱,使决策者不致成为某方面的俘虏的办法,就在于引起争辩、掌握实据和经过深思熟虑的反面意见。\u003c/p>\u003cp>第二,反面意见本身,正是决策所需的“另一方案”。决策时只有一种方案,别无其他选择,那与赌博何异?只有一种方案,失败的机会必高。也许是这决策打从开始就错了,也许是其后因情况变化而使决策错了,如果在决策过程中原有若千方案可供选择,则决策者进可攻、退可守,有多方思考和比较的余地。反之,舍此以外别无他途,决策人在遇到该决策行不通的时候,就只有背水一战了。\u003c/p>\u003cp>1914年德国的舒利芬战略计划。原来的计划到了应该发生效果的紧要关头,忽然发生了变化。\u003c/p>\u003cp>先说德军的作战计划,到头来走不通了,德军始终没有第二套战略方案。所以只好痛苦地撑持下去,走一步改一步。这实在是无可奈何的不幸。实际上前后25年,德军参谋本部从来没有想到增拟另一套计划。参谋本部的力量,全部耗用在研究舒利芬计划的细节上了。\u003c/p>\u003cp>等到舒利芬计划失败时,再也找不出第二条可行之路了。德军所有将领虽然都受过严格的战略训练,可是在那种情况下也只有随机应变。换言之,他们只能时而向东,时而向西,始终不明白到底是为了什么。\u003c/p>\u003cp>最后第三个理由,是反面意见可以激发想象力。当然,纯粹为了某一问题去找答案,并不一定非有想象力不可只有解决数学问题才最需要想象力。但是一位管理者处理问题时,不管是政治、经济、社会,还是军事,通常总是“不确定性”极高,就需要有“创造性”的解决方案,来开创新的局面。这就是说,我们需要想象力,因为缺乏想象力的管理者不可能从另一个不同的全新的角度去观察和理解。\u003c/p>\u003cp>我得承认,有丰富想象力的人并不是太多,但他们也不像人们认为的那么稀少。想象力需要被激发后才能充分发挥出来,否则它只能是一种潜在的、尚未开发的能力。不同意见,特别是那些经过缜密推断和反复思考的、论据充分的不同意见,便是激发想象力的最为有效的因素。\u003c/p>","explains":"\u003cp>【what&amp;概念对比】\u003c/p>\u003cp>拆页中讲到了为什么要运用反面意见，这里我们来讲一下，什么叫做反面意见。反面意见就是字面上的意思，指不同的意见。\u003c/p>\u003cp>很多人容易把反面意见和反对意见混淆，反对意见，是我觉得你的方案不行，更关注于事件的困难点，而不是如何去解决。\u003c/p>\u003cp>我这里给大家举几个例子，大家就能明白两者的区别了：\u003c/p>\u003cp>比如说，领导想安排你去校园招聘，你因为手上事情多，就提出拒绝，这是反面意见吗？（停2s）不是，因为没有关注目的，只关注困难点，这是反对意见。\u003c/p>\u003cp>比如说，领导想安排你去校园招聘，你知道他想把你往管理层方向培养，但你只想专心搞技术，于是建议领导让其他同事来做这个事情，这是反面意见吗？（停2s）不是，因为并没有改变事件的角度，只是表达了你对一个事情的否定，所以还是反对意见。\u003c/p>\u003cp>领导想安排你去校园招聘，你知道他想把你往管理层方向培养，但你只想专心搞技术，所以你提出线上招聘这个明显不可行的方案，这是反面意见吗？（停2s）不是，因为你并没有真正思考出可行的方案，只是想把这个事情推掉，这还是反对意见。\u003c/p>\u003cp>如果说领导想安排你去校园招聘，你知道他想把你往管理层方向培养，但你只想专心搞技术，于是你从资源合理分配的角度，推荐另一位更适合的同事去校招，领导也开始认真思考你的说法，这个才是反面意见。\u003c/p>\u003cp>所以我们可以很容易知道，反面意见要在关注目的的基础上，从不同的角度，提出有价值的方案。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>因此，当我们很认真的想要回应他人，并且不想让ta觉得我们是没想法或者爱挑刺时，我们可以采取以下三个步骤来表达我们的反面意见，让他人认同我们的想法。\u003c/p>\u003cp>【HOW加工步骤】具体怎么做呢？我为大家总结了回应的三个步骤：\u003c/p>\u003cp>一、回应时先跟对方确认目的\u003c/p>\u003cp>当他人跟你说一个方案，希望你提出意见时，你要先思考他的目的是什么，可以先猜测，并寻求解答，“听完你刚才的话，想跟你确认下，你的目的是……对吗？”或者直接提出询问，“在我说出我的想法之前，能不能先问一下你的目的是什么？”\u003c/p>\u003cp>二、从一个新的角度去观察和理解\u003c/p>\u003cp>一般是对立面、特殊情况，或者是从他人的角度，可以思考以下几个问题：\u003c/p>\u003cp>“如果不做，可能会发生什么” “如果发生了意外，可以怎么改进？”或者“如果是其他人，他们会怎么想？”\u003c/p>\u003cp>三、提供一个方案备选\u003c/p>\u003cp>根据我们前面确定的目的和角度，提出一个备用方案，这个方案考虑到一些前面没有考虑到的点，能让对方在做出选择的同时权衡利弊。\u003c/p>\u003cp>“我觉得如果你的目的是，按照之前的做法，如果遇到XX意外无法成行，是否可以考虑把XX作为备用方案？”“我觉得如果你的目的是，从老板的角度，他可能会更注重XX，我们是否可以考虑XX方案，并将两个方案优劣列出来，请老板评估？”等，这样也可以引导对方思考其他更多的可能性。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>为了帮助大家进一步理解这三个步骤，举个发生在我身上的例子，双十一快到了，我的闺蜜又在纠结买买买的事情了，前几天她看中了一套护肤品，说打了好多折扣，都已经快准备付款了，还要问我的意见，按照以往的经验，我知道自己是拦不住她的，即使我跟她说不要买，她还是会买。但这次，我尝试了前面我们学到的三步骤，我问她说，“英啊，你买护肤品希望皮肤变更好吧”，不意外的得到了肯定的答复。“但你现在买这套护肤品的原因是因为它降价了，而不是因为现在需要，你前两个月在香港买的护肤品还剩下很多，如果这套护肤品还没拆封，又有新的护肤品打折，你会怎么做？”英已经无话可说了，显然她已经想到自己可能的做法了，于是我又说“你觉得是否可以过几天再买呢？也许到时候你会对其他护肤品动心也说不定。”最后结果是，她采纳了我的意见，还谢谢我帮忙拉回了她的理智，我觉得很有成就感。\u003c/p>","interaction":"\u003cp>【A2】催化应用\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>有一个关于学习的研究成果，在大脑中过一遍，等于实际应用了一遍。\u003c/p>\u003cp>接下来请大家摇身一变成为金牌编剧，请发挥想象力编一个剧本，剧本的主题是：\u003c/p>\u003cp>在未来一个月里，你可能在什么场景下需要运用反面意见:\u003c/p>\u003cp>可能是朋友要做一个决策，或者是领导给你分配任务，也有可能是同事/家人就某个事情找你讨论……\u003c/p>\u003cp>你应用了刚才我分享的三个步骤去回应他，请大家设想一下那个场景，花2分钟讨论，1分钟写下关键字（需包含场景发生的具体时间、地点、人物、对话过程）。待会请一位小伙伴上来分享。（3分钟）。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>时间： 这个周末\u003c/p>\u003cp>地点： 逛街\u003c/p>\u003cp>人物： 莫念和他的朋友\u003c/p>\u003cp>背景： 朋友在创业，一天和女朋友去逛街看到一辆车，50万，是自己很喜欢的车，两个人都很想买。\u003c/p>\u003cp>对话过程：\u003c/p>\u003cp>莫念：你为什么想买这辆车？（确认目的）\u003c/p>\u003cp>朋友：我女朋友喜欢这款车，我从小就喜欢这款车。我现在买得起，而且贷款利息又不高，我就想买。\u003c/p>\u003cp>莫念：你买这辆车就是为了面子吗？（进一步确认目的）\u003c/p>\u003cp>朋友：可能不是，主要是我想那么久了啊，带有面子的成分。\u003c/p>\u003cp>莫念：你觉得拿这笔钱可以做其他什么事情？（考虑新的角度）\u003c/p>\u003cp>朋友：可以开拓新业务，可以用来提升自己等。\u003c/p>\u003cp>莫念：我觉得你当前把钱花在提升客户质量上，帮助会更大，你客户不会因为你开个特别好的车就跟你做生意的。（从客户的角度）\u003c/p>\u003cp>朋友：好像有点道理。\u003c/p>\u003cp>莫念：所以我觉得你可以先不买这辆车，租车或借车或买辆便宜的代步车会是更好的选择，你觉得呢？\u003c/p>\u003cp>朋友：确实。\u003c/p>\u003cp>【拆书家反馈点评】\u003c/p>\u003cp>感谢莫念的分享，他运用了回应三步法，首先，确定了朋友买车的目的后，从朋友客户的角度思考了问题，最后，提出了租车或借车或买辆便宜的代步车的选择。通过这样的做法，说服了朋友先不买50万的车。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>每个人思考问题都会有片面的时刻，多运用反面意见，将一件事情从两个方向看待，就相当于考虑了两件事情，只要这样才能对事情有更深层次的理解，也才能更好的应对各种突发状况。今天分享给大家的“回应三步法”能帮助你们更好的运用反面意见，大家不妨多试试。我的拆书到此结束，谢谢大家的倾听！&nbsp;\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1542200153000,"updated_at":1542200203000,"ria":true},{"id":6424,"topic":"三问法排除浪费时间的内容","learn_goal":"学习用三问法将自已一天当时的事务里把浪费时间的活动找出来，并","remark":"彼得•德鲁克《卓有成效的管理者》，它是德鲁克最著名的管理学著作之一这本书主要是论述了职场人如何做到卓有成效。","level":"TF1-2","duration":15,"status":29,"type":0,"chaishujia":{"username":"上好佳","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"大家好，我的名字叫：王佳，我在群里英文名字：欧若拉。来到杭州有三年了，培训出身，群里出了名的“孩子王”。我2018的目标是想成为一名榜上有名的拆书家。今天我给大家带来的片段来自彼得•德鲁克《卓有成效的管理者》，它是德鲁克最著名的管理学著作之一这本书主要是论述了职场人如何做到卓有成效。\r\n今天我们的学习目标是：让我们学着将自已一天当时的事务里把浪费时间的活动找出来，并尝试将这类活动从时间表上排除出去。","ratings_count":1,"texts":[{"id":9729,"quote":"\u003cp>（管理者）要做系统的时间管理。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以试问自己下列几个问题。\u003c/p>\u003cp>1、首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录表拿出来，逐项逐项地问：“这件事如果不做，会朋什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>2、第二个该问的问题是：“时间记录表上的哪些活动可以由别人代为参加而又不影响效果？”\u003c/p>\u003cp>3、还有一项浪费时间的因素，是管理者自己可以控制并且可以消除的。这项因素是：管理者在浪费别人的时间。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>好的，时间到了，看到大家都看完了。下面我将用2分钟用自已的话重述原文知识，也就是I部分的讲解。时间管理的重要性我们不必多说，这里德鲁克给出了管理者管理时间的3个办法。在每天中以小时为单位记录工作时间的记录表中：\u003c/p>\u003cp>1、第一问：“对每一条依次提问：这件事如果不做，会有什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>2、第二问：“这件事可以由别人代为参加吗？”\u003c/p>\u003cp>3、第三问：“这件事有没有浪费别人的时间。”\u003c/p>\u003cp>讲一件我的反面案例：我是一家企业的总裁助理，上一周，因为一款产品的推动在进度上过慢，我便自己动手设计了一张产品海报，现在想来，这就是浪费了我自已的时间，如果不做，而是汇报进度时提醒平面设计部及时提交会更好的；这是第一问教会我的，如果我不做也是会有人专门去做这项工作，我太着急了，所以，以后类似这些他人的工作我今后会尽量不做，而是以提醒和指导为主。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>现场分组：首先请大家两人一组，我们现场拆书与您自己使用RIA略有不同，您无需读过这本书，只需要跟着接下来的步骤我们一同来参与即可。\u003c/p>\u003cp>激活经验：从过去选一个对你来说比较典型的工作日。在我发的纸张的下半部分的表格里写下这一天你都做了些什么。要稍微具体些，比如不能只写“开会“，要写明会议内容。（约2分钟）\u003c/p>\u003cp>请每组人员一对一分享，拿着对方的时间记录表，每一项问德鲁克曾建议的问题。“这件事如果不做，会有什么后果？“”这件事可以由别人代为参加吗？“”这件事有没有浪费别人的时间？“（约3分钟）\u003c/p>\u003cp>现场学习者分享：分享结束了，请问现场有哪位小伙伴愿意分享一下感觉，学习者橘子分享了她的上周一的一个工作日做的事情（橘子一家互联网企业的人事经理）\u003c/p>\u003cp>早上9：00—10：00召开部门周例会（上周总结及本周计划）；\u003c/p>\u003cp>11：00—11：50帮助其它部门处理人员矛盾；\u003c/p>\u003cp>下午13：00—15：00制定下半年公司人员招聘计划；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 16：00—17：30请营销端经理参与讨论如何有效减少店铺人员流失\u003c/p>\u003cp>学习者橘子分享：当我的组员问我这三个问题时，我第一个感觉是，呀，确实帮助其它部门处理人员矛盾应该是部门负责人的工作，这件事如果不做，对我不会有影响，而应该是让他们自已解决，解决不了我们再介入沟通解决；还有制定下半年公司人员招聘应该是招聘岗位人员根据公司实现需求调研后编写的，也就是说这件事可以由招聘岗人员去做；请营销端经理参加的会议，因为会议没有聚焦，我更是在浪费浪费营销端的时间。“\u003c/p>\u003cp>好的，非常感谢橘子的分享，我们会发现我们其实在日常工作或者生活中，是会无意识的浪费很多的时间，所以，我们发现，运用这三个直击灵魂的三个问题，就会将我们避免重复或者替他们做，也可能从浪费的时间里找到更值得去做的事情了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1541832885000,"updated_at":1541832912000,"ria":true},{"id":6314,"topic":"诊断自己的时间，提升自我及团队效能","learn_goal":"熟练掌握自我诊断时间的方法","remark":"德鲁克经典管理著作","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"杨颖春","city":"厦门"},"club":{"name":"厦门鹭见欢喜分舵","city":"厦门"},"prologue":"【学习目标】\r\n通过本次学习，学习者能够运用本拆知识诊断自己在某个事件/场景中的时间使用情况。\r\n分组：\r\n我叫杨颖春，我的3个标签是公司职员、生命舞者、一级拆书家，今天定级TF2-1，我们先分下组，左边一组右边一组，\r\n图书介绍 \r\n今天我要给大家分享的内容来自这本书《卓有成效的管理者》。\r\n【F】这本书讲的是学习方法论，这本书《卓有成效的管理者》的作者是彼得.德鲁克，是一位著名的管理学家，书中重点阐述了成为一个卓有成效管理者的五项要素，包括：善用时间、关注结果、善用人才、要事第一、有效决策。\r\n【A】这本书，是管理学类图书中非常畅销及实用的一本，仿如良师益友，虽然面对的是不同的事实，却能从不同的角度说出你不曾想、更不曾想到的理念，常有茅塞顿开之感。\r\n【B】（B1）那么大家是否曾经苦恼过，为什么我的时间不够用，我都这么加班加点了，还是不能如期完成工作，时间都去哪了？还有就是我已经事先安排好做每件事的时间了，为什么到最后我自己的事一件没做，全部做的是别人的事等等这些问题，你都可以从书中找到启发。（B2）而今天我要分享的这个片段，能帮助你记录并分析时间的使用情况。","ratings_count":1,"texts":[{"id":9606,"quote":"\u003cp>【R 阅读原文】拆页来自彼得.德鲁克《卓有成效的管理》掌握自己的时间之如何诊断自己的时间P34-36节选\u003c/p>\u003cp>要提高管理理的有效性，\u003cstrong>第一步就是记录其时间的实际情形\u003c/strong>。重要的是，必须在处理某一工作的“当时”立即加以记录，而不能事后凭记忆补记。\u003c/p>\u003cp>许多有效的管理者都经常保持这样一份记录，每月定期拿出来检讨。至少，有效的管理者往往以连续三四个星期为一个时段，每天记录，一年内记录两三个时段。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间使用得很乱，浪费在种种小事上。经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免回到浪费的状态上去。\u003c/p>\u003cp>\u003cstrong>第二步就是要做有系统的时间管理。\u003c/strong>我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以问自己下列几个问题：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果\u003c/strong>\u003cstrong>?\u003c/strong>\u003cstrong>”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/strong>\u003c/p>\u003cp>然而许多大忙人，天天在做一些他们觉得难以割舍的事，比如应邀讲演、参加宴会、担任委员和列席指导之类，不知占去了他们多少时间，而这些工作，他们本身既不一、感兴趣，做得也根本不够精彩。然而他们得承受这些负担，一年又一年，就像从天而降的灾难一样躲也躲不了。其实，对付这类事情，只要审度一下对于组织有无贡献，对于他人有无贡献，或是对于对方的组织有无贡献。如果都没有，只要谢绝就可以了。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果\u003c/strong>\u003cstrong>?\u003c/strong>\u003cstrong>”\u003c/strong>\u003c/p>\u003cp>多年来在管理方面都在研究授权问题。任何组织，几乎每一位主管人员都接到过上级有关做好授权的指示，而且他们本人也曾屡屡对其下属阐明授权的重要。但是这样的告诫是否产生效果，实在令人怀疑。原因非常简单，只是因为没有完全明了授权的意义。如果认为授权的意思是说：我的工作应由别人来做，那就错了；因为你既然拿了薪水，就该做你自己的工作。又有人认为：充分授权之后，最闲散的经理人便应该是最好的经理人。这样的看法不但荒唐，而且也是不道德的。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>还有一项是时间浪费的因素，是管理者可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/strong>\u003c/p>\u003cp>这种现象并不明显，但有一个简单方法可以诊断出来:&nbsp;去问问你的下属。即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。\u003c/p>\u003cp>许多管理者都意识到了哪些事情会浪费他们的时间，然而他们却不敢面对这个问题。他们怕因小失大，造成错误。殊不知即使有了错误，也可以很快弥补。能够大量消减不必要的和非生产性的工作，则工作就进行得快多了。\u003c/p>\u003cp>事实上，一位管理者大刀阔斧减少不必要的工作，绝不会有太大的风险。人总有一种倾向，高估自己地位的重要性，认为许多事百躬亲不可。纵然是最有效的管理者，仍然免不了有许多不必要的和生产性的工作。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>好，大家都阅读完了本片段，\u003c/p>\u003cp>What：这个拆页列举出了如何诊断自己的时间的二个步骤及三个方向；是管理者对时间加以记录，并且是“实时”的记录，以确保记录的准确性及做系统的时间管理将非生产性的和浪费时间的活动找出来。\u003c/p>\u003cp>Why：为什么要诊断自己的时间？由于组织本身的需要，处理人事问题的需要，以及创新和变革的需要，最终都是为了提高我们自身的工作效率，都使得我们不能不讲求时间的管理了。而要很容易掌控好时间，首先要了解自己是如何使用时间的，必须对时间进行诊断。\u003c/p>\u003cp>How：拆页里已经详细给出了二个步骤\u003c/p>\u003cp>1、第一步就是记录其时间耗用的实际情形。\u003c/p>\u003cp>2、第二步就是要做有系统的时间管理\u003c/p>\u003cp>三个方向\u003c/p>\u003cp>（1）找出哪些事情可以不做。\u003c/p>\u003cp>（2）找出哪些事情可以有别人来做。 \u003c/p>\u003cp>（3）别浪费别人的时间。\u003c/p>\u003cp>\u003cstrong>不这么做的坏处：\u003c/strong>\u003c/p>\u003cp>如果不做时间的诊断，会有哪些坏处，\u003c/p>\u003cp>第一，&nbsp;&nbsp; 恶性循环，重复做着一件事； \u003c/p>\u003cp>第二，&nbsp;&nbsp; 浪费自己与他人的时间；\u003c/p>\u003cp>第三，&nbsp;&nbsp; 造成整体效率低下，同事间合作不愉快\u003c/p>\u003cp>\u003cstrong>【例子】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我是研发部的主管，整天忙下来没效率，又被上级\u003c/strong>\u003cstrong>K\u003c/strong>\u003cstrong>，要找出我当下的原因在哪，针对我一天的工作内容进行记录，我的时间的使用情况\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>）跟进研发进度\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>）协调与其他部门的配合\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>）出差人员的确定\u003c/strong>\u003cstrong>4\u003c/strong>\u003cstrong>）别部门聚会邀请\u003c/strong>\u003cstrong>5\u003c/strong>\u003cstrong>）开会\u003c/strong>\u003cstrong>6\u003c/strong>\u003cstrong>）参加其他部门的会议\u003c/strong>\u003c/p>\u003cp>\u003cstrong>其中第\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>、\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>是下属就能做的事，而且他们会做得很好；第\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>、\u003c/strong>\u003cstrong>4\u003c/strong>\u003cstrong>项是不需做的事，别部门的邀请只是礼貌知会，并不是一定要我出席的，出差人员的确定，直接就可以敲定；第\u003c/strong>\u003cstrong>5\u003c/strong>\u003cstrong>、\u003c/strong>\u003cstrong>6\u003c/strong>\u003cstrong>项是浪费别人时间的事，会议，只要看会议记录就能完成。\u003c/strong>\u003cstrong> \u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>显像提问】\u003c/strong> \u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>经过刚才对拆页片断的学习，大伙试想下在自己的生活和工作中，平常有觉得时间不够用，是否有对时间进行诊断呢；假如你是一个总经理助理，你需要从事的事务是非常多，如招聘、面试、协调等等这些事务，在你忙得焦头烂额，情绪暴涨，甚至非常愤怒的时候，你是否意识到你的时间不够用，你是否对你的时间进行诊断，现在在场的小伙伴可以试想下类似过往经历中是否有类似时间不够用，是否有对时间不够用进行诊断，现在小组内讨论。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴的分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>小伙伴的工作是管理协调技师贴膜及和4S店对接，有一次，4S店反馈，昨天贴的车膜有出现卷边及起泡，里面还有一个小杂物，催着要贴模的技师去处理，当时我花了很多时间和4S店一直解释，这是什么情况，同时4S店一直催我让技师赶紧过去处理，我一听就一直催我的技师，你现在到哪里，4S店很急，最后因这个事故，整件事情处理起来很不愉快，技师也和我抱怨说你电话不要一直催，在路上堵车，最后和同事关系搞得很不好，自己的心情也不好，所有时间都浪费在和4S店沟通及催促技师上。\u003c/p>\u003cp>非常感谢这位小伙伴，他给我们阐述了时间使用情况的，现在我想问的是，你在处理这件事情的时候是否使用了时间诊断这个步骤。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1+\u003c/strong>\u003cstrong>反思加工】\u003c/strong>\u003cstrong>&nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>谢谢这位小伙伴的分享，接下来我们借着这位小伙伴所提供的案例，结合今天我们一起学习的知识点，如何诊断自己的时间，再次组内讨论，也可以将自己的案例拿出来讨论，我们想像下通过今天学习的如何诊断时间步骤，用在我们用在日常工作中，现在用2分钟的时间组内讨论。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴的分享，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>运用今天所学方法进行诊断我的时间使用情况，第一步骤，事件已经发生，我要静下心来梳理，我对时间的分配进行诊断，我要记录下事件，我的时间主要使用在以下2个方面，1）4S和我反馈膜的情况，我要先安抚下他的情绪，解释说什么情况；2）我将信息反馈给贴膜的技师，让他到4S店看情况；对这2个时间进行诊断，1、找出什么事情根本不必做，不需要向4S店人员解释我们膜的情况，我只要说，我将情况向技师反馈，等技师看了情况会和你们沟通，不需要解释什么，不然造成4S店对接人员多虑；2、不要浪费别人的时间，我不需要去催技师，让他早点到，多打电话会影响技师的情绪，只要将情况告知技师即可；3、可以由他人处理的事，即现场情况由技师和4S店沟通就好，我不清楚现场，这不是我来做的；通过这个方法，进行时间诊断。\u003c/p>\u003cp>\u003cstrong>结束语，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>谢谢这位小伙伴的分享，他优化的案例非常契合我们今天的学习目标，如何诊断自己的时间，也希望今天学习的如何诊断自己的时间，能为大家带来提高工作效率。今天我的分享到此结束，谢谢大家！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1540343817000,"updated_at":1540343817000,"ria":true},{"id":6242,"topic":"掌控自己的时间","learn_goal":"通过关注管理者有效时间的掌握，达到快速提升管理者技能。","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"pumafly","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>大家好，我的名字叫粟文杰，刚才已经简单介绍过我自己了，粟裕大将的粟，文化的文，杰出的杰。我的三个标签是职业生涯规划师，那我拿到的第一个认证就是职业生涯规划师，因为它可以让我走得更远。第二个标签是做管理相关的培训，因为我蛮喜欢，所以我今天的第一拆就是彼得·德鲁克的很优秀的《卓有成效的管理者》；第三个我想做一个小小的拆书家。第一次就是因为在长沙图书馆听王老师的拆书《生命中什么可能》，内容相当精彩，我听了她的最后一节课，所以深深影响了我成为一个拆书家的梦想。\u003c/p>\u003cp>接下来我跟大家介绍下“拆书家”。其实拆书家和拆书帮都很有意思的，我第一次接触就被深深吸引住了。我们先看下，它有个R是什么意思？叫I叫APPRIOATION,其实培训师也有一个困惑，培训完了，学员回去很快忘了，这样培训效果往往不好。所以说，RIA这种方式可以帮助大家更好的读书，所以特别推荐给大家。\u003c/p>\u003cp>以前我们在学校里面学习新知，叫“学好数理化，走遍天下都不怕”而拆书法可以帮助大家更好学会新知，并且能够学以致用。\u003c/p>\u003cp>拆书帮是一个全国公益性组织，全国各地都有，我们每次出去学习和培训的 时候，\u003c/p>\u003cp>我都会推荐朋友和推荐“你可以进入拆书帮”，只要加入“互动吧”APP就可以找到了。你去哪里都可以找到这个组织。那么如何成为一个三级的拆书家呢？第一个，通过不断拆书和层层过关；第二个要有一个这种姿势的帅气照片；那么你就成为一个很厉害的“拆书家”了\u003c/p>","ratings_count":1,"texts":[{"id":9523,"quote":"\u003cp>【原文】&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 关于管理者任务的讨论，一般都从如何做计划说起。这样看来很合乎逻辑。可惜的是管理者的工作计划，很少真正发生作用。计划通常只是纸上谈兵，或只是良好的意愿而已，很少能够真正实现。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp; 根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间，最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\u003c/p>\u003cp>&nbsp;&nbsp; 记录时间；\u003c/p>\u003cp>&nbsp;&nbsp; 管理时间；\u003c/p>\u003cp>&nbsp;&nbsp; 统一安排时间。\u003c/p>","explains":"\u003cp>【分享8小时之外工作时，这样会影响到下属休息的时间。其次，合理的安排时间，才会让管理工作更有序，员工更开心。很多工作都有顺序和流程，并且在最合适的时候做正确的事情，会让管理更高效。那么只有把时间更合理的管理，这样才会在事情发展过程中找寻事件在单位时间内的规律而更高效。\u003c/p>\u003cp>怎么有效做到时间管理呢？三个步骤：记录时间，管理时间和统一安排时间。记录时间是第一个核心步骤，因为大部分人都认为自己时间没有问题。事实上来说，时间的“黑洞”是严重存在的，上个月我就曾经记录过我时间的利用情况，没有记录之前，我觉得自己很高效，上个月第一周我记录了我工作有效的时间，发现才真正占比到所有工作时间的DOIT的25分钟内可以高度集中，我们就可以设置几个SAY NO的方式，或开启关闭模式。通过这样统一安排时间，我们就能按照事件重要程度和紧急程度来更好规划我们的管理工作，做一个有效的管理者。&nbsp;在应用场景方面，其实新上岗的管理者遇到类似情况会比较多。因为无法区分紧急和重要的维度，往往就眉毛胡子一把抓，分不清重点，往往最后都扮演了救火队员的角色，管理起来也显得很焦虑。在我们平时的日常工作时间管理的这三个步骤也是有效的。因为记录时间，用工具管理时间，以及统一安排时间都会让我们平时的工作更高效。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>我有一位同事，2个月前提升地区经理。因对管理工作不了解，上岗后工作，表格一堆事情，每天随访到很晚，夜里也在加班，发邮件。家人也在不断抱怨，最重要的是，业绩也不太好，员工不是很满意。\u003c/p>\u003cp>这个时候他找到我，希望我给点建议。我发现他的工作没有做时间管理，经常想一出是一出，于是，我给他建议，采用时间管理的三个步骤。在八小时内，记录以前做的事情，并开始认真分析，找到时间黑洞；通过紧急重要两个维度把事情进行分类，并按照四类型事情的不同处理方式进行管理\u003c/p>\u003cp>第一步：在记录时间时，他有困难后，很困惑，也很焦虑。我们发现他希望做的事情有两个问题；和自己预期有较大的差距，大部分事情都不是希望做的事情，此外也跟近段管理工作目标相关性较小。如何解决呢？其实有点没有头绪，因此我们采取记录的方式，把近一周的工作全部回忆记录了下来，找到时间黑洞，然后进行第二步。\u003c/p>\u003cp>第二步：管理时间：我们找到第一类事情紧急不重要，如客户的抱怨和员工的离职。重要不紧急事情，优秀员工深入沟通，更多了解业务和学习管理知识。第三类事情是紧急不重要的事情，如老板的很多邮件处理，很多公司日常工作和表格的提交。最后一类，不重要不紧急的事情，打王者荣耀和刷朋友圈。\u003c/p>\u003cp>第三步：统一安排时间：我们分类后，先把紧急重要的事情在三天内强制性完成。然后把重要但不紧急的事情做了一个月，一周及近三天的安排，逐步提高；日常表格和很多工作，他找到一个做得很好的员工，他来负责，授权他来协助处理。王者荣耀删除，以及朋友圈关闭。特别优先把重要紧急和重要不紧急的事情放到每天的八个小时的时间安排表里面，每天跟进复盘。\u003c/p>\u003cp>结果：很快一个月时间，整体管理工作进展很好，销售业绩提升了，下属对他的反馈较以前显著好转，晚上再也没有加班过了。他对自己的管理工作更有信心了，此外能平衡生活，有更多时间跟家人一起进行欢乐时光。\u003c/p>\u003cp>反思：确实在时间管理的过程中，只是凭借自己的盲目感觉，往往会被繁琐的日常事务牵着鼻子走，抓不到重点。而通过时间管理的三个步骤，记录时间，管理时间以及统一安排时间，就会发现通过这三个步骤有效地管理时间能更有效地做好工作和任务，而且让我们更轻松。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>目标：十月的工作非常忙，很多会议，培训，还有工作上的事情让我有点感觉工作量很大。我准备通过记录时间，管理时间和统一安排时间三个步骤对我的时间进行管理，希望能够提高我的工作效率，让我的工作和生活能够平衡。\u003c/p>\u003cp>具体步骤：\u003c/p>\u003cp>DOIT的2 管理时间：按照紧急重要的四类事情划分法则，把所有的事情进行处理。见客户，处理日常管理的工作是紧急重要的事情。虽然这个季度销售任务高，但我管理经验足，所以这类事情我放在紧急重要的类型。健身和学习管理知识我会分配到重要不紧急的事情上，因为我想做一个优秀的管理者，所以我会高度关注这类型事情。很多不重要的电话和应酬社交，以及公司的进销存作业表我放在不重要和紧急类型。而刷朋友圈放在不重要不紧急。\u003c/p>\u003cp>2小时的健身和每天早上3个小时学习，作为我每天重要但不紧急的事情处理，这将用我精力最充沛的时间段很多不重要的电话，不采取不主动接，然后回复有什么事情我乐意帮到你。而作业表格我将交给团队最资深有发展意愿的小黄，授权她来负责。最后减少用手机和关闭朋友圈的方法来安排这部分不重要且不紧急的事情，这样的安排做成我的周计划。严格按照安排的时间表执行。\u003c/p>\u003cp>反馈：每天和每周及每月都进行复盘，看看哪些时间安排事件是处理有效的，哪些不够高效。同时，减少不重要不紧急，以及重要不紧急的事件，积极授权，卸载抖音和手机游戏等造成时间黑洞的程序。复盘后持续跟进循环再次进入第一个步骤。\u003c/p>\u003cp>希望通过以上的时间管理步骤，能够让我真正高效管理，平衡生活，开心每一天。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1539690032000,"updated_at":1539740718000,"ria":true},{"id":5862,"topic":"掌握自己的时间","learn_goal":"合理管理自己的时间，以避免浪费碎片化时间，更合理的利用时间。","remark":"时间是最特殊的资源，不可代替，没有丝毫弹性，同时呢即是限制因素又是必须具备的一个条件，那我们如何更有效率的来掌握自己的时间呢？！","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"鱼和十滴水","city":"哈尔滨"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"开场:\r\n 各位热爱学习的伙伴，大家下午好，欢迎大家来参加今天的拆书过级活动，我是今天的拆书过级者钟雪。我先用三个标签来介绍一下自己。\r\n第一个标签，拆书过级者，最近需要不断的去充实自己，从而顺利过级学到真东西。\r\n第二个标签，读书人，对皇帝内经的读书分享会情有独钟。\r\n第三个标签，师父给我起的外号强人，就是强忍着学习的人。 \r\n【分组】一会在分享的环节，我们的伙伴们两两一组，分成4组。 \r\n接下来，我再介绍一下今天要学习的图书《卓有成效的管理者》 \r\nF（特征）:这本书的作者是一代管理学宗师德鲁克教授，自1966年首次出版以来，已被翻译成二十多种语言，是世界上众多企业管理者的必读书籍，也是管理实践中指导管理者如何做到卓有成效的指南。\r\nB（优势）:这本书最吸引我的地方，就是书中的方法论并非是作者的主观臆断，而是作者通过大量的管理实践总结出来的，可以说本书是一本实战类的指导书籍。\r\nA（利益）: 【场景介绍法】在工作和生活中，我们可能会遇到以下的情况，时间不够用，每天的时间管理琐事都不够更谈不上学习了，真的是忙的焦头烂额，最后还不知自己忙了什么。在遇到这些情况的时候，我们是继续放任时间的不经意流逝，还是唉声叹气，沉默以对呢？其实，我们还有四两拨千斤的方式，利用《卓有成效的管理者》中的时间管理三步法，来有效管理和利用各种琐碎时间。 \r\n观察点2、选择图书是实用类或者理论类图书。\r\n 观察点5、在FAB学习法中，可以清晰的分辨出FAB。\r\n今天，我们来体验一下《卓有成效的管理者》中的一个片段【掌握自己的时间】\r\n【设定学习目标】期望现场的各位伙伴在学习完这个片段后，能运用我们今天学习的【掌握自己的时间】的三步法，更有效的利用自己的时间，避免无时间可用的情况。 \r\n观察点4、学习目标包括学习者可被观察到、被测量到的行为或者动作，现场学习设计清晰的体现了该学习目标。","ratings_count":1,"texts":[{"id":9075,"quote":"\u003cp>卓有成效的管理者 &nbsp; p24\u003c/p>\u003cp>掌握自己的时间\u003c/p>\u003cp>关于管理者任务的讨论，一般都从如何做计划说起，这来很合平逻辑。可惜的是管理者的工作计划，很少真正发生作用计划通常只是纸上谈兵，或只是良好的意愿而已，很少能够真正\u003c/p>\u003cp>实现。\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方オ是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。\u003c/p>\u003cp>观察点3、【R】所选拆页，包括How的内容；且内容未超过2页图书内页。 &nbsp; &nbsp;\u003c/p>","explains":"\u003cp>I 拆书家讲解引导\u003c/p>\u003cp>【I】我看到，大部分伙伴已经看完了我们的拆页，没有读完也不要紧，我会带着大家一起解读一下今天的拆页。 &nbsp; &nbsp;\u003c/p>\u003cp>【是什么】这个拆页主要讲的是，【适用边界】当我们无时间可用，却又有很多事需要我们去做时，例如：我来拆书帮过级，每天要看很多书还有很多课程，没那么多时间选拆页以及练习。当出现了这种时间不够用的情况，我们可以应用掌握自己的时间的三步法，来有效利用自己的时间。\u003c/p>\u003cp>&nbsp;【为什么】大家可能会好奇，为什么要有效利用时间呢？实际上，不合理利用时间，不但浪费时间还会觉得时间不够用。不知道大家是否有这样的经历，当我们正在忙某件事时，这时又来好多事需要去处理，就导致我们时间更不够用，而时间呢又是不可再生资源，最终弄的焦头烂额，心急如焚。 &nbsp;\u003c/p>\u003cp>【怎么做、细化步骤】\u003c/p>\u003cp>&nbsp; &nbsp; 下面，我再说一下，如何用掌握自己的时间三步法。\u003c/p>\u003cp>&nbsp; &nbsp; 第一步，记录时间，把自己每天做的事情都及时记录下来以免忘记，像流水账一样。\u003c/p>\u003cp>&nbsp; &nbsp; 第二步，管理时间，根据第一步来测算真正属于自己的时间是多少，都分布在那个时间段，属于工作的时间都有哪些固定分配的时间段，哪些事情无意义，哪些事情不需我们来做。\u003c/p>\u003cp>&nbsp; &nbsp; 第三步，统一安排时间，规划出自己大段学习时间和工作中集中处理事件解决问题以及思考的时间。&nbsp;\u003c/p>\u003cp>这里举个例子，上个月孩子爸爸的车中介和汽车租赁公司谈了一笔生意，两天时间给127台车缴税落户，办理临牌，平时我们带着孩子一起一天落户十到二十台都觉得手忙脚乱，那我们当时是如何应用时间管理三步法的呢？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;第一步，记录时间，把我们以前准备时间和去窗口办理业务的时间都流水账一样记录下来。\u003c/p>\u003cp>&nbsp; &nbsp; 第二步，管理时间，缴税业务以及临牌业务落户业务的资料是重复整理的，而且还占用正常办公时间，这是在浪费时间，而且整理的资料还很分散。\u003c/p>\u003cp>&nbsp; &nbsp; 第三步，统一安排时间，用晚上时间准备临牌业务，缴税业务以及落户业务的资料，五点气床去税务大厅排队集中缴税，（孩子爸爸去办理临牌），集中一下午和第二天一上午时间来办理落户业务，下午则用来收尾。（这中间的零碎时间还可以解违章等业务）\u003c/p>\u003cp>【预防异议】可能大家会觉得这么做太麻烦了，直接就一件事接着一件事的去做不是更好吗？其实，如果我们不这么做，可能会更麻烦，因为一件事接着一件事的去做，没有统一安排，会更浪费时间，会觉得更忙碌，最后还不知道忙些什么。\u003c/p>\u003cp>观察点6、【I】的讲解中，给出比原书更细化的行动步骤，或者将书中的案例进行意译\u003c/p>","interaction":"\u003cp>A 学习者拆为己用\u003c/p>\u003cp>那我们如何有效应用今天的拆页呢？\u003c/p>\u003cp>【A3】【场景设计】忙碌的人\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;洋洋在一家正在扩张期的培训公司里工作， 是张经理的下属，洋洋的问题是每次张经理布置给洋洋的工作（用一周时间为本公司的业务部准备培训销售训练计划），洋洋都会忙忙碌碌，又不能按时完成，而且有同事也和洋洋私下说你每天都很忙，怎么还没完成工作呢。同时洋洋自己也觉得总是在忙又不知忙些什么，也想请教下张经理如何有效的利用时间，更有效的完成工作任务。张经理在和洋洋谈论这件事的时候，一定要提出自己对于时间管理的建议，洋洋也会认真的倾听，所以在对话时要谈时间管理的具体步骤和操作。毕竟洋洋这个人还是不错的，大家都很喜欢她。她不但幽默、工作能力强，而且很勤奋。但如果洋洋能掌握好自己的时间就会更好了。 &nbsp; &nbsp;\u003c/p>\u003cp>这种情况下，如果你是张经理，去找洋洋谈谈如何更有效的利用时间，有可能洋洋不是很理解。设想一下，如何去分享让时间更有效，来让洋洋更有效的管理自己的时间，更有效率的工作呢？\u003c/p>\u003cp>解决这个问题方法很多，但我们今天就尝试一下，利用掌握自己时间的三步法解决问题。 &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>首先，请各位利用手里的便签，写出掌握自己时间的三个步骤。如果你是张经理去和洋洋沟通，如何分享掌握自己时间的三个步骤来让洋洋更有效率的工作，以及更有效的去掌握自己的时间呢。请我们的每个伙伴写好我们的便签，然后我们分别扮演两个角色，进行演练。 &nbsp;\u003c/p>\u003cp>现在，可以按照刚才的分组，进行演练，一位扮演张经理、另一位扮演洋洋。 &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; 时间2分钟，2分钟后，我会请各个小组开始两轮的演练，最终我们会请两位伙伴上台进行演示。 &nbsp; &nbsp;\u003c/p>\u003cp>请王辉和李晶两位小伙伴上台演练（掌声）\u003c/p>\u003cp>学习者演练：\u003c/p>\u003cp>学习者案例：洋洋（王辉扮），张经理（李晶扮）\u003c/p>\u003cp>[张经理]洋洋，能说说每天都在忙什么吗？\u003c/p>\u003cp>[洋洋]张经理，我每天忙的很乱。\u003c/p>\u003cp>[张经理] 那这样，洋洋，你每做一件事就把它记录在本子上。\u003c/p>\u003cp>[洋洋]好的，我记录做课件以及准备讲课的演练等每件事的时间以及做了那些事。\u003c/p>\u003cp>[张经理]现在呢管理时间，在看看那些事，用了多长时间，其中有没有无意义的，以及别人可代替的，那些事是重复的。\u003c/p>\u003cp>[洋洋]好的，张经理，在做课件时，一些零碎的打印文件会占用我很多时间。\u003c/p>\u003cp>[张经理]当然就统一安排时间了，把无意义的事不做，别人可代替的事不做，统一安排工作时间，重复的事情呢一次性做完，你的打印文件等琐碎事件可以由培训助理去做。\u003c/p>\u003cp>[洋洋]好的，谢谢张经理，麻烦张经理和培训助理说下。\u003c/p>\u003cp>……【演练完毕】\u003c/p>\u003cp>【强有力的结束语】最后感谢各位小伙伴的精彩分享，期望通过我们今天的学习，各位伙伴都能运用学到的三步法，更有效的利用自己的时间，避免无时间可用以及浪费时间。最后让我们再回顾一下掌握自己时间步骤：记录时间，管理时间，统一安排时间。最后呢期望各位都能更好地认识自己的时间，莫等年迈白发时想起那句“莫等闲，空悲切，白了少年头”而懊悔不已。\u003c/p>\u003cp>以上是我今天分享的内容，再次感谢小伙伴们。\u003c/p>\u003cp>观察点7、【A3】给出一个非常具体、确定的场景，学习者可以在此场景中演练或讨论或应用新学技能。\u003c/p>\u003cp>观察点8、使用【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点，进行组内角色扮演。&nbsp;\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1534769860000,"updated_at":1534769860000,"ria":true},{"id":5657,"topic":"高效管理","learn_goal":"学会利用整块时间集中高效处理手头上的主要工作","remark":"","level":"TF1-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"棒妈","city":"南京"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>大家好！我是棒妈，我用三个标签介绍一下我自己：1.职场妈妈，我是一名9个月男宝的妈妈，同时在一家事业单位从实文字工作；2.拆书爱好者，从7月份加入拆书训练营，沉迷不能自拔；3.终身学习者，提倡终身学习，自我进化不停歇。\u003c/p>\u003cp>今天推荐的这本书叫《卓有成效的管理者》。这本书的作者是彼得·德鲁克，涉及过管理学的同学，都听说过他的名字。他是现代管理学之父。很多管理学耳熟能详的概念比如：组织、目标管理、绩效管理都是他最先提出来的。他一生写过的文章不计其数，光在哈佛商业评论超过30篇，记录至今没有人打破。写的书有50多本，在130多个国家传播，可以想象他的影响力有多大。\u003c/p>\u003cp>有人问彼得·德鲁克一个问题，写了这么多书，最满意的是哪本，他想了半天，说最满意的有两本，第一本是《成果管理》，《成果管理》提出战略，也就管理高层最爱提的规划公司未来发展方向的战略这个概念。第二本是《卓有成效的管理者》。《卓有成效的管理者》提出了知识工作者的概念。\u003c/p>\u003cp>我们现在听知识工作者这个概念，没有什么感觉。但是在当时，1966年的时候，这是一个非常新的概念。因为当时，德鲁克新奇地发现，当时社会正在进行一次大的转型，人们的主要工作正在由体力工作向知识工作转变。最先意识到这种转变，并且迎接这种转变的国家，如美国、瑞士、日本，二战后经济复苏都发展的很好。随着知识工作者增多，管理方式、难度带来新的挑战。知识工作者的主要工作是思考。思考这个东西，看不见摸不着。怎样将知识转换成具体的成果？对知识工作者的成绩继续衡量？正在大家苦恼的这个问题的时候，彼得·德鲁克出了这本书，书中从5个方面设置了一个大方案，论述了知识工作者怎样变的卓有成效。下面让我们一起走进这本书。\u003c/p>","ratings_count":2,"texts":[{"id":8843,"quote":"\u003cp>不过，话又得说回来：集中自己的时间，集中的“方法”倒在其次，重要的是时间如何用法。许多人把次要的工作集中起来办理，因而匀出一段整块时间来。但这样的方法并无太大的作用。因为这样的方法，不啻在心理上或时间上，仍然放不下那些次要的事情，放不下那些很少贡献而又认为不能不做的事情。结果终究还会产生新的时间压力，来占用他的自由时间，牺牲他应该做的事。几天或几星期后，他已经 “集中”的自由时间，又会被那些所谓“新的问题、新的紧急事件、新的麻烦”瓜分得无影无踪了。 \u003c/p>\u003cp>有效的管理者，第一步应先估计究竟有多少“自由时间”，真正是他自己的时间，然后保留出相当分量的一段连续性的整块时间来。一旦发现还有别的事情在“蚕食”他保留的时间，便立刻再仔细分析他的时间记录，再将其中比较次要的工作重新过滤一次。他们已知道这层道理，因此不至于过分删减。\u003c/p>\u003cp>一切卓有成效的管理者都懂得：对时间的控制与管理不能一劳永逸。他们要持续不断地做时间记录，定期对这些记录进行分析，还必须根据自己可以支配的时间的多少，给一些重要的活动定下必须完成的期限。\u003c/p>\u003cp>有一位极有效的主管，身边经常带着两张这样的完成期限表。一张是有关紧急事件的，一张是做起来自己并无兴趣但却非做不可的。每次在发现完成时间比预定期限落后时，他就警觉到可支配时间已有溜走的迹象了。\u003c/p>\u003cp>总而言之，时间是最稀有的资源。若不将时间管理好，要想管理好其他事情就只是空谈。而分析自己的时间，也是系统地分析自己的工作，鉴别工作重要性的一种方法。\u003c/p>\u003cp>&nbsp;“认识你自己”这句充满智慧的哲言，对我们一般人来说，真是太难理解了。可是，“认识你的时间”却是任何人只要肯做就能做到的，这是通向贡献和有效性之路。\u003c/p>","explains":"\u003cp>如何利用整块时间集中高效处理手头上的主要工作？\u003c/p>\u003cp>第一步：对时间进行诊断，分析出究竟有多少是“自由时间”。\u003c/p>\u003cp>第二步：在“自由时间”，保留出相当完整的一整段时间，集中处理手头上主要工作。\u003c/p>\u003cp>第三步：集中处理手头上主要工作的时候，对时间做分析，防止其他事情蚕食手头上的主要工作，同时给重要活动下定完成期限。\u003c/p>\u003cp>【举例子】以我为例，9月我手头上主要工作是撰写月底新闻发布会上的汇报材料。一开始接到这个通知的时候，我是填缝加塞式的撰写，有时候是一边打电话，一边写材料，有时候是一边刷微信，一边写材料。写了一个星期，我发现我的材料一点进展都没有。\u003c/p>\u003cp>后来，我对自己的时间进行了诊断，我发现有的会议可参加可不参加，不参加的，和领导说一声关系也不大；有的沟通电话，让办公室其他同事打效果也是一样的。诊断自由时间是每天上午9点到12点。\u003c/p>\u003cp>接着，我利用这三个小时候的时间，关闭网页，关闭噪音污染，集中写材料，\u003c/p>\u003cp>写到一半的时候，发现有的观点需要推翻重来，包括论点和论据；有的数据要问业务部门；有的资料需要翻阅以前资料。后来发现每天三个小时时间不够用，我利用晚上忙完家里的事情，夜深人静的时候，创造出属于自己的自由时间，静下心来花一个小时写材料，保证在截止日期前交稿。\u003c/p>\u003cp>经过这一周每天四小时，将材料写好了。交给领导，领导还比较满意。\u003c/p>\u003cp>我举这个例子想说明我们手头上的深度工作是需要预热的，预热是需要整块的时间的。而只有花一整段时间才能预热，进入沉浸的状态，而只有进入沉浸状态，才能够进行深入的思考，才能不断打磨自己的产品。而如果时间被切割成一块一块，东一榔头西一棒槌，是不能打磨高效的产品。\u003c/p>\u003cp>第一步，我通过授权、不参加无关紧要会议创造了自由时间；第二步，在自由时间中，关掉网页、qq，屏蔽外界干扰，集中精力写材料；第三，做时间记录分析，发现每天三小时写材料还是不够的，深夜加班一小时，最后在规定日期交稿。\u003c/p>\u003cp>【给学习者分组】在进入A1环节之前，给大家分个组，左手边：李兵和Yimy一组；右手边：鱼姐和双双一组。\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp>请大家回忆一下，自己在日常工作或者生活中，有没有自己看起来很忙，实际上一事无成的经历？或者没有把业余时间集中起来，导致重要工作被延误的经历？ \u003c/p>\u003cp>给大家3分钟时间，在组内分享一下。\u003c/p>\u003cp>请一位小伙伴和大家分享。\u003c/p>\u003cp>学习者李兵：我在公司也是做管理的，我早上第一件事列三只青蛙，和蝌蚪。对接的相关人员会列好，下属安排哪些要授权的也列好，在中午下班前和下午下班前会对接下完成情况怎样。\u003c/p>\u003cp>这个时间的使用效率能够达到80%，但是没有达到100%，为什么？尝试做记录的时候有问题，比如关注这个事情是一个小时，但是有时候有干扰了就会打扰到我，干扰后，我会关门，集中精力花了一个半小时或者两个小时时间，时间延长来处理事情。有时候用工具，如番茄钟，保持整块时间处理重要问题。1.授权，创造自由时间；2.排除干扰，关门，找出整块时间集中处理工作；3.对时间分析，利用番茄钟专心高效处理紧要事情。\u003c/p>\u003cp>A2:\u003cbr>\u003c/p>\u003cp>刚才李兵分享了时间管理遇的例子，最后请大家想一下，未来一周，如何利用手头上的整块时间处理手头上的主要工作？写下具体的可操作的步骤。请大家在便签上写下，给大家1分钟。\u003c/p>\u003cp>Yimy:1.预估整段时间:19:00——20:30;21:00——22；30；2.事件：读书写作；3.干扰处理：记录时间花销，及干扰项，清空大脑，排除干扰；4.清单：写出重要的事情或者紧急的事情清单，花整块时间处理。\u003c/p>\u003cp>李兵：目标:未来一周，记录自己的管理时间。计划：1.每天每项工作启动时，结束时记录时间；2.每天下班前回顾时间，看看有时间记录无毛病；3.睡觉前写个小自传反思（15分钟）。\u003c/p>\u003cp>双双：1.在重要紧急的事情上，提前与参与者确认好时间节点；2.将重要不紧急的事情评定为如果可以授权，授权他人完成，盯紧节点即可；3.预留出自我反思与改进的时间。\u003c/p>\u003cp>今天拆书活动到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1533048504000,"updated_at":1534907000000,"ria":true},{"id":5534,"topic":"用“重人之长”代替“”视人之短”","learn_goal":"用“重人之长”代替“”视人之短”","remark":"多问“此人能做些什么”，而不必问“此人不能做些什么”，这样更有成果","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"彭梦","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>大家好，我是彭梦，用三个标签来介绍一下自己，第一个标签是销售，这个很好理解，我从事的工作是销售；第二个标签是希望自己成为终身学习者，我认为只有不断学习，才能不落后于社会；第三个标签是重新拾起健身的健身爱好者。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>下面由我为大家介绍一下什么是拆书和拆书帮。拆书是以学习者为中心而非以知识为中心的学习方法，它会让你关联过去，规划未来，分为个人学习的拆书法和组织学习的拆书法：个人学习的拆书法是RIA便签读书法，R就是原文片段，I是用自己的话重述原文，A分为A1和A2，A1是联系过过往的经验，你有没有遇到过类似的事情，你当时是怎么做的？不管是自己经历的，或者是看到发生在别人身上的，都可以。A2是指向未来，在以后的工作和生活中，你会怎么运用本片段中讲到的方法，具体地写下来然后去做。书中的方法让人读一本书就能达到参加同主题培训的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>“拆书帮”是基于拆书学习法的学习爱好者社群，表现为各地的拆书帮分舵，全国有40家正式分舵和29家筹备分舵，而我们郑州轩辕分舵就是这40家正式分舵中的一家，拆书帮是非盈利性质的，要帮助更多的学习爱好者成长为拆书家。这就是拆书以及拆书帮的介绍。下面进入今天的拆书环节，今天我要拆的书是《谈话的力量》中的一个片段，怎样有效地表达直接的称赞，学会有效表达直接的称赞的技巧，在称赞中让对方感受到尊重与真心，让双方更好的交流。请大家用2分钟的时间阅读手中的拆页，阅读完后请举手示意我一下。\u003c/p>\u003cp>&lt;技能点—如何介绍拆书帮&gt;\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","ratings_count":3,"texts":[{"id":8705,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>怎样有效地表达直接的称赞&nbsp; 《谈话的力量》\u003c/p>\u003cp>&nbsp;最常见的赞扬方法就是表达直接的称赞。这种赞扬直接告诉对方你对他们的行为、外表和气质的哪些方面表示赞赏。每次在课堂上讲到这个技巧，我总是以让学生们对我或其他人说一些赞扬的话开始的。\u003c/p>\u003cp>以下是有一次我记录下来的几种赞扬：\u003c/p>\u003cp>行为：“你是一位好老师。”外表：“你的头发很漂亮。”衣着：“我很喜欢你的鞋。”\u003c/p>\u003cp>这样的称赞可以通过两种方式进行改进：\u003c/p>\u003cp>1、具体一些。如果你毫无保留地告诉对方你的喜好，让他们相信你的话只适用于他一个人，而不是任何一个人，那么你的话就会更加有力，令人信服。例如：\u003c/p>\u003cp>行为：“我喜欢你在我们练习的时候，亲自给每个人做辅导。”\u003c/p>\u003cp>外表：“我觉得这个新发型让你的眼睛更加漂亮了。”\u003c/p>\u003cp>衣着：“那双棕褐色的路夫鞋很配你的卡其裤。”\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>2、称呼对方的名字。人们认为，自从柏拉图和苏格拉底以来多数人都觉得自己的名字是世界上最动听的声音，会对包含其名字话语给予更多的注意。此外，称呼对方的名字也可以让对方觉得你的赞扬是专门针对他的。例如：\u003c/p>\u003cp>行为：“艾伦，我喜欢你在我们练习的时候，亲自给每个人做辅导。”\u003c/p>\u003cp>外表：“艾伦，我觉得这个新发型让你的眼睛更加漂亮了。”\u003c/p>\u003cp>衣着：“艾伦，那双棕褐色的路夫鞋很配你的卡其裤。”\u003c/p>\u003cp>同样地，你很可能也发现很多人难以接受你直接的赞扬。出于谦虚，或者没有别的回答方式，他们通常会拒绝你的赞扬，从而让你感到受挫，使你以后的赞扬话语减少。\u003c/p>\u003cp>行为：“这只是在做我应该做的。”\u003c/p>\u003cp>外表：“我倒觉得理发师剪得太短了。”\u003c/p>\u003cp>衣着：“你喜欢这样的旧鞋？”\u003c/p>\u003cp>无论出于什么样的原因，你都可以做些什么，让你的赞扬更有效果，更容易让对方接受：你可以在赞扬之后加上问题。（开放式问题最好，但只要是问题就行。）这样的话，当对方听到你的赞扬时，就不用苦苦地找一个回应的方法，只需说声谢谢，然后回答你提出的问题。\u003c/p>\u003cp>最后，我们把原来的赞扬具体化一些，加上对方的名字，再加上一个问题，就是这样：\u003c/p>\u003cp>行为：“艾伦，我喜欢你在我们练习的时候，亲自给每个人做辅导。说说看，你观察到的\u003c/p>\u003cp>最常犯的错误是什么？”\u003c/p>\u003cp>外表：“艾伦，我觉得这个新发型让你的眼睛更加漂亮了。你是怎样想到要换这个发型的？”\u003c/p>\u003cp>衣着：“艾伦，那双棕褐色的路夫鞋很配你的卡其裤。你是怎么决定买这种款式的？”\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>这个片段用生动具体的例子给我们讲了一种赞扬别人的方法，就是在称赞别人的时候尽量具体一点，并且加上对方的名字，最后再提出一个开放式的问题。\u003c/p>\u003cp>为什么我们要这么称赞别人呢？美国着名心理学家威廉·詹姆士说:“人类本性上最深的企图之一是期望被赞美、钦佩、尊重。”心理学研究表明,爱听称赞是每个人都会的想法，而越具体、越生动地称赞更能打动人，更能达到更好的效果。\u003c/p>\u003cp>那我们到底应该怎么称赞别人呢？\u003c/p>\u003cp>第一步：我们要在开始之前先称呼对方的名字，让对方感到尊重；\u003c/p>\u003cp>第二步：让称赞尽量具体一点，比如说可以用形容词，用类比句，用成语这样可以让对方感受到你真心实意的称赞，是有认真想过的，不是敷衍的，因为越具体的事情越能打动人；\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>第三步：在称赞后边提出一个开放性的问题，这样可以让对方把话接起来，有利于进一步沟通。\u003c/p>","interaction":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 【A1】 拿我自己举例吧，上周末跟我妹在家聊对工作和生活的计划时，聊到了对钱的分配上，我说我不管每个月有多少钱都会花到一分都不剩，甚至还会欠信用卡一部分钱。就很苦恼。她给出了很好的建议：养成存钱的习惯，算出平时的生活开销，剩下的钱，哪怕只有100块也行，每个月把它存进一张固定的银行卡。雷打不动，慢慢地养成习惯就能存下钱了，这样很具体地告诉了我该怎么做才能解决我现在最大的问题。我当时心里很感激她，对我解决现在的月光现状特别有帮助，心里暗暗地说：我以后一定对她更好。但是当时不知道怎么表达，只是不停地在说：这个方法真好，真的挺好。然我妹就很平静的说了一句：“反正我用着挺好的。”是挺好的，我又附和了一句，然后就结束了。当时其实我是很想说一些赞扬的话，但是就是不知道怎么说，词穷的无奈，也无法让我妹明白当时我想感谢她的心情。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【A2】大家都知道，我的萍萍师妹过级的速度特别地积极和迅速，给我树立了一个很好的榜样。以前我总说自己忙，没时间。但是我看到萍萍工作也很忙，但是她还是会制定过级计划，迅速过级，是她的这种行为激励着我不再为自己找借口，开始准备过级。\u003c/p>\u003cp>下周日我们聚餐时，我准备将今天片段里讲到的方法运用一下，第一步称呼对方：萍萍师妹，第二步把称赞具体化，把行为具体描述一下，就是你在工作很忙地情况下还能制定这么快速地过级计划，并且快速的过级，像一个灯塔一样指引着我，不断地给我勇气和目标，让我往前走，真的特别感谢你。最后再抛出一个开放性的问题：你是怎么安排工作和练级的时间呢，能跟我分享一下吗？这样听着会不会更加形象具体，更具真心呢？\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp;&nbsp; 谢谢大家，我今天的分享就到这里就结束了，希望大家都能在工作和生活中能够能更好的去称赞别人，让对方感受到尊重和真诚，让我们的工作和生活以及人际关系更加协调。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1531922558000,"updated_at":1531923109000,"ria":true},{"id":5524,"topic":"卓有成效的管理者必须高效利用时间","learn_goal":"学习后，学习者将掌握如何诊断自己的时间","remark":"怎样才能高效利用时间呢？时间的浪费是多种原因造成的，其中有一种原因就是管理者在浪费自己和别人的时间。本节拆书家将带你学习高效利用时间的方法，教你掌握经理人的自我时间管理，以及经理人对下属成员的时间管理。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"曾金泉","city":"东莞"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>大家好，我是拆书帮的新晋拆书家曾金泉。 我的三个标签是：国家二级人力资源管理师，高级培训师，工商管理硕士。&nbsp;\u003c/p>\u003cp>现任职深圳清华紫荆同学会供应链行业协会副会长，并主要针对文化创业领域进行投资。在人力资源管理中，我最擅长模块主要是人力资源规划、招聘、培训。最喜欢的一句话：不抱怨，多努力，传播正能量！曾服务部分客户：深圳市罗湖供电局等。&nbsp;\u003c/p>\u003cp>开始之前，我要向大家介绍拆书学习法和拆书帮。\u003c/p>\u003cp>\u003cstrong>“拆书”，\u003c/strong>顾名思义，就是把书本中的知识点拆为已用。它是一种非常优秀的学习方法，就是通过RIA的方法把书本中的知识点通过一系列的方法来进行阅读、理解、应用，从而将书本中的知识点完整地纳入个人的知识体系。特别适合爱好读书的人和团队，适合学习型组织。\u003c/p>\u003cp>\u003cstrong>“拆书帮”\u003c/strong>就是这样一群爱好学习的志同道合的兴趣者们的自动自发的团队。它可以是一组人，也可以是一群人。可以是小集体，也可以是大团队。它不仅仅有社群的形式，还有各地的拆书帮分舵，比如说我就是来自东莞乐享分舵的学员。其实我更喜欢它叫“拆书帮俱乐部”。我们的教育长老叶佐旭是一位年轻帅气阳光的小伙，他告诉我们，拆书帮是一个公益性的组织，希望能帮助到更多爱好学习的小伙伴们更快成长。\u003c/p>\u003cp>今天我们一起来学习和拆解片段来自《卓有成效的管理者》。这本书的作者是德鲁克， 该书论述了一个管理者要如何做到卓有成效，这本书也是德鲁克最著名的管理学著作之一。\u003c/p>","ratings_count":1,"texts":[{"id":8695,"quote":"\u003cp>如何诊断自己的时间?\u003c/p>\u003cp>首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果?&quot;，如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>第二个该问的问题是：“时间记录上的哪此活动可以由别人代为参加而又不影响效果?\u003c/p>\u003cp>还有一项时间浪费的因素，是管理者自己可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/p>","explains":"\u003cp>卓有成效的管理者必须高效利用时间。高效利用时间必须要诊断自己的时间。时间的浪费是多种原因造成的，很多时候，管理者在浪费自己和别人的时间。所以管理者本人要时刻警觉这个问题的存在。有效的管理者知道，时间是一项限制因素，时间也完全没有替代品。所以，有效的管理者与其他人最大的区别就是他们非常珍惜自己的时间。他们从一开始就能很清楚的做好时间规划和安排。有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。本节片断正是教我们如何高效利用时间的方法，做好时间诊断。在诊断时间的使用时，管理者要善于利用工具，比如说做时间记录表，并对时间记录表进行分析，同时对时间的安排做好统筹规划。这么做的好处是对时间的安排一目了然，提高时间的有效性。不这么做的话，我们可能就会浪费自己或别人的时间。\u003c/p>\u003cp>那么，怎样才能诊断时间、高效利用时间呢？\u003c/p>\u003cp>1、记录时间：使用时间记录表。\u003c/p>\u003cp>2、管理时间：分析做与不做的影响，自己做和别人做的影响分析与管理。\u003c/p>\u003cp>3、统一安排时间：统筹规划，不浪费自己和别人的时间。\u003c/p>\u003cp>这个方法可以适用经理人的自我时间管理，也适用于经理人对下属成员的时间管理。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>过去的一周，我每天都在焦虑中，总觉得时间不够用，越焦虑，我就越喜欢不停地找下属员工谈话，但每次谈的都是类似的问题。昨天中午，我又找人力资源部张主管谈了一个半小时的工作安排，但是谈来谈去还是那一个问题：就是如何让员工高效工作，张主管几次想打断我的谈话都没有成功，最后他耐着性子听我把话说完，然后，很不开心地离开了我的办公室。我听到他在座位上抱怨我话太多，浪费他的时间，晚上又要加班了。\u003c/p>\u003cp>现在回想，作为一名高级管理者，我应该对自己的工作时间进行规划，利用时间记录表记录我的时间安排，分析做和不做的好处和坏处，分析自己做还是安排别人做的影响，并对工作模块统一安排时间，不要浪费下属员工的时间也不要浪费自己的时间，最终提高自己的工作时间的有效性，提高工作效率和公司的管理效率。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>下周一我要马上应用时间诊断，做好时间记录，管理自己的时间，统一安排自己的时间，计划下周的任务在工作时间内全部完成，并不浪费其他同事的工作时间。\u003c/p>\u003cp>我打算这么来做，1. 针对我下周的全部工作事项绘制一周时间记录表。2. 对一周时间记录表进行时间诊断，针对罗列的工作事项明确工作事项的轻重缓急，并完成二项确认：确认工作事项占用时间利用的有效性：做和不做的影响对比；确认工作事项占用时间利用的高效性：自己参加或者别人参加的结果对比。3．在周例会以及OA系统上确认一周工作安排及时间安排，统一部门部属成员的工作任务和时间计划。做好时间的诊断，将有助于我对自己的时间进行管理，也有助于我对下属成员的时间。如果不进行时间诊断，我可能又要犯和上周相同的错误，管理不好自己的时间，同时也浪费下属的时间，工作低效，而且下属员工们也将对他们的管理者——我，产生不信任或者抱怨。因此，做好时间诊断很重要，大家可以将时间诊断应用在自己的工作中间，将非常有帮助。我今天的拆书到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1531650090000,"updated_at":1531650943000,"ria":true},{"id":5385,"topic":"要事优先1","learn_goal":"学习后，学习者能够获得一种为目标设定优先顺序的方法","remark":"设定了很多目标，但不知道重点在哪里、不知从哪个着手开始？只要4步，这个问题将成为过去。请你来到东莞分舵分场，让拆书家带你找到答案！","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"姜庆海","city":"东莞"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>各位小伙伴，大家好！我是姜庆海，很高兴、也很紧张，接下来由我进行TF1-1打怪晋级。首先，用三个标签做一下自我介绍：\u003c/p>\u003cp>第一个标签：拆书家晋级路上的拆书小白。从2015年就已经接触赵周老师的拆书学习法，后面也参加了一些在线课程，但一直没有找到正确的入门方法。今年3月份，加入到拆书帮东莞乐享分舵，并参加了全国RIA训练营，下定决心一定要学习好拆书法、做一名合格的拆书家。\u003c/p>\u003cp>第二个标签：项目管理，在消费性电子产品行业有近十年的新产品开发项目管理从业经验。\u003c/p>\u003cp>第三个标签：两岁宝爸。家有男宝一名，调皮好动，在教育宝宝、陪伴宝宝成长的路上痛并甜蜜快乐着。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>前两周，当我把我们分舵的训练营开营活动post在微信群之后，有好多好友来问：什么是拆书帮？拆书，是把一本书一页一页的拆下来吗？接下来，就跟大家分享一下什么是拆书帮。\u003c/p>\u003cp>“拆书”是由赵周老师创立的一种以学习者为中心的学习方法论，它强调用知识关联学习者的相关经验、规划具体的应用场景，解决成人学习中普遍存在的没时间、看不懂、记不住的问题。\u003c/p>\u003cp>拆书法分为供个人学习的拆书法和供组织学习的拆书法。供个人学习的拆书法，使用三个便签，使学习者仅通过阅读一本致用类图书就能达到参加同主题培训的效果。供组织学习的拆书法，由拆书家将一本书加工成一场现场培训，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，具体表现为全国各地的拆书帮分舵，也叫拆书帮俱乐部，比如我们东莞乐享分舵。拆书帮分舵是公益性组织，他的使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>拆书帮的口号是：不破不能立，不拆不成器。\u003c/p>","ratings_count":1,"texts":[{"id":8540,"quote":"\u003cp>我们今天要拆解的原文片段，来自于现代管理学大师彼得德鲁克的代表作《卓有成效的管理者》第5章--《要事优先》。\u003c/p>\u003cp>下面呢，把原书的拆页发给大家，请大家用一分钟左右的时间阅读一下。阅读完毕的小伙伴，待会请举手示意我一下。\u003c/p>\u003cp>【卓有成效的管理者 – 先后次序的考虑】\u003c/p>\u003cp>如何决定优先，研究起来确实很复杂。不过我们可以说，在决定哪些应该优先、哪些可以延缓这个问题上，最重要的并不是分析，而是拿出应有的勇气来。\u003c/p>\u003cp>以下是几条可以帮助确定优先次序的重要原则，每条都与勇气密切相关：\u003c/p>\u003cp>• 重将来而不重过去\u003c/p>\u003cp>• 重视机会，不能只看到困难\u003c/p>\u003cp>• 选择自己的方向，而不是盲从\u003c/p>\u003cp>• 目标要高，要有新意，不能只求安全和方便\u003c/p>","explains":"\u003cp>我们一起来回想一下，自从跨过千禧年的大门，信息化社会，在过去二十年内得到快速的发展。这20年，不论从社会环境方面还是人的观念方面，都发生了翻天覆地的变化。社会高速发展，也给大家提出了越来越高的要求。要怎样才能跟上社会发展的节奏、不掉链子呢？大家都知道，要通过不断的学习充电、让大脑更新换代。也正是在这样的情况下，“并行”这个理念变得越来越流行，大家都想多学习一门本领、一种语言、多一个奔小康 奔富裕的手段。\u003c/p>\u003cp>但是，我们真的有足够多的精力，能够并行不悖的进行多个计划吗？大家伙想想自己，去年年初定下的几个年度目标，比如，健身计划、学习计划、旅游计划、社会拓展计划、工作计划。。。等等，每个都想去做，实际上有几个在目标期限内得到实现了？\u003c/p>\u003cp>很多目标都没有实现，是吗？是的，这是一个问题。\u003c/p>\u003cp>无可否认，个人的精力是有限的。当我们的目标过于分散，什么都想去做，结果往往是什么都做不成。在这有限的精力之中，为了使效益最大化，我们首先需要做的，是要给目标定个优先顺序，确定哪些应该优先、哪些应该延缓。而实现这一点，需要人们拿出勇于取舍的勇气。作者提出，通过以下几个重要原则，你将了解到如何确定优先次序：\u003c/p>\u003col>\u003cli>\u003cp>重将来而不重过去：以将要获得的收益高低来衡量\u003c/p>\u003c/li>\u003cli>\u003cp>重视机会，不能只看到困难：以可以获得提高自己综合竞争力的机会高低来衡量\u003c/p>\u003c/li>\u003cli>\u003cp>选择自己的方向，而不是盲从：以自我内心渴望程度来衡量\u003c/p>\u003c/li>\u003cli>\u003cp>目标要高，要有新意，不能只求安全和方便：以个人知识面的扩大和个人能力的提升程度来衡量\u003c/p>\u003c/li>\u003c/ol>\u003cp>以上几点，仅针对一般性目标而言，如果目标上升到非物质层面或者牵涉到原则问题，则情况可能会有所不同。比如，道德因素约束、法律法规制约等等。\u003c/p>","interaction":"\u003cp>【分享A1便签】\u003c/p>\u003cp>2016年底，我给自己定了以下几个年度目标，计划都要在2017年底实现：\u003c/p>\u003cp>1. 每天坚持英语听说练习，在年底让自己的英语水平上一个大台阶\u003c/p>\u003cp>2. 每周六坚持英语公益讲课\u003c/p>\u003cp>3. 通过项目集管理认证（PgMP）考试\u003c/p>\u003cp>4. 寻找一份更好的工作机会\u003c/p>\u003cp>5. 坚持运动，体重保持在65kg\u003c/p>\u003cp>6. 学习时间管理课程，管理好自己的时间\u003c/p>\u003cp>等到2017年底总结时，才发现，好吧，6个目标之中只有第4个目标算是实现了。其余的，要么刚开始没多久就搁置了，要么半程中不了了之。分析下来，目标之所以没有全部达成，除了目标太多以及高估自己的能力之外，最重要的一点，就是没有给这些目标设定一个合理的优先顺序。\u003c/p>\u003cp>&nbsp;【分享A2便签】\u003c/p>\u003cp>重新思考了一下2018年的年度目标，主要有以下几个：\u003c/p>\u003cp>1. 拆书法从入门到进阶，成为合格的拆书家\u003c/p>\u003cp>2. 考取初中英语教师证\u003c/p>\u003cp>3. 坚持英语学习，在年度内上一个台阶\u003c/p>\u003cp>4. 练习硬笔书法，达到让自己比较满意的程度\u003c/p>\u003cp>5. 成为公司项目管理方面的内部讲师\u003c/p>\u003cp>根据以上“先后次序的考虑”拆解的结果，我计划在两周之内，给2018年年度目标排列下优先顺序。具体做法如下：\u003c/p>\u003cp>5个年度目标，将按照以下4个指标分别进行评估，次序最优先者得5分，次序最低者得1分。汇总各指标的总分，总分越高则该目标优先顺序越高，总分越低则优先顺序越低。\u003c/p>\u003cp>4个指标：\u003c/p>\u003cp>1. 哪个目标，是由于过去的某种经历而有所坚持的，而非看重于未来收益？（注：为方便计算，目标越是基于未来收益考虑，则该目标得分越高）\u003c/p>\u003cp>2. 哪个目标，能最大程度的提升自己的综合竞争力？\u003c/p>\u003cp>3. 哪个目标，是自己内心渴望实现的？\u003c/p>\u003cp>4. 哪个目标， 能真正扩大自己的影响圈？\u003c/p>\u003cp>好了，今天跟大家分享的TF1-1打怪晋级到此为止。谢谢大家的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1529843583000,"updated_at":1529844194000,"ria":true},{"id":4996,"topic":"林妹妹TF1-2过级","learn_goal":"组织高效会议","remark":"林妹妹TF1-2过级","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"林妹妹","city":"石家庄"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"大家好，我是林妹妹，今天我要拆书过的等级是TF 1-2。我就用大家熟悉的三个便签法来介绍下自己，向日葵、PPT制作者和营养师是我给自己的三个便签。\r\n1）我性格开朗、乐观，一直自诩自己是属向日葵的，内心充满阳光；\r\n2）过去的两年里，业余时间我通过线上课程、阅读书籍、参加训练营等方式学习PPT制作，目前还在持续进阶，希望通过自己的一技之长可以为身边的朋友带来一些帮助；\r\n3）我已经通过了ACI注册营养师的考试，凭着自己的热情和毅力，期待自己能够成为一名出色的营养师。\r\n 我今天拆的书是《卓有成效的管理者》，这本书的作者彼得·德鲁克，是管理学科开创者，他被尊为“大师中的大师”、“现代管理学之父”，他的思想传播影响了130多个国家。这本书也获得了“启蒙中国现代管理第一书”的美誉。","ratings_count":2,"texts":[{"id":8091,"quote":"\u003cp>原文片段：R《卓有成效的管理者》P67&nbsp;&nbsp; 有效的会议\u003c/p>\u003cp>&nbsp;有效的管理者在会议开始时，会\u003cstrong>先\u003c/strong>说明会议的目的和要求达成的贡献。\u003cstrong>同时\u003c/strong>，他还要设法让会议紧紧围绕着主题。他绝不会使会议成为一次摆龙门阵的机会，任大家随便发言。当然，如果会议的目的是在激发大家的思想和创见，他也不会仅让某一个人滔滔不绝。他会刺激每一位与会人员的发言兴趣。但是\u003cstrong>在会议结束之前\u003c/strong>，他会回到开场所介绍的主题，使会议获得的结论与主题相符。\u003c/p>","explains":"\u003cp>&nbsp; 对于职场人士来说，会议在工作中非常普遍，而且往往是职位越高的管理者，参加的会议也越多，各种讨论会、协调会、项目例会等等。即使是刚刚走向工作岗位的职场小白，也少不了参加公司安排的一场又一场新员工培训会。然而，当我们回顾自己参加过的一场场会议时，是否会感慨大量的时间浪费在了会议上。曾经听同事调侃道“人生太短，经不起太长的会议”，那怎样做才能让会议更有效？\u003c/p>\u003cp>&nbsp;&nbsp;我提炼了十八字箴言：会前明确目的，会中围绕主题，会后归纳结论。\u003c/p>\u003cp>1）&nbsp; 会前明确目的是前提。如果会议的组织者连开会的目的都不清楚，那这会议就纯属浪费时间了。\u003c/p>\u003cp>2）&nbsp; 会中围绕主题是核心。想必大家肯定经历过开着开着会，就偏离主题了。跑偏的情况时有发生，这时候需要有人及时拉回到轨道上，不然讨论一堆和主题不相关的，又是在做无用功了。\u003c/p>\u003cp>3）&nbsp; 会后归纳总结是保障。大家参加会议，最后常常以 “今天的会议到此结束”作为收尾。然而真正有效的会议，临结束前，要和会议开场相呼应，要对会议得出的结论或是成果进行总结，并且明确下一步具体的行动。这样才让参会的人对于会议的成果及自己的行动有了清晰的了解，才真正达到了会议的目的。\u003c/p>\u003cp>最后补充一点，对于采用头脑风暴旨在激励每个人提供创意的会议，一定要避免个人主义，要做到雨露均沾，让每个人都有机会发言。\u003c/p>\u003cp>&nbsp; &nbsp;接下来，我举一个工作当中的一个例子。我是一名IT从业者，从事烟草行业信息系统的建设。上周甲方组织我们项目组和另外一个厂家的项目组，召开了关于系统融合的讨论会。会议提纲提前一周发送给我们，会议过程中也依照提纲的内容进行了逐项讨论，最后明确了会议的讨论成果和各方下一步的工作内容。在我看来，这是一场高效且有成果的会议。\u003c/p>","interaction":"\u003cp>A1:我刚才分享了自己在工作中的一个例子，接下来请大家思考下，自己在职场中曾经参加或是组织过的一场会议，会议的过程是怎样的场景，是否是一次很高效的会议。\u003c/p>\u003cp>&nbsp; &nbsp;我们按照这条中轴线，分成左右两组。接下来就请每个人回忆自己在工作或生活中参加过的一个会议的场景，回忆下会前、会中、会后分别是怎样的，在小组内分享。5分钟后，我们请一位伙伴做分享。\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>案例分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; \u003c/strong>&nbsp;Mona：我上周刚参加完本月的区域例会，参会的有我所在区域的6个职能岗负责人（人力、培训、财务等）和1个区总。会议过程中，基本都是区总在和其中的某一个岗位一对一地聊，尤其是和财务岗负责人，聊了半个多小时。期间其他人就干瞪眼，什么也做不了。最后，整个会议持续了三个多小时，然而做为参会人，除了自己和领导沟通的十几分钟，其他时间都白白浪费了。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;A2:最后请各位根据自己对今天片段的理解，结合我提炼的会议十八字箴言：“会前明确目的，会中围绕主题，会后归纳结论”，思考如何将今天所学的方法应用到自己最近即将参加或是主持的一场会议，让会议更加高效。\u003c/p>\u003cp>&nbsp; &nbsp; 请大家今写出自己的A2便签，也就是自己的下一步行动。要提醒大家的是，这个行动决不能是空喊口号，应该是具体的做法，有明确的时限和可观测的结果，也就是通过自己怎样的行动预估会达到的效果。给大家2分钟，写一下。\u003c/p>\u003cp>&nbsp;\u003cstrong> &nbsp;案例分享：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;Mona：我要在下周三之前，找区总沟通关于月例会召开时间和方式的问题，将现阶段集中开月例会存在大量时间浪费的问题进行说明，并建议将集中开会改为不定期的一对一沟通，针对问题联系对应职能部门进行沟通，而不是漫无目的地聊，这样一来，每个参会者的可以节省2小时左右的工作时间，达到提升工作效率、会议更加高效的目的。\u003c/p>\u003cp>&nbsp; &nbsp;总结：\u003c/p>\u003cp>&nbsp; &nbsp;今天我向大家分享了如何让会议更加高效的三步法则，希望无论是在职场的会议中抑或是生活的沟通中，大家都能应用这个方法，让我们的会议和沟通更加高效。\u003c/p>\u003cp>&nbsp; &nbsp;愿每个人都成为卓有成效的管理者。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1523775653000,"updated_at":1523775653000,"ria":true},{"id":4975,"topic":"林妹妹1-1过级","learn_goal":"林妹妹TF1-1","remark":"一群平凡的人，能做出不平凡的事业吗？这是完全可以做到的，只要我们组织中的每一个人都做到卓有成效。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"林妹妹","city":"石家庄"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>&nbsp; &nbsp;大家好，我是林妹妹，今天我要拆书过的等级是TF 1-1。我就用大家熟悉的三个便签法来介绍下自己，向日葵、PPT制作者和营养师是我给自己的三个便签。 1）我性格开朗、乐观，一直自诩自己是属向日葵的，内心充满阳光； 2）过去两年里，业余时间我通过线上课程、阅读书籍、参加训练营等方式学习PPT制作，目前还在持续进阶，希望通过自己的一技之长可以为身边的朋友带来一些帮助； 3）上周刚刚参加了ACI营养师的考试，凭着自己的热情和毅力，期待自己能够成为一名出色的营养师。\u003c/p>\u003cp>&nbsp; &nbsp;“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习。以通过考试为目的的学习，是以知识为中心，而拆书则是强调以学习者为中心，要用知识关联学习者的经验、规划具体的运用场景。拆书，重要的不是快速找到书中的重点，那跟我其实没太大关系，重要的是拆书能不能为我创造价值、为我解决问题。\u003c/p>\u003cp>&nbsp; &nbsp;拆书法分为供个人学习的拆书法和供组织学习的拆书法：个人学习通过运用“便签学习法”.，让人读一本致用类图书就能达到参加同主题培训的效果；组织学习依靠RIA现场学习”，由拆书家将一本书加工成一场现场培训，引导和促进一群人把知识拆为己用。以学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>&nbsp; “拆书帮”是基于拆书法的学习爱好者社群，表现为各地的“拆书帮分舵”，其使命是“释放学习促进者的能量”，帮助更多学习爱好者成为拆书家。我很开心能够加入拆书帮这个大家庭，在成长的道路上和志同道合的伙伴共同进步。\u003c/p>","ratings_count":2,"texts":[{"id":8067,"quote":"\u003cp>\u003cstrong>《卓有成效的管理者》　\u003c/strong>作者：彼得·德鲁克\u003c/p>\u003cp>\u003cstrong>时间对管理者的压力　\u003c/strong>\u003cstrong>（\u003c/strong>\u003cstrong>P27\u003c/strong>\u003cstrong>－P28\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>管理者经常受到种种压力，迫使他不得不花费一些时间在非生产性的和浪费时间的事务上。身为管理者，不管他是不是经理人，总有许多时间耗用于毫无贡献的工作上。大量时间都不可避免地浪费了。而且他在组织中的地位越高，组织对他的时间要求往往越大。\u003c/p>\u003cp>有一家大公司的负责人告诉我，他在担任公司总经理的两年中，除了圣诞节和新年元旦两天之外，每天晚上都有应酬。凡是宴会，都是“公事”，每一次都得花几个小时，而他又非参加不可。不管是欢送服务满50年的老同事退休，还是宴请与公司有往来的政府官员，总经理都需要出席，参加这种会见是他的一项任务。这位总经理对这类应酬并不抱幻想，他知道这种饭局对公司发展没什么好处，而他本人既对此没有兴趣，也不认为这有助于自我发展，但他仍然必须出席，仍然需要高兴地参加宴会。\u003c/p>\u003cp>诸如此类的时间浪费，实在不胜枚举。公司一位重要客户若打来电话，业务经理绝不敢说：“等一下，我太忙了。”也许这位大客户，谈的是上星期六的一场桥牌，或是他的千金考上了理想的大学，但业务经理不能不洗耳恭听。医院院长得出席每一次医务会议，要不然所有的医生护士和职员都会认为院长瞧不起他们。政府官员也同样得忙于应付议员们的来访和了解某些情况，而那些情况也许只要随手一翻电话簿或是《世界年鉴》，就马上可以得到。这样的事，整天都在不断地发生。\u003c/p>\u003cp>非经理人员也不见得好到哪里。他们也同样会受到各种占用时间的要求的轰炸，这对他们的生产力一点作用也没有，但他们却不能不应付。\u003c/p>\u003cp>每一位管理者的时间，都有很大部分是被浪费掉的。表面上看起来，每件事似乎都非办不可，但实际上却毫无意义。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp;我们服务于所在的组织，用自己的知识、行动和决策影响组织的绩效，是一名管理者；抑或在生活中，每个人都是管理者，主宰自己的人生。\u003c/p>\u003cp>&nbsp; &nbsp;然而，现实的情况是，我们把大量的时间浪费在了收效甚微甚至是毫无成效的事情上，例如，出席各种又臭又长的会议、参加毫无兴趣的聚会、疲于应对各种琐碎而又重复的日常事务、代人写发言稿……迫于外界的种种压力或是自身极强的使命感，我们做了大量这些内心原本并不很乐意做的事，也因此浪费了大把的时间。\u003c/p>\u003cp>&nbsp; &nbsp;为什么会出现这种情况呢？\u003c/p>\u003cp>&nbsp; &nbsp;过高地估计自己的重要性。当我们身处其中，总想当然地认为这件事与自己有莫大的关系，觉得自己如果不参与这件事就没法顺利进行，所以就承担了很多没有成效的事务。\u003c/p>\u003cp>然而，当我们回顾自己过往的时间都去哪儿了，会意识到自己在某些事务中的重要性并没有那么高，并不是所有的事都要亲力亲为、非我莫属。内心要清楚哪些事是真正对自己重要的，适当拒绝、有所取舍，才能将更多的时间和精力投入到更重要的事中，让自己有所成，不辜负我们最美的年华。\u003c/p>","interaction":"\u003cp>A1: &nbsp; 我所在的项目组要承担甲方已经上线的财务核算、供应链、国有资产等多个业务系统的日常维护工作。目前项目共有四名成员，由我和另外一名经验丰富的同事（赵总）带两个新人。这周恰逢月末，各个系统需要结账，系统出现的问题也比较多。昨天我们办公室的电话一直响不停，QQ也一直不断地接受到新消息。因为赵总和我的工作年限较长，一方面甲方和我们俩比较熟悉，另一方面我们经验相对丰富，解决问题比较快。结果导致我们两人一整天花了大量的时间处理很多重复性问题，像是分配人员的权限、调整打印模板等等，自身并没有因此得到提升，而领导安排我编写的一个项目售前方案，虽然很重要却毫无进展。\u003c/p>\u003cp>&nbsp; &nbsp; 与忙得不可开交的赵总和我形成鲜明对比的，是项目上的两个新人。他们有充足的时间，却觉得无事可做，他们苦于无法快速掌握系统和业务的相关知识， 整天漫无目的地看项目文档，没有什么收获，于他们而言，大把的时间也白白浪费掉了。\u003c/p>\u003cp>虽然项目组成员的工作经验和职级都有不同，但每个人都感受到自己有太多的时间浪费在了没有成效的事情上。\u003c/p>\u003cp>A2:鉴于项目成员的现状，我准备采取如下行动：\u003c/p>\u003cp>&nbsp; &nbsp;下周一(4月2日)和赵总沟通，将我们目前的工作重心进行调整：一方面是让新人有事可做、有所成长。将我们目前接到的一些基础性问题交由新人处理，并由他们向甲方反馈处理结果，同时从下周一起，利用一周的时间让新人逐渐承接起接听客户电话等相关的初级工作，快速承接起系统维护的工作，让他们的工作内容更丰富，充分利用时间创造价值，提升能力；另一方面是赵总和我将把更多的时间投入到价值更高的事情上，包括新产品的学习、客户关系经营等，对于项目而言会有更高的产出。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1523159835000,"updated_at":1527996059000,"ria":true},{"id":4926,"topic":"学习有效之聚焦贡献","learn_goal":"如何学会聚焦贡献","remark":"相信你一定读过管理学的圣经——《卓有成效的管理者》，或者你正在准备读他的路上。\r\n可是，书中告诉我们的“卓有成效”要怎样才能实现呢？来紫禁之巅，让我们一起，试试看吧。","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"鼓","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"开场： 开场： 今天给大家带来的这本书，是《卓有成效的管理者》 F-彼得德鲁克，管理学学科的开创者，1966年写下了这本《卓有成效的管理者》，总结了想“卓有成效”必需的五大特点：时间管理、聚焦贡献、有效决策、用人之长和要事优先。 A-比尔盖茨也说过：“在所有的管理学书籍中，德鲁克的著作对我影响最深。”而在德鲁克的众多管理学著作当中，这本书是他最著名的著作之一。因为一般的管理学书籍都在告诉你怎么管你的下属，而这本书，还告诉了你怎么管理你自己。 B-相信大家都读过时间管理、有效决策等等相关的知识，那么我负责任的告诉大家，这本书正是这些知识的本源。通过这本书上教给我们的时间管理的方法，你会觉醒你的时间都去哪了，书上介绍的聚焦贡献，你会开始探索你在工作中真正的价值……总之，如果你想要变得“卓有成效”，多读几遍这本书，会让你在面对变幻莫测的市场和全球化竞争的困惑时得到新的启示。","ratings_count":1,"texts":[{"id":8008,"quote":"\u003cp>学习目标：跟我一起进行此次现场学习后，在面对自己的岗位工作时，不仅是只在意自己的工作内容，而且可以用1思考工作2关联外部3聚焦贡献4审视自身 的方法找到自己实现“卓有成效”的正确路径。。\u003c/p>\u003cp>这本书中给我触动最大的部分，就是聚焦贡献。今天，我给大家带来的这一个拆页，是教会我们作为企业核心人员，如何来做出贡献，从而变得“卓有成效”。片段会有些拗口难懂，我做了一些标记，大家可以着重阅读。今天也会多给大家一些阅读时间，读完可以抬头示意我。如果拆页里你觉得有些不好读懂，没有关系，可以先思考右侧的四个问题，填到空格里。等一下，我们一起来讲解，试试看。\u003c/p>","explains":"\u003cp>我们来一起对比着拆页，看看右侧思考的四个问题。\u003c/p>\u003cp>如果第一个问题中，你的工作是需要脑力劳动的，是需要自己独当一面的，那么恭喜你，你的企业非常的需要你，而且尤其希望你可以“卓有成效”。\u003c/p>\u003cp>那谁来评定你的“卓有成效”呢，正是第二个问题中，你所回答的：会受益的部门。如果他们从你的工作中受益了，你的工作就是“卓有成效”的。\u003c/p>\u003cp>那我们这些专业的人才，怎么来做到“卓有成效”呢？\u003c/p>\u003cp>比如说，你是一个产品设计工程师。那是不是你每天做好自己的设计，然后多加班多干活，就算是一个好员工了呢？拆页背后，根据拆页的内容，我帮大家梳理了四条建议，我们对比着看一看。\u003c/p>\u003cp>1、首先，审视自己的工作。如果你的工作是设计工程师，你的主要工作内容，大多会是产品设计和方案编制。那么第二步，就需要\u003c/p>\u003cp>2、找到与你相关联的部门或者工作。相互协作。这一步需要的是你向外看，找出与你相关联的部门。比如和设计工程师相关联的部门很重要的一个会是销售部门。你的设计思路，产品的特性，有可能直接会影响到销售人员的销量。那么他们从你工作中的收益，就对你的工作起着直接评判的作用。那么第三点，就需要\u003c/p>\u003cp>3、把焦点落到你的贡献上，就是我们第三个问题，我能做些什么贡献可以使销售人员更好卖这份产品呢？这一步，非常关键，你清晰的找出自己能为他人所做的贡献点之后，你才能尽情的发挥你自己的专业优势。比如，要想让销售，从你这里得到益处，那就要思考怎么才能让产品卖的好，是不是就可以更多的关注现在市场上卖的最好的产品都有哪些特质？然后拿这些特质，来指导你的设计呢？到第四步，\u003c/p>\u003cp>4、反思自身的收获与成长。如果你做了第三步中的那些事情，你会发现你做的设计会更有目标性，更有指导性，而组织的整体绩效也会随着你对产品的深入研究而增长。你自己的设计工作，也会因为你比同类的设计师多思考了一步，而更贴近市场，不断得到好评。那么，你这样会不会变得更加“卓有成效”呢？当然，如果这一环节你的答案是否定的，那么你需要重新想想，是不是你前面做的关联外部和所做的贡献方向是不对的，需要重新审视自己了。\u003c/p>","interaction":"\u003cp>刚刚是我举得一个小案例，接下来我们一起来做一个演练：\u003c/p>\u003cp>场景：\u003c/p>\u003cp>马雨，是一个销售经理。他最近很惆怅，他的业绩今年又是全公司第一，但是公司却将年度卓越贡献员工奖颁给了业绩不如他的刘西。他约你一起喝酒，并且抱怨。你运用今天的四步法，怎么帮他进行分析呢？\u003c/p>\u003cp>（背景材料：马雨，坚持销量为王，谁能带来业绩谁就应该是公司的NO.1。经常为了产品卖不出去而去找领导投诉设计部设计的产品不符合市场规律，不好卖。在生产部不能准时交货的时候，更会大发雷霆。当然，马雨敢冲敢干的火爆脾气也帮他年年夺得公司的销量冠军，公司领导对他是又爱又恨。\u003c/p>\u003cp>刘西，入职5年，带领的团队销量持续增长。在重视和客户的交往维护的同时，和公司相接处的业务板块都有很好的交流。每季度会带着销量不好的产品去到生产部经理办公室一坐一天。）\u003c/p>\u003cp>&nbsp;给大家3分钟的时间，思考一下你如果是马雨的好朋友，会怎么帮他分析，使他变得“卓有成效”。可以借助我们拆页边上的问题，也可以添加一些你们自己设计的背景资料。思考完后，请大家一个人扮演马雨，一个人扮演马雨的好朋友，来引导着马雨，用我们的四步法找到变得“卓有成效”的好方法吧。\u003c/p>\u003cp>对话当中，请把你的关键点记录下来，写在咱们拆页的背后。便于大家一会进行公开分享。\u003c/p>\u003cp>马雨：唉……不知道公司咋想的，今年最重视的“卓越员工奖”又没有给我！！！\u003c/p>\u003cp>马雨的好朋友：亲，话不能这么说。你总是只盯着销售的工作……\u003c/p>\u003cp>马雨：咦？这话什么意思？……\u003c/p>\u003cp>好朋友：你觉着你现在工作的主要内容是啥？\u003c/p>\u003cp>马雨：销售啊。把业绩提升啊。\u003c/p>\u003cp>好朋友：那你做销售和公司哪些部门相关呢？\u003c/p>\u003cp>马雨：生产部，要去他那拿货；设计部，要去看产品雏形\u003c/p>\u003cp>好朋友：那这两个部门，你能为他们提供点什么，能让他们设计的更好或者生产的更快呢？\u003c/p>\u003cp>马雨：有客户经常反应我们货总是不能按时到货，设计的产品也不接地气，导致我们的货就不好卖！\u003c/p>\u003cp>好朋友：那你跟他反馈了么？你跟他反馈的时候，有提出具体的不接地气的原因么？\u003c/p>\u003cp>马雨：……没有啊。我干嘛跟他们费那话。\u003c/p>\u003cp>好朋友：那如果你能和他们从客户的角度思考“更加能接地气”的产品设计方案或者多告诉他一些客户的真实声音、新的需求点，你觉得他们愿意接受么？\u003c/p>\u003cp>马雨：没想过哎，应该是会的吧。他们也接触不到客户啊。天天自己天马行空的乱想。\u003c/p>\u003cp>好朋友：你是能接到客户的第一手信息的，这件事只有你知道，你是这两个部门最重要的消息源，那你把客户的关键信息告诉他们，会对他们的工作有帮助么？\u003c/p>\u003cp>马雨：肯定的呀。\u003c/p>\u003cp>好朋友：那他们在你的帮助下设计生产的产品提升了，你是不是也会更好卖呢？\u003c/p>\u003cp>马雨：那当然啊！这么说来，我好像是该试试看，跟他们多交流，告诉一些真实的市场信息，可能我们的产品改进会做的更好。这样我和客户之间的联系，也不仅仅是买卖的关系，还有和公司反馈，获取一手信息的重要联系。我的贡献点好像可以增多了哎。\u003c/p>\u003cp>好朋友：你看，这就对了嘛。好好加油，照这样下去，你会越来越卓有成效，明年的卓越员工，一定是你的！\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>谢谢精彩的分享，其实，刚刚我们这位好朋友，就是从先帮马雨审视工作，再帮找到相关的部门，然后发现与他相关的外界来评判的贡献点，一一突破，让马雨找到了新的工作思路。\u003c/p>\u003cp>那其实，通过这个小练习，我们是不是也发现，在运用这些方法时，不仅可以提问对方，也可以提问自己呢？希望大家回去，给自己留一天的时间，把这四步方法对比自己的工作，安静的思索一下，如果思索过后，别人再次问你的工作是什么，你能在介绍你的主要工作的同时说出你对公司的贡献来的话，那将是我今天最大的荣幸。\u003c/p>\u003cp>谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1522398929000,"updated_at":1522398929000,"ria":true},{"id":4925,"topic":"学习“有效”之聚焦贡献-鼓","learn_goal":"我们的“卓有成效”要怎样才能实现呢？来紫禁之巅，让我们一起，","remark":"相信你一定读过管理学的圣经——《卓有成效的管理者》，或者你正在准备读他的路上。\r\n可是，书中告诉我们的“卓有成效”要怎样才能实现呢？来紫禁之巅，让我们一起，试试看吧。^_^","level":"TF3-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"鼓","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":null,"ratings_count":0,"texts":[{"id":8007,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1522398610000,"updated_at":1522399697000},{"id":4924,"topic":"学习“有效”之聚焦贡献","learn_goal":"书中告诉我们的“卓有成效”要怎样才能实现呢？来紫禁之巅，让我","remark":"相信你一定读过管理学的圣经——《卓有成效的管理者》，或者你正在准备读他的路上。\r\n可是，书中告诉我们的“卓有成效”要怎样才能实现呢？来紫禁之巅，让我们一起，试试看吧。^_^","level":"TF3-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"鼓","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"学习目标：在跟随我完成本次RIA现场学习后，学习者能够在工作场景中，使用“思-问-做-变”的方法，实现从“被动工作”到“主动工作”的转变。\r\n大家好，我是鼓，一个希望用生活小故事来帮你有所改变的拆书进阶者。等下有个小研讨，请大家两两一组。","ratings_count":1,"texts":[{"id":8006,"quote":"\u003cp>【事件场景】\u003c/p>\u003cp>上周五，一直和你合作友好的供货商A公司，突然要把商品价格提高一倍，这个时候你就纠结了，内心有两个小人打架：“我的职责是做好信息的搬运工，这种大事快汇报给领导，交给高层来定夺吧”。另一个小人说：“这件事一直是我在跟进，我要不要再跟供货商多争取一下呢？多争取会不会领导以为我从中得好处呢？”\u003cbr>\u003c/p>\u003cp>我们工作中，很经常会遇到这样要不要多做一些事的纠结。头脑中两个小人打架是常有的事情。\u003c/p>\u003cp>【提问】一般情况下，你最终会选择哪个小人呢？是自己做好分内的事就好了，还是希望为了公司再拼一把呢？\u003cbr>\u003c/p>\u003cp>【影响】做好自己份内的事情，还是做出能对公司有好处的事情，这两个选择总会成为我们在实现工作目标路上的分岔路，一次选不对可能还能绕路回来，但习惯性的选不对就会让你离你的工作目标越来越远。\u003c/p>\u003cp>【解决】怎么样算是选择正确了呢？我今天给大家带来的这本书：《卓有成效的管理者》中第52页中就讲到：重视贡献的管理者，会不被其本身的部门或者专长所限制，他更关注的是自己与组织目标之间的关系。所以他的所作所为会与其他人不同。从而变得卓有成效。\u003c/p>\u003cp>这也是我今天想跟大家分享的内容。德鲁克在这本书中，强调，想要卓有成效，需要聚焦贡献，那我们应该怎么做呢？请大家用2分钟时间阅读拆页，读完的朋友抬头示意。\u003c/p>","explains":"\u003cp>好，大家读完了。我们一起来聊聊贡献。\u003c/p>\u003cp>【强化讲解概念】\u003c/p>\u003cp>小丽下周的汇报需要各个部门协助统计工时，于是你做了一张表，列举了各个员工的工时量，还贴心的做了一个与上月的数据对比。小丽看到后非常开心，因为这些数据帮他的汇报增加了亮点，那么这个时候，你是不是做出了贡献？答案当然是肯定的。\u003c/p>\u003cp>但是，老张的部门统计后，就给小丽发了个短信：部门总共32个人，按规定完成工时要求。这时，老张是不是做了贡献？不是的，老张那只能是叫完成本职工作。说严重点，他那可能只是应付差事。\u003c/p>\u003cp>【知识点逻辑】对比你和老张的不同行为，我们发现，贡献的一个关键要素是什么？是成果，你的这个成果有没有帮助到企业或者企业中的员工实现效能提升。有了，才叫贡献。\u003c/p>\u003cp>【不这么做的坏处】那我们为什么要做出贡献呢？因为你如果想要做出贡献，就需要你去思考你的工作，那如果你不思考工作而只是被动接受领导交代的任务，你的工作绩效还会有所提升么？你的企业还需要你么？你的价值点又在哪呢？ \u003c/p>\u003cp>【适用边界】说到底，聚焦贡献的过程其实是一个从被动工作到主动工作的转换过程。当然，如果你的领导已经明确指示了这件工作不用你再管了，那这个时候，你还要聚焦贡献么？我认为在这件事上是可以不用了，因为你有更多需要关注的更重要的事情，去做出贡献。\u003c/p>\u003cp>【步骤】+【举例】那我们怎么样做才算是聚焦贡献？才能实现从被动工作到主动工作的转变呢？\u003c/p>\u003cp>我给大家带来四步：我们拿开场时候给大家举例和客户谈价格那件事来说。\u003c/p>\u003cp>1、思：我在这件事上，是否愿意作出贡献？这个供货商是我一直跟进的，所以我的答案是yes，我想在我工作中更为精进，所以我会到第二步：\u003c/p>\u003cp>2、问：我能做的贡献是什么？贡献的成果是什么？我快速的想到，如果能找到另一家同样品质的供货商，会不会是公司乐意需求的？于是，到第三步：\u003c/p>\u003cp>3、做：那就先试试看。于是我去找了B\\C两家供货商，对比分析后去找领导：领导，接到A公司的通知今年要涨价5%，我做了一下市场调研，发现整体价格都已经上涨，但是B公司量大的话会有1个点优惠，C公司环保要求更高一些，您看今年是维持A公司的合作还是换公司呢？\u003c/p>\u003cp>这个时候，我们到了，第四步\u003c/p>\u003cp>4、变：有没有发现，你在这个工作的过程中，你从让领导做问答题变成了选择题？而你这件工作的成果是不是可以让公司变得有更多的效能提升？你在实现自己工作目标的过程中，是不是由被动接受变成主动出击了呢。还有就是，你是不是发现你的领导看你的眼神也变得越来越欣赏了呢？\u003c/p>\u003cp>这就是我们因为聚焦了贡献所以产生的转变。\u003c/p>","interaction":"\u003cp>刚刚我举了一个工作中可能会遇到的场景，不知道这个场景是否激起了你心中一些更精彩的小故事呢？接下来，我想请大家两两一组，自己也编一段关于从被动工作然后通过聚焦贡献，然后到主动工作的小剧本，这个小剧本最好是虚拟的一个场景。\u003c/p>\u003cp>在剧本中，请用1分钟来阐述故事的起因，用2分钟来把我们刚刚讲的思、问、做、变的方法运动到当中去，然后再用半分钟，告诉我们故事的圆满结局是什么。\u003c/p>\u003cp>&nbsp;先给大家五分钟的时间来小组内讨论一下，一会请一个小组来跟我们做分享。\u003c/p>\u003cp>&nbsp;好，请一组小伙伴来分享一下你的案例。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>我:故事起因：我在一家公司做app，我老板告诉我有一个需求，是需要把A公司的广告加到我们状态栏上。故事的人物关系有：职员“我”，老板B。\u003c/p>\u003cp>B:我们最近接到A公司的广告，需要加到咱们app的状态栏上面。一周内要完成。\u003c/p>\u003cp>我:我觉得加到状态栏不好吧。状态栏是系统公用的啊。把他改了的话，用户投诉会增大啊。\u003c/p>\u003cp>B:A公司是我们赞助商，必须加！赶紧去做吧。\u003c/p>\u003cp>（于是，我内心开始思考，刚学的四步：1、我愿意做出贡献么?答案是肯定的，我想把这事情做好。于是，我的2问，我能做的贡献是什么？我希望可以同时满足老板和客户的需求。所以，我的3做，如下：）\u003c/p>\u003cp>我:老板，如果我有更好的交互效果的话，能行么？也能达到这种效果\u003c/p>\u003cp>B:一周能搞定么？这效果能实现么？上面说怎么办就怎么办就好了，别多事。改错了，你担着啊？\u003c/p>\u003cp>我:我认为这效果是可以的。如果我们把这个广告加在底部的流动栏里，不仅可以满足广告收益，而且还能提高我们的用户体验，并且还能给我们app带来更多的下载量和用户的浏览量。您觉着这个方案可行么？\u003c/p>\u003cp>B:这么听起来，好像问题也不大。你先试试吧。\u003c/p>\u003cp>（通过这四步，我的领导的思想变化了，他对我的做法也比较满意，我们公司也因此变得收益更大了。）\u003c/p>\u003cp>【结语】谢谢这个精彩案例的分享。我们\u003cstrong>大家也发现，我们这四个步骤，其实就是帮我们越来越聚焦于贡献的这个过程。思：找出意愿，问：划定范围，做：锁定目标，变：实现提升，希望大家可以回去在工作中，也多多尝试，然后变得越来越卓越。我是鼓。谢谢大家今晚的陪伴。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":8035,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1522393939000,"updated_at":1522679204000,"ria":true},{"id":4923,"topic":"学习有效之要事第一","learn_goal":"要怎样才能实现卓有成效","remark":"相信你一定读过管理学的圣经——卓有成效的管理者，或者你正在准备读他的路上。\r\n可是，书中告诉我们的“卓有成效”要怎样才能实现呢？来紫禁之巅，让我们一起，试试看吧","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"鼓","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"大家好，我是鼓，一个希望用平淡故事来帮助你有所感悟的拆书进阶者，希望每次都能有一点点有用的地方帮助到你。在开始前，大家先分一下小组，等一下有一个小研讨，我们两两一组，跟身边的伙伴搭成2人对子。\r\n今天给大家带来的这本书，是《卓有成效的管理者》\r\nF-feature彼得德鲁克，管理学学科的开创者，1966年写下了这本《卓有成效的管理者》，总结了想“卓有成效”必需的五大特点：时间管理、聚焦贡献、有效决策、用人之长和要事优先。\r\nA-advantage比尔盖茨也说过：“在所有的管理学书籍中，德鲁克的著作对我影响最深。”而在德鲁克的众多管理学著作当中，这本书是他最著名的著作之一。因为一般的管理学书籍都在告诉你怎么管你的下属，而这本书，还告诉了你怎么管理你自己。\r\nB-benefit相信大家都读过时间管理、刻意练习甚至包括你熟知的1w小时定律等等相关的知识，那么我负责任的告诉大家，这本书正是这些知识的本源。通过这本书上教给我们的时间管理的方法，你会觉醒你的时间都去哪了，书上介绍的聚焦贡献，你会开始探索你在工作中真正的价值……总之，如果你想要变得“卓有成效”，多读几遍这本书，会让你在面对变幻莫测的","ratings_count":1,"texts":[{"id":8005,"quote":"\u003cp>学习目标：在跟随我完成本次RIA现场学习之后，学习者能够在下次需要分配手头各种事物的优先次序时，可以运用“往远看-重机会-不盲从-有突破”这四条“重要原则”，来挑选出自己真正的“要事”。\u003c/p>\u003cp>卓有成效的重要一项技能，就是学会分配自己的事情，可以做到“要事优先”，所以，我们今天来拆的第一个片段，就是“如何来挑选你的要事”。请大家看一下我们的拆页READING那一部分。读完抬头示意我就好。\u003c/p>","explains":"\u003cp>拆页中给了我们帮助抉择什么是“要事”的四个可参考的重要原则。稍微有些抽象，我们来举个栗子看看。\u003c/p>\u003cp>最近公司开始要发展国际化路线，同事们都积极准备开始补习英语，每天都在朋友圈开始打卡。可我的拆书到了2-3碰到了瓶颈，需要重拆2级，本来计划的10月拆到3级的计划破灭了。\u003c/p>\u003cp>那么我该怎么抉择我的要事呢？我们来对比一下拆页：\u003c/p>\u003cp>1、前两条我们放在一起看，重将来而不是过去，重机会而不只是困难。我给他总结了六个字：往远看，重机会。我的拆书虽然目前遇到了一些困难，但随着级别难度加大，对我的逻辑思维和语言表达能力提升也会加大，这些能力正是我之后一段时间内最需要的两种能力。\u003c/p>\u003cp>2、不盲从。公司是要国际化，但我自己的岗位实际是用不到英语的，现在一窝蜂的去跟着大家学英语，对我个人的帮助比起拆书而言，显得力量弱了许多。\u003c/p>\u003cp>3、目标要高要有新意，这点很重要。我们每天有很多紧急的事情要做，但真正重要的其实只有1-2个，让我们突破舒适区的事情才能是为要事。如果我可以轻轻松松的就拆过3级的话，那拆书就不能成为我的要事了，因为他不能帮助我实现个人突破。这也再一次印证了刚刚讲的往远看，重机会。\u003c/p>\u003cp>那么有的小伙伴会问，这里每一条都符合才是“要事”么？我认为是不需要的，正如拆页上所说，这些都是帮助你找到勇气的方法，真正有勇气开始判断哪件事是要事了，真正的要事其实就已经在你的内心浮现了。\u003c/p>","interaction":"\u003cp>分步催化的A2-1：\u003c/p>\u003cp>请大家跟我一起想一想，下周一早上，你坐到办公桌前，看到桌上周五留下的一摞资料，抬起手来准备再接着做的时候，你突然又想起来该收一下邮件，打开邮箱你发现领导早上给你转了封客户邮件，需要马上联系，这时候，你又瞥见电脑桌面上倒计时里，赫然提醒你离你提交最终方案稿还剩5天。。。。啊。我的天哪……那么，请大家思考一下，下周一，你做到办公桌前面，可能会需要你下周处理的事情，都有哪些？请列在工作表当中。给大家2分钟的时间。赶紧开始吧。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>催化应用（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>\u003cstrong>待\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>办\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>事\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>件\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>事件\u003c/strong>\u003cstrong>A\u003c/strong>\u003c/p>\u003c/td>\u003ctd>我要写一份项目结题报告\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>事件\u003c/strong>\u003cstrong>B\u003c/strong>\u003c/p>\u003c/td>\u003ctd>我要参加一个领导力年会\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>事件\u003c/strong>\u003cstrong>C\u003c/strong>\u003c/p>\u003c/td>\u003ctd>给公司建立一套培训体系\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>事件\u003c/strong>\u003cstrong>D\u003c/strong>\u003c/p>\u003c/td>\u003ctd>我要上传上月拆书的实录\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>分步催化的A2-2：\u003c/p>\u003cp>那么，在下周要做的这些工作中，如果用刚刚的这四个重要原则来做参考，哪件会是你的最重要的事情呢？请大家邀请你的同桌小伙伴帮你分析一下，看看哪件事才真正的是你的“要事”。\u003c/p>\u003cp>往远看——重机会——不盲从——有突破\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>待办事项\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>\u003cstrong>事件\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>目前遇到的问题（不盲从）\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>会给你带来的机会\u003c/strong>\u003cstrong>/\u003c/strong>\u003cstrong>帮助（重机会）\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>你自己希望的发展方向（往远看）\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>希望目标（有突破）\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>1\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>事件C\u003c/p>\u003cp>给公司提交一份培训体系建立方案\u003c/p>\u003c/td>\u003ctd>之前公司没有这个体系，大家也都觉着难，躲着这个活，我自己也没做过，需要找大量的资料。可能会比较辛苦。\u003c/td>\u003ctd>可能成为这个领域的专家\u003c/td>\u003ctd>我本身是想在3年内成为HR方面的专家，并且可以担任公司的培训负责人。\u003c/td>\u003ctd>这次机会正好是我自己发展方向上相一致的工作，可以帮我在此领域得到更多的收获，也会为我成为公司培训负责人积累经验。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>2\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>3\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>4\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>通过对比分析，学习者找到了他的要事：事件C。并做出决定：每天都给这件要事留下来至少3小时整快的作业时间，在一个月内完成这份方案。其余日常的零散时间，去处理当前不那么紧急的事情。\u003c/p>\u003cp>（简单点评：谢谢大梦的分享，在对比了四件事情后，找到了和自己的期待方向最为一致的，事件c，虽然看起来暂时会辛苦一些，但是这件事做好了，对于自己是好处多多的。恭喜大梦，找到了自己的要事。）\u003cbr>\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>要事第一，在很多管理学的书籍中都会有涉及。今天在这里拆解这个片段，也是又一次印证了这个理论在管理当中的重要性。希望大家在日常工作的时候，多多思考多多使用。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1522391497000,"updated_at":1522391497000,"ria":true},{"id":4622,"topic":"掌握自己的时间，运用记录，管理，安排三个步骤管理时间，优化自","learn_goal":"掌握自己的时间，运用记录，管理，安排三个步骤管理时间，优化自","remark":"","level":"TF2-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"唐云霞","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"大家好，非常高兴能在这里与大家相遇。我是唐云霞，我的三个标签是：成长中的培训师；写作；烘焙。欢迎跟我有相同便签的下来链接。\r\n【学习目标】跟随我完成本次RIA现场学习后，学习者能够运用记录，管理，安排3步骤管理时间，并能优化自己的时间安排；【F】《卓有成效的管理者》这本书作者是美国彼得德鲁克，他开创了现代管理学，被称为现代管理学之父，本书讲述了优秀管理者应具备的5大特征【A】这本书也因此成为开启现代管理学的第一书而畅销世界，至今被管理界比尔盖茨，张瑞敏等拜读和推荐，是一本能让人终生受用的案头必读书。【B】各位有没有觉得自己每天都很忙，但一天结束后又发现没做成什么事？或者是事情太多杂乱无章，想分摊给下属或同事，但又不知道该如何授权和安排？你想掌控自己的时间，让你对事情的决策和安排变得更准确更卓有成效，都可以从这本书中得到启发。","ratings_count":1,"texts":[{"id":7661,"quote":"\u003cp>\u003cstrong>掌握自己的时间\u003c/strong>\u003c/p>\u003cp>关于管理者任务的讨论，一般都从如何做计划说起:。这样看起来很合乎逻辑。可惜的是管理者的工作计划，很少真正发生作用。计划通常只是纸上谈兵，或只是良好的意愿而已，很少能够实现。\u003c/p>\u003cp>根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占用的时间。最后，再将“可自由运用的时间”,由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\u003c/p>\u003cp>·记录时间;\u003c/p>\u003cp>·管理时间;\u003c/p>\u003cp>·统一安排时间。\u003c/p>\u003cp>有效的管理者知道，时间是一项阻制因素。任何生产程序的产都会受到最稀有资源的制约。而在我们称之为“工作成就的生产程序里，最稀有的资源，就是时间。\u003c/p>\u003cp>时间也是最特殊的一项资源。在其他各项主要资源中，资金一项实际上是相当充裕的。我们很久以前就已经了解到，制约经济增长与经济活动的，并不是资金的供给不足，而是对资金的需求不大。此外另一个限制因素是人力，总还是可以雇到人才，尽管要雇用到足够的优秀人才并不容易。只有时间，是我们租不到，借不到，也买不到，更不能以其他手段来获得的。\u003c/p>","explains":"\u003cp>【what】这个片段提到，有效的管理者并不一开始就执行计划，而是先认清自己的时间用在什么地方。记录时间知道时间花在什么地方以后，再根据现状来调整，哪些事情的时间要增加/减少/授权/消除，调整以后，再对时间统一安排。【how】那如何掌握自己的时间呢，有3个步骤：\u003c/p>\u003cp>第一步：记录时间；写下你一天/周，要做什么事情\u003c/p>\u003cp>第二步：管理时间；根据记录判断1、哪些事情根本不必做，2、哪些事情可以让别人替代；3、哪些事情需要减少或增加时间\u003c/p>\u003cp>第三步：统一安排时间；完成第二步后，重新排列整理；【举例】拿我自己来说吧，我回想下班后都在干什么，好像啥也没干。 然后我开始按片段要求，每天用APP记录自己一天的时间安排；下班后，7点过到家吃完饭，8点到10点看电视/玩手机，10点哄孩子睡觉，然后拖地，11点玩手机逛淘宝，12点洗漱睡觉。记录后分析后纠正，1、看电视是根本不必的，要消除，2、哄孩子睡觉/拖地不用每天都干，跟老公交换替代，3、逛淘宝时间减少到半小时内，读书需要增加1个小时。重新定义后，我晚上下班后的时间变成了：8-9点陪孩子玩，9-10点看书，10-11点和老公轮流哄孩子睡觉和做家务，11-12点洗漱玩手机逛淘宝追剧；结果就是，当我每记录一次，行为会纠正一次，不再沉迷逛淘宝看电视《卓有成效的管理者》买了3年终于上个星期看完了。【预防异议】&nbsp;有的小伙伴会说，我知道时间管理很重要，可按你的方法，要记录时间还要管理安排太麻烦了，这也浪费精力。感觉有点麻烦，但我在运用的过程中发现；有了记录就知道时间花在哪，就会刻意去纠正，哪些该增加减少，哪些可替代消除，重新排列后再来统一安排，当我做完以后才恍然大悟，这不但没浪费精力，反而效率高了很多，【适用边界】学了掌握自己的时间是不是所有的时间都要管理呢？？显然不是，比如每周二固定都要开会，是你控制不了的，所以这里的时间管理，指的是你可控制的时间，可以由你自由安排的那部分时间。\u003c/p>","interaction":"\u003cp>【分组】请大家设想一下，下周一到公司后，打开电脑坐在椅子上，想想今天要做哪些事儿？或者说，你下班后回到家吃完饭，坐在沙发上想一想你接下来要做哪些事？想好以后在小组里分享。时间3分钟，稍后邀请小伙伴进行分享。\u003c/p>\u003cp>小伙伴分享：&nbsp;自己负责公司年会，下周要买礼品，排节目，租衣服，年底福利计算等等，一堆事情杂乱无章。\u003c/p>\u003cp>设想一下：接下来，请大家思考，还是刚才大家分享的那个场景做那些事情，应用今天学习掌握自己的时间的方法，规划你的时间管理和安排，看看以后你准备怎么做呢？想好以后在小组里分享。时间3分钟，稍后邀请2名小伙伴进行分享。\u003cbr>\u003c/p>\u003cp>小伙伴分享：&nbsp;下周有做的事情有：组织散学典礼、班主任会议、科研分析报告，教学质量分析报告，还有登报挂失身份证，通过今天的运用时间管理方法：散学典礼可以让助理替代，我只出席当天会议；那我下周工作变成：班主任会议、科研分析报告、教学质量分析、挂失身份证。\u003c/p>\u003cp>【结语】以上就是我2-2的全部内容，我是唐云霞感谢聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1517719020000,"updated_at":1517719020000,"ria":true},{"id":4596,"topic":"找回我们浪费的时间","learn_goal":"让我们学习将非生产性的和浪费时间的活动找出来，尽可能将这类活","remark":"卓有成效是管理者必须做到的事，但是在所有的知识组织中，每一位知识工作者其实都是管理者——即使他没有所谓的职权，只要他能为组织做出突出的贡献。 管理者的成效往往是决定组织工作成效的最关键因素；并不是只有高级管理人员才是管理者，所有负责行动和决策而又有助于提高机构工作效能的人，都应该像管理者一样工作和思考。本周就请你跟我们一起学习将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。","level":"TF1-2","duration":15,"status":29,"type":0,"chaishujia":{"username":"AURORA佳","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"大家好，我的名字叫：王佳，我在群里英文名字：欧若拉。来到杭州有三年了，培训出身，群里出了名的“孩子王”。我2018的目标是想成为一名榜上有名的拆书家。今天我给大家带来的片段来自彼得•德鲁克《卓有成效的管理者》，它是德鲁克最著名的管理学著作之一这本书主要是论述了一个管理者如何做到卓有成效。倾注了德鲁克极大的心血。\r\n分组：首先请大家两人一组，我们现场拆书与您自己使用RIA略有不同，您无需读过这本书，只需要跟着接下来的步骤我们一同来参与即可。","ratings_count":1,"texts":[{"id":7631,"quote":"\u003cp>《卓有成效的管理者》作者：彼得·德鲁克\u003c/p>\u003cp>（管理者）要做系统的时间管理。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以试问自己下列几个问题。\u003c/p>\u003cp>1、首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录表拿出来，逐项逐项地问：“这件事如果不做，会朋什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>2、第二个该问的问题是：“时间记录表上的哪些活动可以由别人代为参加而又不影响效果？”\u003c/p>\u003cp>3、还有一项浪费时间的因素，是管理者自己可以控制并且可以消除的。这项因素是：管理者在浪费别人的时间。\u003c/p>","explains":"\u003cp>WHAT 管理要管什么？一般人会说管人管事。而“管理学之父“彼得·德鲁克认为，管理者先管时间。\u003c/p>\u003cp>HOW时间管理的重要性我们不必多说，这里德鲁克给出了管理者管理时间的3个办法。在每天中以小时为单位记录工作时间的记录表中：\u003c/p>\u003cp>1、第一问：“对每一条依次提问：这件事如果不做，会朋什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003c/p>\u003cp>2、第二问：“这件事可以由别人代为参加吗？”\u003c/p>\u003cp>3、第三问：“这件事有没有浪费别人的时间。”\u003c/p>\u003cp>如果你接触过一般的“时间管理“课题，对比一下就会发现，这3条中有2条都是管理者特有的时间管理问题。哪两条？第2条和第3条。\u003c/p>\u003cp>既能让下属做好的事情，若我自己去做，就是浪费时间；因为只有管理者才有权占用时间，也只有管理者才可能浪费别人的时间而不自知。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>现场分组\u003c/p>\u003cp>激活经验：从过去选一个对你来说比较典型的工作日。拿一张白纸，以30分钟为单位，写下这一天你都做了些什么。要稍微具体些，比如不能只写“开会“，要写会议内容。（约2分钟）\u003c/p>\u003cp>请每组人员一对一分享，拿着对方的时间记录表，一项一项问德鲁克曾建议的问题。“这件事如果不做，会有什么后果？“”这件事可以由别人代为参加吗？“”这件事有没有浪费别人的时间？“（约4分钟）\u003c/p>\u003cp>备注：现场活动注意事项 ：\u003c/p>\u003cp>（1 ）讲自己的故事，关注自己的技能提升。\u003c/p>\u003cp>（2 ） 不点评他人的发言，不给他人的故事/问题提建议\u003c/p>\u003cp>A2\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>检查别人的时间记录表，反省自己的时间记录表，你认为自己可以做出哪些改变或采取哪些行动？请用1分钟规划自己的应用和行动步骤（A2），越具体越好。并且估算出如果这么做了，每个月能为你节省多少时间。（约3分钟）\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1517299008000,"updated_at":1517299008000,"ria":true},{"id":4550,"topic":"如何管理自己的时间","learn_goal":"通过记录时间，并做到时间的统计、分析、回馈，最终提高时间效率","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"陈小媚","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"【自我介绍】大家好，我是媚如，在国内最大的考试公司上班，负责广东、广西的校园渠道业务。我今天准备的是是TF1-2分享。【分组】现在给大家分组，由我的左手边开始两两一组。【图书介绍】先给大家介绍今天的书籍《卓有成效的管理者》，作者是美国作家彼得德鲁克，是当代国际上最著名的管理学家，被称为“大师中的大师”。他的《卓有成效的管理者》已成为全球管理者必读的经典。这本书论述了管理者的成效往往是决定组织工作成效的最关键因素，同时组织里的每一个人都是管理者，所有负责行动和决策而又有助于提高机构工作效能的人，都应该像管理者一样工作和思考。如何卓有成效？书中的第一个点讲的是记录并分析时间的使用情况，今天分享的就是“记录并分析时间的适用情况”的片段内容。","ratings_count":2,"texts":[{"id":7572,"quote":"\u003cp>\u003cstrong>如何诊断自己的时间：\u003c/strong>\u003cbr> &nbsp;&nbsp;&nbsp; 要提高管理者的有效性，第一步就是记录其时间耗用的实际情形。\u003cbr> &nbsp;&nbsp;&nbsp; 许多有效的管理者都经常保持这样的一份时间记录，每月定期拿出来检讨。至少，有效的管理者往往以连续三四个星期为一个时段，每天记录，一年内记录两三个时段。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间耗用得很乱，浪费在种种无谓的小事上。经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免再回到浪费的状态上去。\u003cbr> &nbsp;&nbsp;&nbsp; 第二个步骤就是要做到有系统的时间管理。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。要做到这一步，可以试问自己下列几个问题。\u003cbr> &nbsp;&nbsp;&nbsp; 1、 首先要找出什么事根本不必做，这些事做了也完全是浪费时间，无助于成果。将时间记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果？”如果认为“不会有任何影响”，那么这件事便该立刻取消。\u003cbr> &nbsp;&nbsp;&nbsp; 2、 第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 多年来在管理方面都在研究授权问题。任何一个组织——企业、政府、学校和军事机关，几乎每一位主管人员都接到过上级有关做好授权的指示，而且他们本人也曾屡屡对其下属阐明授权的重要。但是这样的谆谆告诫是否产生效果，实在令人怀疑。原因非常简单：只是因为没有完全明了授权的意义。如果认为所谓授权，意思是说：“我的”工作应该由别人来做，那就错了；因为你既拿了薪水，就该做你自己的工作。又有人认为：充分授权之后，最闲散的经理人便应该是最好的经理人。这样的看法不但荒唐，而且也是不道德的。\u003cbr> &nbsp;&nbsp;&nbsp; 3、 还有一项时间浪费的因素，是管理者自己可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003cbr> &nbsp;&nbsp;&nbsp; 这种现象并不明显，但有一个简单方法可以诊断出来：去问问你的下属。有效的管理者懂得有系统及诚恳地问他的下属：“请你想想看，我常做哪些浪费你的时间而又不产生效果的事情？”问这样的问题，而且问得对方敢说真心话，才是有效管理者的特色。\u003cbr> 即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; 阅读完原文的片段，首先请大家回忆一下昨天你都做了什么，似乎没做什么，但总觉得自己很忙。是忙的刷手机，还是忙的工作？大家的时间花在哪里，自己说的清楚吗？如果不清楚时间用在哪里，我们如何谈时间管理，对不对。\u003cbr> &nbsp;&nbsp;&nbsp; 第一步要记录自己的时间，看看自己到底24小时都做了什么？记录时间的方式可以用纸笔，也可以用APP进行记录，这个可以根据自己的习惯来处理。当我们知道自己的时间的消耗情况，才可以对时间的有效的管理和运用。\u003cbr> &nbsp;&nbsp;&nbsp; 第二步，对时间的运用进行分析调整。举个例子，我修改一个客户协议，本该20分钟能处理，但我的时间记录表我花了1个小时，多出来的40分钟我用在哪里去了？大部分情况有可能我去刷手机，或者跟其他人聊天去了。\u003cbr> &nbsp;&nbsp;&nbsp; 针对时间记录的情况，我们需要去梳理自己的事项哪些是浪费的，这部分内容需要减少。在减少事项上可以划分两个大类：\u003cbr> &nbsp;&nbsp;&nbsp; \u003cstrong>第一种，对自己的要求：\u003c/strong>\u003cbr> &nbsp;&nbsp;&nbsp; 1、\u003cstrong>“我不要做”\u003c/strong>：做不做都不会带来质的改变，也没什么好处，要减少这种事项。比如刷朋友圈、刷微博，逛淘宝。这个是首要减少\u003cbr> &nbsp;&nbsp;&nbsp; 2、\u003cstrong>“不要我做”\u003c/strong>：除开自己必要的工作职责外，别人能力范围内，交给别人处理。比如：帮别人签收快递\u003cbr> &nbsp;&nbsp;&nbsp; \u003cstrong>第二种，对他人的要求：\u003c/strong>\u003cbr> &nbsp;&nbsp;&nbsp; 3、\u003cstrong>“不增负”\u003c/strong>：作为上级，给下级安排的工作的时候，需要考虑是否无效工作，是的话就不要给下属增加负担。\u003cbr> &nbsp;&nbsp;&nbsp; 4、\u003cstrong>“要减负”\u003c/strong>：作为下属，如果你的上级没及时发现无效工作已经影响你的工作职责，需要有技巧地跟你的上级领导反馈并提出协调方案。书本是没讲解到这点，但我们也可以主动去做。\u003cbr> &nbsp;&nbsp;&nbsp; 总的来说书本介绍的方法首先是记录时间，其次是通过从4个方面进行分析，从而减少时间的浪费，提高时间的使用。\u003c/p>\u003cp>&nbsp; &nbsp; 那么结合我自己过往的经历分享一下：\u003c/p>\u003cp>&nbsp; &nbsp; 1、从来没有对自己的时间进行一个记录，每天都不知道时间花在哪里了。\u003cbr>&nbsp; &nbsp; 2、查看了自己的手机后台，发现每天花在微信的时间最多，但用微信处理工作的内容是占少数的，大部分都是在聊天，玩跳一跳。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>很多人都不知道每天时间花费在了哪里，小伙伴会不会有一些感触，想想自己在时间的记录和管理方面，针对自己的生活或者工作有没有类似或者相关的经验？现在请大家在小组内分享，时间是2分钟\u003c/p>\u003cp>好的，现在请一位小伙伴来分享自己刚刚在小组内分享的内容？\u003c/p>\u003cp>（参与学习者分享：自己在生活和工作中都没有很好的管理和记录时间，在这一方面确实做的不够好）\u003cbr>\u003c/p>\u003cp>那刚刚说到我自己不清楚自己时间花在哪里了，我今天就下载一个”ihour”APP,准备对自己每天上班时间，间隔1小时进行一次工作记录，包括工作内容和时长，实际的工作时长和备注情况，不要求记录做到很精细。每天统计、每周进行梳理和回顾，将这些浪费时间的事件进行逐步删减，先减少“我不要做”的事件；再减少“不要我做”其最后主动跟上级沟通减少一些非生产性工作。坚持2个月时间看看自己时间利用提高多少。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>\u003cstrong>你也会开始管理自己的时间，给自己记录时间并管理自己的时间吗？如果我的A2有触动到你，令你想到更合适自己的A2,请你花1分钟的时间在便签纸上写上1-3点自己未来行动步骤或应用，需要具体的时间、做法，并预期达到的效果，请大家开始动笔吧。\u003c/strong>\u003c/p>\u003cp>(学习者A2记录\u003c/p>\u003cp>A：今日下载一个”ihour”APP，开始记录自己的时间，连续记录一个礼拜下班后晚上8点到10点的时间消耗情况，并在下周三做一个时间总结。\u003c/p>\u003cp>B：针对自己的上班时间做记录，连续记录一个月，然后按照刚才的时间分析方法看自己有哪些浪费的地方，进行时间更有效的利用。）\u003c/p>\u003cp>今天的分享到这里结束，请大家用便签写下想对我说的话，包括建议、需要做的更好的地方。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1516619610000,"updated_at":1516699136000,"ria":true},{"id":3469,"topic":"吴佳音TF1-1定级训练","learn_goal":"完成定级","remark":"德鲁克经典管理图书","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"吴佳音","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"一、自我介绍（1分钟）\r\n大家好，我叫吴佳音，一个很矛盾的人，有多矛盾呢？看我的名字就知道了。\r\n吴：一口吃掉一个天，但我却一直相信人外有人，天外有天。我自认是个谦虚的人。\r\n佳：两个土堆起来的山，靠山吃山。可我却选择离开目前的舒适区，参加拆书帮，勇于自虐。我自认是个积极进取的人。\r\n音：音乐，可我不懂乐器、不识五线谱、不唱歌、甚至于基本不听歌，除了现在偶尔听听儿歌。但我接受这个不完美的自己，我自认是个知足的人。\r\n我叫吴佳音，一个谦虚、知足并积极进取的人。\r\n二、拆书帮介绍（2分钟）\r\n“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以演讲者、知识为中心。\r\n拆书分为个人学习的拆书法和组织学习的拆书法。\r\n个人学习的应用就是便签法；我是在7月份参加了拆书帮的便签训练营，收获良多。其中，RIA的方法给了我很多启示，原本我看书都是停留在阅读层面，现在我发现，I是非常重要的，可以帮助我进行分析内容，并准确提取对我有意义的方式、方法。A1则帮助我去反思，很多时候事过境迁，未能及时提取经验。但是通过A1去反思，从而提取出成功或失败的经验。A2给自","ratings_count":0,"texts":[{"id":6341,"quote":"\u003cp>己一个明确的目标，我应该怎么做，而且做法是以我可控可执行的方式去完成。\u003cbr>\u003c/p>\u003cp>另外的一种方式是组织学习，我参加了多次现场的带拆，也收获良多。让我从中学习到很多东西，并且回去后可以拆为己用。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;拆书家不是权威，权威是拆书家所选的图书，拆书家扮演的是引导者、促动师、催化师的角色。我目前参与的是拆书帮鹭岛抚琴分舵，这是一个非常人性化的成人学习社区，我也从中获得很多灵感。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;如何向上司提出建议？如何让自己的建议被采纳？今天我们需要一起来学习这个拆页：卓有成效的管理者P91-92，第四章如何发挥人的长处——如何管理上司\u003cbr>\u003c/p>","explains":"\u003cp>&nbsp; &nbsp;当需要向上司提建议时，需了解上司的长处和特点；在陈述建议时，应根据上司的类型（如读者型、听者型）选择相应的表述方式；所提出的建议最好是其责权范围内的。\u003c/p>","interaction":"\u003cp>\u003cstrong>分享&nbsp;A1&nbsp;便签\u003c/strong>\u003c/p>\u003cp>质检岗位就是做质量检查的，主要的工作内容是抽样、评价、反馈（无论优秀、达标、不达标、错误）。为了能更有效的预防不达标甚至是错误的情况出现，需要对其工作内容进行调整。因调整了工作内容，故需要修改质检岗位原有的考核标准。\u003c/p>\u003cp>因我是曾在这个岗位工作过一年半，凭借经验对考核标准提出不少建议。但最终的考核标准中，仅有“修改抽样标准”是我的建议为基础进行修订后确定的，其他建议虽也有部分被采纳，但并非以我的建议为基准。\u003c/p>\u003cp>现在回想，应该是我提出“修改抽样标准”的表述方式与其他建议不同。我先汇总了上一年度的数据，按月分析，最后提出建议。若使用新的抽样标准后，将会获得什么样的结果，与上一年度的结果有何不同，有何益处。\u003c/p>\u003cp>上司是个很理性的人，注重客观性。我提出修改抽样标准建议时，所使用的表述方式是符合上司一贯的思维方式。\u003c/p>\u003cp>\u003cstrong>分享&nbsp;A2&nbsp;便签\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>目前，我每月需向这位上司提交上个月的质检报告并提出建议，可尝试调整为以下方式\u003c/p>\u003cp>1、数据汇总：按时间、按类别、按组别……2、数据分析：优秀、有改善、急需解决、需预防3、提出建议。\u003c/p>\u003cp>如上周有新的产品上线，产品介绍容易出现疏漏。9月初的报告中，我会汇总该类别的样本，分析出问题点，提出解决方案，并建议以后在产品上线前的售前培训中，应强化该项目。\u003c/p>\u003cp>这个售前培训工作安排是上司的职权范围，建议容易被采纳。\u003c/p>\u003cp>这就是我今天跟大家分享的内容，希望能对今后的工作有所帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1503328227000,"updated_at":1505643376000,"ria":true},{"id":2881,"topic":"五个思考习惯","learn_goal":"学习并养成：成为卓有成效的管理者五个思考习惯","remark":"这本书是现代管理学之父，大师中的大师彼得·德鲁克的经典之作，他称自己是“社会生态学家”，他对社会学和经济学的影响深远，是启蒙中国现代管理终生受用的案头必读书。通过阅读本书，可以让大家相信，一群平凡的人，能做出不平凡的事业，只要组织中每个人都卓有成效。","level":"TF1-1","duration":12,"status":0,"type":0,"chaishujia":{"username":"牛牛0519","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"大家晚上好，我是贾文卿。首先做个自我介绍，我的三个标签是：第一个标签是一名银行从业人员，第二个标签是一名理财师，第三个标签是一个读书爱好者。今天我是作为一个拆书家1级和大家分享TF1-1。我们今天的主题就是如何成为卓有成效的管理者？我希望通过平时专业理财服务和拆书和拆书帮的训练，与工作学习更有效的结合，能够帮助他人，提升自己。\r\n 接下来给大家介绍“什么是拆书和拆书帮？”。刚才Mary萍已经和大家简单介绍了一下。首先是“拆书”，这是一种学习方法论，不是把书拆掉。它是以提升能力、解决问题为目标的成人学习，拆书强调以学习者为中心而不是以知识为中心，侧重把书本中知识转化为学习者自身的能力。\r\n拆书分为个人学习型和组织学习型，\r\n 个人学习型的拆书就是RIA便签读书法：第一步是R-(Reading)，阅读图书片段；\r\nI-Interpretation)，用自己的语言重述知识；A-(Appropriation)学习者拆为己用。\r\n便签读书法是非常适合一个人读书时帮助理解、记忆和转化运用能力的读书方式。\r\n组织学习型的拆书就是我们今天现场的这种学习，是拆书家通过一本书","ratings_count":0,"texts":[{"id":5658,"quote":"\u003cp>原文片段：\u003c/p>\u003cp>下列五项是要成为一个卓有成效的管理者，必须在思想上养成的习惯。\u003c/p>\u003cp>1.有效的管理者知道他们的时间用在什么地方？他们所能控制的时间非常有限，他们会有系统的工作，来善用这有限的时间。\u003c/p>\u003cp>2. 有效的管理者重视对外界的贡献。他们并非为工作而工作，而是为成果而工作，他们不会一接到工作就一头钻进去，更不会开头就探究工作的技术和手段，他们会首先自问：“别人期望我，做出什么成果？”\u003c/p>\u003cp>3. 有效的管理者善于利用长处，包括自己的长处，上司长处，同事的长处和下属的长处，他们还善于抓住有利形势，做他们想做的事，他们不会把工作建立在自己的短处上，也绝不会去做自己做不了的事。\u003c/p>\u003cp>4．有效的管理者集中精力于少数重要的领域，在这少数重要的领域中，如果能够有优秀的绩效就可以产生卓越的成果。他们会按照工作的轻重缓急设定优先次序，而且坚守优先次序，他们知道要事第一。重要的事先做，不重要的事放一放，除此之外也没有其他的办法，否则反倒会一事无成。\u003c/p>\u003cp>5．最后，有效的管理者必须善于做有效的决策，他们知道有效的决策，事关处事的条理和秩序问题，也就是如何按正确的次序采取正确的步骤。他们知道一项有效的决策，总是在“不同意见讨论”的基础上作出判断，它绝不会是一致意见的产物，他们知道快速的决策多为错误的决策，真正不可或缺的决策数量并不多，但一定是根本性的决策。他们需要的是正确的战略，而不是令人眼花缭乱的战术。\u003c/p>","explains":"\u003cp>接下来大家看到我们每人发了一个文章的拆页片断。\u003c/p>\u003cp>选自这本书《卓有成效的管理者》，它的作者是现代管理学之父，大师中的大师彼得·德鲁克的经典之作，通过阅读本书，可以让大家相信，一群平凡的人，能做出不平凡的事业，只要组织中每个人都卓有成效。\u003c/p>\u003cp>请大家用3分钟时间，阅读手中已下发的片段，这个片断在原中的P/22-23页。有读完的伙伴，可向我举手示意。\u003c/p>\u003cp>（两个标注“▼▲”中间的部分）。\u003c/p>\u003cp>好的，我看大多数小伙伴都已经读完，没有读完的小伙伴也没有关系，我们可以一起来解读。\u003c/p>\u003cp>今天分享的是：如何成为卓有成效的管理者？\u003c/p>\u003cp>要成为一个卓有成效的管理者，必须在思想上养成五大习惯：\u003c/p>\u003cp>1、善用有限的时间，\u003c/p>\u003cp>2、重视对外界的贡献，\u003c/p>\u003cp>3、善于利用长处，长处有自己的、上司的、和同事间的，\u003c/p>\u003cp>4、集中精力于少数重要的领域，\u003c/p>\u003cp>5、善于做有效的决策。&nbsp;\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>我讲一下我个人工作上的心得。我们分行刚开业的时候，只一些上海的企业来开卡，周边是没有主动来的客户办业务的。根据惯性思维，我建议社区做一些社区营销。当时领导并不认可，我们不可能象大行那样做普惠制的服务，一下辅100多个网点。所以呢，当时不太理解，领导也让我们去周边的四季新城等小区做一下社区营销，但做了2次社区宣传后我才发现，这样做的确是很有问题：我们做活动，一定是周六周末，所以的人都是加班加点，投入很大的精力，但是效果并不佳。周边的百姓可能是冲着礼品来的。拿了礼品就走了。柜台上还是没有人来做业务。还有这些贪图礼品的是低质量的客户。全部到柜面来开卡时，我们真正有效的客户反而体验度不好。排队很长，反而会影响到我们。所以呢，我学了这个片断回想之前我们领导的决策是对的。他就是卓有成效的管理者的思路来定义的，他要把我们有限的时间、精力、资源放在我们目标客户当中，偏重财富管理，做我们有针对性的群体。才能达到有效，现在想想还是蛮对的。虽然学了这样，有时在实际生活中还是做不到。\u003c/p>\u003cp>比如说刚刚过去一个季度，我们的业绩不是特别好，最后三月下旬业绩覆盖了整个季度，回过头的想我们还是没有把有效的时间用好。我们分析了一下数据没有集中把时间做该做的时间，没有统筹规划，如果说整个一个季度都象这半个月一样，那效果一定是非常好了。这个就是失败的一个例子。\u003c/p>\u003cp>所以学了这个片断，总结一下过去和未来对我们还是很有帮助的。\u003c/p>\u003cp>&nbsp; A2\u003c/p>\u003cp>所以在最近，我们推广一个新的业务，叫移动支付清算业务，在座各位肯定都用微信和支付宝。微信除了发红包，可能还会买个东西什么的。这个业务就是我们帮商户把支付宝和微信合并为一个码，把资金直接归集到商户的卡上，费率还有优惠。但是我们在做的时候发现其他银行已经先行一步了。所以周末我们分析了一下怎么做？\u003c/p>\u003cp>目前的情况是竞争激烈，时间紧，人手少。我总结归纳了5点思维方式：\u003c/p>\u003cp>1、&nbsp; 在整个4月份把它作为一个重点业务。\u003c/p>\u003cp>2、&nbsp; 我们要做一些中型大型的商户，他们贡献大。\u003c/p>\u003cp>3、&nbsp; 对方也有利益，他们量大费率优惠有效果。\u003c/p>\u003cp>4、&nbsp; 利用我们自己的优势 ，我们的卡在全国所有ATM取现免费，电子渠道所有跨行跨市跨省转账全免费。充分发挥我们的优势推广给大家。\u003c/p>\u003cp>5、所有员工全面开花来做这个重点业务，才能更有效。\u003c/p>\u003cp>这个就是今天我的TF-1的分享。结束语：不破不能立，不拆不成器——拆书帮，把图书的知识拆解为自己的能力！希望今天的片断能够给大家工作或生活有一定的启发。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497187635000,"updated_at":1497187881000,"ria":true},{"id":2665,"topic":"学习者能通过记录某段时间的实际耗用，分析记录的情况，合理安排","learn_goal":"能通过记录某段时间的实际耗用，分析记录的情况，合理安排时间","remark":"卓有成效的管理者》是管理学宗师级人物德鲁克教授的智慧结晶。他对中国管理者的价值是难以计量的。","level":"TF2-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"黄鹂","city":"上饶"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是行走在拆书帮升级打怪之路上的斗士黄鹂。我是个阳光向上的青年，想学习很多东西，比如心理学，亲子教育，婚姻家庭，人际沟通等等。要学习这么多的东西就需要更多的时间。我今天带拆的内容就跟时间管理相关，拆解的是TF2-2，我们先来分组。\r\n一、学习目标\r\n在跟随我完成本次拆书RIA现场学习后，学习者能通过记录某段时间的实际耗用，分析记录的情况，合理安排时间，高效地完成事情。\r\n二、图书介绍（1-2分钟）\r\nF特征：《卓有成效的管理者》是管理学宗师级人物德鲁克教授的智慧结晶。他对中国管理者的价值是难以计量的。\r\nA优势：本书被誉为是启蒙中国现代管理第一书，是终生受用的案头必读书。它不是说只有高级管理者才能做到卓有成效，每一个普通人学会卓有成效。所有负责行动和决策而又有助于提高机构工作效能的人，都应该像管理者一样工作和思考。\r\nB利益：这本书告诉我们怎样合理管理时间，怎样选拔人才，做决策时考虑的要素是什么等等。结合真实的故事与案例，令人易懂可操作。","ratings_count":0,"texts":[{"id":5403,"quote":"\u003cp>三.R阅读原文拆页\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp; 要提高管理者的有效性，第一步就是记录其时间耗用的实际情形。许多有效的管理者都经常保持 这样的一份时间记录，每月定期拿出来检讨。至少，有效的管理者往往以连续三四个星期为一个时段，每天记录，一年内记录两三个时段。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间耗用得很乱，浪费在种种无谓的小事上。经过练习，他们在时间的利用上必有进步。但是管理 时间必须持之以恒，才能避免再回到浪费的状态上去。\u003c/p>\u003cp>因此，第二个步骤就是要做有系统的时间管理。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这活动从时间表上排除出去。要做到这一步，可以试问自己下列几个问题。\u003c/p>\u003cp>1. &nbsp; &nbsp;首先要找出什么事根本不必做，这些是做了也完全是浪费时间，无助于成果。将时间按记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果？”如果认识“不会有任何影响”，那么这件事便立刻取消。\u003c/p>\u003cp>然而许多大忙人，天天在做一些他们觉得难以割舍的事，比如应邀讲演、参加宴会、担任委员和列席指导之类，不知占去了他们多少时间。而这些工作，他们本身既不感兴趣，做得也根本不够精彩。然而他们得承受这些负担，一年又一年，就像从天而降的灾难一样躲也躲不了。其实对付这类事情，只要审度一下对于组织有无贡献，对于他本人有无贡献，或是对于对方的组织有无贡献。如果都没有，只要谢绝就得了。\u003c/p>\u003cp>2. &nbsp; &nbsp;第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果？”“授权”这个名词，通常都被人误解了，甚至是被人曲解了。这个名词的意义，应该是把可由别人做的事情交付给别人，这样才能做真正应由自己做的事——这才是有效性的一大改进。\u003c/p>\u003cp>3. &nbsp; &nbsp;还有一项时间浪费的因素，是管理者自己可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/p>\u003cp>这种现象并不明显，但有一个简单方法可以诊断出来：去问问你的下属。有效的管理者懂得有系统及诚恳地问他的下属：“请你想想看，我常做哪些浪费你的时间而又不产生效果的事情？”问这样的问题，而且问得对方敢说真心话，才是有效管理者的特色。\u003c/p>\u003cp>即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。事实上，一位管理者大刀阔斧减少不必要的工作，绝不会有太大的风险。人总有一种倾向，高估自己地位的重要性，认为许多事非躬亲不可。纵然是最有效的管理者，仍然免不了有许多不必要的和非生产性的工作。\u003c/p>","explains":"\u003cp> （举例） 晚饭后，大家都吃饱了，A边洗碗边叮嘱：“孩子，快点做作业,别等下又做到十点多。”电视机前，孩子和丈夫 两个人正讨论手机游戏。孩子不耐烦地说：“我就玩一会儿，等你做完事陪我做作业，有些我不会的。”A加快了与锅碗瓢盆斗争的速度，好不容易整理干净。丈夫说：“切点水果吧！”A抱怨：“你在那玩手机，不会自己弄啊！”“一直都是你做的，你切的好看”A沉默了。边打毛衣边陪孩子做完作业，已经是将近10点钟了。洗漱后躺下，赶紧看看手机朋友圈，手机刷屏，不一会儿就到十一点了。看到朋友圈里一篇《你的时间去哪儿了》，她不禁感慨，都五月份了，年前计划要考证，要每天看书一小时，可怎么也没有时间看，难道每天没有24小时吗？\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp;（讲解）） 在生活中跟A一样，很多人都在年初有很多的梦想和计划，可真正实施起来，他会感觉根本没有时间去做。每天都陀螺似的忙着，年终发现计划还没有落实，梦想成了空想。你有没有考虑过给自己的时间做个账本，看看哪些是属于时间盈利的，哪些是属于时间资源闲置，哪些属于浪费资源的？给你的时间做个账本，找出时间的实际耗用情况，思考怎样有系统地管理时间。思考分析关于时间管理的三个问题:1.找出“不必做的事”，删除掉。2.找出能授权的事，借他人的时间。3.找出无益于他人时间的无效时间，控制或消除掉。 &nbsp;\u003c/p>\u003cp> &nbsp; &nbsp; （预防异议） 也许有人对这个记录时间存在异议:我这上班都忙死了， 哪有空记录时间的耗用情况，这不是画蛇添足吗？可你没有记录时间，不知道你的时间 都花在哪些地方，是有效利用，还是浪费时间。不思考记录时间的账单，你的“忙”可能就是瞎忙，要知道磨刀不误砍柴工。记录时间并不是耽误时间，而是将时间利用的更加有效。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>：早晨的忙乱慌张时间，上午的工作黄金时段，晚上的休闲充电时刻……你在工作和生活中哪个时间段是你觉得最需要记录并分析的过去一周的的这个时段，你都在做些什么，哪些事占用了你的时间。你大概记得每件事花费的时间是多少。\u003c/p>\u003cp>本次拆书学习后，你打算怎样记录你觉得需要调整的时段，分析你在这个时段时间耗用的性价比。思考一下，哪些事是我们说的不必做的，可以授权的以及无益于双方的。你准备怎样来规划管理你的“生命”之时。请在小组内分享你的应用。\u003c/p>\u003cp>\u003cstrong>学习者案例实录：\u003c/strong>\u003c/p>\u003cp>每天在学校上班，除了上课，下午没事就睡。晚上就睡不着，要么出去打麻将，要么教儿子做作业，边玩手机。等儿子做完作业，我还是睡不着，就接着玩手机看电视到十一二点。学习后就知道，真的是恶性循环。计划考会计证，每天下午睡到2点，然后开始看书书。晚上陪儿子做作业的同时，自己也看书，这样对儿子和自己都好。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1495093802000,"updated_at":1495094237000,"ria":true},{"id":2643,"topic":"如何找到整段时间","learn_goal":"分析时间，安排好整段时间完成重要事项","remark":"这本书是现代管理学之父，大师中的大师彼得·德鲁克的经典之作，他称自己是“社会生态学家”，他对社会学和经济学的影响深远，是启蒙中国现代管理终生受用的案头必读书。通过阅读本书，可以让大家相信，一群平凡的人，能做出不平凡的事业，只要组织中每个人都卓有成效。","level":"TF1-2","duration":14,"status":0,"type":0,"chaishujia":{"username":"牛牛0519","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"把准备好的复印原书折页发给现场学习者。\r\n大家晚上好，我是贾文卿。今天很高兴由我来给大家做TF1-2的拆书分享。首先做个自我介绍，我的三个标签是一名银行从业者，一位妈妈，也是一位读书爱好者。希望通过拆书家训练把工作学习和家庭生活更好的连接，提升自己，帮助他人。\r\n现在请在座各位分一下组，3-4人一组，。。。。\r\n 今天我要拆的片段来自这本书《卓有成效的管理者》P.49页。如何将零碎的时间集中起来支配？\r\n*这本书是现代管理学之父，大师中的大师彼得·德鲁克的经典之作。讲了卓有成效是所有人都可以学会的。\r\n*这本书是管理类图书中世界上非常畅销的一本，很多知名公司的CEO和成功管理者都非常这本书，一读再读，常读常新。\r\n*您有没有觉得管理是一个很烦的事？你有没有想像过能像张瑞敏管理海尔集团一样成功？这本书帮张瑞敏理清思路，自创了日清工作法。让管理者首先学会自我管理，在不断学习有效性的过程中成为一名卓有成效的管理者。直至让团队的每个成员都卓有成效。\r\n 请大家用1分钟时间，阅读手中的片段（两个标注“▼▲”中间的部分）。有读完的伙伴，可向我举手示意。","ratings_count":0,"texts":[{"id":5379,"quote":"\u003cp>拆书来源：《卓有成效的管理者》P.49页，作者彼得·德鲁克。\u003c/p>\u003cp>原文片段：\u003c/p>\u003cp>1 不过，话又说回来：集中自己的时间。集中的“方法”倒在其次。重要的是时间如何用法。许多人把次要的工作集中起来办理。因而匀出一段整块时间来。但这样的方法并无太大的作用。因为这样的方法，不啻在心理上或时间上，仍然放不下那些次要的事情。放不下那些很少贡献而又认为不能不做的事情。结果终究还会产生新的时间压力。来占用他的自由时间。牺牲他应该做的事。几天或几星期后，他已经“集中”的自由时间，又会被那些所谓“新的问题、新的紧急事情、新的麻烦”瓜分得无影无踪。\u003c/p>\u003cp>2 有效的管理者，第一步，应先估计究竟有多少“自由时间”，真正是他自己的时间，然后保留出相当分量的一段连续性的整块时间来。一旦发现还有别的事情在“蚕食”他保留的时间，便立刻再仔细分析它的时间记录，再将其中比较次要的工作重新过滤一次，他们已知道这层道理，因此不至于过分删减。\u003c/p>\u003cp>3 一切卓有成效的管理者都懂得：对时间的控制与管理，不能一劳永逸。他们要持续不断地做时间记录，定期对这些记录进行分析，还必须根据自己可以支配的时间的多少，给一些重要的活动定下必须完成的期限。\u003c/p>","explains":"\u003cp>好，大部分伙伴都看好了拆页的内容，没看完也没关系，我们一起来过一遍。这个片断看上去很容易理解，如何集中利用零碎时间，就是分三个步骤：\u003c/p>\u003cp>首先\u003cstrong>管理零碎时间前，应先估计一下自己真正有的“自由时间”；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二个是分清主次，保留出一段连续性的整块时间来，用于主要工作，而非次要工作；最后一个还要持续自检，并给重要活动设定必须完成期限。\u003c/strong>\u003c/p>\u003cp>从我个人经历分享一下，我刚来一个新的单位，新的环境，新的团队成员，新的业务，让我一直都觉得时间不够用，周末晚上经常加班，我女儿经常看不到我。成效不明显。\u003c/p>\u003cp>最近学习这个片断，学习将零碎时间整理好，集中起来支配的方法。我把每天所有做的事情连续记录下来，分析后，发现自己的时间里管理工作和营销工作主次不分。一会儿管理，一会儿营销。很多时间都被杂七杂八的事所干扰，被一些不重要的营销工作浪费很时间。\u003c/p>\u003cp>现在经过分析，通过做每周做计划，首先针对最重要的事一定腾出一部分时间空出来。重要服务的人员客户时间留出。\u003c/p>\u003cp>我规定自己4月底前，第一、一定要把重要的工作分配到每一个团队成员。第二，因为我管理财业务，上次行要求有个分析，针对双录工作要有一个调查报告。规定在月底，我设定在最后第二周一定要完成。月底前万一有什么不妥还可以再改。第三个是月末指标，每周我一定要见一位最重要的客户。\u003c/p>\u003cp>经过梳理，4月底我是按序完成的了所有的工作，另外，4月份的几个周末，我基本没有加班。这个月我基本上能把有效的时间管理好了。腾出时间做家庭的管理。\u003c/p>","interaction":"我是这样做的，那么下面请大家想想自己是否有遇到过这样的情况&nbsp;，\r\n没把自行支配的零碎时间没有管理好，导致重要工作被延误的经历。\r\n或者工作中和学习中，有没有过这样的情景：半天下来感觉很忙，\r\n但领导教给的重要的事情没有做。好象自己很忙，如果给自己2个小时整块的时间，\r\n足以办理一件或两件重要的事了？现在给大家5分钟。与组内伙伴分享一下。\r\n最后请一位伙伴和大家分享。\r\n大家可以边分享边记录。想一想自己在工作生活中碰到这样的一种情境。\r\n时间有时会被突然的一个电话或采访者占用。\r\n下面请一位伙伴用1分钟的时间给大家分享一下。\r\n&nbsp;学习者案例记录：\r\n刘老师：分享一个今天的事，工作计划中给财务总监写一封信，但一直拖到下班时才交，当中被一会儿签一个字，当中还插了2个零时性的会议，所以就会一直拖到最后才完成。现在看了这个片断，觉得还是时间没管理好。\r\n好的，谢谢分享！\u003cp>谢谢小伙伴的分享，最后\u003cstrong>请大家想一下，未来一个月\u003c/strong>，您会怎么做，是否能够达到更好的效果呢？\u003c/p>\u003cp>请大家在便签上写下的自己的规划写下来，给大家1分钟，写好的请举手示意。注意不是表决心，要是具体的做法，有明确的时限，有可衡量的或可观测的预期结果。\u003c/p>\u003cp>&nbsp; 这就是我的TF-2拆书分享，总而言之，时间最稀有的资源，认识你的时间是任何人只要肯做就能做到的，这是通向有效性之路必经之路。\u003c/p>\u003cp>首先\u003cstrong>管理零碎时间前；第二个保证重要事情有时间做，就是分清主次；最后一个还要持续自检，并给重要活动设定必须完成期限。\u003c/strong>\u003c/p>\u003cp>大家可以通过分析自己的时间，保留整块的时间做最重要的事，最后还将不断定期分析改进。才可以更好地把零碎的时间集中起来利用好。感谢大家参与。\u003c/p>学习者案例分享\u003cp>&nbsp; &nbsp;吴老师：近期一直在做促动师的活动，有时一个下午拿着手机，这里回一条，那个事回应一下，一会儿半天就过去了，导致正事没有做好，所以，自己要注意要管理好零碎的时间，先把重要事情列出来，保留整块的时间给重要的事，再行动，同时也要持续自我检查，有没有偏离，给重要的事情设定一个必须完成的期限。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1494912059000,"updated_at":1497189356000,"ria":true},{"id":2568,"topic":"找寻“自己都去哪儿了？”的答案","learn_goal":"找寻“自己都去哪儿了？”的答案，做有系统的时间管理，提高做事","remark":"找寻“自己都去哪儿了？”的答案，做有系统的时间管理，提高做事","level":"TF2-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"黄鹂","city":"上饶"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是新手拆书家黄鹂。接下来由我为大家带来的是TF2-1的内容拆解。首先我们分一下小组（现场随机）\r\n一.学习目标\r\n在跟随我完成本次RIA现场学习后，大家能诊断自己的时间都去哪了，通过记录一周工作时间耗用情况，做有系统的时间管理，提高我们做事的效率。\r\n二.图书介绍（1-2分钟）\r\nF特征（核心是“书”、用于满足好奇心）\r\n德鲁克教授是当代著名的思想家，一代管理学宗师，《经济学人》称它为“大师中的大师”。\r\nA优势（重点是“比较”，用于建立安全感）\r\n本书被誉为是启蒙中国现代管理第一书，是终生受用的案头必读书。它不是说只有高级管理者才能做到卓有成效，每一个普通人学会卓有成效。所有负责行动和决策而又有助于提高机构工作效能的人，都应该像管理者一样工作和思考。\r\nB利益（强调的是学习者的利益，用于引发兴趣）\r\n有没有觉得自己每天都很忙，到又没做成什么事？做事情杂乱无章，不知该如何安排？工作交给他人，又不知道给谁？本书从掌握自己的时间，怎样处理事情有效，如何选拔人才到怎样进行决策，用生动真实的故事与策略结合，有趣易懂可操作！","ratings_count":0,"texts":[{"id":5294,"quote":"\u003cp>要提高管理者的有效性，第一步就是记录其时间耗用的实际情形。许多有效的管理者都经常保持 这样的一份时间记录，每月定期拿出来检讨。至少，有效的管理者往往以连续三四个星期为一个时段，每天记录，一年内记录两三个时段。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间耗用得很乱，浪费在种种无谓的小事上。经过练习，他们在时间的利用上必有进步。但是管理 时间必须持之以恒，才能避免再回到浪费的状态上去。\u003c/p>\u003cp>因此，第二个步骤就是要做有系统的时间管理。我们先要将非生产性的和浪费时间的活动找出来，尽可能将这活动从时间表上排除出去。要做到这一步，可以试问自己下列几个问题。\u003c/p>\u003cp>1.首先要找出什么事根本不必做，这些是做了也完全是浪费时间，无助于成果。将时间按记录拿出来，逐项逐项地问：“这件事如果不做，会有什么后果？”如果认识“不会有任何影响”，那么这件事便立刻取消。\u003c/p>\u003cp>然而许多大忙人，天天在做一些他们觉得难以割舍的事，比如应邀讲演、参加宴会、担任委员和列席指导之类，不知占去了他们多少时间。而这些工作，他们本身既不感兴趣，做得也根本不够精彩。然而他们得承受这些负担，一年又一年，就像从天而降的灾难一样躲也躲不了。其实对付这类事情，只要审度一下对于组织有无贡献，对于他本人有无贡献，或是对于对方的组织有无贡献。如果都没有，只要谢绝就得了。\u003c/p>\u003cp>2.第二个该问的问题是：“时间记录上的哪些活动可以由别人代为参加而又不影响效果？”“授权”这个名词，通常都被人误解了，甚至是被人曲解了。这个名词的意义，应该是把可由别人做的事情交付给别人，这样才能做真正应由自己做的事——这才是有效性的一大改进。\u003c/p>\u003cp>3.还有一项时间浪费的因素，是管理者自己可以控制并且可以消除的，这项因素是：管理者在浪费别人的时间。\u003c/p>\u003cp>这种现象并不明显，但有一个简单方法可以诊断出来：去问问你的下属。有效的管理者懂得有系统及诚恳地问他的下属：“请你想想看，我常做哪些浪费你的时间而又不产生效果的事情？”问这样的问题，而且问得对方敢说真心话，才是有效管理者的特色。\u003c/p>\u003cp>即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。事实上，一位管理者大刀阔斧减少不必要的工作，绝不会有太大的风险。人总有一种倾向，高估自己地位的重要性，认为许多事非躬亲不可。纵然是最有效的管理者，仍然免不了有许多不必要的和非生产性的工作。\u003c/p>","explains":"\u003cp>\u003cstrong>（讲解）\u003c/strong>你有没有记录过你一天的时间是怎么过的？一周的时间呢？一个月呢？记录时间耗用的实际情况，是磨刀不误砍柴工，记录后你会更明白时间的利用率。思考怎样有系统地管理时间，需要思考分析三个问题:1.找出“不必做的事”，删除掉。2.找出能授权的事，借他人的时间。3.找出无益于他人时间的无效时间，控制或消除掉。\u003c/p>\u003cp>\u003cstrong>（不这么做的坏处）\u003c/strong>时间和身体都是自己的私有财产，可一个不知道时间管理者人过的很忙，活的很累，甚至这样，你还得不到他人的同情与认可。 也许有人对这个记录时间存在异议:我这上班都忙死了， 哪有空记录时间的耗用情况，这不是画蛇添足吗？可你没有记录时间，不知道你的时间 都花在哪些地方，是有效利用，还是浪费在无谓的类似手机刷屏的小事上。不思考记录时间的账单，不知道哪些事可以不做，哪些事由他人代劳，哪些事是我们浪费他人的时间，怎能提高自己和他人的效率！\u003c/p>\u003cp>\u003cstrong>(举例）\u003c/strong>周一一早走进教室上第三节课，嘴快的孩子说:“老师，周贤文一组今天地没扫干净，我们班扣分了！” &nbsp;“老师，你没跟我们说是我们扫地。” &nbsp; 被告反驳道。我才想起来，我上周忘记布置了。“知道了，不怪你们，是老师上周五忘记布置了。你们这组这周扫地，知道了吗？好，我们开始上课吧！”走近讲台一看，乱七八糟的粉笔，本子，还有学生捡到放那的文具用品，不得不清理一下。转身，再把上节课老师的板书擦掉。时间就过去了5分钟，作为三年级孩子的班主任，我总是觉得他们太小了，很多事都自己动手做，像布置教室，出黑板报，值日安排，图书借阅等等。所以，有时候回家还在做工作！班级管理的事都由我一个人来做，能不累吗？在时间管理的学习后，我开始思考自己的时间，并记录时间的实际耗用。结果发现大部分工作都是小事占用时间，没有规划。进过思考后，我召开班级会议，和学生一起讨论哪些事由哪些人来负责，安排岗位，像黑板保洁员，讲台整理员，地面保洁员，雨具管理员等共32个岗位，授权让学生做，不但节约了我的时间，学生自主管理后做事更有责任心和效率，不必等到别人安排！\u003c/p>","interaction":"\u003cp>\u003cstrong>五.A1 激活经验（显像提问\u003c/strong>）\u003c/p>\u003cp>（约2分钟）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>：\u003c/p>\u003cp>时间都去哪了？还没好好做事，一天就过去了。日子一天天的重复，我陀螺似的转悠，每天过的好累啊！你有没有在年关的时候思考一下这一年我都做了什么，怎么时间这么快，可感觉自己计划还没实现，或是内心空落落。仔细想想你的一天所做的事，这件事真的是我非做不可吗？这件事真的非我做不行吗？我有没有做浪费他人时间和自己时间的是呢？\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>\u003cstrong>六.A1+（反思加工）\u003c/strong>（7-9分钟）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>想想人生数十年，弹指一挥间，怎样高效做事，愉快生活呢？运用我们今天探讨如何诊断自己时间的步骤，看看我们能不能做的更好！请大家讨论一下，并把Ta写下来！\u003c/p>\u003cp>\u003cstrong>学习者案例实录:\u003c/strong>\u003c/p>\u003cp>洗衣做饭不用干，主要是带孩子，但还是感觉乱糟糟，没时间打理。还想有空看看书，学习英语，但每次都没有时间。发现时间主要花在看手机和追剧上。看手机的时间很快就过去了。其实可以利用这段时间来打扫卫生，阅读。明天开始记录7:00--10：00这段时间的安排，先记录一周。\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>总时长15-20分钟\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1494139843000,"updated_at":1494159029000,"ria":true},{"id":2369,"topic":"如何统一安排可以自由支配的时间","learn_goal":"学习这个片段","remark":"","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"李媛","city":"南京"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【开场】大家好，我叫李媛。一个7岁男孩的妈妈，主业是某集团人力资源总监，副业是职业咨询师，爱好看书、绘画，目前正在学习手绘，同时还是一名项目管理爱好者，正走在PMP考证的路上。拆书将我们聚在一起，期待与大家一起拆出风采。\r\n【介绍拆书帮】接着来为大家介绍一下拆书与拆书帮的基本情况。“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。 \r\n拆书分为个人学习的拆书法和组织学习的拆书法：个人学习的应用就是便签法；组织学习的应用就是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\r\n在拆书学习活动中，拆书家不是权威，权威是拆书家所选的图书，拆书家扮演的是引导者、促动师、催化师的角色，启发、引导学习者进行更深入的思考，促进学习者把知识转化为行动，践行“知行合一”。“拆书帮”是一个全国性的成人学习社群，目前在北京、上海、广州、深圳等全国30多个城市都建有拆书帮的学习者俱乐部（也叫拆书帮分舵）。拆书帮分舵是一种公益性的学习组织，它的使命是帮助更多的学习爱好者成长为拆书家。","ratings_count":0,"texts":[{"id":5065,"quote":"\u003cp>下面请大家阅读今天带拆的原文片段，给大家3分钟的时间，请看完的伙伴给我一个示意。\u003c/p>\u003cp>【统一安排可以自由支配的时间】\u003c/p>\u003cp>一位管理者的职位越高，其不能自行支配的时间也一定越多。组织的规模越大，其用于维系组织运行，而非用于发挥组织功能及生产的时间也一定越多。\u003c/p>\u003cp>因此，有效的管理者知道他必须集中他的自由时间。他知道他需要集中整块时间，时间分割成许多段，等于没有时间。时间如果能集中，即使只有一个工作日的1/4，也足可办理几件大事。反之，零零碎碎的时间，纵然总数有3/4个工作日，也是毫无用处。\u003c/p>\u003cp>所以，时间管理的最后一步，应该是将可由管理者自行支配的零碎时间集中起来。\u003c/p>\u003cp>至于如何集中，则各人有各人的办法。有些高层人员，在一星期内，留有一天在家工作。许多杂志主编和主持研究的科学家，就常采用此法。\u003c/p>\u003cp>还有人将会议、审核、问题分析等例行工作，规定排在一星期内的某两天中办理，而将其他日子的整个上午保留下来，用于处理真正重大的事务。\u003c/p>","explains":"\u003cp>好的，大家已经阅读完原文了，下面开始I便签的分享。\u003c/p>\u003cp>基层员工的时间相对来说是自由的，可以自行支配专注于将自己的工作目标完成；而管理者的时间大多情况下是别人的，所以要能集中有限的自由时间。我们经常从电视中看到一名高管从踏进办公室那一刻起，办公室门外就已经排了长长的队，等待他审批、决策，同时客户电话不停歇。职位越高，自己可支配的时间就越少，时间被分割成众多碎片，忙于处理各种琐碎之事，往往真正重要的事情却被耽搁。\u003c/p>\u003cp>虽然可自由支配的时间相对较少，但有效的管理者会将可支配的时间化散为整，集中时间处理，也足可以办理几件大事。将时间化散为整的方法有很多：\u003c/p>\u003col>\u003cli>\u003cp>如书中提到的高管们可以一周内有一天的时间在家办公；\u003c/p>\u003c/li>\u003cli>\u003cp>将例行工作，如会议、审核等工作安排在固定的两天进行集中处理；\u003c/p>\u003c/li>\u003cli>\u003cp>对工作进行分类处理，如签批性工作的统一放在固定的某一天的上午或下午；如需要沟通讨论的事情放在每天的上午，下午专门用来办理其他事情；\u003c/p>\u003c/li>\u003cli>\u003cp>要将自己的时间安排告诉他人，让大家知晓，以免经常被打扰。\u003c/p>\u003c/li>\u003c/ol>","interaction":"\u003cp>\u003cstrong>【A】学习者拆为己用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1】下面为大家分享我的A1便签。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请回想日常工作中的你时间是如何安排的？有没有时间被分割的现象？\u003c/strong>\u003c/p>\u003cp>工作中要管理集团及下属6家子公司的人力资源工作，日常的事情很多，每家子公司都存在着不同层面的问题，每天疲于各种沟通、协调，有时一整天都进不了自己的办公室，经常有时想安静地写点东西的时间都没有。\u003c/p>\u003cp>比如最近在拟一些高管的年度责任书，正写着就有人进来沟通事情，有时一聊就是一两个小时，刚结束下一个人又来了，结果一个责任书两三天下来只写了几个字。\u003c/p>\u003cp>\u003cstrong>【A2】最后为分享我的A2便签。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结合本知识点，以日后的工作中将如何优化你的工作时间？\u003c/strong>\u003c/p>\u003cp>最近的工作有点疲于应付，而且精力不集中，导致一会做这一会做那，最后成效不高，感觉很忙，但没有忙出结果。结合本知识点，对以后工作时间做如下调整：\u003c/p>\u003col>\u003cli>\u003cp>每天上午9:00以后不再看与工作无关的内容\u003c/p>\u003c/li>\u003cli>\u003cp>在没有突发事件的情况下，上午专注于写东西、思考问题，下午用来沟通、协调事情；如果中途有人来打扰，若不是紧急的事情尽量将时间协调到下午\u003c/p>\u003c/li>\u003cli>\u003cp>一件事情尽量在固定内容内一次性做完，不分割时间；比如在写某方案时直到方案写完再去做其他事情，而不是边写边想其他事\u003c/p>\u003c/li>\u003cli>\u003cp>面试时间尽量都安排在下午\u003c/p>\u003c/li>\u003c/ol>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1492136023000,"updated_at":1492136023000,"ria":true},{"id":2362,"topic":"统一安排可以自由支配的时间","learn_goal":"帮助管理者将零碎时间集中起来","remark":"","level":"TF1-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"李媛","city":"南京"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【自我介绍】大家好，我叫李媛。一个7岁男孩的妈妈，主业是某集团人力资源总监，副业是职业咨询师，爱好看书、绘画，目前正在学习手绘，同时还是一名项目管理爱好者，正走在PMP考证的路上。拆书将我们聚在一起，期待与大家一起拆出风采。\r\n 【介绍拆书帮】 \r\n“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。 \r\n拆书分为个人学习的拆书法和组织学习的拆书法：个人学习的应用就是便签法；组织学习的应用就是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\r\n在拆书学习活动中，拆书家不是权威，权威是拆书家所选的图书，拆书家扮演的是引导者、促动师、催化师的角色，启发、引导学习者进行更深入的思考，促进学习者把知识转化为行动，践行“知行合一”。在拆书帮内部有一本人人必读的书——《这样读书就够了》，目前已经被韩国引进出版了韩文版，相信不久的将来，还会出英文版，名扬全世界。\r\n“拆书帮”是一个全国性的成","ratings_count":0,"texts":[{"id":5054,"quote":"\u003cp>\u003cstrong>【统一安排可以自由支配的时间】\u003c/strong>\u003c/p>\u003cp>一位管理者的职位越高，其不能自行支配的时间也一定越多。组织的规模越大，其用于维系组织运行，而非用于发挥组织功能及生产的时间也一定越多。\u003c/p>\u003cp>因此，有效的管理者知道他必须集中他的自由时间。他知道他需要集中整块时间，时间分割成许多段，等于没有时间。时间如果能集中，即使只有一个工作日的1/4，也足可办理几件大事。反之，零零碎碎的时间，纵然总数有3/4个工作日，也是毫无用处。\u003c/p>\u003cp>所以，时间管理的最后一步，应该是将可由管理者自行支配的零碎时间集中起来。\u003c/p>\u003cp>至于如何集中，则各人有各人的办法。有些高层人员，在一星期内，留有一天在家工作。许多杂志主编和主持研究的科学家，就常采用此法。\u003c/p>\u003cp>还有人将会议、审核、问题分析等例行工作，规定排在一星期内的某两天中办理，而将其他日子的整个上午保留下来，用于处理真正重大的事务。\u003c/p>\u003cp>另一个常见的办法，是每天下午都排定一段时间，在家里办公。\u003c/p>","explains":"\u003cp>好的，大家已经阅读完原文了，下面开始I便签的分享。\u003c/p>\u003cp>基层员工的时间相对来说是自由的，可以自行支配专注于将自己的工作目标完成；而管理者的时间大多情况下是别人的，所以要能集中有限的自由时间。我们经常从电视中看到一名高管从踏进办公室那一刻起，办公室门外就已经排了长长的队，等待他审批、决策，同时客户电话不停歇。职位越高，自己可支配的时间就越少，时间被分割成众多碎片，忙于处理各种琐碎之事，往往真正重要的事情却被耽搁。\u003c/p>\u003cp>虽然可自由支配的时间相对较少，但有效的管理者会将可支配的时间化散为整，集中时间处理，也足可以办理几件大事。将时间化散为整的方法有很多：\u003c/p>\u003col>\u003cli>\u003cp>如书中提到的高管们可以一周内有一天的时间在家办公；\u003c/p>\u003c/li>\u003cli>\u003cp>将例行工作，如会议、审核等工作安排在固定的两天进行集中处理；\u003c/p>\u003c/li>\u003cli>\u003cp>对工作进行分类处理，如签批性工作的统一放在固定的某一天的上午或下午；如需要沟通讨论的事情放在每天的上午，下午专门用来办理其他事情；\u003c/p>\u003c/li>\u003cli>\u003cp>要将自己的时间安排告诉他人，让大家知晓，以免经常被打扰。\u003c/p>\u003c/li>\u003c/ol>","interaction":"\u003cp>\u003cstrong>【A1】下面为大家分享我的A1便签。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请回想日常工作中的你时间是如何安排的？有没有时间被分割的现象？\u003c/strong>\u003c/p>\u003cp>工作中要管理集团及下属6家子公司的人力资源工作，日常的事情很多，每家子公司都存在着不同层面的问题，每天疲于各种沟通、协调，有时一整天都进不了自己的办公室，经常有时想安静地写点东西的时间都没有。\u003c/p>\u003cp>比如最近在拟一些高管的年度责任书，正写着就有人进来沟通事情，有时一聊就是一两个小时，刚结束下一个人又来了，结果一个责任书两三天下来只写了几个字。\u003c/p>\u003cp>\u003cstrong>【A2】下面为大家分享我的A2便签。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结合本知识点，以日后的工作中将如何优化你的工作时间？\u003c/strong>\u003c/p>\u003cp>最近的工作有点疲于应付，而且精力不集中，导致一会做这一会做那，最后成效不高，感觉很忙，但没有忙出结果。结合本知识点，对以后工作时间做如下调整：\u003c/p>\u003col>\u003cli>\u003cp>每天上午9:00以后不再看与工作无关的内容\u003c/p>\u003c/li>\u003cli>\u003cp>在没有突发事件的情况下，上午专注于写东西、思考问题，下午用来沟通、协调事情；如果中途有人来打扰，若不是紧急的事情尽量将时间协调到下午\u003c/p>\u003c/li>\u003cli>\u003cp>一件事情尽量在固定内容内一次性做完，不分割时间；比如在写某方案时直到方案写完再去做其他事情，而不是边写边想其他事\u003c/p>\u003c/li>\u003cli>\u003cp>面试时间尽量都安排在下午\u003c/p>\u003c/li>\u003c/ol>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1492062568000,"updated_at":1492062822000,"ria":true},{"id":2037,"topic":"有效的决策（选择）","learn_goal":"在若干方案的决策时能根据所学从中选取最合适的方案","remark":"  大家都知道，决策是一种判断，是若干项方案中的选择。所谓选择，通常不是“是”与“非”间的选择，绝大多数的选择，都是任何一项方案均不一定明显优于其他方案时的选择。比如我这家店的咖啡价格，我是定高端、低端还是中端路线好呢？我要买房子了，我选择在哪里买呢？假设我分别看好了新世纪新城与西城楼的商品房，价格都差不多，我如何决策或者选择呢？我该考虑哪些因素？本次拆书告诉你如何有效决策或者选择。","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"Poul","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！我是今天的拆书家叶佐旭，今晚拆解的书籍是《卓有成效的管理者》。一群平凡人，能做出不平凡的事业吗？这本书告诉我们是完全可以做到的，只要我们组织中的每一个人都能做到卓有成效。每个人都必须卓有成效吗？卓有成效是管理者必须做到的事，而要做到卓有成效就必须学会舍弃与选择，今天我们一起来揭开舍弃与选择的秘籍。《卓有成效的管理者》这本书的作者是德鲁克，是管理学的奠基者，这是一本风靡业界、流传已久的管理学畅销书。它将管理理论与丰富实践案例相结合，阐述如何成为一名卓有成效的管理者，帮助你提升工作效率、降低工作成本，让工作产生更大的成效与成果。","ratings_count":0,"texts":[{"id":4667,"quote":"\u003cp>P124 有效的管理者一定要求先有若干种不同的衡量方案，再从其中选取最适当的一种。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;费尔和斯隆的决策，主要的意义，绝不是表示决策应标新立异，也不是表示决策应有引人争议的特性，而是表示出决策的主要特征，一般的选择与决策主要有以下几步。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;一、要确实找出解决问题时必须满足的界限，换言之，应找出问题的“边界条件”。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;二、仔细思考解决问题的正确方案是什么，以及这些方案必须满足哪些条件，然后再考虑必须要的妥协、适应以及让步事项，以期该决策能被接受。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;三、决策方案要同时兼顾执行措施，让决策变成可以被贯彻的行动。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; 大家都知道，决策是一种判断，是若干项方案中的选择。所谓选择，通常不是“是”与“非”间的选择，最多只是“大概是对的”与“也许是错的”之间的选择。而绝大多数的选择，都是任何一项方案均不一定明显优于其他方案时的选择。比如我这家店的咖啡价格，我是定高端、低端还是中端路线好呢？我要买房子了，我选择在哪里买呢？假设我分别看好了新世纪新城与西城楼的商品房，价格都差不多，我如何决策或者选择呢？我该考虑哪些因素？\u003c/p>\u003cp>&nbsp; &nbsp; 决策的第一要素：确实应要了解决策应遵循的原则或者规范。比如说决策后我至少要达成什么目的或者目标？常称为“边界条件”。边界条件说明得越清楚和越精细，则据以做出的决策越有效，越能解决需解决的问题。我的目标是三个：公立小学（教学培养质量）、方便接送（时间成本）、每年花费成本不超过1万（成本）。\u003c/p>\u003cp>&nbsp; &nbsp;决策的第二要素：是研究“正确”的决策是什么，而不是研究“能为人接受”的决策是什么。举刚才的例子，最正确的决策就是选一家在上班路线附件的公立学校，而且户籍满足条件所花费成本最低。但很难吧？因此在选择时总会采取折中办法的倾向，如果我们不知道符合决策原则或者“正确”决策是什么，就无法辨别正确的这种和错误的折中之间的区别，最终不免走到错误的折中方向去。\u003c/p>\u003cp>&nbsp; &nbsp; 决策的第三要素：决策方案具有可操作性。从决策开始，我们就应该将行动的承诺纳入决策中，否则便是纸上谈兵。事实上，一项决策如果没有列举一条一条可行动的步骤，并指派为某某人的工作和责任，那便不能算是一项决策，最多时一种意愿而已。比如我说公立学校，如果我是16年从汕尾刚搬过来东莞的，户籍以及积分入学均不符合条件，我估计要入读公立学校操作起来就不大可能了。\u003c/p>","interaction":"\u003cp>拆书家提问：我们刚刚学习了有效决策往往就是从几个方案中选择最合适的一个，现在一起来做一个演练，请大家认真听一下要演练的场景：假设你上班在东城大道，现在住在鸿福路一个小区房子，面积是110平方米，你现在想要二胎，准备改善住房、找个四房的。你看了有三个目标小组的房子比较符合需求，新世纪星城、恒大华府（1）以及红山大厦的二手房，都是150平米左右。你现在比较犹豫，请你根据所学内容给这三个房子排个选择的优先顺序。请各小组讨论如何给购房排序，运用决策的三要素内容，并说出每个要素需要考虑的要点内容是什么。各小组讨论6分钟，6分钟后请至少1个小组进行分享。\u003c/p>\u003cp>春秋组分享讨论结果：我们先讨论了购房选择的基本原则（也就是边界条件），本来是有4点的，后来舍弃了1点，就三点：1.是否有好的小学学位；2.预算：不超过1.8万元/平方米；3、一手房还是二手房，一手房最好。\u003c/p>\u003cp>恒大华府房价：是新建楼盘，大概1.6万/平方米，学位是莞城中心小学，东莞一流的小学学位；\u003c/p>\u003cp>新世纪星城：第四期有新建楼盘，房价大概也是1.6万/平方米，但学位是东城第二小学，学位相比恒大华府要差。\u003c/p>\u003cp>红山大厦：属于二手房，10多年的房子，房价大概1.2万/平方米，学位好像是南城胜和小学。\u003c/p>\u003cp>我们讨论的结果最后的选择顺序是：第一：恒大华府；第二：新世纪星城；第三：红山大厦（不考虑）。主要理由：恒大华府的学位要比新世纪星城、红山大厦的学位好很多；从房价来说，恒大华府跟新世纪星城的房价差不多，可能新世纪星城的房价贵一点，二手房红山大厦最便宜，但由于新房的价格我们可以接受，就暂不考虑二手房。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1488120417000,"updated_at":1488120417000,"ria":true},{"id":2034,"topic":"要事优先之学会舍弃","learn_goal":"面对一件过去的事时能根据所学内容判断是否要事、是否应该舍弃","remark":"我们之前讲了“要事优先”，也讲了“要事原则”的核心是注重未来而不是现实，注重机会而不是现实压力。把精力放在能产生成果或者贡献的重要事情上，既然要事优先，那就是说“非要事”要排在后面甚至舍弃，哪些“非要事”要舍弃呢？我们一起来拆吧。","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"Poul","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！我是今天的拆书家叶佐旭，今晚拆解的书籍是《卓有成效的管理者》。想必很多职场人士都对这本书籍非常熟悉。你们认为你说在的组织都是卓有成效的吗？你认为你自己的工作是卓有成效吗？作为职场中人，如何成为一名卓有成效的管理者，这本书将会给你满意度的答案。《卓有成效的管理者》作者是德鲁克，是管理学的奠基者，这是一本风靡业界、流传已久的管理学畅销书。它将管理理论与丰富实践案例相结合，阐述如何成为一名卓有成效的管理者，帮助你提升工作效率、降低工作成本，让工作产生更大的成效与成果。","ratings_count":0,"texts":[{"id":4664,"quote":"\u003cp>P4 &nbsp;当一个管理者要想专心致志于重要机会时，必须摆脱过去，摆脱已经没有价值的事情。以免时间、精力和重要的资源，被那些不再产生成果的事情所占据。无论一个管理者多么睿智、多么有远见卓识，总是要受到时间和空间的限制。过去的一切终究会过时或者不合时宜，必须给予舍弃。管理者必须定期检讨，一旦确认某些事情没有继续做下去的必要，就应该给予终止，转向更有价值的事情。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; 我们之前讲了“要事优先”，也讲了“要事原则”的核心是注重未来而不是现实，注重机会而不是现实压力。把精力放在能产生成果或者贡献的重要事情上，既然要事优先，那就是说“非要事”要排在后面甚至舍弃，哪些“非要事”要舍弃呢？这一片段讲到的是定期检讨，学会舍弃过去或者已经没有价值的事情。\u003c/p>\u003cp>&nbsp; &nbsp; 摆脱过去或者终止一件没有价值的事情并不容易。这类事情往往代表着过去的辉煌和成就，也关系着当事者的口碑、情感和面子。终止这些事情没有好的办法，需要非常的勇气和决心。比如在我们公司，有很多销售人员把大量精力放在集团客户（尤其是低价值）支撑等售后环节，花很多事情在维系上，无论大小客户，比如账务、产品故障、关系维系等问题，但是很多分配的目标高价值集团确迟迟没有跟进、也没有反馈。其实我们的目标是提升信息化收入，最重要的事情应该聚焦在商机挖掘与业务拓展方面，其他事情是仅次来处理。大家可能会想：维系客户、服务客户也很重要呀？没错，可是重要的事情也得排序，所有事情都重要就变得都不那么重要，涉及影响客户满意度关键的问题上也是要努力，但重要性得排个序。还有一个例子，我记得在2年前，我负责营销管理工作，当时集团客户市场的产品有60多个，例如车讯通、农讯通等等，但是我们信息化收入20%的产品产生了92%的收入，另外有80%的产品产生了8%的收入，可是每个月我们都要对这些客户、这些产品进行支撑，耗费大量精力，后来我们建议公司进行了清理，目前留下的集团产品不超过10个。\u003c/p>\u003cp>&nbsp; &nbsp; 因此，我们要舍弃过去、摆脱已经没有价值的事情，第一:判断我们的目标或者要实现的成果是什么？第二:过去乃至现在做得这些事情对于实现目标或者成果价值有多大？是直接作用还是间接作用；第三：勇敢舍弃一些跟目标实现关联度低或者没有关联，以及一些低价值的事情。\u003c/p>","interaction":"\u003cp>设想一下2017年已经就在脚下了，一天早上你突然想起今天的拆书，感觉自身日常工作（或者生活上）你的行程安排得满满当当的，你停下来问自己，这些事情都重要吗？哪些事情我是可以舍弃的？怎么做可以把你的优势发挥的更好？\u003c/p>\u003cp>请在小组内分享你的应用。5分钟后请一个组给大家分享一下。\u003c/p>\u003cp>小鱼分享：我已经初步制定了2017年的目标以及自身的计划，17年想把重点放在个人成长方面，但感觉有很多东西要学，比如烘焙以及一些照顾家庭方面的琐碎技能。经过了一些梳理，发现烘焙跟自己定的目标并没有什么直接关系，个人精力是有限的。反而，我觉得应该发挥自身的优势，自己是计算机专业的，之前一直想在计算机领域进行深造、考个职称，但是之前一直没有去做，现在觉得应该把它放在今年的首要事情去做、考个计算机职称，把那些烘焙等一些事情舍弃掉，而重新梳理了自己的年度要事。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1488098962000,"updated_at":1488100910000,"ria":true},{"id":2030,"topic":"充分发挥自己的长处","learn_goal":"学习者能够清晰说出自己至少一个优势，并能发挥所长解决问题。","remark":"大部分管理者能了解他们自己不能做什么。其实日常工作中，很多人经常抱怨：上司不同意他们做什么，公司政策不让他们做什么，体制不允许他们做什么，因此他们的时间和才干，都在无限委屈中浪费了。有效的管理者可不这样，他们又是怎么呢？应该如何面对这些问题、解决这些挑战？我们本片段的拆解将为你揭开答案。","level":"TF2-1","duration":18,"status":0,"type":0,"chaishujia":{"username":"Poul","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！我是今天的拆书家叶佐旭，拆的书籍是《卓有成效的管理者》。一群平凡人，能做出不平凡的事业吗？这本书告诉我们是完全可以做到的，只要我们组织中的每一个人都能做到卓有成效。每个人都必须卓有成效吗？卓有成效是管理者必须做到的事，但是在所有的知识组织中，每一位知识工作者其实都是管理者--即使他没有职权，只要他能为组织作出贡献。《卓有成效的管理者》这本书作者是德鲁克，是管理学的奠基者，这是一本风靡业界、流传已久的管理学畅销书。它将管理理论与丰富实践案例相结合，阐述如何成为一名卓有成效的管理者，帮助你提升工作效率、降低工作成本，让工作产生更大的成效与成果。","ratings_count":0,"texts":[{"id":4660,"quote":"\u003cp>P99&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; 本章所讨论的如何用人之长，不仅有个态度问题，而且有一个敢不敢去实践的问题。用人之长，可以从实践中获得改进。我们只要注意认识我们的下属，观察我们的上司，多问“此人能做些什么”，而不必问“此人不能做些什么”，最后我们肯定能养成重视人之所长以及善用人之所长的态度。久而久之，我们也能以同样的问题来问自己了。\u003c/p>\u003cp>&nbsp; &nbsp; 在一个组织中，有效性的每一面，都是“机会的开发，问题的消失”。尤其是对人，这一点更是特别重要。有效的管理者，把每一个人都视为可以开发的机会，包括他本人在内。他知道唯有长处可能产生成果，而抓住弱点则只能造成令人头疼的问题。纵然没有弱点，也不能产生什么成果。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; 大部分管理者能了解他们自己不能做什么，而我们更应该关注自己能做什么。日常工作中，很多人经常抱怨：上司不同意他们做什么，公司政策不让他们做什么，体制不允许他们做什么，因此他们的时间和才干，都在无限委屈中浪费了，难以有所成就。当然，有效的管理者肯定关心自己所面临的局限性，但他们也应该了解自己能做的和该做的其实还有很多。尽管有人觉得委屈，不能做事，但有效的管理者却能勇往直前。由于他们勇往直前，所以别人感到非常严重的障碍，在他们面前却都烟消云散了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;曾经有过这样的1个案例：美国某一民营铁路公司的管理层人人都知道政府的限制很多，几乎不准许公司做任何计划，原有的管理团队都因为政府的政策限制在抱怨，工作上没有什么突破。但当一位主管财务工作的新任副总裁到任之后，由于还没有顾虑政府的限制，不久就直接到华盛顿，拜访“州际商业委员会”，提出他构想中的几项革新方案要求核准，委员会告诉他说：“你提出的方案，某几项与我们无关，至于其他的方案，你回去试行一下，如果可行，我们自然会支持你”。后来，这位副总裁推行的部分改革方案得到了政府的大力支持，干出了前任从未干出的业绩。\u003c/p>\u003cp>&nbsp; &nbsp; 有时，所谓“别人不让我干”，恐怕是惰性和没有勇气的借口吧。就算是客观条件有限制，也一定可以做出许多有意义的重要工作来。有效的管理者会发掘机会，找出许许多多重大的工作，就只怕他的时间和资源不够而已。如果不能聚焦机会与长处，而总看到限制与问题，那只能是徒增工作烦恼、时间和精力浪费在抱怨中无法实现突破，更难以解决问题、实现目标。\u003c/p>\u003cp>&nbsp; &nbsp;因此，我们在碰到问题时，不再询问“我不能做什么”，而是询问自己“能做些什么”；不要找痛点，而是聚焦机会，看哪些是能做的事情，明确自己的优势在哪里，在碰到问题时发挥自己的长处和优势，从而制定至少一个解决方案。\u003c/p>","interaction":"\u003cp>一、拆书家提问：你有没这样的一个经历，你刚到一个新的岗位或者换了岗位（亦或接手一个项目工作），你的前任工作绩效并不好或者很普通，工作交接时他跟你说这个岗位限制很多，你以前是怎么应对的？\u003c/p>\u003cp>君君案例分享：我是东莞某个小学的一名教师，从事教育行业也有20多年了，在教学的同时也开始负责行政管理方面的工作，直至副校长。我记得刚做行政管理工作那时候，前任跟我说在这个体制里面，教职工很难管理，手上的管理工具很少、激励自由度很有限、人员难于管理等诸多难题。可能做老师做久了，很容易看到别人身上的缺点，就像批改作业一样，就会跟别人提出来，想去纠正。我以前在遇到问题时很多时候是看到自己不能做啥，没去好好想想自己能做啥。今天的拆书也让我想起，前任校长曾跟我们说：看事情要多看别人的优点，很多时候要睁一只眼、闭一只眼，多去看到别人的长处，少看别人的短处。以前我们学校有个男的数学老师，表现很差、很懒，但是有点才华、普通话说得很好。老校长觉得他课堂口才不错、普通话说得好，就推荐他去参加“赛课”。自从磨练了他后，他也拿了一个不好不差的奖回来。自从“赛课”回来之后，我们发现他整个人的相比之前变化很多，做事不那么懒散了、上课也认真多了，其实发挥一个人的优势，也可以帮助他改正自己的不足，这个事情给我启发挺大的。\u003c/p>\u003cp>二、拆书家提问：结合你的案例或者经验，根据拆书中的建议，为了更好发挥优势，你认为应当如何处理当时的这类问题？\u003c/p>\u003cp>君君分享：我觉得如果以后遇到人员管理问题， 我不会再去想由于体制原因说这不能做、那不能做，多去想哪些能做？自己优势在哪？怎么解决问题？比如刚才的人员管理问题，我认为能做以下几点：一是多去看教职工的优点，利用他们的优点去解决问题；二是多跟他们谈心，告诉他们哪些地方做得好，给予精神上的鼓励。\u003c/p>\u003cp>晓勤分享：我先简要说说我的经验体会，再讲我会如何做。我公司两年前做了一个组织架构的调整，以前的几个班组调整合并成一个大的班组，由我来负责管理。一个组员的前任组长跟我说，我的某个团队成员为人很计较、很难分配工作给他，建议我不要花心思在他身上、重要工作不要安排给他做。我刚接到这个信息时，也觉得他这个不怎么好，不应该花心思在他身上，而应该抓重要项目、抓骨干员工。后来我慢慢发现，其实他也是有优点的，他做事严格按照流程或者规则办。我们是负责业务办理的团队，后来我就让他负责检查已经完成业务办理的资料，他很挑剔、能发现毛病，这个工作很合适他，最重要的是他对这工作也挺满意的，这种安排也让组织的效率得到提升。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 今天拆了这个片段，让我想起这事，触动真的很大，我觉得遇到问题真的是要多想想办法，想能做什么，不要老是看到困难、看到人家的不足。我觉得应该要充分挖掘团队每一个成员的优点，发挥其所长、将其放大。一是我应该建立团队成员的优势列表，每人至少两个。二是检查回顾每个人的长处是否得到了发挥，如果把人放到了一个不能发挥其长处的岗位，就要考虑调整，尽量使得人尽其才、团队效能最大化。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1488031697000,"updated_at":1488031697000,"ria":true},{"id":2026,"topic":"善于管理自己的时间","learn_goal":"如何善于利用整块时间和碎片化时间来做好事情","remark":"它的作者是彼得.德鲁克（美），他是管理学科开创者，被尊为“大师中的大师”、“现代管理学之父”，他的思想传播影响了130多个国家。中国领导人胡耀邦、朱镕基、微软总裁比尔.盖茨都积极推荐此本书。","level":"TF3-3","duration":55,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"大家好，我是金家东，拆书帮常州龙城分舵宣传长老，二级拆书家。今天很高兴由我来给大家做TF3-3的拆书分享。在跟随我完成第一片段RIA现场学习后，让学习者知道善用工作中整块时间完成任务的重要性。这本书《卓有成效的管理者》，作者是彼得.德鲁克，启蒙中国现代管理第一人。【事件场景】当我们在办公室完成一个工作计划的时候，关好门窗，一杯茶、一支烟，静静的思考，希望理出一个思路。可是突然的敲门声打断了我们的思路，一切又得从头开始。我们往往一个事情还没有做完，后面就跟了一大堆的事情在等着我们。不断的加班剥夺了我们的许多业余时间。我们是否时常问自己“时间都去哪里了呢”？【提问】是我们的工作时间没有达到应有的长度吗？是我们杂七杂八的小事情比别人多吗？是我们的工作能力方面有待提升吗？如何才能找到有效的时间管理的方法？你找到了吗？【影响】如果我们没有做好时间管理，就会浪费自己和他人的时间，影响我们的工作效率和重要任务的完成质量。【解决】这本书告诉我们，完成重要的事情必须要用整块时间去完成，碎片化的时间也可以有效合理的去运用，这样可以帮你解决如何高效的管理时间，达到事半功倍，成为卓有成效的管理者。","ratings_count":0,"texts":[{"id":4654,"quote":"\u003cp>片段一：P28-29\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;每一位管理者的时间，都有很大部分是被浪费的。表面上看起来，每件事似乎都非办不可，但实际上却毫无意义。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;但是，即使是只想获得最低程度的有效性，管理者的绝大部分任务也需要相当多的整块时间。如果每一次所花的时间少于这个极限，事情就做不好，所花的时间就是浪费，再做就得从头开始。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;举例来说，写一份报告大概得花6-8小时才能完成初稿。如果说每次花15分钟，每天2次，一共花上2星期，虽然总时间也达到7小时，恐怕结果还是一张白卷。但是如果能够关起门来，切断电话，连续做上五六个小时，一份相当不错的初稿就应该差不多了。有了这份初稿，他才能做零星的补充，才能逐字逐句地润色、修改和整理。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;科学实验工作也与此相似。起码需要5-12小时的整块时间，才能把仪器调整妥当，做成一次实验。如果中间被打断，恐怕就得重新开始。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;每一位知识工作者，尤其是每一位管理者，要想有效就必须能将时间做整块的运用。如果将时间分割开来零星使用，纵然总时间相同，结果时间也肯定不够。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;尤其是与他人一起工作时，这一点更加重要。与他人一起工作，正是管理者的中心工作之一。人都是时间消费者，而大多数人也是时间浪费者。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;与他人只接触三两分钟，是绝不会产生什么结果的。要想与他人做有效的沟通，总得花上足够的时间。一位经理人员如果以为他与下属讨论一项计划、一项方针，或者一项工作表现，只需要15分钟就够了，那他一定是自欺欺人。如果你真想影响别人，那至少需要一个小时以上。如果你想和别人建立良好的人际关系，就需要更多的时间。\u003c/p>","explains":"\u003cp>【清晰的how】通过刚才那个片段的学习，我们知道：1、管理者需要用整块时间去完成重要的任务。2、不让整块时间碎片化。3、尤其是这个任务是与他人一起完成时，更加必须是整块的时间。假如你不这样做，会浪费大部分的时间。\u003c/p>\u003cp>&nbsp;&nbsp;【适用边界】这个片段告诉我们的是善用整块时间去完成重要的工作任务，对于一些杂事，譬如交话费、聚会、聊天等需要碎片化时间去处理的事情，都不在讨论的范围之内。\u003c/p>\u003cp>&nbsp;&nbsp;【概念】什么是整块时间呢？就是你工作的整段时间中，安静且不被打扰的连续性时间，一般是二个小时以上。什么是碎片化时间呢？就是短暂的、随时可能被打扰的间断性时间，一般是一个小时以下。\u003c/p>\u003cp>&nbsp;&nbsp;【对比概念】我们上班时间是8小时，这个8小时是不是整块时间呢？\u003c/p>\u003cp>&nbsp; 【学员回答】不是。\u003c/p>\u003cp>&nbsp;&nbsp;【匹配例子】在年底的时候，老板交代我做年会的流程，当时我一口答应了。由于在工作中其他的事情比较多，经常有同事来打扰，导致8小时的时间被分割成碎片化的时间。虽然做流程的总时间远远超过8小时，但是做出来的流程连自己都不满意。学习了片段后，我花了半天时间召开了相关部门的会议，把要配合的各部门事情做了规划，再用半天的时间在家里，手机关机，安静地把整个流程做完。\u003c/p>\u003cp>&nbsp;&nbsp;【提问】大家觉得完成一个任务，是时间的总长度重要呢？还是时间的连续性重要呢？\u003c/p>\u003cp>&nbsp; 【学员回答】时间的连续性重要。\u003c/p>\u003cp>&nbsp;&nbsp;【知识点】所以，完成任务的时间并不仅仅在于长度，关键在于完成任务的连续性！因为有时间的连续性才有工作的有效性！\u003c/p>\u003cp>&nbsp;&nbsp;如果你这个任务是与他人一起完成的，那么你用整块的时间尤其重要，因为这不但会浪费自己的时间，也会浪费别人的时间。\u003c/p>","interaction":"\u003cp>【A2催化应用】拆书家提问设计（逐字稿）：\u003c/p>\u003cp>在最近的一个月左右，你工作中需要完成一个工作报告、或销售计划，也或者生活中你需要规划一下孩子的学习计划、或家庭的未来规划等，你想要一个怎么样的安静环境和多长的整块时间去完成呢？请写出一个故事的场景，写出关键信息就可以了。接下来设计出人物、情节变化（包括：起因、经过、结果）和当时双方的对话、动作等，其中部分内容请使用原文拆页中告诉我们的“要用整块时间去完成大部分任务的重要性”，摘要写在一张纸上。时间五分钟，5分钟后我们请人站起来分享他的剧本。现在开始…\u003c/p>\u003cp>\u003cstrong>说明\u003c/strong>\u003cstrong>：\u003c/strong>从心理学角度，编剧本是心理对照，让自己先在脑海中过一遍，就像运动员在脑海中想练习的动作一样，可以提高工作效率。\u003c/p>\u003cp>【剧本分享】：分享人Mrry萍\u003c/p>\u003cp>【场景】下周二上午，在公司会议室的封闭环境中，讨论修改完善公司的规章制度。\u003c/p>\u003cp>【起因】公司现有的规章制度有许多不完善的地方，需要修改。\u003c/p>\u003cp>【经过】会议主持Mrry萍和团队伙伴一起，每个人针对规章制度不完善的地方提出自己的看法和修改建议，经过大家讨论达成一致。\u003c/p>\u003cp>【结果】公司的规章制度得到优化和完善。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":4655,"quote":"\u003cp>片段二：P48-49\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;所以，时间管理的最后一步，应该是将可有管理者自行支配的零碎时间集中起来。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;至于如何集中，则各人有各人的办法。有些高层人员，在一星期内，留有一天在家工作。许多杂志主编和主持研究的科学家，就常采用此法。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;还有人将会议、审核、问题分析等例行工作，规定排在一星期内的某两天中办理，而将其他日子的整个上午保留下来，用于处理真正重大的事务。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;上个例子中的某银行总裁，正是这样管理时间的。召开业务会议、约请高级职员讨论和接待重要客户之类的工作，都排在星期一和星期五。星期二、三、四的下午，则不排固定的工作，用来处理其他事务，例如研究突发的人事问题、约见回国的国外分行经理、接待重要客户，或前往华盛顿出差之类。但是在这三天的上午，他会事先安排时间来处理重要事项，并以90分钟为一个单元。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;另一个常见的办法，是每天下午都排定一段时间，在家里办公。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;卡尔森教授在他的研究报告中，曾提到一位最有效的管理者。这位管理者每天上午上班前，总有90分钟时间留在家里，不接电话，专门从事研究工作。如果还要准时上班，那么早上在家里自然就得早早开始工作了。不过这种做法，总比每天下班后把重要事务带回家去，晚饭后再花3小时处理的方式好得多。因为那样不免过度劳累了，中年以上的人最好是早起早睡。但现在喜欢把工作带回家来开夜车的人越来越多，这往往会造成一种不好的情况：人们以为可以晚上加班，因此反倒没有抓紧白天的工作时间。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;不过，话又得说回来：集中自己的时间，集中的“方法”倒在其次，重要的是时间如何用法。许多人把次要的工作集中起来办理，因而匀出一段整块时间来。但这样的方法并无太大的作用。因为这样的方法，不啻在心理上或时间上，仍然放不下那些次要的事情，放不下那些很少贡献而又认为不能不做的事情。结果终究还会产生新的时间压力，来占用他的自由时间，牺牲他应该做的事。几天或几星期后，他已经“集中”的 &nbsp;&nbsp;自由时间，又会被那些所谓“新的问题、新的紧急事件、新的麻烦”瓜分得无影无踪了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;有效的管理者，第一步应先估计究竟有多少“自由时间”，真正是他自己的时间，然后保留出相当份量的一段连续性的整块时间来。一旦发现还有别的事情在“蚕食”他保留的时间，便立刻再仔细分析他的时间记录，再将其中比较次要的工作重新过滤一次。他们已知道这层道理，因此不至于过分删减。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;一切卓有成效的管理者都懂得：对时间的控制与管理不能一劳永逸。他们要持续不断地做时间记录，定期对这些记录进行分析，还必须根据自己可以支配的时间的多少，给一些重要的活动定下必须完成的期限。\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次RIA现场学习后，让学习者学会有效利用碎片化时间的方法。\u003c/p>\u003cp>【A1自测】请大家用1-2分钟的时间，在能否有效管理时间方面给自己评分，以下5个题目，请按照1~6分的标准给自己打分，1代表完全不符合，6代表非常符合。完成的伙伴请举手示意。\u003c/p>\u003cp>【自测表格】\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;能否有效管理时间方面给自己评分\u003c/p>\u003cp>请你做一个简单的测试，看看你在开会前思考和设计方面的现状。以下5个题目，请按照1~6分的标准给自己打分，1代表完全不符合，6代表非常符合。请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1表示很不符合，6表示非常符合，请用“√”方式）。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1.我总是用整块时间去完成重要的任务。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2. 我总是定期做时间记录。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3. 我总是事先预估有多少是“真正属于自己的自由时间”，从而保留出相当份量的一段连续性整块时间。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4. 如果预计的整块时间不够完成一个重要的任务，我总是会把碎片化的时间进行过滤和删减，以保证整块时间。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5. 我总是对重要事情有一个必须完成的期限。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp;【解释自测题】通过刚才给自己在有效管理时间方面的评分，让自己客观看待有效管理时间的现状，这次自测量表是采用行为特征量化的方式，让学习者了解现状的一种测评方法。测评结果不是唯一的标准和一成不变的，只是当下的一种反映，同时也是作为让我们在沟通反馈方面做的更好的一个参考和新的起点。\u003c/p>\u003cp>&nbsp;&nbsp;让我们来看看自己的得分情况呢？\u003c/p>\u003cp>&nbsp;&nbsp;假如您的总分在15分以下，说明你在时间管理方面有待改善。假如你的总分在20分以上，说明你能够有效的管理时间。\u003c/p>\u003cp>【拆书家讲解引导】\u003c/p>\u003cp>【清晰的how】通过阅读刚才的片段，相信大家已经对“有效利用碎片化时间”有了进一步的理解。\u003c/p>\u003cp>碎片化时间的利用的几个方法：\u003c/p>\u003cp>1、事先预估有多少是“真正属于自己的自由时间”，保留出相当份量的一段连续性的整块时间来。\u003c/p>\u003cp>2、如果完成重要任务的整块时间不够，可以过滤碎片化时间来进行补充。\u003c/p>\u003cp>3、定期做时间记录，对重要事情定下时间期限。\u003c/p>\u003cp>【案例】上周的一天晚上，我回家做一个工作计划，预计晚饭后有2个小时的空余时间可以完成。做的过程中，发现时间不够，我就把本来用于睡前看书的半小时时间挪过来，完成了工作计划。\u003c/p>\u003cp>【概念】什么是“真正属于自己的自由时间”呢？就是有一整块可以自己支配且不受打扰的时间。什么是时间期限呢？就是预计完成任务的时间段或者截止日期。\u003c/p>\u003cp>【对比概念、提问】我们下班以后的时间是不是就是“真正属于自己的自由时间”呢？对的，肯定不是，因为下班后会有许多杂事干扰我们，譬如做饭、接孩子、家务等等，把下班后的时间分割成碎片化的时间。\u003c/p>\u003cp>【适用边界】这个片段的适用边界是告诉我们如何过滤利用碎片化时间，整合成一大段整块时间的方法，对于碎片化时间去做什么，不在讨论的范围之内。\u003c/p>\u003cp>【提问】做一件重要的事情，为什么要规定一个时间期限呢？\u003c/p>\u003cp>【知识点】时间期限规定了一个你必须完成任务的时间节点，让你更加有紧迫性，防止你的拖延症，只有做到这点，你才能成为卓有成效的管理者。\u003c/p>","interaction":"\u003cp>【A3促动参与】\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>我们刚刚学习了整块时间的重要性以及碎片化时间的运用方法，接下来用微行动学习方式进行演练。首先介绍行动学习一般是某人提出的一个真实具体的问题开始，主持人引导大家思考和进行有洞察力的提问，从而对经验进行反思和质疑，更深入认识问题的本质，直到得到创造性的解决方案。\u003c/p>\u003cp>接下来请某一个伙伴提出一个问题，我们用微行动学习的步骤：1.明确问题；2.引导分组讨论问题本质；3.明确问题本质；4.引导分组讨论解决方案；5.请每组派代表讲解小组的成果。分步进行演练：\u003c/p>\u003cp>\u003cstrong>第一步\u003c/strong>\u003cstrong>、\u003c/strong>\u003cstrong>明确\u003c/strong>\u003cstrong>问\u003c/strong>\u003cstrong>题\u003c/strong>\u003cstrong>：（5分钟）\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>首先，这是一个真实存在的问题。我们在近一个月中，可能有一个培训项目、或者销售计划需要开始实施，也或者一个工作计划、工作报告需要去编写或执行，怎样提高我们的工作质量和效率呢？请大家用\u003cstrong>一分钟\u003c/strong>的时间把你当下要实施或执行的任务和问题写在便签纸上。\u003c/p>\u003cp>写好后，请大家用\u003cstrong>3分钟\u003c/strong>的时间在小组内分享。\u003c/p>\u003cp>分享完后，大家确定共识，解决一位伙伴的问题。给大家\u003cstrong>一分钟\u003c/strong>的时间。\u003c/p>\u003cp>【学员共识的一个任务】要实施或执行的事情是：培训项目的实施。\u003c/p>\u003cp>\u003cstrong>二、\u003c/strong>\u003cstrong>分组讨论问题本质\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>现在是问题澄清的环节，大家可以向问题所有者提问。（问题的拥有者可以反馈也可以不反馈）\u003c/p>\u003cp>【提问】什么样的培训项目呢：1、新员工培训，2、员工技能培训。\u003c/p>\u003cp>【学员选择】新员工培训\u003c/p>\u003cp>三\u003cstrong>、.明确\u003c/strong>\u003cstrong>问题本质\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>（真正的问题是什么？）（把这个问题重构一下，就是明确了问题的本质）\u003c/p>\u003cp>【提问1】培训的时间是几天？\u003c/p>\u003cp>【回答】下周二-周四\u003c/p>\u003cp>【提问2】培训的人数和流程呢？\u003c/p>\u003cp>【回答】学员是20个一线焊接员工，半天时间的规章制度培训，一天半的焊接知识和实操。学员需要通过考核。\u003c/p>\u003cp>【提问3】培训目标是什么？\u003c/p>\u003cp>【回答】如何让员工尽量多的通过培训考核。\u003c/p>\u003cp>【问题本质】如何提升员工培训的合格率。\u003c/p>\u003cp>\u003cstrong>四、引导\u003c/strong>\u003cstrong>分组讨论解决方案\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>&nbsp;下面针对这个问题，伙伴们在小组内进行讨论，给大家2分钟时间每个人写出2条解决方案，然后在小组内分享，用3分钟的时间共识出6条解决方案。请大家把解决问题的方案写在便签纸上。在实施和执行的过程中，我们如何兼顾整块时间和碎片化的时间？\u003c/p>\u003cp>1、【提问】你希望合格率提升到什么程度，你会感到满意呢？\u003c/p>\u003cp>&nbsp; &nbsp;【回答】由85%，提升到95%\u003c/p>\u003cp>2、提升合格率的解决方案（学员分享）\u003c/p>\u003cp>（1）用整块时间培训，中间不要间断。\u003c/p>\u003cp>（2）找到没有通过的原因，加以分析。\u003c/p>\u003cp>（3）提升讲师的授课水平。\u003c/p>\u003cp>（4）请焊接经验丰富的老员工教实操。\u003c/p>\u003cp>（5）培训时间的调整（实操多一些）。\u003c/p>\u003cp>（6）授课方法多样化。\u003c/p>\u003cp>（7）优化课程。\u003c/p>\u003cp>（8）分析问题。\u003c/p>\u003cp>（9）提高入职门槛。\u003c/p>\u003cp>（10）调整培训重点。\u003c/p>\u003cp>（11）优化师资。\u003c/p>\u003cp>（12）培训激励（老师和学员的双向激励）\u003c/p>\u003cp>\u003cstrong>五、分组讲解\u003c/strong>\u003c/p>\u003cp>请各小组派人给大家分享你们小组成果。\u003c/p>\u003cp>现在请问题的拥有者谈谈，你今天的收获，伙伴们共识出的解决方案，你回去所能运用到的？\u003c/p>\u003cp>&nbsp;【问题提出者收获】\u003c/p>\u003cp>1、用整块时间培训，中间不要间断。\u003c/p>\u003cp>2、优化课程。\u003c/p>\u003cp>3、提高入职门槛。\u003c/p>\u003cp>4、培训的双向激励。\u003c/p>\u003cp>【A2】催化应用：\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>&nbsp;&nbsp;在未来的一个月左右，你可能在工作中需要完成一个工作报告、或销售计划，也或者生活中你需要规划一下孩子的学习计划、或家庭的未来规划等：1、选定一个场景，请用今天学习的拆页“如何有效管理时间”的方法，写下运用方法的关键词，在小组内进行分享，时间2分钟。2、回去进行实践并做复盘，实践的过程和复盘的内容可以发到群里，拆书家伙伴可以点评。\u003c/p>\u003cp>【案例】\u003c/p>\u003cp>1、用2个小时完成一个销售计划，在家里安静完成。\u003c/p>\u003cp>2、选择一个封闭的地方，对管理人员培训一天。\u003c/p>\u003cp>3、在小孩子的房间，安静地和儿子谈一下学习计划和具体的规划，用时3小时。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>要成为卓有成效的管理者，我们必须做好记录时间、管理时间，统一安排时间这三个重要步骤，用整块时间去完成重要事情，有效利用碎片化的时间，真正成为时间的主人。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1487903231000,"updated_at":1487905273000,"ria":true},{"id":1911,"topic":"如何将零碎的时间集中起来支配","learn_goal":"学会如何将零碎的时间集中起来支配","remark":"F：这本书是现代管理学之父，大师中的大师彼得•德鲁克的经典之作。讲了卓有成效是所有人都可以学会的。\r\nA: 这本书是管理类图书中非常畅销的一本，很多知名公司的CEO和成功管理者都非常这本书，值得一读再读，常读常新。\r\nB: 您有没有觉得管理是一个很烦的事？你有没有想像过能像张瑞敏管理海尔集团一样成功？这本书可以帮你理清思路，让管理者首先学会自我管理，在不断学习有效性的过程中成为一名卓有成效的管理者。直至让团队的每个成员都卓有成效\r\n","level":"TF2-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"牛牛0519","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"把准备好的复印原书折页发给现场学习者。\r\n大家晚上好，我是贾文卿。今天很高兴由我来给大家做TF2-1的拆书分享。首先做个自我介绍，我是一个银行团队负责人，也是一名银行内部培训师，为企业员工提供专业知识技能的培训宣讲，为广大客户提供专业理财服务和理性投资理念倡导，希望通过拆书家训练与工作学习更好的连接，提升自己，惠及他人。\r\n 今天我拆的这本书是《卓有成效的管理者》。F：这本书是现代管理学之父，大师中的大师彼得·德鲁克的经典之作。讲了卓有成效是所有人都可以学会的。\r\nA: 这本书是管理类图书中非常畅销的一本，很多知名公司的CEO和成功管理者都非常这本书，值得一读再读，常读常新。\r\nB: 您有没有觉得管理是一个很烦的事？你有没有想像过能像张瑞敏管理海尔集团一样成功？这本书可以帮你理清思路，让管理者首先学会自我管理，在不断学习有效性的过程中成为一名卓有成效的管理者。直至让团队的每个成员都卓有成效。\r\n现在请在座各位分一下组，3-4人一组。","ratings_count":0,"texts":[{"id":4522,"quote":"\u003cp>拆书家：贾文卿\u003c/p>\u003cp>拆书级别：TF2-1\u003c/p>\u003cp>拆书主题：如何将零碎时间集中起来支配？\u003c/p>\u003cp>拆书来源：《卓有成效的管理者》P.49页，作者彼得·德鲁克。\u003c/p>\u003cp>原文片段：\u003c/p>\u003cp>1 不过，话又说回来：集中自己的时间。集中的“方法”倒在其次。重要的是时间如何用法。许多人把次要的工作集中起来办理。因而匀出一段整块时间来。但这样的方法并无太大的作用。因为这样的方法，不啻在心理上或时间上，仍然放不下那些次要的事情。放不下那些很少贡献而又认为不能不做的事情。结果终究还会产生新的时间压力。来占用他的自由时间。牺牲他应该做的事。几天或几星期后，他已经“集中”的自由时间，又会被那些所谓“新的问题、新的紧急事情、新的麻烦”瓜分得无影无踪。\u003c/p>\u003cp>2 有效的管理者，第一步，应先估计究竟有多少“自由时间”，真正是他自己的时间，然后保留出相当分量的一段连续性的整块时间来。一旦发现还有别的事情在“蚕食”他保留的时间，便立刻再仔细分析它的时间记录，再将其中比较次要的工作重新过滤一次，他们已知道这层道理，因此不至于过分删减。\u003c/p>\u003cp>3 一切卓有成效的管理者都懂得：对时间的控制与管理，不能一劳永逸。他们要持续不断地做时间记录，定期对这些记录进行分析，还必须根据自己可以支配的时间的多少，给一些重要的活动定下必须完成的期限。\u003c/p>","explains":"\u003cp>今天我要拆的片段来自这本书《卓有成效的管理者》P.49页。如何将零碎的时间集中起来支配？\u003c/p>\u003cp>\u003cstrong>请大家用2分钟时间，阅读手中的片段（两个标注“▼▲”中间的部分）。有读完的伙伴，可向我举手示意。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; 好，大家都看好了~内容，看上去容易理解：就是管理零碎时间前，应先估计一下自己真正有的“自由时间”，然后保留出一段连续性的整块时间来，用于主要工作，而非次要工作。同时还要持续自检，并给重要活动设定必成期限。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我选择这个片段的原因是作为一个新的单位，新的环境，新的团队成员的管理者，我一直都觉得时间不够用，手里的事做都做不完，但实际上虽然把一些主动梳理的不重要的事减掉了，但后来还是在处理其他客户突然来行办理的各类事情。最近利用这个流程，元旦时我进行了一个梳理，把所有需要做的事情列一个表，把重要的几个事项标星，上周连续几天，专门把一部分时间空出来。把领导要报的几个方案和计划先做了出来。最近几天均抽了固定的两小时，把手里需要思考的几件列出了提纲，感觉思路比较清晰了。我分析自己实际是工作重点没控制好，很多零碎的时间都被杂七杂八的事所干扰，另外未进行定期记录和过程管理进行反思总结。\u003c/strong>\u003c/p>","interaction":"\u003cul>\u003cli>\u003cp>\u003cstrong> &nbsp;拆书家提问设计（逐字稿）：下面请大家想工作中和学习中，有没有过这样的情景：半天下来感觉很忙，但重要的事情没有做。如果给自己2个小时整块的时间，足以办理一件或两件大事了？但零碎时间被这里跑过来一个人问个他的问题，被其他同事发来的短信或微信求助的事情霸占了。\u003cbr>\u003c/strong>\u003c/p>\u003c/li>\u003cli>请大家写下自己类似的情况和场景。请用便签记录相关的情况，写好的伙伴请举手示意.\u003c/li>\u003cli>\u003cp>\u003cstrong>好的，时间到，下面请一位伙伴给我们大家分享一下。\u003cbr>\u003c/strong>\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>如果时光倒流再来一次，回到刚才的A1那个场景，您来重新规划这段时间，您会怎么做，是否能够达到更好的效果呢？\u003cbr>请大家在便签上写下的自己的想法，给大家1分钟，写好的请举手示意。\u003cbr>（1分钟后）好的，我看大家都完成了，请大家在小组内分享一下你们的案例。\u003cbr>（6分钟后）这就是我的TF-2拆书分享，总而言之，时间最稀有的资源，认识你的时间是任何人只要肯做就能做到的，这是通向有效性之路。感谢大家参与。\u003cbr>学习者案例记录：\u003cbr>\u003c/strong>\u003c/p>\u003c/li>\u003c/ul>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>明艳：\u003c/p>\u003cp>12月底要写年终总结，同时这个月的月度总结也要写，这时也是一个人才盘点的一个月份，而且也是各个部门问我要数据的时候（如绩效数据等）。所以一天下来，各种事情都向你涌来。结果就是一天下来，我感觉事情都没完成。比如说总结还是没完成，盘点还是没做完。这种感觉比较强烈。就是这种场景比较强烈。\u003c/p>\u003cp>根据时间保证相对一段时间来做一个计划：\u003c/p>\u003cp>做总结（一小时，上午9:00-12:00）\u003c/p>\u003cp>人才盘点（10:00-12:00）\u003c/p>\u003cp>中午约谈吃饭。（把零碎的时间用起来）\u003c/p>\u003cp>数据下午来。。。\u003c/p>\u003cp>丁总：重要的事情放在第一位\u003c/p>\u003cp>颖越：每天下班时把第二天的事安排好。每天约一个人第二天吃午饭。（节约半小时）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1486063572000,"updated_at":1490027189000,"ria":true},{"id":1763,"topic":"如何决定优先","learn_goal":"学会科学选择放弃或优先的思路和方法","remark":"简介：（书）\t这本书是现代管理学之父，大师中的大师彼得•德鲁克的经典之作，他称自己是“社会生态学家”，他对社会学和经济学的影响深远，是启蒙中国现代管理终生受用的案头必读书。通过阅读本书，可以让大家相信，一群平凡的人，能做出不平凡的事业，只要组织中每个人都卓有成效。","level":"TF1-2","duration":14,"status":0,"type":0,"chaishujia":{"username":"牛牛0519","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"大家晚上好，我是贾文卿。今天很高兴由我来给大家做TF1-2的拆书分享。首先做个自我介绍，我是上海银行常州分行私人银行与财富管理中心负责人，也是银行内部培训师，为企业员工提供专业知识技能的培训宣讲，为广大客户提供专业理财服务和理性投资理念倡导，希望通过拆书家训练与工作学习更好的连接，提升自己，惠及他人。\r\n现在请在座各位分一下组，3-4人一组。\r\n 这本书是现代管理学之父，大师中的大师彼得·德鲁克的经典之作。经典经得起时间考验，值得一读再读，常读常新。它可以帮你理清思路，从任何新事变中发掘本质，找到历史渊源。管理者学会自我管理，在不断学习有效性的过程中成为一名卓有成效的管理者。","ratings_count":0,"texts":[{"id":4332,"quote":"\u003cp>请大家用1分钟时间，阅读手中的片段（两个标注“▼▲”中间的部分）。有读完的伙伴，可向我举手示意。\u003c/p>\u003cp>如何决定优先？研究起来确实很复杂，不过我们可以说，在决定哪些应该优先、哪些可以延缓这个问题上，最重要的并不是分析，而是拿出应有的勇气来。\u003c/p>\u003cp>以下是几条可以帮助确定优先顺序的重要原则，每条都与勇气密切相关：\u003c/p>\u003cp>※重将来而不重过去；\u003c/p>\u003cp>※重视机会，不能只看到困难；\u003c/p>\u003cp>※选择自己的方向，而不盲从；\u003c/p>\u003cp>※目标要高，要有新意，不能只求安全和方便。\u003c/p>\u003cp>试看许多在研究方面卓然有成的科学家的成就，与其说是他们的研究能力决定了研究的成果，倒不如说是他们寻求机会的勇气决定的研究的成果，（当然，像爱因斯坦创相对论，玻尔创原子结构，或普朗克创量子论这样的天才除外）。大凡从事研究的科学家选择研究课题时，如果着眼于易于成功而非着眼于接受挑战。那他们纵然能够成功，其成功也相当有限。他们的成功，也许可以使他们的名字在别人的论文中出现，但却不能创造出一条以他们姓名来命名的“某某氏定律“来。所以真正的成就，只属于那些善于抓住机会，选择研究课题的人，属于那些能把别人确立的准则只当作制约因素，而不当作决定因素的人。\u003c/p>","explains":"\u003cp>怎样确定优先顺序可以看以下4条重要原则，每条都与勇气密切相关：\u003cbr>\u003c/p>\u003cp>※重将来而不重过去；\u003c/p>\u003cp>※重视机会，不能只看到困难；\u003c/p>\u003cp>※选择自己的方向，而不盲从；\u003c/p>\u003cp>※目标要高，要有新意，不能只求安全和方便。\u003c/p>\u003cp>真正的成就，只属于那些善于抓住机会，选择研究课题的人，属于那些能把别人确立的准则只当作制约因素，而不当作决定因素的人。\u003c/p>\u003cp>最近开家长会，对孩子的成绩比较担忧，回家和孩子谈话问她有什么打算？孩子主要谈到的是数理化的困难，过去初中三年，数学就一直没好过，所以肯定不能念理科。觉得美术类的学校容易考好，想自我放弃数学。现在看到确定优先顺序的这4条重要原则，感觉孩子的想法有问题。和她们班主任谈了话，谈到今年高中扩招，今年的艺术类未来招生应该也有困难，而且最关键的是艺术类的学校选择和未来就业选择面比较窄，好的学校分数也不低。所以文化基础课是绝对不能放弃的，甚至要更努力。但一旦文化课好，专业分加上去，会比较占优势进好一些的学校。多了一次机会。所以从长远看，把数学学好还是很重要的，通过报美术可以向更高一层的目标够一下。现在孩子认识到了，所以兴趣和升学重要性，所以为了未来可以选择更多机会，目前优先的事是把数学补上去。给自己定一个大学的目标，小朋友讲厦门大学，那数学的分数就不能放松了，所以目前自己开始重视数学的学习，同时也请了一对一的家教。\u003c/p>","interaction":"\u003cp>请大家在各自的小组内分享自己的经验。您在生活、工作或学习中碰到实际的问题是如何决定优先？请大家写下刚才针对A1&nbsp; 反思案例，然后在自己小组中进行分享，在这个环节，给大家4分钟。\u003c/p>\u003cp>\u003cstrong>好的，时间到，下面请一位伙伴给我们大家分享一下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>现场经典实录：\u003c/p>\u003cp>伙伴—大贝\u003c/p>\u003cp>公众号的提升，原来的粉丝不多，我想正视现在的困难，不能象一开始不敢广为转发，要在朋友圈里转的时候，告诉大家那是我写的文章，放弃原来做的生活感悟的一些素材，专门分享与职场相关的。并给自己定了一个小目标，希望自己的公众号能成为大V号。\u003c/p>\u003cp>谢谢这位小伙伴给我们分享的案例，接下来请大家把自己对怎样决定事项的优先收获后准备的行动计划写下来。提醒不仅是要决心，要有具体的动作，要有明确的时限，对将来的期望。时间1分钟，完成请举手。\u003c/p>\u003cp>好的，今天我们练习的是《卓有成效的管理者》中如何决定优先？的片断，我们知道了决定优先与勇气相关，要将来和机会，根据自己的情况选择而不是其他人的，定的目标要有一定高度。希望对大家有用。\u003c/p>\u003cp>这就是我的TF-2拆书分享，感谢大家参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1483462203000,"updated_at":1489346888000,"ria":true},{"id":1709,"topic":"卓有成效的管理者五个思考习惯","learn_goal":"学会成为卓有成效的管理者五个思考习惯","remark":"这本书是现代管理学之父，大师中的大师彼得•德鲁克的经典之作，他称自己是“社会生态学家”，他对社会学和经济学的影响深远，是启蒙中国现代管理终生受用的案头必读书。通过阅读本书，可以让大家相信，一群平凡的人，能做出不平凡的事业，只要组织中每个人都卓有成效。","level":"TF1-1","duration":12,"status":0,"type":0,"chaishujia":{"username":"牛牛0519","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"大家晚上好，我是贾文卿，常州龙城分舵首批RIA训练营的六君子之一。今天很高兴由我来给大家做TF1-1的拆书分享。首先做个自我介绍，我是一名银行从业人员，二十多年一直是一名传统银行的从业者，现在是一名银行高端客户部负责人，也是银行内部培训师，为企业员工提供专业知识技能的培训宣讲，为广大客户提供专业理财服务和理性投资理念倡导，希望通过拆书家训练与工作学习更好的连接，提升自己，惠及他人。\r\n 接下来给大家介绍“拆书和拆书帮是什么？”。首先是“拆书”，这是一种学习方法论，以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，把书本中知识转化为学习者自身的能力。拆书分为个人学习型和组织学习型，个人学习型的拆书就是RIA便签法，组织学习型的就是我们今天现场的这种学习，是拆书家通过一本书加工出一场现场学习，引导和促进所有的参与者将相关的知识拆为己用。\r\n“拆书帮”是基于拆书方法的学习爱好者社群，也叫拆书帮俱乐部，是帮助更多的学习爱好者进行学习分享的公益性组织。快乐而温暖。\r\n 这本书是现代管理学之父，大师中的大师彼得·德鲁克的经典之作，他称自己是“社会","ratings_count":0,"texts":[{"id":4269,"quote":"\u003cp>原文片段：\u003c/p>\u003cp>下列五项是要成为一个卓有成效的管理者，必须在思想上养成的习惯。\u003c/p>\u003cp>1.有效的管理者知道他们的时间用在什么地方？他们所能控制的时间非常有限，他们会有系统的工作，来善用这有限的时间。\u003c/p>\u003cp>2. 有效的管理者重视对外界的贡献。他们并非为工作而工作，而是为成果而工作，他们不会一接到工作就一头钻进去，更不会开头就探究工作的技术和手段，他们会首先自问：“别人期望我，做出什么成果？”\u003c/p>\u003cp>3. 有效的管理者善于利用长处，包括自己的长处，上司长处，同事的长处和下属的长处，他们还善于抓住有利形势，做他们想做的事，他们不会把工作建立在自己的短处上，也绝不会去做自己做不了的事。\u003c/p>\u003cp>4．有效的管理者集中精力于少数重要的领域，在这少数重要的领域中，如果能够有优秀的绩效就可以产生卓越的成果。他们会按照工作的轻重缓急设定优先次序，而且坚守优先次序，他们知道要事第一。重要的事先做，不重要的事放一放，除此之外也没有其他的办法，否则反倒会一事无成。\u003c/p>\u003cp>5．最后，有效的管理者必须善于做有效的决策，他们知道有效的决策，事关处事的条理和秩序问题，也就是如何按正确的次序采取正确的步骤。他们知道一项有效的决策，总是在“不同意见讨论”的基础上作出判断，它绝不会是一致意见的产物，他们知道快速的决策多为错误的决策，真正不可或缺的决策数量并不多，但一定是根本性的决策。他们需要的是正确的战略，而不是令人眼花缭乱的战术。\u003c/p>","explains":"\u003cp>今天分享的便签是：如何成为卓有成效的管理者？\u003c/p>\u003cp>要成为一个卓有成效的管理者，必须在思想上养成五大习惯：善用有限的时间，重视对外界的贡献，善于利用长处，集中精力于少数重要的领域，善于做有效的决策。&nbsp;\u003c/p>","interaction":"\u003cp>分行刚开业的时候，柜面自然来的客户特别少。根据惯性思维，我建议社区做一些社区营销。领导并不认可，他说那样做未来柜面会很乱。但看我不理解，就让我们开展一些这样的活动试试，做了2次社区宣传后我才发现，这样做的确是很有问题：一方面我们花了大量的时间和人力在社区宣传，但起效慢，而且周边普通客户对我们业务的贡献度较低。另一方面，太多普通客户占了柜面，使高端客户体验度很差。人多起来柜面根本服务跟不上，柜面人员特别累并占用过多的时间，反面使柜面服务质量差了。现在想来我们的定位的确必须要在真正的重要客群上下功夫，才能达到有效。把柜面的时间用于我们适合的群体，才能突出我们的优势，提高效率。现在学习了卓有成效的管理者的五大思想习惯，想来领导一开始的决策是正确的。利用有限的人力、物力、时间，集中精力做中高端客户的财富管理，充分发挥我行品质优势，才能更有效的利用资源和时间，从而提高整体贡献，这才是有效的决策。\u003c/p>\u003cp>&nbsp; &nbsp;作为部门团队负责人，在工作重点的选择上要重视这五点。目前我们正在制定年底及新年与某旅游公司的合作，借助他们的团队及物理资源协助我们宣传，他们在全市有100多个网点，工作人员及客群均较多。长期看应全面合作。但仅年终及新年的时间并不长，我要考虑充分利用这段短期的时间，提升综合贡献度。本周我准备首先仅合作武进湖塘地区的几个门店（离我行近），4个月的时间把这几个门店的工作人员集中培训，利用他们营销人员的特长，主要介绍我行优势信用卡和借记卡。集中精力提升发卡量。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482768032000,"updated_at":1489346196000,"ria":true},{"id":1708,"topic":"卓有成效的管理者的五个习惯","learn_goal":"学会卓有成效的管理者的五个习惯","remark":"这本书是现代管理学之父，大师中的大师彼得•德鲁克的经典之作，他称自己是“社会生态学家”，他对社会学和经济学的影响深远，是启蒙中国现代管理终生受用的案头必读书。通过阅读本书，可以让大家相信，一群平凡的人，能做出不平凡的事业，只要组织中每个人都卓有成效","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"牛牛0519","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":null,"ratings_count":0,"texts":[{"id":4268,"quote":"\u003cp>原文片段：\u003c/p>\u003cp>下列五项是要成为一个卓有成效的管理者，必须在思想上养成的习惯。\u003c/p>\u003cp>1.有效的管理者知道他们的时间用在什么地方？他们所能控制的时间非常有限，他们会有系统的工作，来善用这有限的时间。\u003c/p>\u003cp>2. 有效的管理者重视对外界的贡献。他们并非为工作而工作，而是为成果而工作，他们不会一接到工作就一头钻进去，更不会开头就探究工作的技术和手段，他们会首先自问：“别人期望我，做出什么成果？”\u003c/p>\u003cp>3. 有效的管理者善于利用长处，包括自己的长处，上司长处，同事的长处和下属的长处，他们还善于抓住有利形势，做他们想做的事，他们不会把工作建立在自己的短处上，也绝不会去做自己做不了的事。\u003c/p>\u003cp>4．有效的管理者集中精力于少数重要的领域，在这少数重要的领域中，如果能够有优秀的绩效就可以产生卓越的成果。他们会按照工作的轻重缓急设定优先次序，而且坚守优先次序，他们知道要事第一。重要的事先做，不重要的事放一放，除此之外也没有其他的办法，否则反倒会一事无成。\u003c/p>\u003cp>5．最后，有效的管理者必须善于做有效的决策，他们知道有效的决策，事关处事的条理和秩序问题，也就是如何按正确的次序采取正确的步骤。他们知道一项有效的决策，总是在“不同意见讨论”的基础上作出判断，它绝不会是一致意见的产物，他们知道快速的决策多为错误的决策，真正不可或缺的决策数量并不多，但一定是根本性的决策。他们需要的是正确的战略，而不是令人眼花缭乱的战术。\u003c/p>","explains":"\u003cp>今天分享的便签是：如何成为卓有成效的管理者？\u003c/p>\u003cp>要成为一个卓有成效的管理者，必须在思想上养成五大习惯：善用有限的时间，重视对外界的贡献，善于利用长处，集中精力于少数重要的领域，善于做有效的决策。&nbsp;\u003c/p>","interaction":"\u003cp>我行2015年6月27日正式开业，刚开业的时候，柜面自然来的客户特别少。根据惯性思维，我建议社区做一些社区营销。领导并不认可，他说那样做未来柜面会很乱。但看我不理解，就让我们开展一些这样的活动试试，做了2次社区宣传后我才发现，这样做的确是很有问题：一方面我们花了大量的时间和人力在社区宣传，但起效慢，而且周边普通客户对我们业务的贡献度较低。另一方面，太多普通客户占了柜面，使高端客户体验度很差。人多起来柜面根本服务跟不上，柜面人员特别累并占用过多的时间，反面使柜面服务质量差了。现在想来我们的定位的确必须要在真正的重要客群上下功夫，才能达到有效。把柜面的时间用于我们适合的群体，才能突出我们的优势，提高效率。现在学习了卓有成效的管理者的五大思想习惯，想来领导一开始的决策是正确的。利用有限的人力、物力、时间，集中精力做中高端客户的财富管理，充分发挥我行品质优势，才能更有效的利用资源和时间，从而提高整体贡献，这才是有效的决策。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482767913000,"updated_at":1489339943000,"ria":true},{"id":1669,"topic":"如何才能集中精力干好一件事","learn_goal":"学习者能够做到怎样集中精力干好一件事","remark":"它的作者是彼得.德鲁克（美），他是管理学科开创者，被尊为“大师中的大师”、“现代管理学之父”，他的思想传播影响了130多个国家。中国领导人胡耀邦、朱镕基、微软总裁比尔.盖茨都积极推荐此本书。","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"大家好，我是金家东，拆书帮常州筹备分舵的宣传长老，二级拆书家。今天很高兴由我来给大家做TF3-2的拆书分享。在跟随我完成本次RIA现场学习后，学习者能够做到怎样集中精力干好一件事。这本《卓有成效的管理者》是管理学大师德鲁克撰写，他被称为管理者永恒的导师。\r\n【事件场景】在生活中我们是否会一边玩着手机，一边和我们的家人谈话？在工作中，有时候领导交待我们一件事情，感觉太容易了，明天再做吧；或者我们会同时做几件事情，因为我们自我感觉是最聪明的。\r\n【提问】你这样做，你的家人是怎样的反应呢？领导交待给你的事情有没有很好的完成呢？你有没有感觉到，自认为最聪明的我们，往往总是做错事吗？\r\n【影响】聪明的人，往往却不会成功。假如我们不能认真和家人谈话，对方会认为你不重视而引起不和睦；工作中不能集中精力做好一件事情，会导致我们犯错；对工作中的事情不重视，会导致你产生拖延症，而最后急急忙忙赶工的结果是可想而知的。\r\n【解决】今天这个片段，告诉我们怎样去规划好时间，不至于最后匆忙赶工，改掉我们的拖延症，从而能够每次只集中精力干好一件事情。","ratings_count":0,"texts":[{"id":4230,"quote":"\u003cp>【A1】请大家自测\u003c/p>\u003cp>拆书节提问设计（逐字稿）：\u003c/p>\u003cp>请大家用1-2分钟的时间，在“集中精力干事情”方面给自己评分，以下5个题目，请按照1~6分的标准给自己打分，1代表完全不符合，6代表非常符合。完成的伙伴请举手示意。\u003c/p>\u003cp>在集中精力做好一件事情这方面给自己评分\u003c/p>\u003cp>&nbsp;请你做一个简单的测试，看看你在集中精力干事情方面的现状。以下5个题目，请按照1~6分的标准给自己打分，1代表完全不符合，6代表非常符合。请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1表示很不符合，6表示非常符合，请用“√”方式）。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1.我认为做事情总不免有出乎意料的情况发生。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.做一件事情，我总是紧在前面，以免最后赶工。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3. 做好一件事情，我会按部就班，稳定前进。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4. 我不喜欢拖延。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5. 我不会同时做几件事情。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【I】解释自测题\u003c/p>\u003cp>通过刚才给自己在“集中精力干好一件事情”方面的评分，让自己客观看待能否圆满完成一件事情的现状，这次自测量表是采用行为特征量化的方式，让学习者了解现状的一种测评方法。测评结果不是唯一的标准和一成不变的，只是当下的一种反映，同时也是作为让我们在“集中精力干好一件事情”方面做的更好的一个参考和新的起点。\u003c/p>\u003cp>假如你的总分在15分以下，那你在集中注意力做事情方面应该有所提高。\u003c/p>\u003cp>假如你的总分在20分以上，那你在集中注意力做事情方面做的就比较好。\u003c/p>\u003cp>【R】阅读原书拆页\u003c/p>\u003cp>请大家用2分钟时间，阅读手中的片段（标注“☆”中间的部分）。请阅读完的伙伴向我举手示意。\u003c/p>\u003cp>好了，时间到。如果有小伙伴还没看完的，也没有关系。我可以在后续的分享中，继续为大家解读。\u003c/p>\u003cp>【R原文片段】《卓有成效的管理者》P100\u003cbr>\u003c/p>\u003cp>一个人如何能够完成这么多的大事，而且是这样艰巨的大事，“秘诀”尽在其中：每次只集中精力干好一件事。而结果是，他们所用的时间总比别人少的多。\u003c/p>\u003cp>有些人一事无成，而实际上他们却做得很吃力。第一，他们低估了完成一件任务所需的时间。他们总以为万事顺利，却总不免有出乎意料的情况发生。其次，所谓意料之外者，正应该在我们意料之中。而所谓意料之中，往往从来没有令人愉快的意外。所以，有效的管理者对时间需求的估计宁可有余，而不可不足。第二，一般的管理者（往往也是不大有效的管理者）总喜欢赶工--而赶工的结果，总不免使进度更加落后。有效的管理者不愿赛跑，他们按部就班，稳定前进。第三，一般的管理者喜欢同时着手几件要事，结果对每一件事，他们都无法获得足够的最低整块时间。只要如何一件事情受阻，全部事情也都跟着受阻了。\u003c/p>\u003cp>有效的管理者知道他们要完成许多工作，但他们在一段时间内只集中努力做好一件事--集中他们本人的时间和精力，以及整个组织的时间和精力。他们坚持把重要的事情放在前面先做，而每次只做好一件事。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导\u003cbr>\u003c/p>\u003cp>通过阅读刚才的片段，相信大家已经对“如何集中精力干好一件事情”有了进一步的理解。接下来让我们一起来学习这个片段：\u003c/p>\u003cp>1.&nbsp;这一段的关键词是什么？\u003c/p>\u003cp>2.&nbsp;这些关键词是什么关系，先后顺序或逻辑是什么？\u003c/p>\u003cp>3.&nbsp;作者陈述了哪些主要观点？\u003c/p>\u003cp>要想做成一件事情所用的时间总比别人少的多，你必须每次只集中精力干好一件事，具体步骤是这样的：1、不要低估了完成一件任务所需的时间。2、不在最后时刻赶工，应该按部就班，稳定前进。3、不要同时做几件事情。\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>我们刚刚学习了“集中精力干好一件事情”技巧，为了让大家更好地理解，接下来设置一个场景让大家在小组内讨论演练。请大家认真听一下这个演练的场景：公司决定在2017年1月15日举行年会，距今天只有20多天了。老板让HRD做年会的总导演，而HRD本身还有部门的事情要做，那么HRD如何集中精力做好年会的准备工作呢？在准备工作中，HRD和各个部门需要就节目流程、财务预算、后期保障、人员安排等进行交流协调。公司给HRD配备一个副导演，负责各部门之间的协调。\u003c/p>\u003cp>现在请每2人一组进行演练，一个扮演总导演，用今天拆页“集中精力干好一件事情”的技巧对副导演进行工作安排，另一个扮演副导演和总导演进行互动对话。\u003c/p>\u003cp>演练时间6分钟，现在开始，6分钟后，我会邀请一组角色扮演。\u003c/p>\u003cp>【角色扮演】\u003c/p>\u003cp>导演李朋三：从15日年会开始倒推，14日布置会场，12日开始第二次彩排，第二周第一次彩排，第一周节目安排。你看看怎么样？\u003c/p>\u003cp>副导演马文丽：好的，我就按照这样的安排去推进执行。我会集中精力做好这件事的。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>在生活或工作中，我们经常需要和孩子、父母和爱人决定家庭里的大小事情，譬如你在家里做饭的时候，又要照顾孩子，这时候你怎么集中精力做饭呢？或者你和公司里的领导、同事和员工决定经营及管理事务，譬如这周要交年度总结，你又要兼顾部门的其他工作，你会怎样集中精力做好总结呢？请用今天学习的拆页技巧，在一周内（保鲜期内）选个场景做一次具体的任务。\u003c/p>\u003cp>回去进行实践并做复盘，实践的过程和复盘的内容可以发到群里，拆书家伙伴可以点评。\u003c/p>\u003cp>学习者案例记录：公司要做述职报告，在年会上发言，要求这个星期完成，而本部门还有许多事情要做：1、完成述职报告的预计时间大概4个小时。2、每天安排1个小时。晚上空余时间构思内容。3、在写报告的同时，集中精力做这一件事情，不被其他事情打扰。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1482457255000,"updated_at":1488085075000,"ria":true},{"id":1616,"topic":"如何因事用人","learn_goal":"无论是工作亦或是生活中，我们如何运用每个成员的长处（因事用人","remark":"没有人是完美的，一个有长处之人必定有其短处。我们认识一个人需要从不同侧面进行了解，从而让某其位的人能够事半功倍谋其事！","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"sammi","city":"贵阳"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"这次RIA现场，旨在引导大家，无论是工作亦或是生活中，我们如何运用每个成员的长处来促使工作效率最大化、家庭更和谐。\r\n 今天我带拆的是《卓有成效的管理者》一书其中2个片段。这本书的作者被誉为现代管理学之父的彼得.德鲁克。在贵阳也有以德鲁克命名的周三德鲁克学习社群。\r\n 每个人或多或少都有这样的困扰：我在单位是个领导，但是我的下属工作总达不到我的要求！在家庭里，另一半或是孩子，也总是出现这样那样的一些问题，总让你有操不完的心！ \r\n 这本书为我们论述了一个管理者如何做到卓有成效，也因此成为德鲁克最著名的管理学著作之一。","ratings_count":0,"texts":[{"id":4171,"quote":"\u003cp>片段一：\u003c/p>\u003cp>P71　　有效的管理者知道他们之所以用人，是用人来做事，而不是用人来投主管之所好。他们知道，一位红得发紫的女明星能有票房，让她发发脾气又有什么关系呢。剧团经理知道，如果女明星常发脾气而有助于票房，也许他之所以受聘为经理，就是为了承受她的脾气。以学校来说，第一流的优秀教师会不会奉承校长，肯不肯在教务会议上安静而不咆哮，那有什么关系呢？校长之所以应聘为校长，就是为了使第一流的教师或学者能够教学有效。所以即使在其他方面不太愉快，也是值得的。\u003c/p>\u003cp>　　有效的管理者从来不问：“他能跟我合得来吗？”他们问的是他贡献了什么？”他们从来不问：“他不能做什么？”他们问的是：“他能做些什么？”所以在用人时，他们用的都是在某一方面有所长的人，而不是在各方面都过得去的人。\u003c/p>\u003cp>　　识人之所长以及用人之所长，可以说是人的一种本能。所谓的“完美的人”或“成熟的个性”，这些说法其实都忽视了人最特殊的天赋：人本能地会将其一切资源都用于某项活动、某个领域，以期取得某个方面的成就。换言之，是忽视了人的卓越性。因为卓越通常只能表现在某一个方面，最多也只能表现在个别的几个方面。\u003c/p>\u003cp>　　当然，世上确有多才多艺的人，这就是通常所谓的“全才”。但真正能在多方面都有杰出造诣的人，至今还没有出现。达·芬奇总算多才多艺了，但他最突出的成就只是在绘画上。歌德的诗如果没有流传下来，那我们今天认识的歌德，虽然知道他对光学和哲学有研究，但恐怕不见得能在百科全书上找到他的赫赫大名。几位世人皆知的伟人尚且如此，更何况我们这些凡人。因此，位管理者如果不能发掘人的长处，并设法使其长处发挥作用，那么他只有受到人之弱点、人之短处、人之缺失的影响，结果是既完不成任务，又缺乏有效性。用人时老是坚持客观上不可能达到的标准，或过多地强调别人的弱点，那纵然算不上是滥用，起码也是误用。\u003c/p>\u003cp>片段二：\u003c/p>\u003cp>P73　　有效的管理者并不是不知道人有缺点。他了解他自己的任务，在于如何使某人充分发挥其税务会计的才干，而不斤斤计较他不善于与人打交道。因此，他不会贸然指派这个人出任经理的职位。要与人打交道，完全可以找别人，而第一流的税务会计师更是不可多得的人才。所以，这个人能够做什么，才是组织器重他的原因。而他不能做什么，则仅是他的限制，仅此而已。\u003c/p>\u003cp>　　这层道理谁都清楚。可是，为什么做起来又是另一回事呢？为什么世间的管理者很多，而真能发挥他人长处者却不多？以林肯为例，为什么他要在指派了三位总司令之后，才能学会用人所长的道理？\u003c/p>\u003cp>　　原因很简单。主要是因为管理者往往以为他们首要的任务不在于因人设事，而在于因事用人。所以，通常是先有了某一个职位，再物色人选来出任该职位。这样的步骤，往往引人走入歧途，物色的对象，往往只是一位“最不至于出差错”的人选一也就是仅合乎最低要求”的人选。其结果，自然难免都是平平庸底的人选了。\u003c/p>\u003cp>　　要避免出现这一错误，最常见的解决办法是“因人设事”。然而这哪是什么解决办法，这也许比原有的错误还糟，除非是规模极小、事务极简的组织可能例外。要知道职位应该是根据客观需要而设定的，应由任务而定，而不应因人而定。\u003c/p>\u003cp>　　为什么“因人设事”不能解决问题，是因为组织中任何一个职位的变更，都会造成一连串的连锁反应。组织中的职位都是相互联系、相互依存的，牵一发而动全身。我们不能为了替某人安插某一个职位，而使组织中的每一个人都受到牵连。因人设事的结果，是为了安插某一个人，一大群人都受到连累。\u003c/p>","explains":"\u003cp>片段一：\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;拆页用了4个例子告诉我们，没有人是完美的，一个有长处之人必定有其短处。我们认识一个人需要从不同侧面进行了解。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;我原来就犯过一个错，我总是让能力强的孩子担任我所教的数学科代表，他们每天整理收作业的能力确实很强，但是他们的成绩却不是最好。我还由此批评责备他们不用功学习。搞得孩子们非常气馁，更提不起学习兴趣。\u003c/p>\u003cp>通过拆页学习，现在我委任科代表前会问自己几个问题：\u003c/p>\u003cp>1、他贡献了什么？\u003c/p>\u003cp>2、他能做些什么？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;然后根据科代表一职的工作需求确定谁能担任。\u003c/p>\u003cp>所以我会在平时用心观察每个学生，同时将原来唯一的科代表分拆成为不同的大法师：积极主动帮忙做事的孩子是整理大法师、思维好学科能力强的孩子是学霸大法师。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;这样的有效管理，不仅能够用于工作，家庭分工里也非常实用。\u003c/p>\u003cp>片段二：\u003c/p>\u003cp>&nbsp; &nbsp;看完了吗？有没有觉得每个字都认识但是合起来看不懂？我看第一遍是就特别晕，但觉得应该是很重要的部分，这段拆页我反复看了5遍。它意思是说人和事都同等重要，同时我们需要因事用人，如果两者不能兼得则根据当下的情境两害取其轻。\u003c/p>\u003cp>WHY\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;我和老公创业的翰智达培训，我们两有明确分工：我负责课程、他负责所有外联。但2年下来，我们发现对外机构的连接并不理想。\u003c/p>\u003cp>根据拆页的学习，我们做了以下调整：\u003c/p>\u003cp>1、设置一个岗位（事）\u003c/p>\u003cp>2、讨论他贡献了什么？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;3、他能做些什么？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;4、最后只用这个人的长处，忽略其短处。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;所以我和老公明确对于翰智达来说外联的重要性；然后讨论了彼此这段时间来为翰智达的贡献；再分别理出自己能够做的外联事宜；最后我们决定联系中的机构外联他继续跟进，教育系统外联我来跟进。然后大家如果有关注我朋友圈，能够看到我3个月来在家庭教育指导中心的系列讲座。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;这样的有效促进工作的管理者方法，适用于家庭、同样适用于工作。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;&nbsp;\u003c/strong>\u003c/p>","interaction":"\u003cp>片段一：\u003c/p>\u003cp>A1\u003c/p>\u003cp>大家听我说下面这些话，你觉得哪几句是你熟悉的，甚至是你近期在家庭里说过的：\u003c/p>\u003cp>这个月水电煤气费还没交吧？你怎么还在看电视，吃饭了不用来帮忙吗？这周的衣服怎么又是我来洗！每次全家人出游都是我前前后后做安排！\u003c/p>\u003cp>我们来八卦一下，你最近一次说过类似这些话语，是什么时候？大概什么样的情景？\u003c/p>\u003cp>丹：我每天都在给老公或孩子说这样的话：你怎么还在玩手机？！你怎么还在和孩子玩手机？这句话每天都在重复说！\u003c/p>\u003cp>兰：我老公脾气不好，一大早就会开始吼人。我冒火就会说：你怎么这么不耐烦，能不能有点耐心啊？\u003c/p>\u003cp>琴：我们家经常说这样的话。我是全职妈妈，家里水电煤气费是我在交，我老公经常会这样问我。每一次我们出游，所有具体的事都是我在忙前忙后。\u003c/p>\u003cp>A2\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;设想一下，这周您们全家要一起出游，你要远离那些曾经让你感到生气或愤怒的情绪。运用今天的拆页，哪些安排上可以有不同的做法，怎样做能把每个家庭成员的优势发挥得更好？请大家分享。\u003c/p>\u003cp>丹：我一直都主导所有安排计划，好像形成习惯。但是现在发现我老公其实有很多贡献，对我脾气的忍让，对我的尊重，他在我成长过程中也教会我成熟的处理事情等等……我以后不会有这么多的抱怨啦，会从其他方面去更多的肯定他。\u003c/p>\u003cp>宋：我不会再全部包办，现在想想可以让我的父母准备一些出游食物，安排出游路线。这样我自己也轻松很多。\u003c/p>\u003cp>兰：我们家出去玩，我基本不操心，都我老公安排。现在看到老公能做的东西很多，对家庭有很多贡献。\u003c/p>\u003cp>琴：我可以让4年级的儿子参与到旅行计划中来，这样儿子能够在这次出游中得到最大的成长。也增加家庭凝聚力，让每个人都能够享受这一次旅行。\u003c/p>\u003cp>片段二：\u003c/p>\u003cp>A3\u003c/p>\u003cp>刚刚我们学习了，通过以上4条，我们在一个岗位上寻找合适的人，由此让我们办事效率提高。寻找我们一起做一个演练。请大家认真听要演练的场景：下周三我们要做拆书帮分享会，在这个分享会上，需要有主持人、分享者和摄影大侠。\u003c/p>\u003cp>现在，请每5人一组，进行演练。一个人扮演负责人，其他人扮演想要认领这些任务的自荐者。\u003c/p>\u003cp>演练时间5分钟，5分钟后请大家来分享你们组的最后人选。现在开始。\u003c/p>\u003cp>琴：给我的提示是，每设置一个岗位后，我们可以来衡量自身的优点。然后进行对比，确定人选。\u003c/p>\u003cp>兰：当我们把问题转向直接能贡献什么，到原来这事和我没关系，从这样两种角色来讨论工作时。用“贡献”这样的词语会让彼此间讨论氛围好很多。如果讨论谁负责，那是被强迫的。讨论贡献，感觉是主动、积极的。心里序位会不一样，从被动到主动的转化，让人觉得心里感觉“我愿意”。\u003c/p>\u003cp>宋：有些人可能自己知道自己有某方面长处，但是基于害羞会失去这些机会。\u003c/p>\u003cp>A2\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;设想一下，你是单位领导，通过今天的学习，怎样能让你的下属&nbsp;各司其职、各尽其责。通过今天的学习，你想在家庭或单位中如何运用？请大家都来分享分享。\u003c/p>\u003cp>丹：给我做施工的师傅，我会对他各方面都有要求。通过今天学习，我觉得看到他长处，可以忽略他的不足。只要他做好了岗位上的事，其他事我可以自己有所改变。\u003c/p>\u003cp>兰：用人之所长。我的工作中正好遇到这样的问题。我现在开始考虑，先给员工设置一个具体岗位，这个员工对公司贡献很多，他在培训上有很多经验，能够贡献 他的专业知识以及对公司的忠诚。他能够很好的为公司其他员工做培训课程设计。他最近在工作中因为一层层领导工作关系，目前情绪低落。如果我想发挥他在培训行业的长处，那我可以忽略他目前的情绪状态。\u003c/p>\u003cp>宋：能力也是可以培养的。设置一个岗位（一份工作），激发员工的潜能。\u003c/p>\u003cp>琴：我会把给儿子检查作业这个岗位让给更能胜任的爸爸，发挥爸爸的特长，让孩子得到更专业的帮助。今天回家我就和爸爸沟通，也希望爸爸和儿子能有更好的连接。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1481728337000,"updated_at":1481728337000,"ria":true},{"id":1551,"topic":"如何使专业人员的工作卓有成效","learn_goal":"掌握专业人员卓有成效的本质含义以及实现途径，以更好提升绩效。","remark":"知识工作者并不产生“实物”，他生产的是构想、信息和观念。知识工作者通常是一位专业人员。原则上，只有当他掌握了某种专门知识后，他的工作才能卓有成效。也就是说，他必须有所专长。但是，所谓专长，本身就是片面的、孤立的。一个专业人员的产出必须与其他人的产出结合在一起，才能产生成果。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"Poul","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！接下来，我带领大家一起拆解片段1内容。由于人员比较多，共有12人，为便于交流讨论，我们分三组，每组4人。第一组是我左手边四个，第二组是中间四个，第三组是我右手边四个。\r\n首先，我介绍一下拆解书目《卓有成效的管理者》，是美国管理学宗师德鲁克的经典著作，由机械工业出版社出版。这本书将管理理论与丰富实践案例相结合，阐述如何成为一名卓有成效的管理者，助你成为卓有成效的管理者，提高工作效率、降低工作成本。","ratings_count":0,"texts":[{"id":4096,"quote":"\u003cp>《卓有成效的管理者》第三章“我能贡献什么”片段（P62）：知识工作者并不产生“实物”，他生产的是构想、信息和观念。知识工作者通常是一位专业人员。原则上，只有当他掌握了某种专门知识后，他的工作才能卓有成效。也就是说，他必须有所专长。但是，所谓专长，本身就是片面的、孤立的。一个专业人员的产出必须与其他人的产出结合在一起，才能产生成果。\u003c/p>","explains":"\u003cp>一个专业人员的产出必须与其他人的产出结合在一起，才能产生成果。但这意思并不是说专业人员应变成“通才”，而是说专业人员必须使他本人有效，必须使他的专才有效。他必须考虑到他的产出供什么人使用，也必须了解用户应该知道些什么才能有效使用他的产出，从而产生成果。\u003c/p>\u003cp>这意思是说，知识分子有责任让别人了解自己。有些专业人员认为，普通人应该并且可以做出努力来理解他们，甚至认为他们只要能够和同行的少数专业人员沟通就够了，这真是傲慢的自大。即使是在大学或者研究所，这样的态度也会使专业人员的工作变成无用，使得专业人员的知识学问变成卖弄玄虚的手段，说句实话，目前这样的态度仍然普遍。一个人如果想成为管理者，换句话说，如果愿以贡献为目标，就必须使自己的“产品”--即他的知识能为别人所用。卓有成效的管理者都懂得这一点，因为他们都有想把工作干得更好的心理动力，总想了解别人需要什么、发现了什么以及能理解什么。\u003c/p>","interaction":"\u003cp>一、请各小组用5分钟的时间分享各自的过往经验，为了对组织产生更大的贡献与成果，如何将自身的产出与其他人的产出结合在一起？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享记录1：这让我联想起踢足球，每个队员都有自己的擅长之处，在进攻时主攻队员往往是全场的焦点，但其他队员也一样非常重要，其他队员要发挥自身所长，配合与协作主攻队员过关斩将，更加顺畅进球。\u003c/p>\u003cp>分享记录2：小学每个年度都会开展老师赛课活动，从学校-镇区-县-市-省学校老师中进行层层选拔，虽说每个学校推荐1人参与镇区级学校老师的赛课活动，这也需要团队的共同奉献。选一个老师作为代表，学校进行赛课的一系列培养，将老师们好的经验集于一个代表，有些老师获得荣誉后会回来积极分享（贡献）自己的专长并培养其他老师，有些人则管自己的私事，而勇于承担着则往往获得更多的鼓励，大部分积极贡献的人都会被提拔为干部。\u003c/p>\u003cp>二、用1分钟请大家在便签纸上写下。为了与同事更好配合协作、发挥专业所长，对组织产生更大的贡献与成果，你认为以后要如何做？要求包含具体做法和可衡量或者可观测结果的便签。\u003c/p>\u003cp>分享记录1：我发起筹备拆书帮东莞分舵，目的是为了帮助更多的人成为拆书家，因拆书帮而受益，在三个月内，我要做以下几点：1、搭建拆书活动平台，每周组织一次线下拆书活动；2、组织开展RIA训练营活动；3、指导、帮助其他成员成为拆书家；4、加强与总舵和其他分舵的联系。\u003c/p>\u003cp>分享记录2：我负责微信跨界合作领域的工作，为了更好将自己的产出与别人的产出结合一起产生更大的成果，我认为以后的工作要做到以下几点：1、推动流程标准化，要明确并制定业务与微信运营跨界的流程，明确每一环节流程节点的负责人、工作内容、时限要求等；2、合作模式分类与固化化：将合作场景与合作模式进行分类，以便更好总结经验进行推广。\u003c/p>\u003cp>分享记录3：我一方面要找到自己的专长，另一方面要跟自己的团队队员的专长相互配合协作，为企业贡献更大的成果。\u003c/p>\u003cp>分享记录4：我认为以后的工作中，对上对下平级都要多沟通，取长补短、相互协作，具体措施包含但不限于：1、了解团队成员的优势，取其长处；2、了解自己的优势，发挥自己所长、做好自身工作。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1481102819000,"updated_at":1481102819000,"ria":true},{"id":1550,"topic":"管理者的承诺","learn_goal":"深刻理解“管理者贡献”的具体含义以及行为模式，以提升自身绩效","remark":"有效的管理者一定注重贡献，可是大多数的管理者都做不到这一点。他们重视勤奋，但忽略成果。他们耿耿于怀的是：所服务的组织和上司是否亏待了他们，是否该为他们做些什么。重视贡献，才能使管理者的注意力不为其本身的专长所限，不为其本身的技术所限，不为其本身所属的部门所限，才能看到整体的绩效，同时也才能使他更加重视外部世界。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"Poul","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！我是今天的拆书家叶佐旭，来自中国移动东莞分公司，目前主要负责集团市场运营工作，同时我也是一名广东移动内部培训师，主讲《内部服务与协作》、《PPT制作与演示技巧》等课程。我本人对企业管理这一领域比较感兴趣，今天很高兴跟大家一起来探讨、一起拆解《卓有成效的管理者》这本书籍。\r\n“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到同主题培训的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\r\n“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书俱乐部）。拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。","ratings_count":0,"texts":[{"id":4084,"quote":"\u003cp>《卓有成效的管理者》第三章《我能贡献什么》P53。重视贡献，才能使管理者的注意力不为其本身的专长所限，不为其本身的技术所限，不为其本身所属的部门所限，才能看到整体的绩效，同时也才能使他更加重视外部世界。只有外部世界才是产生成果的地方。因此，他会考虑自己的技能、专长、作用，以及所属的单位与整个组织以及组织目标的关系。\u003c/p>","explains":"\u003cp>有效的管理者一定注重贡献，并懂得将自己的工作与长远目标结合起来。他应该常问：“对我服务的机构，在绩效和成果上，我能有什么贡献？”他强调的是责任。\u003c/p>\u003cp>管理者如果不自问“我可以做出什么贡献”，他在工作中就不会有远大的目标，甚至可能把目标搞错而且特别容易对“贡献”一词只有狭义的理解。一般来说，组织对成效的要求往往表现在以下三个方面：直接成果；树立新的价值观以及对这些价值观的重新确认；培养与开发明天所需要的人才。如果在成效中缺少这三方面中的任何一个方面，那么机构就会衰败甚至垮台。因此，管理者若想做点贡献，就必须在这三方面下功夫。不过，在这三者之中，哪个最重要，哪个其次，那就要看管理者本人的情况，以及他所处的地位以及机构本身的需要了。\u003c/p>","interaction":"\u003cp>A1：我记得10年前，刚入职那两三年，做工作常常都是接到一件任务、则做一件事，很多时候为了做这个事情而做事情，基本不会去想做事的目的是什么？对班组、部门、公司的贡献在哪里？有一天，我回顾总结季度的工作，发现好像自己没有什么业绩材料可以拿出手来讲的。后来，我就做了改进，要清晰自己的定位与岗位价值，将自身的目标与部门、公司的绩效目标有机联系起来。比如，我负责的其中一项工作是区域分公司流程与制度管理，我的直接成果是如何建立规范的流程制度管理体系，使得分公司市场运作更加规范、畅顺，具体疑点的目标是诊断流程制度管理方面的问题，并牵头或者推动相关部门去制定或者优化流程、制度。\u003c/p>\u003cp>A2：有效的管理者一定注重贡献，并懂得将自己的工作与组织的绩效目标有机结合起来。我目前也是团队主管，为了使得管理者的这个承诺能到到落实，我以后将做到以下几点：\u003c/p>\u003cp>1、明确自己的定位以及岗位价值在哪里，即可以为组织带来什么样的贡献，并体现在年度、季度、月度工作目标上。例如我现在负责集团代理管理工作，我的岗位贡献是确保2017年集团代理要完成2个亿的业务收入。\u003c/p>\u003cp>2、计划要有执行与监控：目标分解之后，要有具体的计划与执行步骤，而且要监控计划的执行情况，尤其是成果情况。\u003c/p>\u003cp>3、事后有总结反馈：项目计划完成后，要对自身的工作目标以及岗位贡献进行回顾。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1481101754000,"updated_at":1481101819000,"ria":true},{"id":1220,"topic":"向彼得·德鲁克学时间管理","learn_goal":"学会时间管理的三个步骤","remark":"","level":"TF2-4","duration":30,"status":0,"type":0,"chaishujia":{"username":"鲁锋","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"[事件]你们有没有发现，不知道从什么时候开始，市面上突然出现了很多时间管理、知识管理、人生管理、物品管理的书。[影响]也不知道从什么时候开始，我们的生活变得乱糟糟，我们的时间变成了碎片，我们头脑里的知识快速的过时，朋友圈里的同学们跑的那么快，我们似乎赶不上了，[提问]我们应该怎么办呢？[解决]现代管理学之父彼得·德鲁克在1966年写了一本书叫《卓有成效的管理者》，他告诉我们，在现在这个时代，其实每个人都是管理者，你需要管理你的时间、特长、成果，所以这本书这不仅是一本高管阅读的管理学书籍，他更告诉我们每个人，如何高效的工作和生活。那么今天我们就一起来看看德鲁克是如何教我们时间管理的吧。","ratings_count":0,"texts":[{"id":3471,"quote":"\u003cp>\u003cstrong>【A1】请大家自测\u003c/strong>\u003c/p>\u003cp>我们先做个自测题，看看你在工作方面的时间管理如何：（请阅读下面表格中的每句话，根据实际情况给自己打分，1表示完全不符合，6表示非常符合）\u003c/p>\u003cp>\u003cstrong>【I】解释自测题\u003c/strong>\u003c/p>\u003cp>大家都做完了题目，满分的请举手……[简短互动]这个自测只是让大家了解一下自己的时间管理现状，以及工作是否有效，接下来我们一起来读一下今天的拆页。\u003c/p>\u003cp>\u003cstrong>【R】阅读原文拆页\u003c/strong>\u003c/p>\u003cp>每位管理者的时间，都有很大部分是被浪费掉的。表面上看起来，每件事似乎都非办不可，但实际上却毫无意义。但是，即使是只想获得最低程度的有效性，管理者的绝大部分任务也需要相当多的整块时间。如果每一次所花的时间少于这个极限，事情就做不好，所花的时间就是浪费，再做就得从头开始。\u003c/p>\u003cp>举例来说，写一份报告大概得花6～8小时才能完成初稿。如果说每次花15分钟，每天2次，一共花上2星期，虽然总时间也达到7小时。恐怕结果还是一张白卷。但是如果能够关起门来，切断电话，连续做上五六个小时，一份相当不错的初稿就应该差不多了。有了这份初稿，他才能做零星的补充，才能逐旬逐段地润色，修改和整理。\u003c/p>\u003cp>\u003cstrong>每一位知识工作者，尤其是每一位管理者，要想有效就必须能将时间做整块的运用。如果将时间分割开来零星使用，纵然总时间相同，结果时间也肯定不够。\u003c/strong>\u003c/p>\u003cp>尤其是与他人一起工作时，这一点更为重要。与他人一起工作，正是管理者的中心工作之一。人都是时间消费者，而大多数人也是时间浪费者。\u003c/p>","explains":"\u003cp>我们都是时间的消费者，我们都是时间的浪费者，为什么这么说呢？心理学家做过一个实验，把一些人关在一个黑暗的房间里，很快他就会失去对时间的感知，所以我们对时间的感知是很差的，如果不刻意的去管理时间，那我们的生活就会是一团糟。这也是我们为什么要时间管理的原因。\u003c/p>\u003cp>那么时间管理的关键是什么呢？有人说是利用碎片时间，但德鲁克说不是，时间管理的关键是创造整块时间。我再说一遍，时间管理的关键是创造整块时间。看了拆页的例子，我们都明白为什么需要创造整块时间，因为无论是独自工作、还是和同事、客户沟通，只有整块的时间才是最有效的，所以你要有一个意识，就是要想尽办法的去创造整块时间，避免我们的时间被碎片化。\u003c/p>\u003cp>如何在工作中获得整块的时间呢？彼得德鲁克在书中提出了三个步骤：记录、检讨、集中。\u003c/p>\u003cp>第一步，记录。时间管理不是从排计划开始的，而是从时间记录开始。现在有很多时间管理的手机 app，开始工作点一下，结束工作点一下，记录时间很方便，还可以自动生成统计图表。你可以记录三到四周，然后就知道你在工作时都干了什么。特别提醒，必须当时记录，因为事后是回忆不起来的。\u003c/p>\u003cp>第二步，检讨。排除掉那些无效和浪费时间的工作，你可以拿出你的时间记录表，逐项问自己两个问题：\u003c/p>\u003cp>1. 这件事如果不做，会有什么后果？\u003c/p>\u003cp>2. 哪些事可以由别人做？\u003c/p>\u003cp>上班时看新闻、玩游戏、刷朋友圈这些时间杀手我们就不提了，除此以外，有很多事情是可以不做或者过几天再做的，还有很多事情是可以授权别人去做的，当然你不可能什么琐事都不做，但如果你敢于砍掉这些无效的工作，那么你就能获得很多的时间去做更重要的事情。\u003c/p>\u003cp>第三步，集中。当你砍掉了无效的事情，你就获得了时间，你要做的就是把这些时间集中起来，创造整块时间。比如你可以提前跟老板说一下，每个星期有两三个上午，你会躲在会议室或者楼下的咖啡厅，专注的把最重要的工作完成，你会发现，在这两三个上午你能给公司带来的贡献能超过其他所有的时间。如果你的老板不太好说话，那么也没关系，每天尽量集中几个一个小时到一个半小时的整块时间，来做最重要的事情，你将发现自己会变得卓有成效。\u003c/p>\u003cp>请注意，如果你集中整块的时间，去做次要的事情，那仍然是没价值的，关键是做对的事情，就是对公司和自己的职业生涯有贡献的事情。\u003c/p>\u003cp>举个例子，我以前做过总裁助理，这个岗位的特点就是琐事层出不穷，老板不时的下达各种指令，大到写调研报告、演讲稿、会议纪要，小到订酒店、买书买礼品、复印传真，每天忙的晕头转向，常常不得不加班才能完成工作。后来我开始做时间记录，发现自己的工作状态就是像一只青蛙，不停地在几件事情上跳来跳去——报告写了一半去买书，买书之后又想起来忘了订酒店，一堆事情做完报告才开了个头，于是我就做了个改变，我把琐事都调到下午，这样就创造了一上午的整块时间用来写东西和其他重要的事，一段时间之后我发现不但重要的事情因为用整块时间来做非常高效，那些琐事用整块时间做也变得非常高效了。\u003c/p>\u003cp>所以请务必记住，时间管理的关键是创造整块时间。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>下面我们来演练一下。我发给大家一张表，请写一下你昨天一天的工作，从上班开始写，一直写到下班，我知道你记不清楚，但试着大概写一写。写完之后问自己两个问题：\u003c/p>\u003cp>1、哪些事情可以不做？\u003c/p>\u003cp>2、哪些事情可以交给别人做？\u003c/p>\u003cp>给大家3-4分钟的时间简单写一下。\u003c/p>\u003cp>最后在小组里分享一下：你发现哪些事情可以砍掉？哪些事情应该用整块时间做？你如何创造出你的整块时间来做什么最重要的工作呢？\u003c/p>\u003cp>\u003cstrong>现场完整案例\u003c/strong>\u003c/p>\u003cp>1、哪些事情可以砍掉？答：上网看新闻和买东西；哪些事情应该用整块时间做？答：拆书；你如何创造出整块时间来做？答：不开网页、不看手机，一上班就做。\u003c/p>\u003cp>2、哪些事情可以砍掉？答：同事向我问一些简单的问题，我会请他先自己查；哪些事情应该用整块时间做？答：阅读；你如何创造出整块时间来做？答：早上上班前或晚上睡觉前。\u003c/p>\u003cp>3、哪些事情可以砍掉？答：一部分无效的电话可以不打；哪些事情应该用整块时间做？答：写材料；你如何创造出整块时间来做？答：少打几个电话就有了。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>最后，给大家布置一个事后任务：在下周一到下周三，连续三天，按照今天学到的三个步骤，记录、检讨、集中，创造出自己的整块时间，要求每天在群里发一件自己用1个小时以上的整块时间做的重要事情。\u003c/p>\u003cp>学习者1：我用一小时以上的整块时间做了「重新摆放房间格局」的事情，现在风格大变，可以喊朋友们来玩游戏、看碟片、做深度访谈了！\u003c/p>\u003cp>学习者2：我用六个小时时间和孩子一起参加了月湖雕塑公园的一次户外。\u003c/p>\u003cp>学习者3：我用2个小时左右看完了「抢来」的书《复盘+》，并用1个小时找出周六要拆的片段，形成了大致框架。\u003c/p>\u003cp>学习者4：我集中一小时左右时间整理了《审计备案流程》文档。\u003c/p>\u003cp>学习者5：我集中一个半小时左右测试公司自研的 App。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1477745012000,"updated_at":1477745494000,"ria":true},{"id":1204,"topic":"如何确定会议是否有必要开？以及让会议开的更加有效","learn_goal":"防止不必要的会议和不必要的参与人员引起时间的浪费","remark":"它的作者是彼得.德鲁克（美），他是管理学科开创者，被尊为“大师中的大师”、“现代管理学之父”，他的思想传播影响了130多个国家。微软总裁比尔.盖茨、海尔集团张瑞敏、通用电气首席执行官韦尔奇等都积极推荐此本书。","level":"TF2-4","duration":51,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"今天我们拆的书叫《卓有成效的管理者》，它的作者是彼得.德鲁克（美），他是管理学科开创者，被尊为“大师中的大师”、“现代管理学之父”，他的思想传播影响了130多个国家。微软总裁比尔.盖茨、海尔集团张瑞敏、通用电气首席执行官韦尔奇等都积极推荐此本书。\r\n我们组织中的平凡人是否能够做出不平凡的事业？卓有成效的管理是否可以学会？是否每个人都必须是卓有成效？如何才能卓有成效？《卓有成效的管理者》这本书将给我们完美的答案。","ratings_count":0,"texts":[{"id":3448,"quote":"\u003cp>拆页片段一：即使管理者处理的都是颇有成效的工作，其处理方式仍可能造成别人时间的浪费。\u003c/p>\u003cp>某一大企业机构的财务经理，深感会议浪费了太多时间。通常不管讨论的是什么，他都通知财务部各单位主管全体前来开会。其结果是会议每次都拖得很长。出席会议的每一位主管，为了表示自己对问题的关切，都得表示意见，而表示的意见却大多与问题无关，会议时间自然拖长了。\u003c/p>\u003cp>直到有一次这位财务经理诚恳地问了大家，才知道大家也都认为会议太浪费时间了。可是，他又想到：每一个人在组织中都至为重要，都应该了解情况，开会时如果少请几个人，他又担心会使未被邀请的人觉得他们被忽视。\u003c/p>\u003cp>现在这位财务经理终于找到一个两全的办法了。开会前，他先普遍分发一份开会通知：“兹定于星期三下午3时，于四楼会议室，邀请赵钱孙李四君开会讨论下年度资本预算问题。如哪位需了解这个问题或参与讨论，也请届时出席。如果无法出席，我们将于会后立刻呈送记录，供各位参考并希望提供宝贵意见。”\u003c/p>\u003cp>过去每次会议都要12人参加，花费整个下午，而现在只要4人出席，一个小时就可以结束了，并且没有一个人有被忽视的感觉。\u003c/p>\u003cp>许多管理者都意识到了哪些事情会浪费他们的时间，然而他们却不敢面对这个问题。他们怕因小失大，造成错误。殊不知即使有了错误，也能很快弥补。能够大量削减不必要的和非生产型的工作，则工作就进行得快多了。\u003c/p>\u003cp>拆页片段二：\u003c/p>\u003cp>所谓会议，顾名思义，是靠集会来商议，是组织缺陷的一种补救措施。我们开会时就不能工作，工作时就不能开会，谁也不能同时又开会又工作。一个结构设计臻于理想的组织，应该没有任何会议（在今天动态的世界中，这样的组织当然只是理想而已）。每个人应该都能了解他工作所必须了解的事，也应该都能随时获得他工作所必须的资源。我们之所以要开会，只是因为各有各的工作，要靠彼此合作才能完成某一特定任务。我们之所以要开会，只是因为某一情况所需的知识和经验，不能全部装在一个人的头脑里，需要集思广益。\u003c/p>\u003cp>但问题在于会议太多。一个组织如果经常要以会议方式来共同工作，那么行为科学家们出于善意而为合作所研究的各种机会，就将是多余的了。一个管理者花费在会议上的时间如果过多，便是组织不健全的表现。\u003c/p>\u003cp>每一次会议都会衍伸出许多别的会议，有的是正式的，有的是非正式的，但每次会议总要花好几个小时。所以，要开会，就得有一定的计划，否则不但令人讨厌，而且是一种危险。会议应该是不得已的例外，不能视为常规。一个人人都随时开会的组织，必是一个谁都不能做事的组织。试着看看我们的时间记录，如果发现开会太多---例如参加会议的时间占总时间1/4以上，那一定是一个浪费时间的不健全组织。\u003c/p>","explains":"\u003cp>&nbsp; 第一片段讲解：\u003c/p>\u003cp>&nbsp;&nbsp;阅读完上面的片段，相信伙伴们对“如何有效控制会议时间”有了一定的了解。在会议的邀请函里面，如何做到邀请重要的人参与，而且让未被邀请的伙伴不会觉得被忽视，这样可以减少会议的时间。\u003c/p>\u003cp>&nbsp;有以下4个步骤来进行：\u003c/p>\u003cp>1、明确会议的时间、地点、主题。\u003c/p>\u003cp>2、明确必须参加会议的主要人员名单。\u003c/p>\u003cp>3、没有邀请的人员，有参加意愿也可以出席。\u003c/p>\u003cp>4、无法出席的人员，会后呈送会议记录。\u003c/p>\u003cp>如果不按照这4个步骤来进行，会出现以下后果：1、浪费不必要参加会议人员的时间，即使他们参加会议也不认真听讲。2、有人想参加却没有被邀请，会感到被忽视。3、如果没有会议记录，参加和没有参加会议的人员，没有可能在会议过后再详细了解会议情况。\u003c/p>\u003cp>也许有人会说：我开会就是什么时候想开就开，想让谁参加就让谁参加。这样也没有大的错误，但是按照上面4点来做，大家是否觉得会议会更加有效呢？\u003c/p>\u003cp>举例说明：（1）、上月16日下午《魅力演说》决赛前夕，公司培训部在总部的会议室开展“各部门推广进程的配合”的讨论会。\u003c/p>\u003cp>（2）邀请了营销部（培训宣传）、后勤部（培训物资）、行政部（培训辅助人员）的负责人参加。\u003c/p>\u003cp>（3）、对于没有邀请的其他部门负责人，在通知中说：如果哪位需要了解或者参与讨论，也请届时出席。\u003c/p>\u003cp>（4）、讨论会结束后，我们把会议记录发在管理层微信群里，供无法参加的负责人参考，并希望他们提出宝贵意见。\u003c/p>\u003cp>通过这4个步骤，使会议更加有效，使部门沟通更加协调。\u003c/p>\u003cp>第二个片段讲解：\u003c/p>\u003cp>&nbsp; 好，我看到大多数小伙伴都看好了，没有看完的也没有关系，我会在接下来的时间里面给大家讲解。判断一个会议是否有必要开，可以由这3方面来判断：1、这个工作任务是需要各部门或者各位开会人员彼此合作才能完成。2、这个会议是否有确定了计划？（时间、地点、流程、目标等等）3、是否我们每个月参加的会议时间占了你的工作总时间的1/4以上？如果这点是的话，就需要减少会议的时间。如果上面3点都符合，说明这个会议是需要开的，有一点不符合，我们就应该重新审核这个会议召开的必要性。\u003c/p>\u003cp>&nbsp; 也许有人说，开会都是领导拍脑袋决定的，哪个领导会在会前和你讨论这个会议要不要开？是的，大多数情况是这样。当你的领导交代你去组织一个会议的活动，你应该先审核一下这个会议召开的必要性。如果审核下来不需要召开，你应该拿出理由说服你的领导，或者用另外一种方式取代这个会议（譬如单独沟通等等）。也许你觉得这样做太麻烦了，而且有可能会得罪你的领导。但是你难道想让无效的会议浪费你和大家的时间吗？所以这样做是必要的，而且我们应该倡导和建议养成这样的习惯。\u003c/p>\u003cp>&nbsp; 举个例子：我们再回到第一个片段的例子，这个会议是“《魅力演说》各部门推广进程配合的讨论会”，上面我们讨论了如何让这个会议更加的有效，而且不会浪费非重要人员参与会议的时间，并且通过记录让更多想了解会议内容的伙伴有了解学习的机会。这次我们来根据第二片段的3点看看这个会议是否必要开展：1、这个会议是否需要各部门彼此交流意见和计划？推广中需要各部门的共同协作。2、这个会议是否有确定的计划？（时间：上个月的16日下午1:30点；地点：集团公司会议室；流程：先公布目前进度，再听取各位的小目标，最后确定各部门《营销部、后勤部、行政部》达成目标的时间表。）3、看看我们每个月参加会议的时间占了你的总时间的1/4了吗？否。所以我们这个会议是必要的。那我们再按照第一片段的方法，来确定一下参加这次会议的人员：营销部经理、后勤部经理、行政部经理参加，并且做好会议记录发在群里，没有参加的伙伴可以在群里了解我们的计划和目标。\u003c/p>","interaction":"\u003cp>第一片段：\u003c/p>\u003cp>A1：激活经验\u003c/p>\u003cp>拆书家提问设计（逐字稿）：我们刚刚学习了”如何有效控制会议时间”&nbsp;在组织公司会议时避免浪费不必要的时间。你可能组织一次人事部门关于“如何突破招聘现状”会议、组织一次拆书帮伙伴关于“常州拆书帮如何成为正式分舵”的交流、组织一次公司部门间关于“如何办好一次大型培训”的交流、或者组织一次公司管理层关于“如何创新”的交流会等等场景。请伙伴们回忆一场你组织参加过的会议场景，用1分钟时间把当时参加会议的情况记录下来（会议的内容是什么？邀请哪些人员参加会议？有没有没有邀请的人员？有没有会议的记录？）。完成的伙伴请举手示意。\u003c/p>\u003cp>好，看到伙伴们都已经完成了。下面我们分成2组，每一组针对上面你写的会议场景，根据片段一告诉你们的4个步骤，写出你将如何邀请重要的人参加会议，又不让未被邀请的人员感觉受到忽略。我们分A、B 2个小组开始讨论1分钟，并且请一位伙伴为大家分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、（独独）会议主题是“供应链核心工作推进”，上周因为没有明确会议的时间和参与的人员，导致开会的时候还有人陆陆续续的进来，最后也没有达成一致的目标。这周准备重新开会，按照以上的步骤进行：（1）时间是周五的上午，地点是会议室。（2）主要参与人员市场部、营销部、后勤部。（3）发通知，有未被邀请的人员，有意愿也可以参加。（4）指定专人做记录，并在会后发到群里。\u003cbr>\u003c/p>\u003cp>2、（刘老师）会议主题是“监控系统的安装”，因为没有邀请设备部人员参加，也没有做会议记录，导致会议效果很差。这周六上午会邀请设备部的人员和IT部门、HR部门一起讨论，并且做好会议记录，给没有参加会议人员参考。\u003c/p>\u003cp>第二片段：\u003c/p>\u003cp>A3：促动参与\u003cbr>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>&nbsp; &nbsp;伙伴们，为了实现公司“双十一”的销售目标，销售总监想开一场“供应链核心推广”的会议，并安排助理小王具体负责这次会议的推广和实施。\u003c/p>\u003cp>&nbsp; &nbsp;现在我们把现场的小伙伴分为2人一组，其中一人扮演销售总监，另一个人扮演助理小王。请运用原文知识点，总监可以通过提问的方式来判断这个会议是否有必要召开：\u003c/p>\u003cp>1、这次会议需要哪几个部门参加？\u003c/p>\u003cp>2、会议的时间、地点定了吗？各部门有没有具体的计划？\u003c/p>\u003cp>3、这次会议需要开多少时间？以确定一个月的会议总时间有没有超过1/4.\u003c/p>\u003cp>&nbsp; &nbsp;给大家5分钟时间讨论一下，怎么提问？怎么回答？5分钟后，我邀请一组小伙伴来角色扮演，看看他们原文运用知识点后，判断这次会议是否有必要召开。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>总监：小王，为了迎接“双十一”，我想开一次“供应链核心推广”的会议，由你来负责整个会议的推广和实施。\u003c/p>\u003cp>小王：好的，总监。\u003c/p>\u003cp>总监：你看这次会议需要哪几个部门人员参加？\u003c/p>\u003cp>小王：需要市场部各个经理（负责销售目标的达成）、营销部经理（负责营销活动的推广宣传）、后勤部经理（负责物资供应和后勤保障）来参加。\u003c/p>\u003cp>总监：时间和地点怎么定？\u003c/p>\u003cp>小王：下周一上午9点开始，在集团的会议室。\u003c/p>\u003cp>总监：各部门的计划确定了吗？\u003c/p>\u003cp>小王：我今天就让参加人员准备，在开会的时候必须带着他们的推广计划来。\u003c/p>\u003cp>总监：会议需要多少时间？\u003c/p>\u003cp>小王：一个小时吧。我们这个月会议不多，会议总时间不会超过1/4的。\u003c/p>\u003cp>总监：好，这个会议符合以上知识点，所以有必要召开，你去准备吧。\u003c/p>\u003cp>小王：好的。\u003c/p>\u003cp>A2：催化应用\u003cbr>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：未来的一个月中，在你的公司会议室，领导可能会让你主讲某一个会议，这个会议的内容可能是“公司业绩指标的分析”？也可能是“如何增强团队凝聚力”，等等。对照今天我们所学习的片段，看看这个会议是否符合3点会议必须开的条件？如果需要开这个会议，你需要讲出理由；如果分析出来不需要开这个会议，你也要讲出理由来说服你的领导。3分钟以后我们请每一组选出一位来进行分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、（独独）（1）主题是“供应链核心保障的讨论会”，时间是明天上午，地点是会议室。双十一是一年一次，所以我们都有明确的计划和目标：先找出核心需求，再根据需求来确定我们需要做什么，怎么做？最后确定完成的时间表和质量考核。\u003c/p>\u003cp>（2）参加会议人员：销售部、客服部、采购部，需要各部门协调。\u003c/p>\u003cp>（3）本月会议的次数和时间不多，不超过1/4。\u003c/p>\u003cp>结论：这个会议是必须开的\u003c/p>\u003cp>2、（马老师）“业绩指标的提升会议”\u003c/p>\u003cp>（1）需要市场部、人事部、行政部客服部相互协调参加。\u003c/p>\u003cp>（2）客服部提供数据资源。人事部制定好的奖励政策，团队的建设。行政部提升客户体验度。销售部提升员工销售能力。时间是星期五的下午4点。\u003c/p>\u003cp>（3）时间上40分钟，整体会议时间不超过1/4.\u003c/p>\u003cp>结论：这个会议是必须开的\u003c/p>\u003cp>结语：\u003c/p>\u003cp>（逐字稿）：好！感谢二位小伙伴的分享！通过今天两个片段的学习，每个小组具体案例的现场操作，我们知道了如何让会议更加有效，也知道了如何确定这个会议是否是必须召开的，这样我们在今后的工作中就可以防止不必要的会议浪费了大家的时间，而且让会议效率大大增高。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1477547436000,"updated_at":1477547436000,"ria":true},{"id":1186,"topic":"卓有成效的管理者思想上必须养成的习惯","learn_goal":"顺利通过2-2","remark":"大家有听过“日事日毕，日清日高”吗？最早就是由我们本书《卓有成效的管理者》作者德鲁克提出的，德鲁克认为有效性，并非与生俱来，而是可以后天习得，通过刻意的练习去管理自己，并作出决策，是本书的主题所在，想掌握时间，想发挥自己的长处或者引导下属发挥自己的才能，想高效成为卓越的管理者，带着你的疑问去读，然后指导自己的行动。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"刘红艳","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是刘红艳，我们先分组，2人一组，接下来我们开始今天的拆解.允许我用FAB法向大家介绍《卓有成效的管理者》\r\nF（feature）特征《卓有成效的管理者》被誉为启蒙中国现代管理的第一书，同时本书作者德鲁克呢也倡导实用，认为管理理念应该着重于最后结果，必须落实到实践上来，和我们拆书帮的拆为己用有异曲同工之处。\r\nA（advantage）比较，其他管理类书籍更多的是告诉你怎么管理别人，此书讲的是怎么管理自己，进而做出决策，管理类书籍的首推就是这本书。\r\nB（benefit）利益，有没有同学迷茫自己应该考研、考公务员、还是就业，本书的后两张告诉你如何做决策，有没有伙伴觉得自己每天要做的很多，总觉得时间不够用，去本书中学习怎么掌握时间，若你想更好的管理自己，提升自己的管理能力，都可以从书中得到启发。","ratings_count":0,"texts":[{"id":3491,"quote":"\u003cp>记得小时候我的钢琴老师告诉我：“你弹莫扎特的曲子时，也许不可能像钢琴家施纳贝尔演奏的那样好，但是并没有理由说，你不必像施纳贝尔那样的练习音阶。”回想起来，我的钢琴老师显然少说了一句：最伟大的钢琴家，如果不肯辛勤演练，也一定无法演奏莫扎特的曲子。\u003c/p>\u003cp>也就是说，没有任何理由不让普通人通过练习来获得胜任某项工作的能力。当然若要把什么东西演练到炉火纯青的地步是很不容易的，那也许需要特殊的天赋。但卓有成效所要求的只是能够胜任，只是能演奏出音阶来。\u003c/p>\u003cp>下面两项是要成为一个卓有成效的管理者，必须在思想上养成的习惯。\u003c/p>\u003cp>1、有效的管理者知道他们的时间用在什么地方。他们所能控制的时间非常有限，他们会系统的工作，来善用这有限的时间。\u003c/p>\u003cp>2、有效的管理者重视对外界的贡献。他们并非为工作而工作，而是为成果而工作。他们不会一接到工作就一头钻进去，更不会一开头就探究工作的技术和手段，他们会首先自问：“别人期望我做出什么成果？”\u003c/p>","explains":"\u003cp>\u003cstrong>【讲解】\u003c/strong>这个拆页德鲁克通过乘法口诀“六六三十六”以及钢琴练习这两个例子说明卓有成效需要刻意练习，紧接着就阐述了卓有成效管理者必须在思想上养成的2个习惯：1、where,及时间用到了哪，有人会说工作、生活，这太大了，我们要求具体到每一项，生活是洗衣？做饭？打扫卫生？工作是开会？应酬？做设计？等，具体几点做什么。比如今晚7点我们开始拆书活动2、who,为谁工作，为成果工作,思考：“别人期望我怎么做” 。给大家举一个我自己的案例，\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>上周决定过2-2，周一各种纠结之后把要拆解的片段确定下来，想着还有一周准备，然而周二伙伴考试没考好，找我聊天，我说没事，明天开始准备，第二天剪辑了一些视频，时间就没了，周三开始想案例，什么样的案例会让大家收获更大，想了很多，觉得都不是很合适，又一天过去了，结果周四停电，就这样只剩两天时间，匆匆准备了预备表，结果可想而知，就是我今天还在过2-2，对自己而言，有两个错误，1是不知道自己的时间用在哪，下班后我需要完成拆书预备表的准备，需要学习，还有可能有突然的事情，自己的时间运用处于被动状态，想到哪就做到哪，没有系统的安排。2、就是为了过级而过级，一头扎进去开始准备，忘记思考我拆书是为了什么，为了自己的行动改变，为了一起的伙伴有所收获。\u003c/p>\u003cp>【预防学习者可能的异议】\u003c/p>\u003cp>听完之后，也许有伙伴会说，时间管理或者规划，我做过，但是发现现实中很难按计划来，那难得原因是什么？是自己根本就没有按计划来？还是突发事件比较多？还是自己意志力不够，失败后的反思，一样有收获。也可能有伙伴觉得为工作而工作没什么错，给多少钱干多少活，那你每天重复做着你觉得应该做的工作，能力会得到提升吗？最后你最关心的问题，工资自然不会上涨。\u003c/p>","interaction":"\u003cp>1 .拆书家提问设计（逐字稿）：刚刚听了我的例子和对片段的理解，请大家想一下，有没有这样的经历，因为没有思考时间用在哪，导致事情没有做完，或者完成的质量不是自己期望的，或者为工作而工作，为完成任务而完成任务，比如：做了格式混乱的word，进而导致做出一些错误的决定，失败的行动，比如： 工作重新返工，没有按时完成任务、上班时候总觉得不够用、该背的单词没有背完，忘记了好朋友的生日等，请大家在小组内讨论，讨论结束后请举手示意，我们请1个伙伴给大家分享一下。\u003c/p>\u003cp>学习者案例记录：杨欢分享周一老师布置一篇文章，周天提交，周天晚自习开始着手写，时间紧急，参考同学的作业，匆匆提交，结果不是很好。\u003c/p>\u003cp>2. 拆书家提问设计（逐字稿）：我们刚刚学习了，5个思想习惯，上面也在小组内分享了自己的情境，请大家加工和规划出自己的具体运用，说明你今后怎么运用5个习惯，让自己在该情境下做出正确的决定。请在小组内分享。\u003c/p>\u003cp>学习者案例记录：大庆分享，过级2-2，周二提交预备表，一直到周五，结果周五师傅身体不舒服，下午师傅给建议需要修改，时间仓促。今后的应用为周二准备预备表，周三发师傅，周四定稿，周五练习，周六过级。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1477298225000,"updated_at":1477298333000,"ria":true},{"id":1070,"topic":"如何用战略性思考与反面意见有效决策","learn_goal":"帮助学习者了解决策需要战略性思考，在制定决策的时候会应用反面","remark":"这本《卓有成效的管理者》的作者相信很多人都耳熟能详了，他就是被誉为“大师中的大师”“现代管理学之父”的彼得.德鲁克。他的作品被翻译成30多种语言，全球销量超过600万册，其中《卓有成效的管理者》已成为全球管理者必读的经典，在中国被称为“启蒙中国现代管理第一书”、“终身受用的案头必备书”。这本书自2009年在中国出版，这已经是第33次印刷。\r\n这本书提炼了有效管理的几个主要方面，分成时间管理、聚焦贡献、充分发挥人的长处、要事优先、有效决策等章节，每一节都既有理论、又有案例，特别是案例，贴近我们的实际，读起来很有趣味。\r\n这本书帮助我确信：卓有成效是学得会的，我们每个人都可以成为卓有成效的管理者。","level":"TF2-4","duration":55,"status":0,"type":0,"chaishujia":{"username":"刘云汉","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位小伙伴，晚上好！我是刘云汉，今天很高兴和大家一起拆2-4。我的主题是：如何用战略性思考与运用反面意见有效决策。在跟随我完成本次RIA现场学习后，学习者能够了解决策应该是一种战略性思考，并在制定决策的时候学会重视和应用反面意见。\r\n这本《卓有成效的管理者》的作者相信很多人都耳熟能详了，他就是被誉为“大师中的大师”“现代管理学之父”的彼得.德鲁克。他的作品被翻译成30多种语言，全球销量超过600万册，其中《卓有成效的管理者》已成为全球管理者必读的经典，在中国被称为“启蒙中国现代管理第一书”、“终身受用的案头必备书”。这本书自2009年在中国出版，这已经是第33次印刷。\r\n这本书提炼了有效管理的几个主要方面，分成时间管理、聚焦贡献、充分发挥人的长处、要事优先、有效决策等章节，每一节都既有理论、又有案例，读起来一点不感觉枯燥—今天我拆的两段文字就能让你感受一下，爱上这本书！\r\n学习了这本书，你就会和我一样确信：卓有成效是学得会的，我们每个人都可以成为卓有成效的管理者。\r\n今天我带领大家一同拆解的第一部分内容，来自本书的第6章《决策的要素》中的P116-117中的一个案例。下面，请大家用三分","ratings_count":0,"texts":[{"id":3264,"quote":"\u003cp>斯隆先生著有一本回忆录，书名是《我在通用汽车的岁月》。书中说他在1922年接任时，通用汽车的组织简直是一盘散沙，各自为政。通用汽车原是由几个企业合并而成，但是在合并后，各部门的主管，都像是独立不落的酋长，完全不听“王命”。\u003c/p>\u003cp>解决这样的问题，传统上不外有两种方法。第一种方法，是把这些“强有力的酋长”调离。这就是洛克菲勒建立标准石油公司，和摩根建立美国钢铁公司的办法。第二种办法，是留任这些“酋长”。仍由他们指挥“他们的”事业，而总公司尽量不加以干涉。其实这哪里是解决办法，只是尾大不掉的无政府状态，只有寄希望于“酋长”会因他们本身的经济利益，而顾到总公司的整体利益而已。事实上通用公司的创始人杜兰特和斯隆的前任杜邦，都是采取这种办法。而在斯隆接任时，通用公司败相已露，“酋长”们的不合作，已使得公司濒于关门大吉的边缘了。\u003c/p>\u003cp>斯隆先生看清了问题的根本，认为这并不是因为合并才发生的过渡期间的问题，而是一个大型企业常见的问题。他认为一个大型企业，需要一个有统一方向和一个管制中心；需要有责权的高层管理；也需要积极进取和干练的业务经理，他们应该有选择其经营方法的自由，应该有确切的责任和履行其责任的职权，应该有足以使他们发挥所长的范围，应该是他们的成就得到应有的鼓励。斯隆先生看到了这些需要，其实何止是当时的通用汽车公司有此需要，随着公司的逐渐老化，任何一家有赖发展主管才干的公司，又何尝不有此需要。\u003c/p>\u003cp>在斯隆先生之前，事实上人人都看到了这个问题，都认为是一项人事问题，必须靠权力的明争暗斗，出现最后一个胜利者之后才能解决。然而斯隆确认为这是一个制度上的问题，只有通过建立一个新的组织结构才能解决，所以他构想了分权制度，这既可以保证分公司的经营自主权，又可以体现总公司的方向及政策指导。\u003c/p>","explains":"\u003cp>好，我看到大多数小伙伴都看完了。这个案例是斯隆先生在通用汽车时，面对公司合并后各自为政、一盘散沙的状态，没有像一般人那样大面积人事调动、或者因为困难而听之任之，他认为这是制度问题，因而创立了分权制度，取得了成功。这一段案例，揭示了有效管理的一个实质：我们的决策应该关注于系统性的战略思考，是一种“顶层设计”。\u003c/p>\u003cp>也许有人会对此提出质疑：“顶层设计”那是老板的事情，哪里有那么多的“战略思考”？都去“顶层设计”具体事情谁来干呢？是的，我们在这里不是探讨职责分工的问题，而是强调一个概念：作为一名管理人员，需要有系统思考的能力，而不是仅仅就事论事，这样才能成为一名“卓有成效的管理者”。\u003c/p>\u003cp>相反，如果不这样做，我们满足于自己的当前状态，不去锻炼这样的系统性思考能力，我们可能整天忙于此类日常事务，最多是一名忙碌的管理者，绝对不是一个“卓有成效的管理者”。\u003c/p>\u003cp>举个例子，我作为公司的财务负责人，当公司发展需要资金的时候，我们虽然有足够的银行授信额度，可以贷款，但是我们不能仅仅满足于取得银行贷款让公司正常经营就行了，更需要站在股东的角度，比较上市、债券、融资租赁等各种融资方式，哪种方式更加有利于公司的长远利益。这种的思考方式就应用了“战略性的系统设置”、属于财务领域的“顶层设计”。\u003c/p>","interaction":"\u003cp>在我们的日常管理工作中，我们有没有遇到这样的问题：某个部门或者我们某个下属的工作总是难见成效，我们常常想“这个人不行！换个人就好了”；或者在我们常州拆书帮筹建过程中，有人经常缺席，我们内心是否想过“某某不积极，我们让他成为初始会员是不是错啦？” 每周三的拆书活动前一段时间连续取消好几次，我们是不是简单地归结为“大家忙，现在的时机不对”就自我解脱了？请你把这样的想法或者案例写出来，1分钟。写好的请举手。\u003c/p>\u003cp>（1分钟以后，大家都写完举手。）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：大家写好了？好，下面我们就来训练一下我们的战略思维能力—可以使用刚才的内容，也可以换个角度-- 请大家想一想：我们自己所在的单位，存在的最大的、亟需改善的问题是什么？是业务拓展问题？技术瓶颈？成本下不来？人员流失高？…请你从制度性、系统性战略的角度，考虑应该制定怎样的战略决策？写在纸上，2分钟时间，好了以后我们小组内讨论一下，我们现场分成2组，各组请一位代表来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>贾文卿：部门KPI每个月考核总有些问题，一直就问题谈问题，需要从系统层面反思KPI指标设定的合理性。\u003c/p>\u003cp>金家东：易天集团似乎什么都做，拟提请老板考虑：品牌和核心竞争力\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":3282,"quote":"\u003cp>为什么应该有反面意见，主要有三项理由。\u003c/p>\u003cp>第一，唯有反对意见，才能保护决策者不至沦为组织的俘虏。在一个组织中，所有人都必有求于决策者，每个人都各有所求，都希望主观的决策能对自己有利。上至美国总统如此，下至企业机构中一位初级工程师修改某一项工程设计也是如此。\u003c/p>\u003cp>唯一能突破这一陷阱，使决策者不至成为某方面的俘虏的办法，就在于引起争辩、掌握实据和经过深思熟虑的反面意见。\u003c/p>\u003cp>第二，反面意见本身，正是决策者所需的“另一方案”。决策时只有一种方案，别无其他选择，那与赌博何异？只有一种方案，失败的机会必高。也许是这决策大从开始就错了，也许是其后原因情况变化而使决策错了，如果在决策过程中原有若干方案可供选择，则决策者进可攻、退可守，有多方思考和比较的余地。反之，舍此以外别无他途，决策人在遇到该决策行不通的时候，就只有背水一战了。\u003c/p>\u003cp>最后第三个理由，是反对意见可以激发想象力。当然，纯粹为了某一问题去找答案，并不一定非有想象力不可，只有解决数学问题才最需要想象力。但是一位管理者处理问题时，不管是政治、经济、社会，还是军事，通常总是“不确定性”极高，就需要有“创造性”的解决方案，来开创新的局面。这就是说，我们需要想象力，因为缺乏想象力的管理者不可能从另一个不同的、全新的角度去观察和理解。\u003c/p>","explains":"\u003cp>好，我看到大多数小伙伴都看好了，没有看完的也没有关系，我会在接下来的时间里面给大家讲解。\u003c/p>\u003cp>这一段文字讲述了有效的决策为何要重视反面意见，说了三点：1）保护决策者不沦为组织的俘虏，意思是说：如果管理者提出一种方案没有反对意见，大家似乎都认可这个“唯一方案”，很可能大家都是站着个人利益的角度考虑“我认可这个方案对我个人是有利的”，而不是对组织最有利的选择，决策者这时候就失去了其清醒的独立性而沦为“组织的奴隶”；2）反对意见提供决策需要的另一种方案，Plan B；3）激发想象力。\u003c/p>\u003cp>由此，我们判断一个有效的战略决策要充分重视反对意见，至少有四个标准去衡量：1）有没有反对意见？2）反对意见是否足够？3）可否从中提炼出Plan B？4）与原方案相比，有没有创新？简单地说，四个关键词—有没有？够不够？备选？创新？\u003c/p>\u003cp>也许有人会说：不是所有的决策都有反对意见吧？太多关注反对决策会不会影响到决策效率？决策的注意事项还要注意其他方面的吧？…对于这些问题，书里面都有解答，不是我们今天学习的重点。我们的重点是建立和强化这样的理念：重视反对意见。\u003c/p>\u003cp>重视反面意见到底有多重要？我来举个例子：在座各位还不用微信的请举手—没有，过年还用发短信群发的请举手—几乎没有。这就是互联网时代，移动、电信、联通三大运营商面对微信没有充分重视反对意见的后果—据网上信息，早在三年前微信刚刚出来的时候，三大运营商内部就有人意识到这是一场革命，提出来取消双向收费、降低话费等，但是高层舍不得放弃通话费和一个短信一毛钱的巨额利润，虽然内部反对的声音不断，他们一直没有充分重视这些反对意见、没有真花力气去研究互联网时代、全面免费WIFI时代，移动运营商应该如何转型，从而导致了今天的大败局— 我们用我们学到的四个标准来衡量：反对意见有没有？有！够不够？不够—因为管理层不重视！备选？--没有！创新？没有！三年了，他们还是没有走出困局！\u003c/p>","interaction":"\u003cp>\u003cem>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/em>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>好，现在我们就来体验一下如何“重视和应用反对意见”，好不好？（大家：“好”！）\u003c/p>\u003cp>今天，我们拆书借用的是易天集团的会议室，假设我们大家都是易天集团的中高层干部—在座的有人事的，有业务的，有财务的，有技术的……我们知道，易天集团原来是做手机的，今天这里“联融堂”又是做金融的，前几年开始做地产，去年又涉足旅游业，上个月买下了一片鱼塘……外接很多人在问“你们易天到底是做什么的？”我们在座的中层里面也有人很困扰。在这种情况下，我们的业务总监金总，提出来一个经营决策的提案：“易天集团应该锁定经营业界、发挥核心竞争力、创立自己的品牌！”这个提案听起来是不是挺有道理的？（多数人点头）\u003c/p>\u003cp>金总也很重视这样的决策提案，信心满满！一周前他就准备了一份材料，发给了在座各位，并约定今天开会讨论。\u003c/p>\u003cp>现在各位就是与会者。请应用今天学到的“重视反对意见”的理念，提出反对的理由。金总就由我们金老师扮演。您不用反驳，请耐心倾听和记录大家的意见就可以了。\u003c/p>\u003cp>下面，会议开始—金总，有请！\u003c/p>\u003cp>（金老师）谢谢各位安排时间参加今天的这个会议。会议主题我一周前已经发给大家了，我的提议是“易天集团应该锁定经营业界、发挥核心竞争力、创立自己的品牌！”，理由在邮件里面都有说明，现在请大家发表一下各自的意见。\u003c/p>\u003cp>（大家依次发言，金老师记录）\u003c/p>\u003cp>好，现在请大家帮助金老师整理一下刚才的决策及各种反对意见，对照今天我们所学习的四个标准，看看我们的反对意见有没有？够不够？能提炼出备选方案吗？与最初的方案相比有创新吗？3分钟以后我们请方案拥有者分享。\u003c/p>\u003cp>（3分钟以后）请金总总结发言？（大家鼓掌）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1）&nbsp;&nbsp; 当前市场变幻莫测，赚钱是王道，多方位投资是对的；\u003c/p>\u003cp>2）&nbsp;&nbsp; 关于“品牌”“核心竞争力”，变化快、不明朗，当前的多方位经营实际上也是在探索；\u003c/p>\u003cp>3）&nbsp;&nbsp; 鸡蛋不能放在一个篮子里，理应投资分散\u003c/p>\u003cp>4） 有关这种重大战略，更需要团队共创来决策\u003c/p>\u003cp>金家东：谢谢大家的宝贵意见，结合这些反对意见，反观开始的决定太粗糙了！我需要回去好好整理，修正一下，发挥品牌效应是必须的，当前多方投资尝试盈利点也是可以的，我会后整理好大家的意见后，发给大家再看一下，最后提交高层决策。\u003cbr>\u003c/p>\u003cp>\u003cem>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/em>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003cbr>\u003c/p>\u003cp>大家通过刚才的案例讨论，已经深切体会到了吧—一项听起来很合理的决策，如果多听听反面意见，会从中获得很多你想不到的答案，这就是“重视和应用反面意见”的好处！\u003c/p>\u003cp>在接下来的3分钟里，请大家写一下：你最近想提出的决策是什么？你能想到的反对意见有哪几条？你计划如何听取更多的反对意见？有怎么应用这些反对意见？请写下来，3分钟以后，我请一位小伙伴和我们分享一下。\u003c/p>\u003cp>学习者案例记录（逐字稿）：\u003c/p>\u003cp>（贾老师）我原定的决策是全面修订、系统性解决KPI考核的问题，但是想了一下反对意见，主要有：（1）KPI设定是一项重大复杂的工程，不能轻易实施；（2）存在的都是合理的，对原有KPI和结构不能轻易否定，需要仔细分析；（3）不仅是KPI的设定问题，还有组织文化、执行力等，需要系统解决。所以，我下周的决定是：自己再仔细想想，然后小范围听听反对意见，修改方案，最后提交领导层初步决策，成立专门小组讨论分工和细节，中间需要不断的听取反对意见、而完善，一切计划好了才能实施。\u003c/p>\u003cp>好！通过今天两个片段的学习，我看到大家已经掌握了卓有成效的管理者在决策方面的两个基本点：一是制定的决策要是系统的战略性思考，是顶层设计；二是决策的确认要充分运用反面意见。有了这两点，对于我们今后制定决策、成为一名卓有成效的管理者，我们又迈出了一大步！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1476022979000,"updated_at":1476022979000,"ria":true},{"id":1069,"topic":"发挥上级的长处","learn_goal":"帮助学习者改变思维方式，学会发现上级的长处，并用来改善工作","remark":"《卓有成效的管理者》是被誉为“大师中的大师”“现代管理学之父”的彼得.德鲁克。他的作品被翻译成30多种语言，全球销量超过600万册，其中《卓有成效的管理者》已成为全球管理者必读的经典，在中国被称为“启蒙中国现代管理第一书”、“终身受用的案头必备书”。这本书自2009年在中国出版，这已经是第33次印刷。\r\n这本书提炼了有效管理的几个主要方面，分成时间管理、聚焦贡献、充分发挥人的长处、要事优先、有效决策等章节，每一节都既有理论、又有案例，读起来一点不感觉枯燥—这也是本书畅销的原因之一吧？\r\n通过学习这本书，可以帮助我们确信：卓有成效是学得会的，我们每个人都可以成为卓有成效的管理者","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"刘云汉","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位小伙伴，晚上好！我叫刘云汉，今天我和大家一起完成TF2-3的拆书。今天的目标：在跟随我完成本次RIA现场学习后，学习者能够调整自己的心态，发现上司的长处，并学会如何利用上司的长处，实现管理目标。\r\n这本《卓有成效的管理者》的作者相信很多人都耳熟能详了，他就是被誉为“大师中的大师”“现代管理学之父”的彼得.德鲁克。他的作品被翻译成30多种语言，全球销量超过600万册，其中《卓有成效的管理者》已成为全球管理者必读的经典，在中国被称为“启蒙中国现代管理第一书”、“终身受用的案头必备书”。这本书自2009年在中国出版，这已经是第33次印刷。\r\n这本书提炼了有效管理的几个主要方面，分成时间管理、聚焦贡献、充分发挥人的长处、要事优先、有效决策等章节，每一节都既有理论、又有案例，读起来一点不感觉枯燥—这也是本书畅销的原因之一吧？\r\n通过学习这本书，可以帮助我们确信：卓有成效是学得会的，我们每个人都可以成为卓有成效的管理者。\r\n今天我带领大家一同拆解的内容，就来自本书的第四章《如何发挥别人的长处》中的一节《如何管理上司》。下面，请大家用三分钟阅读一下复印给大家的拆页部分，看好的小伙伴请举手示意。","ratings_count":0,"texts":[{"id":3263,"quote":"\u003cp>卓有成效的管理者要设法充分发挥上司的长处，这是非常重要的。\u003c/p>\u003cp>但是，我却很少看见哪位管理者注意如何管理上司的课题。他们也许会说：“管理下属，我没有什么困难。但是我如何能管理我的上司呢？”\u003c/p>\u003cp>管理上司其实不难，但只有有效的管理者才能了解其中的奥妙，就在于运用上司的长处。\u003c/p>\u003cp>在具体做法上当然应该谨慎小心。实际上，如果上级主管的能力不够，下属通常是无法爬升上去的。上司如果没有升迁，下属只好永远屈居其下。如果有一天上司因成绩不佳调职了，继任者也往往都是来自别的部门，很少在本单位中选人提升。而且新上司到任时，也总是带来他自己的亲信。反之，凡是成功而升迁得快的主管，其下属也是最容易成功的。\u003c/p>\u003cp>暂且不谈谨慎小心，实际上，\u003cstrong>运用上司的长处，也是下属工作卓有成效的关键\u003c/strong>。\u003c/p>\u003cp>只有如此，身为下属者才能将精力集中在自身的贡献上，完成自己想做的工作，取得希望取得的成就。\u003c/p>\u003cp>要使上司能发挥其所长，不能靠唯命是从，应该\u003cstrong>从正确的事情着手\u003c/strong>，并\u003cstrong>以上司能够接受的方式\u003c/strong>向其提出建议。\u003c/p>\u003cp>有效的管理者了解他的上司也是人（然而年轻的下属却不容易有此了解）。上司既然是人，所以肯定有其长处，也肯定有其短处。\u003c/p>\u003cp>若能在上司的长处上下工夫，协助他做好想做的工作，便能使上司有效，下属也才能有效。反之，如果下属总强调上司的短处，那就像上司强调下属的短处一样，结果将一无所成。所以，有效的管理者常问：“\u003cstrong>我的上司究竟能做些什么？他曾有过什么成就？要使他发挥他的长处，他还需要知道些什么？他需要我完成什么\u003c/strong>？”至于上司不能做些什么，那就不必细究了。\u003c/p>\u003cp>一般人常想到如何“改变”他的上司。以政府机构来说，能干的高级官员，常以老师的姿态对待新到任的领导，设法使他的领导克服其缺点。但是有效的管理者考虑的却是：“这位新领导能做些什么？”如果说“他擅长应对，与国会的关系好，与白宫的关系好，与社会各界的关系也好”，那么下属就该设法使这位新领导充分发挥这方面的长处。因为即使有最好的行政，有最好的决策，如果没有好的政治技巧加以表达的话，那就等于零了。这位新领导知道下属的官员支持他，他也会很快在政策及行政方面采纳官员们的意见。\u003c/p>\u003cp>有效的管理者知道他的\u003cstrong>上司是人，所以也知道他的上司一定自有一套有效的方式\u003c/strong>，他会设法\u003cstrong>探寻出上司的这套方式\u003c/strong>。所谓方式，也许只是某种态度和某种习惯，但这些态度和习惯却是客观存在的。\u003c/p>\u003cp>人大致可以分为两种类型：\u003cstrong>“读者型”和“听者型”\u003c/strong>。（只有极少数的人是例外。例如有人靠与他人谈话来获取资料，从谈话中来观察对方的反应，好像装备了一个心理雷达。罗斯福总统和英国的丘吉尔都属于这一例外的类型。）此外也有读者型和听者型兼而有之的，也该算是例外——例如律师。我们面对“读者型”的人侃侃而谈，那是徒费口舌，因为他只能在读过之后才能“听”得进去。同样，我们面对听者型的人递送一册厚厚的报告书，那是徒费笔墨，因为他只能“听”了之后才能掌握要点。\u003c/p>","explains":"\u003cp>好，大多数小伙伴都看完了，如果有还没看完的，也没有关系，我会在后续的分享中继续为大家解读。\u003c/p>\u003cp>这段话首先告诉我们一个概念：“要发挥上司的长处”。为什么呢？因为发挥的上司的长处、能更快的帮助上司成功，而上司的成功就是我们的成功，使我们有条件取得自己希望的成就。如果我们只想着自己，与上司的沟通管理缺失；或者总想着改变上司，上下合作艰难，我们是很难取得职场的成功的。\u003c/p>\u003cp>那怎么发挥上司的特长呢？第一，我们要发现上司的长处是什么：我的上司他擅长做什么？他有过哪些成就？第二，我能做什么，发现自己的价值：要发挥上司的长处，他还需要哪些支援？第三，我该怎么做：上司是听者型还是读者型？听者型喜欢听汇报，读者型喜欢看报告。我们要选择上司容易接受的方式提出自己的建议。\u003c/p>\u003cp>比如我们公司的总经理是财务出生，读了这段文字后，我首先分析他的长处是什么，其中一条是对资金的安全性理解深刻，特别是对重庆子公司的财务资金管理不放心，提出很多问题；其次，我看我能做什么来发挥这些特长：他需要详细了解常州和重庆在资金管理流程、制度和实际执行情况的差异，而这些是我能整理调查出来的；第三，我该怎么做，我选择总经理喜欢的提前发出书面报告+当面口头报告的方式，先把相关的制度、流程、PPT报告发邮件，再约时间开会一起讨论，一来打消了上司的顾虑，二来按照他关注的细节再加强管控。经过这样一轮，他对财务在资金管理方面增强了信心，也获得了一定的成就感；而我们财务从上到下，也对资金安全更加重视和负责。\u003c/p>","interaction":"\u003cp>\u003cem>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/em>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>现在我们假定一个场景：今天是7月19日，上半年工作刚刚结束，您是销售部门的经理，上半年业绩很不错，指标超额完成，你的老板很满意。老板的长处是：业务出生，了解市场，善于鼓舞和激励团队，喜欢开会的时候口头讲话，但是也要求下属提交简明扼要的书面材料。下午2：00，老板走进你的办公室，你刚站起来，他笑眯眯地拍着你的肩膀说：“张经理，坐坐坐！恭喜你啊！上半年的报表我看过了，你们这半年的表现不错啊！这样，明天你组织你们部门所有人，带上各部门经理，我要公开表扬一下你的团队！”然后笑眯眯地走了。你很开心，马上按照惯例，把主要数据和讲话要点发邮件给了总经理，并发出了会议通知。\u003c/p>\u003cp>我们现在需要两位演员，两两一组，一个做老板、一个做销售经理，把第二天开会的场景演绎一下。\u003c/p>\u003cp>想做老板的举手！（现场一半以上的举起手，有人发现举手的多了，又主动放下。）\u003c/p>\u003cp>好！现在就请每个“老板”和身边的“张经理”成立一个小组，你们讨论一下会议讲话的内容，3分钟以后，我们请一组给大家表演一下！\u003c/p>\u003cp>（3分钟以后）好，现在哪两位愿意给我们表演一下？-- 好，吴老师做上司，金老师表演下属。其他人就都是与会者。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>金：今年上半年的销售报表，已经呈报请老板看过了，我们内部也讨论了一下，结合上半年的表现，下半年我们如何去做？下面请吴总指示。\u003c/p>\u003cp>吴：首先非常感谢金总及时提交了上半年的报告，我们上半年的表现很好！下半年我们还要继续努力！\u003c/p>\u003cp>从上半年的报表看出，总体的销售业绩是不错的，极个别销售员的表现还不够到位，希望我们回去认真总结、查查原因；同时希望中层管理人员组织专题会议，把下半年的目标确定下来。对现在各个门店，好的门店的经验要总结好在哪里，哪些值得推广，能不能用到好的门店—这些请金总组织一下，好不好？\u003c/p>\u003cp>金：好！听了吴总的讲话以后，我们更加有信心了！下半年我们要设定好目标，争取把亏的门店扭亏为盈，使整个公司的目标达到吴总的要求。大家说好不好？（所有人：好！）\u003c/p>\u003cp>非常好！感谢吴老师和金老师的精彩演出！今天我的TF2-3拆书到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1476020297000,"updated_at":1476020603000,"ria":true},{"id":996,"topic":"如何因事用人选拔人才","learn_goal":"学习运用“因事用人”的方法来选拔人才","remark":"它的作者是彼得.德鲁克（美），他是管理学科开创者，被尊为“大师中的大师”、“现代管理学之父”，他的思想传播影响了130多个国家。中国领导人胡耀邦、朱镕基、微软总裁比尔.盖茨都积极推荐此本书。","level":"TF2-3","duration":24,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"今天我们拆的书叫《卓有成效的管理者》，它的作者是彼得.德鲁克（美），他是管理学科开创者，被尊为“大师中的大师”、“现代管理学之父”，他的思想传播影响了130多个国家。中国领导人胡耀邦、朱镕基、微软总裁比尔.盖茨都积极推荐此本书。\r\n我们组织中的平凡人是否能够做出不平凡的事业？卓有成效的管理是否可以学会？是否每个人都必须是卓有成效？如何才能卓有成效？《卓有成效的管理者》这本书将给我们完美的答案。","ratings_count":0,"texts":[{"id":3126,"quote":"\u003cp>为什么“因人设事”不能解决问题，是因为组织中任何一个职位的变更，都会造成一连串的连锁反应。组织中的职位都是相互联系、相互依存的，牵一发而动全身。我们不能为了替某人安插某一个职位，而使组织中的每一个人都受到牵连。因人设事的结果，是为了安插某一个人，一大群人都受到连累。\u003c/p>\u003cp>这种现象，并不仅仅出现在政府机构或大企业中。学校需要一位教授生物化学概论的教授。这位教授当然应该是一位好老师，是一位专家。但是生物化学概论这门课程，不论教授个人的兴趣如何，都必须包括这门课程的基本原理。该讲授什么，应按学生的需要而定，无论由谁讲授，都应该讲授这些内容。交响乐团缺了一位大提琴手，乐团指挥绝不会选用一位不擅大提琴但双簧管吹的极好的人选来充数，即使此人吹双簧管的名气远比其他大提琴手响亮，指挥也不会这样做。当然，他更不会为了某一乐师而重写乐谱。剧团经理明知道他的卖座女明星爱耍脾气，也会承受她的脾气，但他却不会因为她发脾气而更改已经宣布的节目单。\u003c/p>\u003cp>我们要坚持因事用人而非因人设事，还有一个微妙的原因。因为只有这样，我们才能为组织提供所需要的各种人才，也只有这样，我们才能容忍各色人等的脾气和个性。能容忍这些差异，内部关系也才能保持以任务为重心，而非以人为重心。衡量成就的高低，应该按照贡献和绩效的客观标准。只有在职位的设计和划分不以人为中心时，这种衡量才有可能。不然的话，我们就会只注意“谁好谁坏”，而忽略了“什么好什么坏”。用人的时候，我们也会仅考虑“我喜欢这个人吗”或“这个人能用吗”，而不会考虑“这个人在这个职位上，是不是能干得非常出色”。\u003c/p>\u003cp>因人设事的结果，是必将产生恩怨派系，组织绝对不能出现这种情况。人事的决策，要凭公平和公正，否则就会赶走了好人，或破坏好人的干劲。同时，组织也需要各方面的人才，否则将缺乏改变的能力，也将难于得到正确的决策所需的不同意见。\u003c/p>","explains":"\u003cp>阅读完上面的片段，相信伙伴们对“坚持因事用人选拔人才”的重要性有了一定的了解。在组织里面，通常是先有一个职位，再物色人选来出任这个职位。如果因人设事，就会像学校请一个体育老师来教数学一样，不管这个体育老师如何的优秀，在数学老师这个岗位上，他还是不能胜任的。\u003c/p>\u003cp>&nbsp;要做到因事用人，我们可以用以下几步来进行：\u003c/p>\u003cp>1、&nbsp;明确岗位的工作责职，不以人为中心来设计职位。\u003c/p>\u003cp>2、&nbsp;根据人才的学历、工作经验、工作能力等判断是否符合这个工作岗位。\u003c/p>\u003cp>3、&nbsp;要容忍人才的脾气和个性，要考虑“这个人能不能干的出色”，而不考虑“这个人我喜欢不喜欢”。\u003c/p>\u003cp>举例说明：上周一下午，公司内部选拔一位门店店长，有2位员工竞聘，胡**，女，26岁，工龄1年，在门店业绩排名月月第一，员工满意度好；李**，男，35岁，工龄3年，以前做过几个月店长，在门店业绩排名中游，员工满意度一般。评议中有领导认为小胡“太年轻，工作经验少，但是能力出色。”有领导认为小李“有一定经验，但是能力欠缺”。最终通过投票小胡当选，因为小胡更加符合店长这个岗位责职，能够带领大家突破门店的业绩。事后证明，这个门店比之前的业绩增长了许多，员工的凝聚力也加强了。按照“因事用人”的方法，小胡在销售能力和员工的团队管理上优势很大，符合店长的岗位职责，虽然在工作经验上有所欠缺，但是会在以后的工作中去慢慢的积累。而小李虽然有当店长的经验，也是因为业绩不佳而退下来的。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：我们刚刚学习了“坚持因事用人选拔人才”的重要性。现在我们进入这样一个场景：明天下午在公司的会议室举办一场财务总监的竞聘会，岗位要求是专业、认真地整理分析财务数据，根据数据改善公司现有问题，并规划公司未来发展方向。竞聘的2位情况如下，郭经理，男45岁，财会研究生，以前在某大公司任财务经理，来我公司4个月，对公司的情况初步了解，门店员工熟悉程度一般，但他的专业性和对数据的分析判断给我们留下深刻的印象；王会计，女36岁，大专会计专业毕业，在公司服务10年多，从基层做起，现在是分公司主办会计，对公司情况非常熟悉，工作认真仔细，但是专业性和数据的分析判断欠佳。\u003c/p>\u003cp>现在坐各位伙伴就是投票选择的领导，根据以上片段中学到的“因事用人”方法，分小组讨论2个人做财务总监这个岗位的优势和劣势，最终选择一个合适的人选。\u003cbr>&nbsp;&nbsp;&nbsp;请用5分钟进行流程设计，现在开始，完成的小组请举手示意。\u003c/p>\u003cp>5分钟后，我会请伙伴们来做演练，请各位评委领导各自谈谈你选择谁做财务总监的理由，看看我们学习了“因事用人”方法后，如何做出自己的判断的。\u003c/p>\u003cp>学习者案例记录（逐字稿）：\u003cbr>\u003c/p>\u003cp>人事经理吴老师：财务总监岗位核心的点是整理分析财务数据，还从技能、学历方面，我倾向于郭经理。\u003cbr>\u003c/p>\u003cp>行政经理蒋老师：郭经理是从大企业出来的，而且对企业的前瞻性比王会计强。经验上面可以慢慢地 积累，我也是倾向于郭先生。\u003c/p>\u003cp>财务经理刘老师：我同意以上2位的建议。补充一点是：财务总监更加强调管理的经验，郭经理在大公 司的经验值得重视。而且主办王会计虽然在公司人际关系上面有一定的优势，但她的经验和能力，还是与财务总监有一定的距离。所以综合上面讲到的3点：1、岗位责职：郭经理胜出。2、学历、经验、能力：郭经理胜出。3、员工满意度方面王会计好一些，但这不是最重要的，人才更多考虑的是能力。总结得出：郭经理能够胜任财务总监这个岗位。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1474967134000,"updated_at":1474967134000,"ria":true},{"id":886,"topic":"系统管理时间","learn_goal":"能够随时记录时间，并通过检讨时间记录，做有系统地时间管理。","remark":"《卓有成效的管理者》 的作者德鲁克教授是管理学科开创者，被尊称为“大师中的大师\"，现代管理学之父。本书从6个方面讲了管理者如何自我管理，使自身变得卓有成效。\r\n这是一本启蒙中国现代管理第一书，终身受用的案头必读书，已成为全球管理者必读的经典。 德鲁克教授的著作被翻译成37种语言，畅销160个国家。\r\n在教育面临极大变革的今天，我们会困惑我们的前行方向，如何做正确的决策？在信息时代，每一个人都是知识工作者，你的时间真的属于你吗？你对家庭和组织的贡献在哪？你的长处是什么？如何将危机变为例行事务？如何做一个有效的决策？ 看似500强高管才读的书， 当我们今天用平凡人的视角来读出不一样的味道，解决我们生活","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"熊媛","city":"上饶市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"分组\r\n图书介绍（1-2分钟）\r\n大家好，我叫熊媛。我今天要拆解的书籍是《卓有成效的管理者》。\r\nF 特征（核心是“书”，用于满足好奇心）：\r\n 《卓有成效的管理者》 的作者德鲁克教授是管理学科开创者，被尊称为“大师中的大师\"，现代管理学之父。本书从6个方面讲了管理者如何自我管理，使自身变得卓有成效。 \r\nA 优势（重点是“比较”，用于建立安全感）：\r\n 这是一本启蒙中国现代管理第一书，终身受用的案头必读书，已成为全球管理者必读的经典。 德鲁克教授的著作被翻译成37种语言，畅销160个国家。 \r\nB 利益（强调的是“学习者”的利益，用于引发兴趣）\r\n 在教育面临极大变革的今天，我们会困惑我们的前行方向，如何做正确的决策？在信息时代，每一个人都是知识工作者，你的时间真的属于你吗？你对家庭和组织的贡献在哪？你的长处是什么？如何将危机变为例行事务？如何做一个有效的决策？ 看似500强高管才读的书， 当我们今天用平凡人的视角来读出不一样的味道，解决我们生活中的时间，合作，贡献，有效性，决策的难题。 从任何新事变中发掘本质，一起创造卓","ratings_count":0,"texts":[{"id":2736,"quote":"\u003cp>学习目标：\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够随时记录他的时间，了解他的时间去哪了。\u003c/p>\u003cp>一、【R】阅读原书拆页\u003c/p>\u003cp>TF&nbsp;2-4&nbsp;原文片段1 &nbsp;《卓有成效的管理者》P20\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;有些管理者常自诩其记忆力很强，我有时请他们把自己使用时间的过程凭记忆做一下估计，并且写下来。然后，我把他们这份东西暂时保存起来。与此同时，我又请他们随时记录他们实际耗用的时间。几个星期或几个月之后，再把他们原来的估计拿出来，跟他们实际的记录相对照，却发现两者之间相去甚远。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;某公司的董事长，十分肯定地对我说他的时间大致分成三个部分：1/3用于与公司高级管理人员研讨业务；1/3用于接待重要客户；其余1/3则用于参加各种社会活动。但是，等实际记录了六个星期之后，跟他原来的估计比较，结果发现在上述三个方面，他几乎没花什么时间。原来，他所说的三类工作，只不过是他认为”应该“花时间的工作而已。因此他的记忆告诉他已将时间用在这三方面了。 六个星期的实际记录，显示他的时间大部分都花在调度工作上了，例如处理他自己认识的顾客的订单，打电话给工厂催货。顾客的订单，本来可以顺利处理的，由于他的干预，反而弄得不能准时交货。这份时间记录是由他的秘书记下来的，当秘书把记录送给他看时，他简直一点儿都不能相信。后来他的秘书又确实地做了几次记录，他才相信自己估计靠不住，开始相信那份记录的真实性。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 所以，有效的管理者指导，如果要管理好自己的时间，首先应该了解自己的时间实际上是怎么耗用的。&nbsp;\u003c/p>","explains":"\u003cp>二、【I】拆书家讲解引导\u003c/p>\u003cp>上次拆书，家长们不约而同提到孩子玩手机或看电视过度，这就是两种不同时间感觉而产生的冲突，当孩子在沉浸中，他觉得时间很短，而我们在等待和催促中会感觉时间很难敖。于是我们最好随时记录时间，用事实和数据来和孩子沟通，特别是已到青春期，还未学习时间管理的孩子们，不妨我们来做一次真正的时间记录。\u003cbr>\u003c/p>\u003cp>&nbsp;\u003cstrong>说意义\u003c/strong>如果完全靠记忆，我们恐怕说不清楚自己的时间是怎么打发的。心理学实验证明：人的时间感觉是最靠不住的。把人关在黑房间里，很快他就会丧失对时间的感觉。而紧闭室内的人，即使有灯光，也不能估计时间的长短。我们全情投入在阅读一本书时，会遗忘了时间，醒悟时时间已飞逝，而当我们在一个冗长乏味的会议中，我们却觉得度日如年。 因此，对于要管理好自己时间的人来说，随时记录实际耗用的时间是必要且重要的。\u003c/p>\u003cp>\u003cstrong>举个例子：\u003c/strong>我在读了这个片段后，选了早上6：30-8：30的时间段，连续记录了3天。确实发现预估时间和实际花费时间相差很大。 我以为我每天早上2小时在拆书，实际很多时间在刷微信，有时被电话干扰了，而且早餐不准时，分担家务不及时的现状，容易引起家人情绪，造成情感账户的支出。 &nbsp;预防异议大家可能会觉得这样随时记录时间没有什么意义，而且太麻烦了，也不太可能在当时就记。还有人会觉得记要花时间，更慢， 其实这样做，能帮助大家提高办事的效率，总之，虽然麻烦，但绝对值得去做。&nbsp;\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>日期\u003c/td>\u003ctd>\u003cp>时间段\u003c/p>\u003c/td>\u003ctd>工作\u003c/td>\u003ctd>时长\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>8月9日\u003c/p>\u003c/td>\u003ctd>\u003cp>6：30\u003c/p>\u003c/td>\u003ctd>\u003cp>起床\u003c/p>\u003c/td>\u003ctd>\u003cp>10分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>6：40-7：40\u003c/p>\u003c/td>\u003ctd>\u003cp>完成共读作业\u003c/p>\u003c/td>\u003ctd>\u003cp>50分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>7：40-7：50\u003c/p>\u003c/td>\u003ctd>\u003cp>早餐\u003c/p>\u003c/td>\u003ctd>\u003cp>10分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>7：50-8：26\u003c/p>\u003c/td>\u003ctd>\u003cp>统计和点评训练营\u003c/p>\u003c/td>\u003ctd>\u003cp>30分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>检讨\u003c/p>\u003c/td>\u003ctd>\u003cp>点评反馈严重超出预期时间\u003c/p>\u003c/td>\u003ctd>写共读作业时注意力受微信干扰\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>日期\u003c/td>\u003ctd>\u003cp>时间段\u003c/p>\u003c/td>\u003ctd>工作\u003c/td>\u003ctd>时长\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>8月10日\u003c/p>\u003c/td>\u003ctd>\u003cp>6：30\u003c/p>\u003c/td>\u003ctd>接电话2通\u003c/td>\u003ctd>\u003cp>20分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>7：00-7：30\u003c/p>\u003c/td>\u003ctd>\u003cp>完成共读作业\u003c/p>\u003c/td>\u003ctd>\u003cp>30分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>7：30-7：50\u003c/p>\u003c/td>\u003ctd>完成3V3作业\u003c/td>\u003ctd>\u003cp>20分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>7：80-8：17\u003c/p>\u003c/td>\u003ctd>\u003cp>点评魔法亲亲2拆\u003c/p>\u003c/td>\u003ctd>\u003cp>27分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>8：17-8：30\u003c/p>\u003c/td>\u003ctd>\u003cp>早餐\u003c/p>\u003c/td>\u003ctd>\u003cp>13分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>检讨\u003c/td>\u003ctd>\u003cp>调整写作业时不开微信。明显效率增高。\u003c/p>\u003c/td>\u003ctd>\u003cp>老公叫我去吃早餐时，婆婆让我去晾下衣服。\u003c/p>\u003c/td>\u003ctd>\u003cp>延迟早餐时间引起他人情绪\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>日期\u003c/td>\u003ctd>\u003cp>时间段\u003c/p>\u003c/td>\u003ctd>工作\u003c/td>\u003ctd>时长\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>8月11日\u003c/p>\u003c/td>\u003ctd>\u003cp>6：30\u003c/p>\u003c/td>\u003ctd>\u003cp>起床\u003c/p>\u003c/td>\u003ctd>\u003cp>10分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>6：40-7:10\u003c/p>\u003c/td>\u003ctd>\u003cp>完成共读作业\u003c/p>\u003c/td>\u003ctd>\u003cp>30分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>7：20-7：40\u003c/p>\u003c/td>\u003ctd>完成3V3作业\u003c/td>\u003ctd>\u003cp>20分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>7：40-8：10\u003c/p>\u003c/td>\u003ctd>每日3拆\u003c/td>\u003ctd>\u003cp>30分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>8：10-8：30\u003c/p>\u003c/td>\u003ctd>\u003cp>早餐\u003c/p>\u003c/td>\u003ctd>\u003cp>20分钟\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>检讨\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>形成这段时间的常规。\u003cbr>\u003c/p>\u003c/td>\u003ctd>授权儿子帮我晾衣服。电话\u003c/td>\u003ctd>\u003cp>继续随时记录这段时间。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>拆书家提问设计：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;显像提问现在，请大家想想自己是否也有类似的经验，预估时间和实际消耗时间不同。比如：原定3小时完成的报告花了5小时；定了10分钟的约会，一聊投机了就用了半小时；孩子写作业拖拉，孩子一玩就不回家了等等，在你的期望和你的效率不匹配时的经验，有没有？请在小组中讨论一下，我请2人分享。&nbsp;\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>\u003cstrong>学习者A：7岁的孩子说出去玩半小时,结果一玩就是天黑了.\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者B: &nbsp;14岁的孩子写作业预估3小时,结果做了5小时. 妈妈觉得他拖延了.&nbsp;\u003c/strong>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>反思加工&nbsp;如果今后再遇到同样场景，你会如何运用今天学到的方法呢？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>\u003cstrong>学习者A：为孩子做一个时间记录. 从出去晚开始到回来时结束.\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":2737,"quote":"\u003cp>学习目标：\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够检讨时间记录，做有系统地时间管理。\u003c/p>\u003cp>一、【R】阅读原书拆页\u003c/p>\u003cp>TF&nbsp;2-4&nbsp;原文片段2 《卓有成效的管理者》P27\u003c/p>\u003cp>许多有效的管理者都经常保持这样的一份时间记录，每月定期拿出来检讨。至少，有效的管理者往往以连续三四个星期为一个时段，每天记录，一年内记录两三个时段。有了时间耗用的记录样本，他们便能自行检讨了。半年之后，他们都会发现自己的时间耗用得很乱，浪费在种种无谓的小事上。经过练习，他们在时间的利用上必有进步。但是管理时间必须持之以恒，才能避免再回到浪费的状态上去。&nbsp;\u003c/p>\u003cp>因此，第二个步骤就是要做有系统的时间管理。 我们先要将非生产性和浪费时间的活动找出来，尽可能将这类活动从时间表上排除出去。\u003c/p>","explains":"\u003cp>二、【I】拆书家讲解引导\u003c/p>\u003cp>第一个片段我们可以看到，时间效率不仅是自己的问题，而且可能引发人际冲突，所以当我们不再把时间管理看作只是自我管理的事情时，我们会有更好的和谐关系，因为我们的关注点转移到了有效性这个词上，我们不仅关心“把事情做对”，更关心“做对的事情“。不仅重视效率，更重视贡献和产出。\u003c/p>\u003cp>我不知道大家是否对时间感受到压力， 因为时间是稀缺的资产，大家不得不在多个领域涉足：职场，爱好，自我成长，将康，教育，人际交往，创业，专业。这都是我们需要投入时间和精力，方可产生有效性的地方。 而在信息化变革的年代，时间已经被分割成极小的单位，我们更需要有系统的时间管理，以便有整大块的时间。&nbsp;\u003c/p>\u003cp>翻译书中的案例我们先一起来看看我刚才记录的2小时， 有哪些是我可以从时间表中排除的呢？这些事情就是对组织没有贡献，对个人也没有贡献，对对方也没有贡献的事情。 刷微信， 是让我完成共读作业的一个很大干扰， 属于浪费时间的活动， 再比如：8月9日中的统计和点评训练营，我作为班长的工作是统计，而点评不是我的贡献；在这里点评是非生产性的活动，要排除出去。 我记得有一次，魔法亲亲的馆长邀请我参加他们的一次活动，时间是晚上7点，我犹豫了很久，1. 我参加活动对她们有什么益处？（邀请目的）2.我6：40上完课，赶去时间很紧，肯定迟到。3. 参加活动对我有什么贡献？ 我想了很久，没有找到打动自己的理由，但因为她的盛情，我还是去了，后来果真如自己的判断，是属于非生产性的时间支出。\u003c/p>\u003cp>接着问自己：时间记录上的哪些活动可以由别人代为参加而不影响效果？早上的这2个小时最容易被提醒的时候，是老公叫我吃早餐，儿子叫我检查作业，婆婆叫我晾衣服。除了我自己管理好”切换点&quot;,按时就餐外，我会在前一天和孩子沟通，请他帮忙：我会授权我儿子晾衣服，授权我女儿检查儿子作业。当然这里只是在家庭系统中做了简单的调整，你可以将授权思维迁移到你的环境中，别以为地球离了你就不转了。&nbsp;\u003c/p>\u003cp>最后我们是否浪费了别人的时间。 问问我儿子：我常做哪些浪费你的时间而又不产生效果的事情？他说在我想玩的时候让我定计划，做规划。这就提示我要选择做重要事情的时机，这点涉及到每个人的自省。&nbsp;\u003c/p>\u003cp>上学期，我和李芳在路上，偶然遇到小龙的爸爸妈妈，那时他们正出家门要去办事，我们站在路边一聊聊了一个小时，家长情商可能很好，没有表示着急，李芳一直给我暗示，我都没有意识到，事后李芳告诉我: 人家有急事，我都暗示你好几次结束呢。这就是浪费别人的时间而又不产生效果的典型例子。\u003c/p>\u003cp>细化行动步骤\u003c/p>\u003cp>&nbsp;如下三步可以帮助我们做到有系统的时间管理。\u003c/p>\u003cp>1. 将时间记录拿出来，逐项问自己：这件事如果不做，会有什么后果？找出浪费时间和非生产型支出的活动，从时间表中排除它。\u003c/p>\u003cp>2. 时间记录上的哪些活动可以由别人代为参加而又不影响效果？ 将可由别人做的事情交付给别人，授权可以真正应由自己做的事。\u003c/p>\u003cp>3. 请周围的人们想想看，我常作哪些浪费你的时间而又不产生效果的事情？真实而诚恳的回答会帮助你更好内省。\u003c/p>","interaction":"\u003cp>三、【A3】促动参与\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>我们刚才学习了系统管理时间的三个步骤，现在来做一个演练，请大家认真听这个演练场景：\u003c/p>\u003cp>场景设计：&nbsp;小红是重点中学初三的数学老师，今年带2个班，其中一个是初三的重点班。老公是某事业单位的干部，有1个上小学5年级的孩子。心理学进修者。现在想带孩子去国外旅行，想把英语加强一下，并多学一门韩语，还要有周末的休闲活动。开始感觉时间不够用，迫切需要有系统的时间管理。 这是她一天的工作事项：1. 买菜做饭 2. 每周12节课，3.每天2晚在线学习心理学。4. 英语在网上打卡练语音 5.寻找合适的韩语培训班 6.辅导孩子作业 &nbsp;7.班级家长的沟通 &nbsp;8.朋友聚会和聚餐 &nbsp;9.周末的休闲和爬山 &nbsp;10.学校常规 &nbsp;11.批改作业 &nbsp;......\u003c/p>\u003cp>小组讨论：我们用10分钟的时间小组讨论一下，你们记录一下小红一天的时间支出， 如何把小红的困扰再构建得详细和完整一点。并从这3个方面讨论出1. 要去除哪些非生产性时间支出和浪费的时间支出。2. 可以授权他人的工作 3. 没有产出又浪费别人的时间支出\u003c/p>\u003cp>角色扮演：10分钟后我请一位小红，一位小红的老公来做一次角色扮演，看看小红是如何和老公商讨新的变化，形成时间管理的新方案的。&nbsp;\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>\u003cb>小红: 老公, 我这学期事情好多, 除了学校那一摊,想带儿子出国旅行,把英语口语加强一下, 我们讨论一下怎么把这些事情做好好不好?\u003c/b>\u003c/p>\u003cp>\u003cb>小红老公: 好,有哪些我可以分担的?\u003c/b>\u003c/p>\u003cp>\u003cb>小红: 买菜做饭交给你好不好, 这块好占时间,还有帮我找个韩语培训班. (授权)\u003c/b>\u003c/p>\u003cp>\u003cb>小红老公: 韩语培训班? 英语就好了,韩语培训班就别折腾了. &nbsp; (去除非生产性支出)\u003c/b>\u003c/p>\u003cp>\u003cb>小红: 孩子的作业辅导你可以管一下吗?我们初三的学生还要多和他们家长沟通,督促一下?\u003c/b>\u003c/p>\u003cp>\u003cb>小红老公: 你是老师,孩子作业你可要辅导的. 学校的家长你就少点沟通了,现在大家都忙得很,都初三了, 还有多大改变,这学习就是主动的事情,老师就是个外因呀.&nbsp;\u003c/b>\u003c/p>\u003cp>\u003cb>小红: 你说的也有道理, 好吧, 孩子的学习是重要的, 我把家长们的沟通少一点, 没准还真是浪费他们的时间, 不然朋友聚餐我也降低一下频率, 毕竟带孩子出国锻炼语言能力是关键. &nbsp;(内省)\u003c/b>\u003c/p>\u003cp>\u003cb>\u003cbr>\u003c/b>\u003c/p>\u003cp>四、【A2】催化应用\u003c/p>\u003cp>拆书家提问设计： 现在大家想想你打算在未来如何使用这三步，实现有系统的时间管理，比如在教学工作，人际交往，专业输出，经济自由，孩子教育，健康管理，组织会议等方面，提升自己的有效性。\u003c/p>\u003cp>分步催化\u003c/p>\u003cp>学习者案例记录：\u003cbr>\u003c/p>\u003cp>记录孩子放学回家至晚饭前的时间段7天: 4:50-6:00, 看看孩子的时间消耗在哪里,然后采用三个步骤来帮助他分析,并形成新的时间管理方案.&nbsp;\u003c/p>\u003cp>结语（1分钟）:\u003c/p>\u003cp>时间的感觉是靠不住的，最好记录下时间的实际支出，以便我们能精准地分析，认识自己并找出优化时间管理的办法。同时着眼于有效性，而从消除浪费，授权他人，注重产出这三个方面来系统管理自己的时间。以上就是我今天的拆书分享，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1473634892000,"updated_at":1473634892000,"ria":true},{"id":657,"topic":"共读实践分享：卓有成效的管理者","learn_goal":"成为卓有成效的人","remark":"中英文双语珍藏版","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"熊媛","city":"上饶市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":null,"ratings_count":0,"texts":[{"id":2027,"quote":"\u003cp>P4 &nbsp;知识工作者的工作动力，取决于他是否具有有效性，及他在工作中是否能有所成就。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>关注\u003c/td>\u003ctd>重视\u003c/td>\u003ctd>成果\u003c/td>\u003ctd>内容\u003c/td>\u003c/tr>\u003ctr>\u003ctd>体力工作者\u003c/td>\u003ctd>效率\u003c/td>\u003ctd>把事情做对\u003c/td>\u003ctd>数量与质量\u003c/td>\u003ctd>听命\u003c/td>\u003c/tr>\u003ctr>\u003ctd>知识工作者\u003c/td>\u003ctd>有效性\u003c/td>\u003ctd>做对的事情\u003c/td>\u003ctd>有效性（优势，结果）\u003c/td>\u003ctd>思考\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>有成就感，工作上的有效性是知识工作者的工作动力。&nbsp;\u003c/p>","interaction":"\u003cp>A1: 我带小龙学习，每天感觉不到他明显的进步，很有挫折感，直到那天他爸爸对我说，他明显发现他认识很多字了。&nbsp;\u003c/p>\u003cp>A2: 如何对自己的工作有效性进行评估呢？定期对工作有效性进行评估，以便增强工作动力。收集他人的反馈是很好也很重要的一个环节。&nbsp;\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":2028,"quote":"\u003cp>&nbsp;P2 R:为什么需要卓有成效的管理者？&nbsp;\u003c/p>","explains":"\u003cp>&nbsp;在工业时代，管理者比例不多，有效性问题不凸显。大多是体力工作者，大家关注的是效率，即把事情做对的能力，基本以执行命令为主，如同我们身体的手和脚。同时，早期的知识工作者基本自行开业，其有效性仅和自己有关。 而在今天，知识工作者成为组织里的主力，他们的有效性是由对组织的贡献来判定的。而\u003cstrong>知识工作者的动力取决于有效性\u003c/strong>，\u003cstrong>他要具有做对的事情的能力。\u003c/strong>我们只能协助知识工作者，他们思考，自我管理，自觉完成，自觉贡献，自觉追求工作效益，但他们不生产具有效用的产品。 他们生产的是知识，创意和信息。\u003cstrong>他需要另一位知识工作者将他的产出当作投入，并转化成另一种产出，它们才具有实际的意义(核心竞争力，优势，业绩，资源）\u003c/strong>&nbsp;WHY: 1.知识工作者是组织的主力。 2. 知识工作者是自我管理者，衡量标准是对组织的贡献。 3.知识工作者的工作是生产知识，创意和信息。其动力来源于有效性。4.知识工作者的产出需要另一位知识工作者的转化。 &nbsp;\u003c/p>","interaction":"\u003cp>&nbsp;A1: 我为什么要成为一名知识工作者？（1.我在什么组织中？2.我要对组织有什么贡献？）\u003c/p>\u003cp>拆书帮上饶筹备分舵召集人。 培养出6位三级拆书家。\u003c/p>\u003cp>&nbsp;A2:&nbsp;\u003cstrong>如何转化另一位知识工作者的产出呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1470007216000,"updated_at":1470007216000,"ria":true},{"id":439,"topic":"管理时间","learn_goal":"如何高效利用时间","remark":"作为一名管理者，你在管人、管事各方面都是有效的吗？作为刚走上管理岗的你，事情多了，管理的人也多了，你知道如何达到高效吗？作为即将走上管理岗的你，是否需要提前了解管理者的工作和以前有什么区别，如何合理安排？","level":"TF3-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"喜羊羊","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"作为一名管理者，你在管人、管事各方面都是有效的吗？作为刚走上管理岗位的你，事情多了，管理的人也多了，你知道如何达到高效吗？作为即将走上管理岗的你，是否需要提前了解管理者的工作和以前有什么区别，如何合理安排？\r\n影响：没有效率的管理，会让你每天焦头烂额疲于奔命四处救火，并且会让你在下属面前毫无威信可言，在领导面前难有建树。\r\n解决：现代管理学之父彼得•德鲁克的《卓有成效的管理者》从时间、结果、人员、事件、决策管理几个方面方面深入分析了有效性的定义和原则，让我们可以一一对照分析判断改善提升管理的有效性。","ratings_count":0,"texts":[{"id":996,"quote":"掌握自己的时间自测表 \r\n项目 非常符合 比较符合 不确定 比较不符合 非常不符合\r\n记录时间 \r\n我总是随身携带日程表或备忘录 5 4 3 2 1\r\n我经常通过回顾一天的工作，了解自己的时间是怎么打发的  5 4 3 2 1\r\n我每天都会记下要完成的任务和目标 5 4 3 2 1\r\n管理时间 \r\n要做的事情很多，我却能正确处理好这些事 5 4 3 2 1\r\n我通常都能按照限定的时间去完成工作 5 4 3 2 1\r\n我习惯工作任务亲力亲为，总觉得不放心让别人做 1 2 3 4 5\r\n我觉得手头上的事情经常发生冲突，是因为我不懂或不好意思拒绝不想做的事 1 2 3 4 5\r\n我经常参加为解决同一个问题而召开的会议 1 2 3 4 5\r\n我经常忙于应付突发事件，以至于常常处于紧张状态 1 2 3 4 5\r\n统一安排时间 \r\n我总是把最重要的工作安排在活动效率最高的时间里去做 5 4 3 2 1\r\n我总是能在一个时间段安静完成一件事，不受QQ、微信、电话或者其他人的打扰 5 4 3 2 1\r\n我对自己浪费掉的时间深感懊悔 1 2 3 4 5\r\n时间管理是我们遇到的非常古老的一个问题。无论是做为管理者，所承担的责任更大，工作涉及的面更广事情更多，高效的管理，时间是首要因素。而我们大多数管理者，往往花费了很多时间在非生产性的和事务型的事情上，每天疲惫不堪却效率低下。通过这个量表，可以帮助我们检视我们是否能很好地掌握自己的时间，那么通过刚才的检测，我们大部分的小伙伴都需要改进以提升对时间的有效利用。接下来请大家看看我发到群里面的片段，看看如何提升时间管理的有效性。\r\n根据我的观察，有效的管理者并不是一开始就着手工作，他们往往会从时间安排上着手。他们并不以计划为起点，认识清楚自己的时间用在什么地方才是起点。然后他们管理自己的时间，减少非生产性工作所占有的时间。最后，再将“可自由运用的时间”，由零星而集中成大块连续性的时段。这三个步骤，是管理者有效性的基础：\r\n记录时间；管理时间；统一安排时间。","explains":"看了这个简短的片断，大家告诉我，提升时间管理有效性有哪几个步骤？ \r\n非常正确！分三步：记录时间、管理时间和统一安排时间。接下来我用一个我生活中的案例具体讲解一下这三个步骤的内容。（请大家结合图示）最近我发现我的周末时间很紧张，于是根据今天拆页的步骤进行了一次梳理。第一步，我把周末从早上起床后所做的事情和时间进行了记录：洗衣服晾衣服、收拾房间、做早餐、督促儿子做作业、弹钢琴、拆书准备、画简笔画、察看微信信息、回微信……第二步，开始系统的梳理管理时间，找到不必做的事情：有很多微信信息根本是无关的，决定删掉无关的公众号；找到可以授权做的事情：收拾房间花费了我大量的时间，而于我当前并不是非常有创造力和有意义的事情。我决定找个家政，这样就可以解放出来做更多有意义的事情。对于儿子的作业和钢琴，其实我也不必一直陪着或者不断说教，我只用给他限定时间完成，并给予一定的激励即可。第三步，统一安排一个时间做好一件事。之前找片段的时候，总会受到微信、电话、儿子的干扰。现在把这个时间固定在儿子做作业的时间，关掉手机WIFI，关掉电脑网络，并告诉儿子这个时间段自己和他都要完全自己的任务，互不干扰，等我们都完全后互相检查。这样做了一系列的调整，我终于能在周末轻松完成该做的事情了。","interaction":"小李是新晋级的一名市场部经理，升职以后干劲十足，每天鸡血满满主动加班，部门工作计划、部门月度目标的制定、下属工作安排、下属请求帮助沟通的客户面谈、部门小会公司大会、接听客户的电话、与客户的应酬、撰写项目计划书、财务部请求帮忙收款、甚至还有别的部门找他做PPT的（他的PPT做得很牛）等等，他通通来者不拒，可兴奋劲儿没过几天，就感觉精力不足，每天忙得不可开交，可效率却很低，而他的下属却闲得发慌。于是找到他的领导：王总监，希望领导给他支支招。接下来请小伙伴们四人一组来运用今天的学习的有效时间管理的步骤来帮小李梳理一下，要求每组选出两名演员，一名小李，一名王总监。\r\n小李的故事：\r\n鸟（王总监）：小李啊，有事吗?\r\n丹（小李）：王总，是有点事想请教一下您。不是当了经理吗？最近感觉有些累。\r\n鸟：是吗？是看你怎么最近头顶都有点秃呢。\r\n丹：是啊，最近感觉好多事啊！\r\n鸟：哦，那每天都有些什么事儿啊?说出来我听听？\r\n丹：你看我吧，要做月计划，周计划，每天的计划，有时还要帮下属沟通一下重要的客户，完了我不是PPT做得还不错嘛，偶尔还要帮别的部门做些设计；另外，我不是跟甲方关系熟吗？还要帮财务部收款，都是同事，又不好拒绝。\r\n鸟：哟，我看你还列了计划，来来来，我看看。。。。。。哎呀，你这事儿的确是太多太杂了，我来教教你方法吧！\r\n鸟：太感谢了王总监!\r\n鸟：小李啊，你现在是管理者了，要学会合理运用时间，怎么做呢?第一步，要记录时间，你把你一天做的事，事无巨细全都记录下来，几点到几点，干了什么什么事。然后呢，就是第二步，管理时间，把你记录的这些事梳理清楚，找到不必要做的事情：比如你看你这上面列的，帮财务收款、帮同事做PPT，这都是他们自己分内的事，跟你没有关系啊，你都忙成这样了，还去管闲事？另外找到可以授权的事：你看看你这上面的，客户的电话，哪还需要你个大经理去接？应酬客户、写计划书之类的，这些都可以授权给下属去做的啊。。。。。。通过这样的梳理，你把你所有的工作重新理顺，只做你应该做的事，其他的事情都可以不用做。最后第三步，在每天的时间安排中，安排出一个属于你自己的独立工作时间，并且要告诉你的下属和其他同事，排除一切干扰去做你应该做的最重要的事情。\r\n丹：太感谢了王总！我马上回去梳理梳理！","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1465054294000,"updated_at":1465054294000,"ria":true},{"id":438,"topic":"授权","learn_goal":"如何授权","remark":"作为一名管理者，你在管人、管事各方面都是有效的吗？作为刚走上管理岗的你，事情多了，管理的人也多了，你知道如何达到高效吗？作为即将走上管理岗的你，是否需要提前了解管理者的工作和以前有什么区别，如何合理安排？","level":"TF3-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"喜羊羊","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"作为一名管理者，你在管人、管事各方面都是有效的吗？作为刚走上管理岗位的你，事情多了，管理的人也多了，你知道如何达到高效吗？作为即将走上管理岗的你，是否需要提前了解管理者的工作和以前有什么区别，如何合理安排？\r\n影响：没有效率的管理，会让你每天焦头烂额疲于奔命四处救火，并且会让你在下属面前毫无威信可言，在领导面前难有建树。\r\n解决：现代管理学之父彼得•德鲁克的《卓有成效的管理者》从时间、结果、人员、事件、决策管理几个方面方面深入分析了有效性的定义和原则，让我们可以一一对照分析判断改善提升管理的有效性。","ratings_count":0,"texts":[{"id":995,"quote":"拆页来自本书第二章：掌握自己的时间。作者认为有效的授权可以帮助管理者管理好自己的时间。接下来请大家看看这个片段。\r\n“授权”这个名词，通常都被人误解了，甚至是被人曲解了。这个名词的意义，应该是把可由别人做的事情交付给别人，这样才能做真正应由自己做的事——这才是有效性的一大改进。","explains":"通过这个简单的片断，我们明白了有效“授权”的真正含义是把可由别人做的事情交付给别人，而管理者做真正应由自己做的事。很多管理者总认为很多事情下属干不了，或者认为教他做的时间自己早都做完了，往往大包大揽，自己累死下属也没有激情。还有一些管理者把工作全都指派给了下属，自己无事可干……那么，究竟什么是有效的授权？\r\n举个例子给大家，我在之前的公司上班没多久的时候，从子公司调来一位非常年轻的经理，不仅没有行政人事工作的相关知识和经验，领导范儿还特别足，到任第一次开会，让我们各自汇报了一下自己的工作，然后就把老板安排给她的相关事情给我们一一分配，全都“授权”给我们，自己每天当甩手掌柜，躲在自己的小办公室听音乐聊QQ。结果可想而知，她的好日子没过多久就被干掉了。那么像她这样把所有的事（包括自己应该做的大小事情）都交给别人才叫授权呢？显然不是。\r\n是不是把事情不分轻重不做区别分配，抓到谁就是谁就叫授权呢？还是上面这位小领导，常让行政去做人事该做的事，看到谁就指派给谁。\r\n是不是把事情交待给下属就完事儿了，不管不顾不问就叫授权？小领导一样是如此，任务安排下去就只是在她需要的时候要结果，既不给予权限范围，时间限定，也没有给予任何支持，更不谈相关的培训。\r\n因此，有效的授权是把管理职责范围外的工作授权给能完成好的人，而管理者做真正应由自己做的事。\r\n那么根据上面的例子总结，我们把有效“授权”的步骤总结如下：\r\n第一步：界定授权范围。相关调查表明管理者通常有80%的工作都是可以授权出去的。对照自己的个人职责和部门职责，区分出自己该做的事和应该授权做的事，或者对自己的日常工作进行记录，进而区分出哪些是必须自己做的，哪些是可以授权的。通常对于一个管理者来说，必须自己做的工作就是把大局，用能人。大致包括部门规划、目标下达、人员发展和培训等，而其他事务性、具体业务、专业技术性工作皆可授权。比如有些没必要亲自参加的会议，没必要亲自写的报告。当然，授权不等于推卸责任。\r\n第二步：量其能、授其权。根据下属能力大小、特长、知识水平合理分配工作任务。\r\n第三步：系统授权。清晰告知下属所授权事件的完成目标期限，能给予的支持并适当给予相关经验的传授和培训。","interaction":"个人认为，有效授权不仅可以用到工作中，也可以运用到生活中，比如太忙可以请钟点工打扫卫生，洗碗叠衣服之类的活可以授权给老公和孩子之类。接下来请小伙伴们想一想，在你明天的工作或者周末的生活安排中，有哪些场景是需要你重新思考授权的，又该如何有效进行授权？请四人一组将你的场景编成一段小故事，设计出人物、情节变化和对话动作。要求包含今天所讲的有效授权的步骤。\r\n如何讲故事：跟小朋友的看图说话一样，交待背景人物，动作对话。小TIP：将第一人称换成第三人称。\r\n小妖精的故事：从前有个小妖精叫ＭＯＭＯ，住在一个盘丝洞。有一天周末，小妖精觉得自己的盘丝洞太乱了，到处都是灰尘，还布满了各种蛛丝马迹。工程太庞大，她自己还有其他很重要的事要去做。于是她下载了一个专业的“妖精到家”的ＡＰＰ，请了一位专业的家政来帮她整理盘丝洞。要求是第二天８点到下午５点，家政帮她把厨房的灶台，两个卫生间，卧室的衣柜都做一下清理。另外把各种灰尘和蛛丝马迹也全都清理掉直到只剩下一只蜘蛛。\r\n于是第二天，家政准时到家按小妖精的要求把盘丝洞打扫得干干净净，而小妖精也安静做了一天的项目策划书！","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1465054198000,"updated_at":1465054198000,"ria":true},{"id":430,"topic":"有效的考评方式","learn_goal":"提升会议效率","remark":"这是一本的作者是现代管理学之父彼得•德鲁克的著作，他的著作被译成了37种语言，畅销全球130多个国家。《卓有成效的管理者》这本书已成为全球管理者必读的经典之作！\r\n这是一本非常实用的管理实战工具书，书中德鲁克集中论述了通过现并管理者如何掌握自己的时间、我能贡献什么、如何发挥人的长处、要事优先、决策的要素、有效的决策等几个方面做到卓有成效，通过案例说明等多种方式通俗易懂的阐述了掌握这些能力的方法和工具。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"陈艳蓉","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位伙伴晚上好，我叫陈艳蓉，今天很高兴由我来给大家做TF1-2的拆书分享。\r\n这本书的作者是现代管理学之父彼得•德鲁克的著作，他的著作被译成了37种语言，畅销全球130多个国家。而且……这本书也已成为全球管理者必读的经典之作！\r\n这是一本非常实用的管理实战工具书，通过如何掌握自己的时间、我能贡献什么、如何发挥人的长处、要事优先、决策的要素、有效的决策等几个方面的理论及案例讲解，充分阐述了掌握这些能力的方法和工具。\r\n请大家先用3分钟时间阅读原文片段(第一页和第二页，标有 ………. 的中间部分)，请读完的伙伴举手示意一下。","ratings_count":0,"texts":[{"id":972,"quote":"请大家先用3分钟时间阅读原文片段(第一页和第二页，标有 ………. 的中间部分)，请读完的伙伴举手示意一下。\r\n 但是，一套适当的考评方式，毕竟是不可少的，否则，当一个职务需要某个来承担时，就没有办法对他做出正确的评价，因此，有效的管理者，通常总有他自己的一套与众不同的考评方式。第一步是列出对某人过去职务和现任职务所期望的贡献，再把某人的实际绩效记录与这项期望贡献相对照，然后检讨下面的四个问题：\r\n（1） 哪方面的工作他确实做得很好？\r\n（2） 因此，哪方面的工作他可能会做得更好？\r\n（3） 为了充分发挥他的长处，他还应该再学习或获得哪些知识 ？\r\n（4） 如果我有个儿子或女儿，我愿意让我的子女在他的指导下工作吗？\r\na. 如果愿意，理由是什么？\r\nb. 如果不愿意，理由是什么？\r\n这样的考评方式，显然与通常的做法不同。这套方式以当事人的长处为重心，以当事人能做些什么开始。而当事人的缺点，只是视为他发挥长处和力求成就与有效性的限制而已。\r\n 好了时间到了，如果有小伙伴还没看完的，也没有关系，我会在后续分享中为继续大家解读。","explains":"绩效考评的目的是持续提升个人、部门和组织的绩效。但在实际应用中即不尽人意，在座的各位大多都是管理者可能都有过这样的体会，通过刚才阅读的片段，我想大家可能会有一些感悟。如果没有一套好的对员工的评价方式，就没有办法对员工做出客观、准确的评价。我们可以通过列出对员工的期望，再用他的实际绩效与期望进行对比评价，然后再检讨一下员工哪些工作做得确实很好？\r\n因此，哪方面的工作他可能会做得更好？\r\n为了充分发挥他的长处，他还应该再学习或获得哪些知识？\r\n如果我有个儿子或女儿，我愿意让他去指导工作吗？\r\nA. 愿意，理由是什么？B.不愿意，理由是什么？\r\n记得我们在4月5号前与培训专员一起制定4月考评指标的时候，我给她设定一个培训完成率的期望值，指标值90%，到五月初我会用她4实际达成的完成率与月初设定的期望值进行对比，就非常客观的得出了一个考评结果。\r\n然后我再检讨一下她哪些方面做得好的，比如说培训宣传应用了采访的方式，培训易企秀也做得非常生动。\r\n还有哪些工作可以做得更好，比如：员工岗位技能培训方面可能通过努力会做得更好，\r\n另外为了发挥她的长处她需要加强内部培训制度和培训体系课程的学习。\r\n假如我儿子在她手干活，让她来指导我的儿子，我觉得目前还太愿意，主要是专业知识还比较欠缺。\r\n在检讨完这几个问题后，我将这些情况与培训专员进行沟通反馈，让她学习相关课程，并发挥所长不断提升，我想她的绩效肯定也会越来越好的。","interaction":"拆书家提问设计（逐字稿）：\r\n下面请大家各自用1分钟时间思考一下，想想自己在员工绩效考评时是不是有过类似的经历，在月初制定指标时没有明确期望值？在绩效得分出来后也没有进行相关的思考检讨？也没有将绩效结果应用到员工学习培训、和特长发挥上面的经历？\r\n 请把这样的一个经历写在小便签纸上，我们用2分钟的时间，写好的请举手示意。\r\n好，我看大家都完成的差不多了，没有完成的小伙伴请先放下，我们现在进入下一个环节，小组分享，小组分享4分享大家简要说明，由2、3位来谈谈就可以了。\r\n好计时开始。 \r\n拆书家提问设计（逐字稿）：\r\n通过刚才的分享，我想大家都了解了设定考评期望值及考评后几个检讨问题的重要性。下面请每个人在刚才的纸上继续写上：在接下来的一个月内你们要对员工进行绩效考评时，你将如何应用考评期望值设定和绩效考评四个检讨问题。时间是1分钟，好了请举手示意。好现在开始！\r\n 好，大家都完成了，请一位伙伴来分享下，非常好！\r\n本次我们的拆书分享就到这里，谢谢大家！","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1464963847000,"updated_at":1464963847000,"ria":true},{"id":196,"topic":"卓有成效的管理者","learn_goal":"找出你的合作者的工作动力和长处，支持你工作目标达成。","remark":" 在管理工作与事务中，你是将注意力放在避免短板留意别人的短处，还是关注在如何依据他人的特质，因地制宜，创造更大的价值？同样，在对待你的上司时，你是不闻不问照着做好，亦或抱怨你的上司不够理解你的工作，还是考虑如何调动你老板的优势？本次拆书或许你会得到新的启发","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"Jacky","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"各位好，我是拆书家Jacky，今天我继续拆解《卓有成效的管理者》一书，本书的作者是大家所熟悉的管理学之父德鲁克的经典著作。这本书也是管理者的必读书籍之一。里面提到了管理者所需具备的几个品质：时间管理，关注贡献，要事第一，及决策要素等。\r\n今天我们将讨论如何看待你周围人的优点及缺点, 去挖掘及关注工作合作者的动力和长处，更好的形成共识及获得工作支持。\r\n各位有没有遇到过这样的情形，当你怀着兴奋的心情走进老板的办公室，和他分享一个你工作上的好想法时，他却很可能毫不在意？\r\n你的感受如何？你会如何如何看待这件事？有可能你会抱怨，老板一点也不了解我的这些任务和工作，或者形成对他的一些想法堵在心里，而这样后续也不利于双方相互的工作支持。\r\n如果换个角度去想，我们其实也是总考虑自己的工作和事务，却对老板的压力和任务关注很少，如何做到双赢呢？首先要看到对方的长处，对方擅长做什么，并协助其达成目标。\r\n我们今天的拆解主题就与此相关。","ratings_count":0,"texts":[{"id":277,"quote":"下面我们一起来阅读原文片段。\r\n不管是谁，如果他在任用一个人时只想避免短处，那他所领导的组织最终必然是平平庸庸的。所谓“样样皆通”，实际上可能是一无是处。才干越高的人，其缺点也往往越多。有高峰必有深谷，谁也不可能是十项全能。与人类现有博大的知识、经验、能力的汇集总和相比，任何伟大的天才都不及格。世界上实在并没有真正全能的人，最多只是有在某方面特别有能力的人。\r\n一位管理者如果仅能见人之短而不能识人之长，因而刻意避其所短，而非着眼于发挥其所长，则这位管理者本身就是一位弱者。他会觉得别人的才干可能构成对他本身的威胁。但是，世界上从来没有发生过下属的才干反而害了主管的事。美国的钢铁工业之父卡内基的墓志铭说得最为透彻：“这里躺着的人，知道选用比自己能力更强的人来为他工作。”当然，卡内基先生所用的人之所以能力都比他本人强，是因为卡内基能够看到他们的长处，在工作上运用他们的长处。他们只是在某方面有才干，而适于某项特定的工作。当然卡内基就是他们的卓有成效的管理者。\r\n李将军有一段故事，可以说明使人发挥长处的意义。李将军手下有一位将领常不按照命令行事，往往使李将军预定的计划完全改变。李将军屡次都忍受了，但终于有一次他忍不住大发雷霆。当他平静下来时，一位幕僚问他：“你为什么不将他革职呢？”据说当时李将军不禁一时愕然，无以为答，好一会儿他才说：“多么荒唐的问题！把他撤了，谁还能打胜仗？”","explains":"这段印证了这样一句话：“人非圣贤，谁能无过。”\r\n首先人都是会有优点和缺点的，即使有所说的全才，各项能力的分配也是并非均匀的，举例达芬奇已经是多才多艺了，但他的最突出的成就还是体现在绘画上。因此，人要有所为，是看长处是否得到最好的发挥，而单是木桶理论补短板。\r\n既然是需要看到对方的优点及长处，那应该如何避免只盯着人的不足，转移视角到人的长处呢？书后面给出了两个具体的方法，避免我们走到误区，我们一起来看图示：\r\n1.不专注于“谁好谁坏”，而是“什么好什么坏”，看到的是具体的点，而非陷入到只是对人进行泛泛的评价；\r\n2.在具体事情上，避免对人的能力进行评价，而转换角度，针对这件事或任务上，看他是否适合此项任务。及谈及能力时，应加一个具体的事情或任务。\r\n这样，我们就能在沟通中避免雷区。这个适合于对具体工作和任务的界定，但是当一个人基本无法匹配目前的工作大部分职责时，我们就需要换个角度看看他是否需要换一个职位了。\r\n举例来说，当对方未能按要求做好某件事情时，我们很容易给对方扣一个比如“能力不够”的笼统帽子，但对问题解决基本上没多大用处。但是如果能具体描述一下，他在这个新的领域中，对新的业务不够熟悉，就能够有的放矢，更好的帮助他了。\r\n发现对方的优势，并不意味着一味的包容他的缺点，如果他的能力和擅长点和他当前的岗位有较大的出入时，也需要考虑他是否应该转去做其他的事务或者寻找其他的机会。","interaction":"下面各位结合自己身边的经历，可以想想你有没有犯过之前讲到的问题：对人泛泛评价，对人的能力进行泛泛评价，如果重新让你改一下评价，你会如何来做呢？\r\n@祁玮：我前段时间的一个项目，有两个不同的团队合作，我的团队成员抱怨对方“思路不清出”，“我说的他们都听不懂”，在我做了了解后，发现其实两个团队开始只是自己只关注自己的领域造成的，而应该避免人身攻击。\r\n@Lily：我这边有一个新来的下属，给她安排了三件事包括C&B等都做得不好，在深入沟通后，发现小姑娘她并不喜欢做琐碎或擅长的工作，但我给了他另一次机会，做年会的活动，结果有很多小创意，反响也还不错。于是这给了我的教训是，对方做的未达到要求时，不应该马上给她贴标签，而是要先关注和了解他的优点缺点，再来针对具体事情来做评价。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":278,"quote":"好的，之前我们已经了解，看人需要二象性，而且需要放到具体的事情或任务当中去，并关注她的优点使其能够施展。如果我们再聚焦一下，我们了解老板吗？我们会去思考老板的擅长点吗？下面我们首先来做一个测试。\r\n1分到5分进行测试：\r\n条件 分值：1~5分（1分最低）\r\n1）你能清晰的说出目前你的上司重点关注的3~5项事务； \r\n2）你明确说出你的上司的工作目标，并能找出与你工作的关联关系； \r\n3）当你和他做汇报或提出新想法时，你知道和上司工作目标或方向的关联关系； \r\n4）你能说出至少三个你上司的优点。 \r\n很多时候，我们会抱怨上司不够理解自己及自己的工作，却也一直忽视了上司面临的工作及压力。当你能够更好地帮到你的上司时，其实你的机会也会更多，所以应换个思路想想，我了解老板吗？我如何帮助他发展他的优势呢？\r\n下面我们一起来阅读原文片段。\r\n有效的管理者了解他的上司也是人（然而年轻的下属却不容易有此了解）。上司既然是人，所以肯定有其长处，也肯定有其短处。若能在上司的长处上下工夫，协助他做好想做的工作，便能使上司有效，下属也才能有效。反之，如果下属总强调上司的短处，那就像上司强调下属的短处一样，结果将一无所成。所以，有效的管理者常问：“我的上司究竟能做些什么？他曾有过什么成就？要使他发挥他的长处，他还需要知道些什么？他需要我完成什么？”至于上司不能做些什么，那就不必细究了。\r\n一般人常想到如何“改变”他的上司。以政府机构来说，能干的高级官员，常以老师的姿态对待新到任的领导，设法使他的领导克服其缺点。但是有效的管理者考虑的却是：“这位新领导能做些什么？”如果说“他擅长应对，与国会的关系好，与白宫的关系好，与社会各界的关系也好”，那么下属就该设法使这位新领导充分发挥这方面的长处。因为即使有最好的行政，有最好的决策，如果没有好的政治技巧加以表达的话，那就等于零了。这位新领导知道下属的官员支持他，他也会很快在政策及行政方面采纳官员们的意见。","explains":"读了原文，你印象最深的地方是什么？能否分享一个点？\r\n@Jessica：作为下属，我该做些什么帮助上司发挥长处，比如工作中我应避免过多的打扰，把一些问题想清楚整理好后，再去向上司汇报。\r\n@Jacky回应：恩，提到了该如何帮助上司发挥长处，并举了具体的一个小例子。\r\n@Linda：我这留意到了两点内容，善于利用好上司所擅长的事务，比如说影响力等，另外一点，只有上司发现你做的这件事是在帮助他时，他也才会反过来给你更多的支持。\r\n@Jacky回应：非常好，提到了两点的内容：利用好上司的擅长，要让上司意识到在帮助他，所以在建议方式和技巧上也就需要有所讲究。\r\n讲的都很好，我来做一个小结，里面讲述了两个要点：\r\n其一是，突出说明了，上司也是人，别总将上司认为是你心目中的全才，他也有他的短板和擅长的地方，首先要正确看待他的长处和短处。\r\n其二，不要指望“改变”上司，而是可以思考上司能做些什么，擅长写什么？再去支持帮助他发挥擅长，帮助他成功也就是帮助你成功。","interaction":"那么究竟该如何帮助上司发挥优势，文中提及了一部分比如需要对他的了解，通过问题的方式进行探寻，那么还有没有其他方式呢？哪些方法你回去以后可以用起来？\r\n我们下面来做一个微行动学习，一起来探讨这个问题：\r\n1）问题澄清\r\n了解你上司的工作动力及擅长之处可以有哪些方式？\r\n2）分组讨论及呈现方式\r\n我们分成两组来进行讨论，并将结果写在纸上，你们可以有八分钟的讨论时间，最后每组可以请一个代表来进行2分钟的阐述。\r\n各位清楚了吗？\r\n讨论汇报：\r\n@Jessica: 我们这组讨论到动力这块，可以通过正式及非正式的方式，比如聚会吃饭，挖掘他的需求点，去具体了解上司的工作动力。此外了解上司的优点，可以通过面对面沟通，还可以从他的平级或他的老板等途径去进行了解。还有你自己觉得你和老板的差距点，也是他的优势。\r\n@Lily：我们这组的成员从各自不同的地方去进行探讨。\r\n1）和老板沟通，可以分为正式和非正式的沟通。\r\n正式沟通里面，我们可以利用一些工具，比如我们公司还用到了“good to know you”这样的工具，在新的合作前来做，包括关键时刻等，增进彼此的了解，了解背后他的价值观，而这往往是人的动力背后的东西，此外还有绩效会谈的时候，听听他对愿景目标的管理，也是非常好的方式。\r\n非正式沟通里面，比如吃饭和team building时候都是最佳的时机。可以和他聊天的过程中增进了解。\r\n2）360度的了解方式，和前面这组谈的很像。听听他的平级、上司或其他人如何来谈论他们的工作合作，此外他的履历比如Linkedin都是很好了解老板的方式，举例说我的老板是工科出身，那么他的逻辑性就会很强。\r\n@Jacky的回应：恩，为了要更加了解自己的上司，我们可以采取直接沟通，包括正式和非正式的方式，或者通过一些很好的工具来进行交流；或者可以听听与他合作的人是如何来对他的工作进行评价的，这些方式都有助于了解我们的老板，而这个是我们更好的获取我们老板工作支持的重要过程。\r\n刚才各位已经分享了了解老板工作动力及擅长之处可以有的方式，这些都将帮助我们梳理清老板想要些什么，并在和他交流沟通时，更容易和他同频，你的想法自然更容易被她所接受。\r\n讲故事 & 未来具体的应用：\r\n下面各位试想一下，在你未来的一周，有没有什么机会给你的老板进行工作汇报或者新想法的介绍？这件事情的缘由是什么，未来发生的时间，地点，能否勾勒出一幅画面来，谈谈你将如何和你的老板来谈这个话题，并赢得他的认同的。\r\n@徐慧：我今年想做的一件事是如何做培训评估做的更到位，但之前和老板提，老板也认为很好，但是并没有下文。下周一例会时，我会站在客户期望的角度或是公司发展的角度，和他去谈这个问题，这个是老板非常关心的问题，这样就站在他的角度去看待这个问题，更容易同频，能够帮助他更容易接受。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1458985671000,"updated_at":1458985671000,"ria":true},{"id":176,"topic":"要事第一，先后次序的考虑","learn_goal":"按照优先次序，列出自己近期的工作的1-3个重点。","remark":"在管理者面前，摆着许多值得去做的工作，但管理者的时间却非常有限。因此，这就涉及哪些事情需要优先处理，而哪些事情可以缓一缓再办的决策了。那么，到底根据什么来做这一决策呢？是由管理者来决定，还是由压力来决定？一起来读德鲁克的经典管理之作。","level":"TF3-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"Jacky","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"各位好，我是Jacky，今天为各位带来的是《卓有成效的管理者》，彼得德鲁克也被称为管理学之父，这本书也被许多管理者列为必读书目。\r\n不知道各位有没有这样的体验，在上班刚开始的一天，你打开电脑准备工作，却发现手上一堆的事情，不知从何开始做起，像一团乱麻？你会如何来定义你的工作优先级呢？如果你没有加以区分，或者只忙紧急事务，久而久之，可能将会让你忽略掉真正对你重要、且产生价值最大的事务；在这本书当中，不仅提了需要要事第一，还告诉我们一套如何排列优先次序的原则，供各位学习。","ratings_count":0,"texts":[{"id":237,"quote":"在平时的工作和生活中，你有没有注意到你是如何来划分事情的优先次序呢？下面我们可以通过一个简单的测试题一起来做个1分钟小测验。\r\n条件 分值：1~5分（1分最低）\r\n1）我习惯于一收到邮件，就会立即查看或进行处理； \r\n2）我习惯几件事情并行处理； \r\n3）我习惯于选择处理简单的事情，而导致给较难的事务分配时间和精力不够； \r\n4）相较于事务的处理结果和影响，我更习惯于按照问题的时效性来排列事务的优先次序。 \r\n刚才的这套自测题，主要是让你对自己反观下看待安排事务的优先次序这件事情。\r\n- 分值越小，说明你在处理事务时，更关注如何对优先次序进行排列，如果你的得分在12分以上，就说明你需要在处理事务前，可以先好好考虑事情的价值和优先次序排列了。\r\n我们都了解要事第一，那么该如何来定义优先次序呢？下面我们一起来阅读“优先次序的考虑”这个片段。\r\n决定延缓一项工作，并不是一件愉快的事情。因为我们的“优后”，往往是别人的“优先”。列举一份第一优先的工作单，事事都办，但均浅尝辄止，显然容易得多。这样经常能使人人皆大欢喜，然而结果却是一事无成。\r\n如何决定优先，研究起来确实很复杂。不过我们可以说，在决定哪些应该优先、哪些可以延缓这个问题上，最重要的并不是分析，而是拿出应有的勇气来。\r\n以下是几条可帮助确定优先次序的重要原则，每条都与勇气密切相关：\r\n·重将来而不重过去；\r\n·重视机会，不能只看到困难；\r\n·选择自己的方向，而不盲从；\r\n·目标要高，要有新意，不能只求安全和方便。\r\n试看许多在研究方面卓然有成的科学家的成就，与其说是他们的研究能力决定了研究的成果，倒不如说是他们寻求机会的勇气决定了研究的成果（当然，像爱因斯坦创相对论，玻尔创原子结构，或普朗克创量子论这样的天才除外）。大凡从事研究的科学家选择研究课题时，如果着眼于易于成功而非着眼于接受挑战，那他们纵然能够成功，其成功也相当有限。他们的成功，也许可以使他们的名字在别人的论文中出现，但却不能创造出一条以他们的姓名命名的“某某氏定律”来。所以真正的成就，只属于那些善于抓住机会选定研究课题的人，属于那些能把别人确立的准则只当做制约因素，而不当做决定因素的人。\r\n同样的道理，在企业经营方面，成功的事业，不是迁就现有产品线来开发新产品的事业，而是以开发新技术或开发新事业为宗旨的事业。当然，如果说创新有风险、有艰辛、有不确定性，那么不管创新是大是小，同样是有风险、艰辛和不确定性。化机会为成果，肯定比解决旧问题更有生产性。解决旧问题，总不过是恢复昨天的平衡而已。\r\n优先与延缓的问题不是一成不变的，根据实际情况的变化，经常需要对这种先后次序进行重新考虑和修正。例如，哪位美国总统都不会有一成不变的优先处理某些事项的计划。其实，在完成必须优先处理的事项的过程中，哪些应该优先，哪些可以挪后，也总是在不断变化的。\r\n换言之，一位有效的管理者，会把主要精力集中在当前正在进行的工作上，而不会再去兼办其他工作。完成一件事情之后，他会根据情况的变化，再决定下一步的优先事项。\r\n要想集中精力，全神贯注于一项工作，首先要有足够的勇气，要敢于决定真正该做和真正先做的工作。只有这样，管理者才能成为时间和任务的“主宰”，而不会成为它们的奴隶。","explains":"各位已经读完了这个片段，通过原文我们可以看到作者是如何对优先次序进行定义的。文中讲到了优先次序，提到了几条原则，他认为的关键词是什么？\r\n@海边渔民：里面讲到了勇气这个词；\r\n非常好，那么勇气怎么会和这几条原则进行关联呢，有没有在文中找到这些关联关系呢？\r\n@天蝎：我的理解就是勇气就是敢于应对相应的挑战，去发现机遇。\r\n@Jessica：里面几个原则，除了第一条之外，都需要与勇气有关联，需要迎面接受挑战。\r\n恩，讲的非常好，文中给出的优先次序其实就是：跳出舒适区，看到未来、看到变化，同时看到机遇和挑战。这和我们的头脑的习惯性选择是恰恰相反的。我们的的天生习惯是待在舒适区内，而少冒风险。这样做的结果是可能会丧失掉可能对自己很好的机会。\r\n也正是做出成绩的人，把更多的精力花在面向未来有价值的事情上，找到了工作的新突破口上。同时也获得了更多的回报。","interaction":"好，我们已经基本理解了这几个原则，那么，在实际工作中我们可以如何来参照来衡量我们定义优先级的好坏呢？我这里有一个案例，一起来看一下：\r\n下面我们给出一个具体例子，小A是一名工作2年的销售，他手上有几件事务，但时间有限，他该将自己的精力重点花在哪呢，应该如何入手，按照片段的原则，按小组进行讨论，请两组出来分享你们的讨论结果，并谈谈你们的理由：\r\n1）下周将在帮助他领导提交一份前三个月的数据报告；\r\n2）他的一个重要客户向他反映新的设备使用情况有很多的问题，希望他能尽快处理；\r\n3）他的业务出现了瓶颈期，为达成业务光靠目前的客户群体完成不了业绩；上星期公司已经推出一款新的业务，主打新的市场，就具体产品优势他还没有向市场部的小王仔细了解。\r\n给大家每个人2分钟的思考时间，然后我们现场可以分成两个组，并且分享下你们的讨论结果。\r\n@Jessica：我们关注的是所花精力最多，我们的想法是第三个，因为他们是最直接面向未来的，\r\n@冰蓝：我们也认为是个第三点，面向未来，而且是存在机遇的，其次是客户的抱怨，而我们认为第一点，实际上是“磨刀不误砍柴工”我们平时注重数据积累，做第一点就没有这么困难了。\r\n非常好，经过一番思考后，我们可能发现之前尚未留意到的价值和收获。同样，我们也希望各位能尝试一下用到我们自己的工作当中去，当下你有哪些事情是本应该处于更高的优先级，可惜因为它因为有着“欺骗”性，让我们的工作生活优先级选择出现空白。谢谢各位。\r\n跟踪案例：\r\n下面我来梳理下今天我们讲到的4个原则，来帮助我们进行事务优先级的判定。请各位回去之后，在明天开始新的一天工作时，先停顿下，想想心中的事情，按照我们前面所讲的原则，来制定自己新的一周的工作优先次序，并给出理由。\r\n拆书结束后的微信跟踪A2：\r\n桃子的A2： \r\n1. 接手公司市场经营系统的建设；\r\n2. 推动各部门进行协同设计系统的试点工作；\r\n3. 协调供应商优化协同设计系统的优化；\r\n对手上的工作按昨天Jacky的方法排了一个序，心理过程如下：\r\n1. 市场经营系统关系到公司的业务，会对公司的业务发展有驱动作用，虽然不熟悉，但是是一个机会，属于未来，目标也比较高；\r\n2. 把2和3的顺序对调了一下，因为系统目前存在一些问题，所以，推动方面做的比较低调，但是考虑到未来，应该接受挑战。只有引起更多的关注，才能引导更多的资源投入。\r\nJessica：我的A2:\r\n公司今年有很多导师制的项目，我需要挖掘自己更喜欢也更擅长的事情，之前了解到几家培训公司的转型，有往学习型组织转型的，运用自身的经验助推自己公司的业务，也有提供更多的后续服务，如微课，训练营等，帮助客户把培训内容更落地，而不是上完课就结束。所以在这个方面，需要我去投入更多的精力，通过为公司带来价值，提升自己创造价值的能力。\r\n海边渔民：A2：管培生项目是组织面向未来发展的人才储备计划，虽然现在组织内外都有挑战，我要力挺这个项目，并且在五月15到30日完成两轮面试，坚持高标准地选择。\r\n天蝎：@Jacky 我的A2：目前公司处于调整期，从整体公司运营的角度来看待公司的各类管理问题，因此制定了两个阶段的制度设计①针对目前基础的部分，草拟《劳动合同管理制度》、《考勤管理规定》、《快递接收管理办法》、《行政物品管理登记制度》、《招聘管理制度》、《员工入职管理制度》、《员工离职管理制度》、《加班管理制度》、《新员工转正管理制度》、《固定资产管理制度》、《会议管理制度》。这部分草拟完成，待逐一讨论通过后，可先行实施；②随着目前第三方管理咨询专家的介入，第二阶段要列入计划的有《员工培训管理制度》、《薪酬福利管理制度》、《绩效考核管理制度》\r\n第一阶段属于既着眼于当下，又放眼未来，属于重要又紧急的事项；第二阶段属于放眼未来，属于重要但不紧急的事项。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1458569159000,"updated_at":1458569159000,"ria":true},{"id":68,"topic":"如何组织更高效的会议","learn_goal":"学会组织更高效的会议","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"安静","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"我是今天过TF1-2的拆书家，首先跟大家认识一下我。\r\n与大家一样，我非常爱好读书，虽然读了很多书，感觉没太多收获，但最大的收获就是我影响了身边人。一位是我7岁的儿子，前几天元旦假期我问他新年的读书目标，他张口就来要读100本书，另一方面就是我的同事，我经常把书里读到有益的内容推荐给她们，她们由毕业后多年的不读书，到现在已经通过30个便签读书法和一级拆书家。这是让我感觉读书比较有收获的方面。\r\n除了读书我还比较喜欢爬山，喜欢有挑战的山。目前在实施的是爬爬遍河南的名山。少林嵩山、焦作云台山等非常不错。\r\n 以上就是我，我的名字来源于两个名句：阳春白雪 宁静致远 对，就是杨雪静。在座的有孩子的请举手？爱登山的朋友请举手？好的，以后对培养孩子读书及登山感兴趣的朋友一会相互留下联系方式。\r\n片段和所选书的介绍： 今天跟大家分享的是《卓有成效的管理者》。这本书对我最大的收获是当我遇到管理问题时，发现书中有很多实用的思路和技巧，我们马上能在工作中应用和改进的。","ratings_count":0,"texts":[{"id":71,"quote":"有效的管理者在会议开始时，会先说明会议的目的和要求达成的贡献。同时，他还要设法让会议紧紧围绕着主的贡献题。他绝不会使会议成为一次摆龙门阵的机会，任大家随便发言。当然，如果会议的目的是在激发大家的思想和创见，他也不会仅让某一个人滔滔不绝。他会刺激每一位与会人员的发言兴趣。但是在会议结束之前，他会回到开场所介绍的主题，使会议获得的结论与主题相符。","explains":"大大小小的会议，在我们工作中非常常见。那么如何一场会议有效进行？首先：开始时，先说明会议的目的和要求达成的效果及时间；其次，让会议围绕主题。就像我们以前的聚会，大家讨论某个主题，一旦有人提出他关注的问题，这时候大家特别容易脱离会议主题而去讨论刚提出的非主题问题。这个时候就需要会议组织者时刻注意提醒大家发言围绕主题进行。而我们上次的过级会议，大家目的非常明确，就是要过级。一有跑题的事情出现，就提醒大家这次主题是过级。其他事情等过级结束后再议。\r\n会议目的不同有不同的表现形式，不同表现形式要求与会者参与度不同。既不能任由与会者随意发言，也不会仅让一个人滔滔不绝。而是有意识激发与会者的发言兴趣。\r\n最后，会议结束时回到开场的主题，会议的结论与主题相符。","interaction":"1、 基于以上的情况，您有没有遇到过类似的情况？当时是如何处理的？\r\n2、 你觉得以后再遇到这种情况，如何更好的应对？\r\n除了刚才提到的会议上应用以上三个步骤外，还可以用在哪些方面？比如公司内部沟通，为高效沟通先表明目的和观点，再让对方围绕观点阐述自己的观点，最后做总结与达成的共识。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1452763592000,"updated_at":1452763900000,"ria":true}]};